def searchSymbol(query, limit=None, exchange=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mk_log_id():
        return "rlog_" + uuid.uuid4().hex

    def _normalize_text(s):
        s = s.strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    def _normalize_symbol(s):
        return re.sub(r"\s+", "", s.strip().upper())

    def _coerce_int_like(x):
        if x is None:
            return None
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float):
            if x.is_integer():
                return int(x)
            return None
        if isinstance(x, str):
            s = x.strip()
            if re.fullmatch(r"[+-]?\d+", s):
                try:
                    return int(s)
                except Exception:
                    return None
            if re.fullmatch(r"[+-]?\d+(\.\d+)?", s):
                try:
                    f = float(s)
                    if f.is_integer():
                        return int(f)
                except Exception:
                    return None
        return None

    def _pick_active_key(api_keys):
        # Ambient auth: choose an active key that can serve requests (exists + active).
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    api_keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    instruments = _load("instruments.json")

    used_key = _pick_active_key(api_keys)
    if not used_key:
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": (api_keys[0].get("id") if api_keys and isinstance(api_keys[0], dict) else "unknown"),
            "tool_name": "searchSymbol",
            "params": {"query": query, "limit": limit, "exchange": exchange},
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key is missing or not active.")

    # Quota enforcement (rolling windows)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
            else:
                dt = datetime.datetime.fromisoformat(s)
            return dt
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    key_id = used_key.get("id")
    minute_quota = used_key.get("minute_request_quota", 0)
    daily_quota = used_key.get("daily_request_quota", 0)

    minute_count = 0
    daily_count = 0
    for r in logs:
        if not isinstance(r, dict) or r.get("api_key_id") != key_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt:
            continue
        if dt >= minute_ago:
            minute_count += 1
        if dt >= day_ago:
            daily_count += 1

    would_minute = minute_count + 1
    would_daily = daily_count + 1
    if (isinstance(minute_quota, int) and minute_quota >= 0 and would_minute > minute_quota) or \
       (isinstance(daily_quota, int) and daily_quota >= 0 and would_daily > daily_quota):
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": key_id,
            "tool_name": "searchSymbol",
            "params": {"query": query, "limit": limit, "exchange": exchange},
            "http_status": 429,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "RATE_LIMIT",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": key_id,
            "tool_name": "searchSymbol",
            "params": {"query": query, "limit": limit, "exchange": exchange},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "`query` is required and must be a non-empty string.")

    lim = 50 if limit is None else _coerce_int_like(limit)
    if lim is None or lim < 1 or lim > 1000:
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": key_id,
            "tool_name": "searchSymbol",
            "params": {"query": query, "limit": limit, "exchange": exchange},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "`limit` must be an integer between 1 and 1000.")

    ex = None
    if exchange is not None:
        if not isinstance(exchange, str) or not exchange.strip():
            duration_ms = max(0, int((time.time() - start) * 1000))
            logs.append({
                "id": _mk_log_id(),
                "api_key_id": key_id,
                "tool_name": "searchSymbol",
                "params": {"query": query, "limit": limit, "exchange": exchange},
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": now,
                "updated_at": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "`exchange` must be a non-empty string when provided.")
        ex = exchange.strip()

    # Authorization constraints from api_keys allowlists
    allowed_exchanges = used_key.get("allowed_exchanges")
    allowed_asset_types = used_key.get("allowed_asset_types")

    q_symbol = _normalize_symbol(query)
    q_text = _normalize_text(query)

    matches = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        sym = inst.get("normalized_symbol")
        name = inst.get("name")
        inst_ex = inst.get("exchange")

        if not isinstance(sym, str) or not sym:
            continue
        if not isinstance(name, str) or not name:
            name = ""

        # exchange filter
        if ex is not None:
            if inst_ex != ex:
                continue

        # key allowlist restrictions
        if isinstance(allowed_exchanges, list):
            if inst_ex is None or inst_ex not in allowed_exchanges:
                continue
        if isinstance(allowed_asset_types, list):
            if inst.get("asset_type") not in allowed_asset_types:
                continue

        # match by symbol prefix/contains or name contains
        name_norm = _normalize_text(name) if name else ""
        if sym.startswith(q_symbol) or (q_symbol and q_symbol in sym) or (q_text and q_text in name_norm):
            matches.append({
                "symbol": inst.get("symbol"),
                "name": inst.get("name"),
                "exchange": inst.get("exchange"),
                "assetType": inst.get("asset_type"),
                "currency": inst.get("currency"),
                "country": inst.get("country")
            })

    # sort: prefer symbol startswith, then symbol, then name
    def _rank(row):
        s = row.get("symbol") or ""
        ns = _normalize_symbol(s)
        starts = 1 if ns.startswith(q_symbol) else 0
        return (-starts, ns, (row.get("name") or "").lower())

    matches.sort(key=_rank)
    out = matches[:lim]

    # Update key last_used_at on successful authenticated request
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    duration_ms = max(0, int((time.time() - start) * 1000))
    logs.append({
        "id": _mk_log_id(),
        "api_key_id": key_id,
        "tool_name": "searchSymbol",
        "params": {"query": query, "limit": lim, "exchange": exchange},
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(out),
        "error_code": None,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", logs)

    return {"data": out, "meta": {"limit": lim, "count": len(out)}}

