            "api_key_id": key_id,
            "tool_name": "searchCIK",
            "params": {"cik": cik, "limit": limit},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "`limit` must be an integer between 1 and 1000.")

    cik_norm_full = _norm_cik(cik)
    if not cik_norm_full:
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": key_id,
            "tool_name": "searchCIK",
            "params": {"cik": cik, "limit": lim},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "`cik` must contain at least one digit.")

    # Allow prefix search: compare against digit-only, left padded stored
    # We'll match on stored cik digits (normalized) starting with provided digits (unpadded).
    cik_digits = re.sub(r"\D", "", cik.strip())
    out = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        stored = e.get("cik")
        if not isinstance(stored, str) or not stored.strip():
            continue
        stored_norm = _norm_cik(stored)
        if stored_norm.startswith(cik_digits.zfill(min(10, len(cik_digits))).lstrip("0") or cik_digits) or stored_norm.startswith(cik_digits.zfill(10)) or stored_norm.startswith(cik_digits):
            # associated symbols (best-effort)
            syms = []
            eid = e.get("id")
            if eid:
                for inst in instruments:
                    if isinstance(inst, dict) and inst.get("entity_id") == eid and isinstance(inst.get("symbol"), str):
                        syms.append(inst.get("symbol"))
            # de-dup preserve order
            seen = set()
            assoc = []
            for s in syms:
                if s not in seen:
                    seen.add(s)
                    assoc.append(s)
            out.append({
                "id": e.get("id"),
                "entityType": e.get("entity_type"),
                "name": e.get("name"),
                "cik": _norm_cik(e.get("cik")) if isinstance(e.get("cik"), str) else None,
                "country": e.get("country"),
                "status": e.get("status"),
                "symbols": assoc
            })

    out.sort(key=lambda r: (r.get("cik") or "", (r.get("name") or "").lower()))
    out = out[:lim]

    # For this tool, description says NOT_FOUND if none
    if not out:
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": key_id,
            "tool_name": "searchCIK",
            "params": {"cik": cik, "limit": lim},
            "http_status": 404,
            "cache_status": "miss",
            "duration_ms": duration_ms,
            "result_count": 0,
            "error_code": "NOT_FOUND",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "No registrant matches the provided CIK.")

    # Update key usage
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    duration_ms = max(0, int((time.time() - start) * 1000))
    logs.append({
        "id": _mk_log_id(),
        "api_key_id": key_id,
        "tool_name": "searchCIK",
        "params": {"cik": cik, "limit": lim},
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(out),
        "error_code": None,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", logs)

    return {"data": out, "meta": {"limit": lim, "count": len(out)}}

def searchCUSIP(cusip, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mk_log_id():
        return "rlog_" + uuid.uuid4().hex

    def _pick_active_key(api_keys):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    api_keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    instruments = _load("instruments.json")
    content_items = _load("content_items.json")

    used_key = _pick_active_key(api_keys)
    if not used_key:
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": (api_keys[0].get("id") if api_keys and isinstance(api_keys[0], dict) else "unknown"),
            "tool_name": "searchCUSIP",
            "params": {"cusip": cusip},
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key is missing or not active.")

    # Quota
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1]) if s.endswith("Z") else datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    key_id = used_key.get("id")
    minute_quota = used_key.get("minute_request_quota", 0)
    daily_quota = used_key.get("daily_request_quota", 0)

    minute_count = 0
    daily_count = 0
    for r in logs:
        if not isinstance(r, dict) or r.get("api_key_id") != key_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt:
            continue
        if dt >= minute_ago:
            minute_count += 1
        if dt >= day_ago:
            daily_count += 1

    if (isinstance(minute_quota, int) and minute_quota >= 0 and (minute_count + 1) > minute_quota) or \
       (isinstance(daily_quota, int) and daily_quota >= 0 and (daily_count + 1) > daily_quota):
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": key_id,
            "tool_name": "searchCUSIP",
            "params": {"cusip": cusip},
            "http_status": 429,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "RATE_LIMIT",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate
    if not isinstance(cusip, str) or not cusip.strip():
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": key_id,
            "tool_name": "searchCUSIP",
            "params": {"cusip": cusip},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "`cusip` is required and must be a non-empty string.")

    # Normalize: CUSIP typically 9 chars; allow partial? tool says "CUSIP number"; treat as exact after stripping spaces.
    c = re.sub(r"\s+", "", cusip.strip()).upper()

    allowed_exchanges = used_key.get("allowed_exchanges")
    allowed_asset_types = used_key.get("allowed_asset_types")

    # Find matches in content_items payloads (generic storage). We search common locations:
    # - content_items.identifier_1 == cusip (when used as CUSIP slot)
    # - payload contains keys: 'cusip', 'CUSIP', 'cusipNumber', 'cusipNo'
    matched_instrument_ids = set()
    for ci in content_items:
        if not isinstance(ci, dict) or ci.get("status") == "deleted":
            continue
        if isinstance(ci.get("identifier_1"), str) and ci.get("identifier_1").strip().upper() == c:
            iid = ci.get("instrument_id")
            if isinstance(iid, str) and iid:
                matched_instrument_ids.add(iid)
        payload = ci.get("payload")
        if isinstance(payload, dict):
            for k in ("cusip", "CUSIP", "cusipNumber", "cusipNo"):
                v = payload.get(k)
                if isinstance(v, str) and re.sub(r"\s+", "", v.strip()).upper() == c:
                    iid = ci.get("instrument_id")
                    if isinstance(iid, str) and iid:
                        matched_instrument_ids.add(iid)
            # sometimes lists inside payload
            if "holdings" in payload and isinstance(payload.get("holdings"), list):
                for h in payload.get("holdings"):
                    if isinstance(h, dict):
                        v = h.get("cusip") or h.get("CUSIP")
                        if isinstance(v, str) and re.sub(r"\s+", "", v.strip()).upper() == c:
                            iid = ci.get("instrument_id")
                            if isinstance(iid, str) and iid:
                                matched_instrument_ids.add(iid)

    results = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("id") not in matched_instrument_ids:
            continue

        inst_ex = inst.get("exchange")
        if isinstance(allowed_exchanges, list):
            if inst_ex is None or inst_ex not in allowed_exchanges:
                continue
        if isinstance(allowed_asset_types, list):
            if inst.get("asset_type") not in allowed_asset_types:
                continue

        results.append({
            "cusip": c,
            "symbol": inst.get("symbol"),
            "name": inst.get("name"),
            "exchange": inst.get("exchange"),
            "assetType": inst.get("asset_type"),
            "currency": inst.get("currency"),
            "country": inst.get("country")
        })

    results.sort(key=lambda r: ((r.get("symbol") or "").upper(), (r.get("exchange") or "")))

    if not results:
        duration_ms = max(0, int((time.time() - start) * 1000))
        logs.append({
            "id": _mk_log_id(),
            "api_key_id": key_id,
            "tool_name": "searchCUSIP",
            "params": {"cusip": cusip},
            "http_status": 404,
            "cache_status": "miss",
            "duration_ms": duration_ms,
            "result_count": 0,
            "error_code": "NOT_FOUND",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "The provided CUSIP does not exist in our catalog.")

    # Update key usage
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    duration_ms = max(0, int((time.time() - start) * 1000))
    logs.append({
        "id": _mk_log_id(),
        "api_key_id": key_id,
        "tool_name": "searchCUSIP",
        "params": {"cusip": cusip},
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(results),
        "error_code": None,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", logs)

    return {"data": results, "meta": {"count": len(results)}}

def searchISIN(isin, **_extra):
    import json, os, datetime, time, hashlib, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        rid = "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
        ts = _now_iso()
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _select_active_key():
        keys = _load("api_keys.json")
        # Ambient auth: choose any active key that can serve the call.
        for k in keys:
            if k.get("status") == "active":
                return k
        return None

    def _enforce_quota(api_key_row):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        aid = api_key_row.get("id")
        m = 0
        d = 0
        for r in logs:
            if r.get("api_key_id") != aid:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= minute_ago:
                m += 1
            if ts >= day_ago:
                d += 1

        min_q = api_key_row.get("minute_request_quota")
        day_q = api_key_row.get("daily_request_quota")
        if not isinstance(min_q, int) or min_q < 0:
            min_q = 0
        if not isinstance(day_q, int) or day_q < 0:
            day_q = 0

        # "would exceed" => block when already at or above quota
        if min_q == 0 or m >= min_q:
            return _err("RATE_LIMIT", "Minute request quota exceeded.")
        if day_q == 0 or d >= day_q:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    # Validate params (no additionalProperties already enforced by signature)
    params = {"isin": isin}
    if not isinstance(isin, str) or not isin.strip():
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "searchISIN", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`isin` is required and must be a non-empty string.")

    isin_norm = isin.strip().upper()
    # Basic ISIN format: 2 letters + 9 alnum + 1 digit (check digit). Be permissive but validate shape.
    if not re.fullmatch(r"[A-Z]{2}[A-Z0-9]{9}[0-9]", isin_norm):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "searchISIN", {"isin": isin_norm}, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`isin` must be a valid ISIN string (e.g., US0378331005).")

    api_key_row = _select_active_key()
    if not api_key_row:
        duration_ms = int((time.time() - start) * 1000)
        _log_request("unauthorized", "searchISIN", {"isin": isin_norm}, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    quota_err = _enforce_quota(api_key_row)
    if quota_err:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_row["id"], "searchISIN", {"isin": isin_norm}, 429, "bypass", duration_ms, result_count=None, error_code=quota_err["error"]["code"])
        return quota_err

    # Authorization allowlists (asset/exchange) apply at read-time if present.
    allowed_ex = api_key_row.get("allowed_exchanges")
    allowed_at = api_key_row.get("allowed_asset_types")
    if allowed_ex is not None and not isinstance(allowed_ex, list):
        allowed_ex = None
    if allowed_at is not None and not isinstance(allowed_at, list):
        allowed_at = None

    content = _load("content_items.json")
    instruments = _load("instruments.json")
    inst_by_id = {i.get("id"): i for i in instruments if isinstance(i, dict) and i.get("id")}

    matches = []
    for ci in content:
        if not isinstance(ci, dict):
            continue
        # ISIN stored in identifier slots by rule-of-thumb
        if (ci.get("identifier_1") or "").strip().upper() != isin_norm and (ci.get("identifier_2") or "").strip().upper() != isin_norm:
            # also allow payload.isin
            payload = ci.get("payload")
            if not (isinstance(payload, dict) and (payload.get("isin") or "").strip().upper() == isin_norm):
                continue

        inst_id = ci.get("instrument_id")
        inst = inst_by_id.get(inst_id) if inst_id else None
        if not inst:
            continue

        if allowed_ex is not None:
            ex = inst.get("exchange")
            if ex not in allowed_ex:
                continue
        if allowed_at is not None:
            at = inst.get("asset_type")
            if at not in allowed_at:
                continue

        payload = ci.get("payload") if isinstance(ci.get("payload"), dict) else {}
        matches.append(
            {
                "isin": isin_norm,
                "symbol": inst.get("symbol"),
                "name": inst.get("name"),
                "assetType": inst.get("asset_type"),
                "exchange": inst.get("exchange"),
                "currency": inst.get("currency"),
                "country": inst.get("country"),
                "instrumentId": inst.get("id"),
                "entityId": inst.get("entity_id"),
                "sourceContentType": ci.get("content_type"),
                "reference": {
                    "identifier_1": ci.get("identifier_1"),
                    "identifier_2": ci.get("identifier_2"),
                    "url": ci.get("url"),
                    "title": ci.get("title"),
                },
                "payload": payload,
            }
        )

    # Deduplicate by instrument id + ISIN
    seen = set()
    uniq = []
    for m in matches:
        key = (m.get("instrumentId"), m.get("isin"))
        if key in seen:
            continue
        seen.add(key)
        uniq.append(m)

    if not uniq:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_row["id"], "searchISIN", {"isin": isin_norm}, 404, "miss", duration_ms, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "ISIN not found in catalog.")

    # Update last_used_at on success
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - start) * 1000)
    _log_request(api_key_row["id"], "searchISIN", {"isin": isin_norm}, 200, "miss", duration_ms, result_count=len(uniq), error_code=None)
    return {"data": uniq, "meta": {"result_count": len(uniq)}}

