        min_q = api_key_row.get("minute_request_quota")
        day_q = api_key_row.get("daily_request_quota")
        if not isinstance(min_q, int) or min_q < 0:
            min_q = 0
        if not isinstance(day_q, int) or day_q < 0:
            day_q = 0

        if min_q == 0 or m >= min_q:
            return _err("RATE_LIMIT", "Minute request quota exceeded.")
        if day_q == 0 or d >= day_q:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    # Validate inputs; additionalProperties enforced by signature
    params = {
        "marketCapMoreThan": marketCapMoreThan,
        "marketCapLowerThan": marketCapLowerThan,
        "sector": sector,
        "industry": industry,
        "betaMoreThan": betaMoreThan,
        "betaLowerThan": betaLowerThan,
        "priceMoreThan": priceMoreThan,
        "priceLowerThan": priceLowerThan,
        "dividendMoreThan": dividendMoreThan,
        "dividendLowerThan": dividendLowerThan,
        "volumeMoreThan": volumeMoreThan,
        "volumeLowerThan": volumeLowerThan,
        "exchange": exchange,
        "country": country,
        "isEtf": isEtf,
        "isFund": isFund,
        "isActivelyTrading": isActivelyTrading,
        "limit": limit,
        "includeAllShareClasses": includeAllShareClasses,
    }

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    for k in ["marketCapMoreThan", "marketCapLowerThan", "betaMoreThan", "betaLowerThan", "priceMoreThan", "priceLowerThan", "dividendMoreThan", "dividendLowerThan", "volumeMoreThan", "volumeLowerThan"]:
        v = params[k]
        if v is not None and not _is_num(v):
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"`{k}` must be a number when provided.")

    if sector is not None and not isinstance(sector, str):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`sector` must be a string when provided.")
    if industry is not None and not isinstance(industry, str):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`industry` must be a string when provided.")
    if exchange is not None and not isinstance(exchange, str):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`exchange` must be a string when provided.")
    if country is not None and not isinstance(country, str):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`country` must be a string when provided.")
    for k in ["isEtf", "isFund", "isActivelyTrading", "includeAllShareClasses"]:
        v = params[k]
        if v is not None and not isinstance(v, bool):
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"`{k}` must be a boolean when provided.")

    # limit: service style, cap at 1000 for screener
    default_limit = 100
    max_limit = 1000
    if limit is None:
        lim = default_limit
    else:
        if not _is_num(limit):
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`limit` must be a number when provided.")
        lim = int(limit)
        if lim < 0:
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`limit` must be >= 0.")
        if lim > max_limit:
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "stockScreener", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"`limit` must be <= {max_limit}.")

    api_key_row = _select_active_key()
    if not api_key_row:
        duration_ms = int((time.time() - start) * 1000)
        _log_request("unauthorized", "stockScreener", params, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    quota_err = _enforce_quota(api_key_row)
    if quota_err:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_row["id"], "stockScreener", params, 429, "bypass", duration_ms, result_count=None, error_code=quota_err["error"]["code"])
        return quota_err

    allowed_ex = api_key_row.get("allowed_exchanges")
    allowed_at = api_key_row.get("allowed_asset_types")
    if allowed_ex is not None and not isinstance(allowed_ex, list):
        allowed_ex = None
    if allowed_at is not None and not isinstance(allowed_at, list):
        allowed_at = None

    include_all = True if includeAllShareClasses is None else bool(includeAllShareClasses)

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")
    content = _load("content_items.json")

    # Latest regular unadjusted 1day snapshots (for price/volume and quote-like fields)
    latest_by_inst = {}
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("is_latest_snapshot") is not True:
            continue
        if r.get("timeframe") != "1day" or r.get("adjustment_type") != "unadjusted" or r.get("session") != "regular":
            continue
        iid = r.get("instrument_id")
        if iid and iid not in latest_by_inst:
            latest_by_inst[iid] = r

    # Ratios/Key metrics snapshots: take latest by updated_at for each instrument
    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    km_latest = {}
    ratios_latest = {}
    for ci in content:
        if not isinstance(ci, dict):
            continue
        if ci.get("status") != "active":
            continue
        iid = ci.get("instrument_id")
        if not iid:
            continue
        ct = ci.get("content_type")
        if ct not in ("key_metrics", "ratios"):
            continue
        ts = _parse_iso(ci.get("updated_at")) or _parse_iso(ci.get("created_at")) or datetime.datetime.min
        target = km_latest if ct == "key_metrics" else ratios_latest
        prev = target.get(iid)
        prev_ts = _parse_iso(prev.get("updated_at")) if isinstance(prev, dict) else None
        prev_ts = prev_ts or (_parse_iso(prev.get("created_at")) if isinstance(prev, dict) else None) or datetime.datetime.min
        if prev is None or ts >= prev_ts:
            target[iid] = ci

    def _get_num_from_payload(ci, keys):
        if not isinstance(ci, dict):
            return None
        payload = ci.get("payload")
        if not isinstance(payload, dict):
            return None
        for k in keys:
            v = payload.get(k)
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                return float(v)
        return None

    out = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        # Share class filter
        if not include_all and inst.get("primary_listing_symbol_id") is not None:
            continue

        # Key allowlists
        if allowed_ex is not None:
            ex = inst.get("exchange")
            if ex not in allowed_ex:
                continue
        if allowed_at is not None:
            at = inst.get("asset_type")
            if at not in allowed_at:
                continue

        # Categorical filters
        if exchange is not None and inst.get("exchange") != exchange:
            continue
        if country is not None and inst.get("country") != country:
            continue
        if sector is not None and inst.get("sector") != sector:
            continue
        if industry is not None and inst.get("industry") != industry:
            continue
        if isEtf is not None and inst.get("is_etf") is not bool(isEtf):
            continue
        if isFund is not None and inst.get("is_fund") is not bool(isFund):
            continue
        if isActivelyTrading is not None and inst.get("is_actively_trading") is not bool(isActivelyTrading):
            continue

        # Numerical filters via joins
        md = latest_by_inst.get(inst.get("id"))
        km = km_latest.get(inst.get("id"))
        ratios = ratios_latest.get(inst.get("id"))

        # price, volume from latest snapshot
        price = None
        volume = None
        if isinstance(md, dict):
            if isinstance(md.get("close"), (int, float)) and not isinstance(md.get("close"), bool):
                price = float(md.get("close"))
            if isinstance(md.get("volume"), (int, float)) and not isinstance(md.get("volume"), bool):
                volume = float(md.get("volume"))

        # marketCap, dividend, beta from key_metrics/ratios payloads where possible
        market_cap = _get_num_from_payload(km, ["marketCap", "market_cap", "marketCapitalization"])
        dividend = _get_num_from_payload(km, ["dividend", "dividendPerShare", "dividend_per_share", "dividendYield", "dividend_yield"])
        beta = _get_num_from_payload(ratios, ["beta"])

        # Apply numeric constraints; if value missing, treat as non-match when constraint present
        def _apply_range(val, lo, hi):
            if lo is None and hi is None:
                return True
            if val is None:
                return False
            if lo is not None and val <= float(lo):
                return False
            if hi is not None and val >= float(hi):
                return False
            return True

        if not _apply_range(market_cap, marketCapMoreThan, marketCapLowerThan):
            continue
        if not _apply_range(beta, betaMoreThan, betaLowerThan):
            continue
        if not _apply_range(price, priceMoreThan, priceLowerThan):
            continue
        if not _apply_range(dividend, dividendMoreThan, dividendLowerThan):
            continue
        if not _apply_range(volume, volumeMoreThan, volumeLowerThan):
            continue

        out.append(
            {
                "symbol": inst.get("symbol"),
                "name": inst.get("name"),
                "exchange": inst.get("exchange"),
                "assetType": inst.get("asset_type"),
                "country": inst.get("country"),
                "sector": inst.get("sector"),
                "industry": inst.get("industry"),
                "isEtf": inst.get("is_etf"),
                "isFund": inst.get("is_fund"),
                "isActivelyTrading": inst.get("is_actively_trading"),
                "isDelisted": inst.get("is_delisted"),
                "status": inst.get("status"),
                "price": price,
                "volume": volume,
                "marketCap": market_cap,
                "beta": beta,
                "dividend": dividend,
                "instrumentId": inst.get("id"),
                "entityId": inst.get("entity_id"),
                "updatedAt": inst.get("updated_at"),
            }
        )
        if lim and len(out) >= lim:
            break

    # Update last_used_at on success
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - start) * 1000)
    _log_request(api_key_row["id"], "stockScreener", params, 200, "miss", duration_ms, result_count=len(out), error_code=None)
    return {"data": out, "meta": {"result_count": len(out), "limit": lim}}

def searchExchangeVariants(symbol, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        rid = "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
        ts = _now_iso()
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _select_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("status") == "active":
                return k
        return None

    def _enforce_quota(api_key_row):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        aid = api_key_row.get("id")
        m = 0
        d = 0
        for r in logs:
            if r.get("api_key_id") != aid:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= minute_ago:
                m += 1
            if ts >= day_ago:
                d += 1

        min_q = api_key_row.get("minute_request_quota")
        day_q = api_key_row.get("daily_request_quota")
        if not isinstance(min_q, int) or min_q < 0:
            min_q = 0
        if not isinstance(day_q, int) or day_q < 0:
            day_q = 0

        if min_q == 0 or m >= min_q:
            return _err("RATE_LIMIT", "Minute request quota exceeded.")
        if day_q == 0 or d >= day_q:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    params = {"symbol": symbol}
    if not isinstance(symbol, str) or not symbol.strip():
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "searchExchangeVariants", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`symbol` is required and must be a non-empty string.")

    sym_norm = symbol.strip().upper()

    api_key_row = _select_active_key()
    if not api_key_row:
        duration_ms = int((time.time() - start) * 1000)
        _log_request("unauthorized", "searchExchangeVariants", {"symbol": sym_norm}, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    quota_err = _enforce_quota(api_key_row)
    if quota_err:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_row["id"], "searchExchangeVariants", {"symbol": sym_norm}, 429, "bypass", duration_ms, result_count=None, error_code=quota_err["error"]["code"])
        return quota_err

    allowed_ex = api_key_row.get("allowed_exchanges")
    allowed_at = api_key_row.get("allowed_asset_types")
    if allowed_ex is not None and not isinstance(allowed_ex, list):
        allowed_ex = None
    if allowed_at is not None and not isinstance(allowed_at, list):
        allowed_at = None

    instruments = _load("instruments.json")

    base_matches = [i for i in instruments if isinstance(i, dict) and i.get("normalized_symbol") == sym_norm]
    if allowed_ex is not None:
        base_matches = [i for i in base_matches if i.get("exchange") in allowed_ex]
    if allowed_at is not None:
        base_matches = [i for i in base_matches if i.get("asset_type") in allowed_at]

    if not base_matches:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_row["id"], "searchExchangeVariants", {"symbol": sym_norm}, 404, "miss", duration_ms, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Symbol not found in catalog.")

    # Determine family root(s): if instrument has primary_listing_symbol_id, use that; else itself is root
    roots = set()
    by_id = {i.get("id"): i for i in instruments if isinstance(i, dict) and i.get("id")}
    for b in base_matches:
        rid = b.get("primary_listing_symbol_id") or b.get("id")
        if rid:
            roots.add(rid)

    variants = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        iid = inst.get("id")
        if not iid:
            continue
        root = inst.get("primary_listing_symbol_id") or iid
        if root not in roots:
            continue
        if allowed_ex is not None and inst.get("exchange") not in allowed_ex:
            continue
        if allowed_at is not None and inst.get("asset_type") not in allowed_at:
            continue
        variants.append(
            {
                "symbol": inst.get("symbol"),
                "exchange": inst.get("exchange"),
                "assetType": inst.get("asset_type"),
                "name": inst.get("name"),
                "country": inst.get("country"),
                "currency": inst.get("currency"),
                "instrumentId": inst.get("id"),
                "primaryListingInstrumentId": inst.get("primary_listing_symbol_id") or inst.get("id"),
                "shareClassCode": inst.get("share_class_code"),
                "status": inst.get("status"),
            }
        )

    # Remove the base symbol itself? FMP typically returns set including primary; keep all but ensure unique by instrumentId
    uniq = []
    seen = set()
    for v in variants:
        if v["instrumentId"] in seen:
            continue
        seen.add(v["instrumentId"])
        uniq.append(v)

    if len(uniq) <= 1:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_row["id"], "searchExchangeVariants", {"symbol": sym_norm}, 404, "miss", duration_ms, result_count=len(uniq), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No exchange variants found for symbol.")

    # Update last_used_at on success
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - start) * 1000)
    _log_request(api_key_row["id"], "searchExchangeVariants", {"symbol": sym_norm}, 200, "miss", duration_ms, result_count=len(uniq), error_code=None)
    return {"data": uniq, "meta": {"result_count": len(uniq)}}

