        "status": status,
        "limit": limit,
        "cursor": cursor,
        "sort": sort,
        "order": order,
    }

    # Validate
    if exchange is not None and not isinstance(exchange, str):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`exchange` must be a string when provided.")
    if country is not None and not isinstance(country, str):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`country` must be a string when provided.")
    if isActivelyTrading is not None and not isinstance(isActivelyTrading, bool):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`isActivelyTrading` must be a boolean when provided.")
    if isDelisted is not None and not isinstance(isDelisted, bool):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`isDelisted` must be a boolean when provided.")

    asset_enum = {"equity", "etf", "mutual_fund", "index", "crypto", "forex", "commodity", "note"}
    if assetType is not None:
        if not isinstance(assetType, str) or assetType not in asset_enum:
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`assetType` must be one of the allowed values.")

    status_enum = {"active", "inactive", "delisted"}
    if status is not None:
        if not isinstance(status, str) or status not in status_enum:
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`status` must be one of: active, inactive, delisted.")

    sort_enum = {"symbol", "name", "exchange", "assetType", "updatedAt"}
    if sort is not None:
        if not isinstance(sort, str) or sort not in sort_enum:
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`sort` must be one of: symbol, name, exchange, assetType, updatedAt.")
    if order is not None:
        if not isinstance(order, str) or order not in {"asc", "desc"}:
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`order` must be 'asc' or 'desc'.")
    if cursor is not None and not isinstance(cursor, str):
        api_key_row = _select_active_key()
        api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`cursor` must be a string when provided.")

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    default_limit = 100
    max_limit = 5000
    if limit is None:
        lim = default_limit
    else:
        if not _is_num(limit):
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`limit` must be a number when provided.")
        lim = int(limit)
        if lim < 0:
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`limit` must be >= 0.")
        if lim > max_limit:
            api_key_row = _select_active_key()
            api_key_id = api_key_row["id"] if api_key_row else "unauthorized"
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"`limit` must be <= {max_limit}.")

    api_key_row = _select_active_key()
    if not api_key_row:
        duration_ms = int((time.time() - start) * 1000)
        _log_request("unauthorized", "getCompanySymbols", params, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    quota_err = _enforce_quota(api_key_row)
    if quota_err:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_row["id"], "getCompanySymbols", params, 429, "bypass", duration_ms, result_count=None, error_code=quota_err["error"]["code"])
        return quota_err

    allowed_ex = api_key_row.get("allowed_exchanges")
    allowed_at = api_key_row.get("allowed_asset_types")
    if allowed_ex is not None and not isinstance(allowed_ex, list):
        allowed_ex = None
    if allowed_at is not None and not isinstance(allowed_at, list):
        allowed_at = None

    instruments = _load("instruments.json")

    # Filter
    rows = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if exchange is not None and inst.get("exchange") != exchange:
            continue
        if assetType is not None and inst.get("asset_type") != assetType:
            continue
        if country is not None and inst.get("country") != country:
            continue
        if isActivelyTrading is not None and inst.get("is_actively_trading") is not bool(isActivelyTrading):
            continue
        if isDelisted is not None and inst.get("is_delisted") is not bool(isDelisted):
            continue
        if status is not None and inst.get("status") != status:
            continue

        if allowed_ex is not None:
            ex = inst.get("exchange")
            if ex not in allowed_ex:
                continue
        if allowed_at is not None:
            at = inst.get("asset_type")
            if at not in allowed_at:
                continue

        rows.append(inst)

    # Sort
    sf = sort or "symbol"
    od = order or "asc"

    def _key(inst):
        if sf == "symbol":
            return (inst.get("normalized_symbol") or "", inst.get("exchange") or "", inst.get("id") or "")
        if sf == "name":
            return (inst.get("name") or "", inst.get("normalized_symbol") or "", inst.get("id") or "")
        if sf == "exchange":
            return (inst.get("exchange") or "", inst.get("normalized_symbol") or "", inst.get("id") or "")
        if sf == "assetType":
            return (inst.get("asset_type") or "", inst.get("normalized_symbol") or "", inst.get("id") or "")
        if sf == "updatedAt":
            return (inst.get("updated_at") or "", inst.get("id") or "")
        return (inst.get("normalized_symbol") or "", inst.get("id") or "")

    rows.sort(key=_key, reverse=(od == "desc"))

    # Cursor: opaque base64 of integer offset
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            decoded = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8", "strict")
            if not decoded.startswith("o:"):
                raise ValueError("bad cursor")
            offset = int(decoded.split(":", 1)[1])
            if offset < 0:
                offset = 0
        except Exception:
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_row["id"], "getCompanySymbols", params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = rows[offset: offset + lim]
    next_cursor = None
    if offset + lim < len(rows):
        next_cursor = base64.urlsafe_b64encode(f"o:{offset + lim}".encode("utf-8")).decode("ascii").rstrip("=")

    data = []
    for inst in page:
        data.append(
            {
                "symbol": inst.get("symbol"),
                "name": inst.get("name"),
                "exchange": inst.get("exchange"),
                "assetType": inst.get("asset_type"),
                "country": inst.get("country"),
                "currency": inst.get("currency"),
                "isActivelyTrading": inst.get("is_actively_trading"),
                "isDelisted": inst.get("is_delisted"),
                "status": inst.get("status"),
                "instrumentId": inst.get("id"),
                "entityId": inst.get("entity_id"),
                "updatedAt": inst.get("updated_at"),
            }
        )

    # Update last_used_at on success
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - start) * 1000)
    _log_request(api_key_row["id"], "getCompanySymbols", params, 200, "miss", duration_ms, result_count=len(data), error_code=None)
    return {
        "data": data,
        "meta": {
            "total": len(rows),
            "limit": lim,
            "has_more": (next_cursor is not None),
            "next_cursor": next_cursor,
            "cursor": next_cursor,
            "offset": offset,
            "sort": sf,
            "order": od,
        },
    }

def getFinancialStatementSymbols(exchange=None, sector=None, industry=None, country=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- validate inputs (schema: additionalProperties=false enforced by signature) ---
    if exchange is not None and not isinstance(exchange, str):
        return _err("VALIDATION_ERROR", "exchange must be a string")
    if sector is not None and not isinstance(sector, str):
        return _err("VALIDATION_ERROR", "sector must be a string")
    if industry is not None and not isinstance(industry, str):
        return _err("VALIDATION_ERROR", "industry must be a string")
    if country is not None and not isinstance(country, str):
        return _err("VALIDATION_ERROR", "country must be a string")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "inactive", "delisted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive, delisted")
    if limit is None:
        limit = 100
    if not isinstance(limit, (int, float)) or isinstance(limit, bool):
        return _err("VALIDATION_ERROR", "limit must be a number")
    limit = int(limit)
    if limit < 0:
        return _err("VALIDATION_ERROR", "limit must be >= 0")
    # server-side max
    if limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be <= 1000")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "symbol"
    if not isinstance(sort, str) or sort not in ("symbol", "name", "exchange", "updatedAt"):
        return _err("VALIDATION_ERROR", "sort must be one of: symbol, name, exchange, updatedAt")
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # --- auth / quota selection (ambient) ---
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _parse_iso_z(s):
        try:
            if not isinstance(s, str):
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256((now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]

    def _log(api_key_id, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": "getFinancialStatementSymbols",
            "params": {
                "exchange": exchange,
                "sector": sector,
                "industry": industry,
                "country": country,
                "status": status,
                "limit": limit,
                "cursor": cursor,
                "sort": sort,
                "order": order,
            },
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count,
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    def _eligible_key():
        # choose any active key that is not over quota; if none, decide whether UNAUTHORIZED vs QUOTA_EXCEEDED
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, "UNAUTHORIZED"
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        one_day_ago = now_dt - datetime.timedelta(days=1)

        # Precompute logs by key in rolling windows
        logs = request_logs if isinstance(request_logs, list) else []
        per_key_min = {}
        per_key_day = {}
        in_flight = {}  # best-effort: count very recent requests as in-flight; no explicit completion state exists
        for r in logs:
            if not isinstance(r, dict):
                continue
            kid = r.get("api_key_id")
            ts = _parse_iso_z(r.get("created_at"))
            if kid is None or ts is None:
                continue
            if ts >= one_day_ago:
                per_key_day[kid] = per_key_day.get(kid, 0) + 1
            if ts >= one_min_ago:
                per_key_min[kid] = per_key_min.get(kid, 0) + 1
            # in-flight approximation: last 2 seconds
            if ts >= (now_dt - datetime.timedelta(seconds=2)):
                in_flight[kid] = in_flight.get(kid, 0) + 1

        any_over_quota = False
        for k in active:
            kid = k.get("id")
            if not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            conc = k.get("concurrency_limit")
            if not isinstance(min_q, int) or min_q < 0 or not isinstance(day_q, int) or day_q < 0 or not isinstance(conc, int) or conc < 0:
                continue
            if in_flight.get(kid, 0) >= conc and conc != 0:
                # treat as rate limit
                any_over_quota = True
                continue
            if per_key_min.get(kid, 0) >= min_q and min_q != 0:
                any_over_quota = True
                continue
            if per_key_day.get(kid, 0) >= day_q and day_q != 0:
                any_over_quota = True
                continue
            return k, None
        return None, ("QUOTA_EXCEEDED" if any_over_quota else "UNAUTHORIZED")

    key, auth_err = _eligible_key()
    if key is None:
        # log attempt with 401/429 based on reason
        duration_ms = (time.time() - t0) * 1000
        if auth_err == "QUOTA_EXCEEDED":
            _log("unknown", 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Request quota exceeded")
        _log("unknown", 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing, invalid, or inactive API key")

    # --- cursor decoding ---
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("tool") != "getFinancialStatementSymbols":
                raise ValueError("bad cursor")
            offset = obj.get("offset", 0)
            if not isinstance(offset, int) or offset < 0:
                raise ValueError("bad offset")
            # enforce that cursor is tied to the same filters to be "opaque"
            expected = {
                "exchange": exchange, "sector": sector, "industry": industry, "country": country,
                "status": status, "sort": sort, "order": order
            }
            if obj.get("q") != expected:
                raise ValueError("cursor does not match query")
        except Exception:
            duration_ms = (time.time() - t0) * 1000
            _log(key.get("id"), 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed cursor")

    # --- compute result set: instruments that have financial_statement coverage ---
    instruments = _load("instruments.json")
    content_items = _load("content_items.json")

    covered_instrument_ids = set()
    for ci in content_items:
        if not isinstance(ci, dict):
            continue
        if ci.get("status") != "active":
            continue
        if ci.get("content_type") != "financial_statement":
            continue
        iid = ci.get("instrument_id")
        if isinstance(iid, str) and iid:
            covered_instrument_ids.add(iid)

    rows = []
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        if ins.get("id") not in covered_instrument_ids:
            continue
        if exchange is not None and ins.get("exchange") != exchange:
            continue
        if sector is not None and ins.get("sector") != sector:
            continue
        if industry is not None and ins.get("industry") != industry:
            continue
        if country is not None and ins.get("country") != country:
            continue
        if status is not None and ins.get("status") != status:
            continue

        rows.append({
            "id": ins.get("id"),
            "symbol": ins.get("symbol"),
            "name": ins.get("name"),
            "exchange": ins.get("exchange"),
            "assetType": ins.get("asset_type"),
            "country": ins.get("country"),
            "sector": ins.get("sector"),
            "industry": ins.get("industry"),
            "status": ins.get("status"),
            "updatedAt": ins.get("updated_at"),
        })

    # --- sorting ---
    def _sort_key(r):
        v = r.get(sort if sort != "updatedAt" else "updatedAt")
        if v is None:
            return ""
        return v

    rows.sort(key=_sort_key, reverse=(order == "desc"))

    # --- page by cursor offset ---
    page_rows = rows[offset: offset + limit]
    next_cursor = None
    if offset + limit < len(rows):
        obj = {
            "v": 1,
            "tool": "getFinancialStatementSymbols",
            "offset": offset + limit,
            "q": {
                "exchange": exchange, "sector": sector, "industry": industry, "country": country,
                "status": status, "sort": sort, "order": order
            }
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    # update key last_used_at on success
    kid = key.get("id")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == kid:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    duration_ms = (time.time() - t0) * 1000
    _log(kid, 200, "miss", duration_ms, result_count=len(page_rows), error_code=None)

    return {
        "data": page_rows,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }

