    return {
        "data": page_rows,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }

def getActivelyTradingList(exchange=None, assetType=None, country=None, limit=None, cursor=None, sort=None, order=None, **_extra):
