        target_instrument_ids = {r.get("id") for r in matched if r.get("id") is not None}

    # key allowlists: restrict universe
    allowed_ex = key.get("allowed_exchanges")
    allowed_assets = key.get("allowed_asset_types")

    # Aggregate transcript availability from content_items of type 'financial_report' with identifier_1='earnings_transcript'
    # This is a pragmatic mapping within given schema.
    buckets = {}  # (instrument_id, year, quarter) -> {count, updated_at_max}
    for ci in content:
        if not isinstance(ci, dict):
            continue
        if ci.get("status") != "active":
            continue
        if ci.get("content_type") != "financial_report":
            continue
        if (ci.get("identifier_1") or "").lower() != "earnings_transcript":
            continue

        iid = ci.get("instrument_id")
