        if quarter is not None and qi != quarter:
            continue

        # only accept valid year/quarter if present when filtering; for grouping allow None but output will reflect None
        key_t = (iid, yi, qi)
        b = buckets.get(key_t)
        if b is None:
            buckets[key_t] = {"count": 1, "updated_at": ci.get("updated_at") or ci.get("created_at") or ""}
        else:
            b["count"] += 1
            ua = ci.get("updated_at") or ci.get("created_at") or ""
            if ua and ua > (b["updated_at"] or ""):
                b["updated_at"] = ua

    # Convert to rows
    rows = []
    for (iid, yi, qi), b in buckets.items():
        inst = inst_by_id.get(iid)
        if not inst:
            continue
        rows.append({
            "symbol": inst.get("symbol"),
            "exchange": inst.get("exchange"),
            "year": yi,
            "quarter": qi,
            "transcriptCount": b["count"],
            "updatedAt": b["updated_at"] or inst.get("updated_at")
        })

