            return ((r.get("symbol") or "").upper(), r.get("exchange") or "", r.get("year") or 0, r.get("quarter") or 0)
        if sort == "year":
            return (r.get("year") if r.get("year") is not None else -1, r.get("quarter") if r.get("quarter") is not None else -1, (r.get("symbol") or "").upper())
        if sort == "quarter":
            return (r.get("quarter") if r.get("quarter") is not None else -1, r.get("year") if r.get("year") is not None else -1, (r.get("symbol") or "").upper())
        if sort == "updatedAt":
            return (r.get("updatedAt") or "", (r.get("symbol") or "").upper())
        return ((r.get("symbol") or "").upper(),)

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page_rows = rows[start_i:start_i + limit]
    next_i = start_i + len(page_rows)
