            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order
        }
    }

def getAvailableExchanges(limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getAvailableExchanges"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_req_id():
        # vendor-ish sortable id
        seed = hashlib.sha1(os.urandom(16)).hexdigest()[:22]
        return "fmp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + seed

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rolling_counts(api_key_id, now_aware):
        logs = _load("request_logs.json")
        minute_ago = now_aware - datetime.timedelta(minutes=1)
        day_ago = now_aware - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                d += 1
                if dt >= minute_ago:
                    m += 1
        return m, d

    def _find_active_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        # choose the one with highest remaining quota headroom (minute then daily)
        best = None
        best_score = None
        for k in active:
            mid = k.get("id")
            if not isinstance(mid, str):
                continue
            m, d = _rolling_counts(mid, now_dt)
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or not isinstance(day_q, int):
                continue
            if min_q < 0 or day_q < 0:
                continue
            # score: remaining minute, remaining daily
            score = (min_q - m, day_q - d)
            if best is None or score > best_score:
                best, best_score = k, score
        return best

    def _enforce_quota(key_row):
        m, d = _rolling_counts(key_row["id"], now_dt)
        if m >= int(key_row.get("minute_request_quota", 0)):
            return False, "RATE_LIMIT", "Request quota exceeded.", "quota_minute_exceeded", 429
        if d >= int(key_row.get("daily_request_quota", 0)):
            return False, "QUOTA_EXCEEDED", "Daily request quota exceeded.", "quota_daily_exceeded", 429
        return True, None, None, None, 200

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_req_id(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    # -------- validate inputs (no additionalProperties is handled by signature) --------
    if limit is None:
        limit_i = 1000
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)):
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"limit": limit, "cursor": cursor, "sort": sort, "order": order}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be a number.")
        if isinstance(limit, float) and not limit.is_integer():
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"limit": limit, "cursor": cursor, "sort": sort, "order": order}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be an integer.")
        limit_i = int(limit)
        if limit_i <= 0:
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"limit": limit, "cursor": cursor, "sort": sort, "order": order}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be positive.")
        if limit_i > 1000:
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"limit": limit, "cursor": cursor, "sort": sort, "order": order}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must not exceed 1000.")

    if cursor is not None and not isinstance(cursor, str):
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"limit": limit_i, "cursor": cursor, "sort": sort, "order": order}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`cursor` must be a string.")

    if sort is None:
        sort = "exchange"
    if sort != "exchange":
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"limit": limit_i, "cursor": cursor, "sort": sort, "order": order}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`sort` must be 'exchange'.")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"limit": limit_i, "cursor": cursor, "sort": sort, "order": order}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`order` must be 'asc' or 'desc'.")

    # decode cursor (opaque); accept any string, treat invalid as exhausted (empty page)
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("exch:"):
                start = int(s.split(":", 1)[1])
            else:
                start = int(s)
            if start < 0:
                start = 0
        except Exception:
            start = 10**18  # exhausted

    # -------- auth (ambient) + quota --------
    key = _find_active_key()
    params_obj = {"limit": limit_i, "cursor": cursor, "sort": sort, "order": order}
    if key is None:
        _log("unknown", params_obj, 401, error_code="unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

    ok, ecode, emsg, reason, http_status = _enforce_quota(key)
    if not ok:
        _log(key["id"], params_obj, http_status, error_code=reason)
        return _err(ecode, emsg, reason=reason, http_status=http_status)

    # -------- query real store: distinct exchanges from instruments/content_items --------
    instruments = _load("instruments.json")
    content = _load("content_items.json")

    exch_set = set()
    for r in instruments:
        if isinstance(r, dict):
            ex = r.get("exchange")
            if isinstance(ex, str) and ex.strip():
                exch_set.add(ex.strip())
    for r in content:
        if isinstance(r, dict):
            ex = r.get("exchange")
            if isinstance(ex, str) and ex.strip():
                exch_set.add(ex.strip())

    exchanges = [{"exchange": e} for e in exch_set]
    exchanges.sort(key=lambda x: (x.get("exchange") or ""))
    if order == "desc":
        exchanges.reverse()

    total = len(exchanges)
    page_items = exchanges[start:start + limit_i]
    next_cursor = None
    if start + limit_i < total:
        token = f"exch:{start + limit_i}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    # update last_used_at on success
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    _log(key["id"], params_obj, 200, result_count=len(page_items), error_code=None)
    return {
        "data": page_items,
        "meta": {
            "total": total,
            "limit": limit_i,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": bool(next_cursor),
            "sort": sort,
            "order": order,
        }
    }

def getAvailableSectors(exchange=None, country=None, assetType=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(api_key_id, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        rid = "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + hashlib.sha1(os.urandom(16)).hexdigest()[:12]
        row = {
            "id": rid,
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": "getAvailableSectors",
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj, dict) or obj.get("tool") != "getAvailableSectors":
            return _err("VALIDATION_ERROR", "cursor is invalid for this endpoint")
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return i

    def _encode_cursor(i):
        payload = {"tool": "getAvailableSectors", "i": int(i)}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _resolve_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota_and_touch(key_row):
        logs = _load("request_logs.json")
        try:
            minute_q = int(key_row.get("minute_request_quota", 0))
            day_q = int(key_row.get("daily_request_quota", 0))
        except Exception:
            return _err("VALIDATION_ERROR", "API key quota fields are invalid")
        if minute_q < 0 or day_q < 0:
            return _err("VALIDATION_ERROR", "API key quota fields are invalid")

        now_dt = datetime.datetime.utcnow()
        min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        used_min = 0
        used_day = 0
        kid = key_row.get("id")
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != kid:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= day_ago:
                used_day += 1
                if ts >= min_ago:
                    used_min += 1

        if minute_q == 0 or day_q == 0:
            return _err("QUOTA_EXCEEDED", "API key quota exceeded")
        if used_min + 1 > minute_q:
            return _err("RATE_LIMIT", "Minute request quota exceeded", limit=minute_q)
        if used_day + 1 > day_q:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", limit=day_q)

        key_row["last_used_at"] = now
        key_row["updated_at"] = now
        keys = _load("api_keys.json")
        for i, kk in enumerate(keys):
            if isinstance(kk, dict) and kk.get("id") == key_row.get("id"):
                keys[i] = key_row
                _save("api_keys.json", keys)
                break
        return None

    # validate inputs
    params = {
        "exchange": exchange,
        "country": country,
        "assetType": assetType,
        "limit": limit,
        "cursor": cursor,
        "sort": sort,
        "order": order
    }
    allowed_asset = {"equity", "etf", "mutual_fund", "index", "crypto", "forex", "commodity", "note"}
    allowed_sort = {"sector"}
    allowed_order = {"asc", "desc"}

    if exchange is not None and not isinstance(exchange, str):
        key = _resolve_active_key()
        api_key_id = key["id"] if key else None
        duration_ms = (time.time() - t0) * 1000
        _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "exchange must be a string")
    if country is not None and not isinstance(country, str):
        key = _resolve_active_key()
        api_key_id = key["id"] if key else None
        duration_ms = (time.time() - t0) * 1000
        _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "country must be a string")
    if assetType is not None:
        if not isinstance(assetType, str):
            key = _resolve_active_key()
            api_key_id = key["id"] if key else None
            duration_ms = (time.time() - t0) * 1000
            _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assetType must be a string")
        if assetType not in allowed_asset:
            key = _resolve_active_key()
            api_key_id = key["id"] if key else None
            duration_ms = (time.time() - t0) * 1000
            _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assetType must be one of the supported values")

    if sort is None:
        sort = "sector"
        params["sort"] = sort
    elif not isinstance(sort, str) or sort not in allowed_sort:
        key = _resolve_active_key()
        api_key_id = key["id"] if key else None
        duration_ms = (time.time() - t0) * 1000
        _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be 'sector'")

    if order is None:
        order = "asc"
        params["order"] = order
    elif not isinstance(order, str) or order not in allowed_order:
        key = _resolve_active_key()
        api_key_id = key["id"] if key else None
        duration_ms = (time.time() - t0) * 1000
        _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    if limit is None:
        limit = 500
        params["limit"] = limit
    if not isinstance(limit, (int, float)) or isinstance(limit, bool):
        key = _resolve_active_key()
        api_key_id = key["id"] if key else None
        duration_ms = (time.time() - t0) * 1000
        _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be a number")
    limit = int(limit)
    if limit < 1:
        key = _resolve_active_key()
        api_key_id = key["id"] if key else None
        duration_ms = (time.time() - t0) * 1000
        _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be >= 1")
    if limit > 5000:
        key = _resolve_active_key()
        api_key_id = key["id"] if key else None
        duration_ms = (time.time() - t0) * 1000
        _log_request(api_key_id, params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be <= 5000")

    start_i = 0
    dec = _decode_cursor(cursor)
    if isinstance(dec, dict) and "error" in dec:
        key = _resolve_active_key()
        api_key_id = key["id"] if key else None
        duration_ms = (time.time() - t0) * 1000
        _log_request(api_key_id, params, 400, "bypass", duration_ms, None, dec["error"]["code"])
        return dec
    if dec is not None:
        start_i = dec

    key = _resolve_active_key()
    if not key:
        duration_ms = (time.time() - t0) * 1000
        _log_request("unknown", params, 401, "bypass", duration_ms, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing, invalid, or unauthorized API key")

    quota_err = _enforce_quota_and_touch(key)
    if quota_err:
        http = 429 if quota_err["error"]["code"] in ("RATE_LIMIT", "QUOTA_EXCEEDED") else 403
        duration_ms = (time.time() - t0) * 1000
        _log_request(key["id"], params, http, "bypass", duration_ms, None, quota_err["error"]["code"])
        return quota_err

    instruments = _load("instruments.json")

    sectors = set()
    for r in instruments:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        # scope filters
        if exchange is not None and r.get("exchange") != exchange:
            continue
        if country is not None and r.get("country") != country:
            continue
        if assetType is not None and r.get("asset_type") != assetType:
            continue
        # key allowlists
        if key.get("allowed_exchanges") is not None and r.get("exchange") not in key.get("allowed_exchanges", []):
            continue
        if key.get("allowed_asset_types") is not None and r.get("asset_type") not in key.get("allowed_asset_types", []):
            continue
        s = r.get("sector")
        if isinstance(s, str) and s.strip():
            sectors.add(s.strip())

    rows = [{"sector": s} for s in sectors]
    rows.sort(key=lambda x: (x.get("sector") or "").lower(), reverse=(order == "desc"))

    total = len(rows)
    page_rows = rows[start_i:start_i + limit]
    next_i = start_i + len(page_rows)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i) if has_more else None

    duration_ms = (time.time() - t0) * 1000
    _log_request(key["id"], params, 200, "miss", duration_ms, result_count=len(page_rows), error_code=None)
    return {
        "data": page_rows,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order
        }
    }

def getAvailableIndustries(sector=None, exchange=None, country=None, assetType=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _hash_key(s):
        # Store uses key_hash; authenticate by comparing client-presented value OR id.
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _parse_cursor(cur):
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if obj.get("v") != 1:
                return None
            if obj.get("tool") != "getAvailableIndustries":
                return None
            ix = obj.get("i")
            if not isinstance(ix, int) or ix < 0:
                return None
            # basic filter binding
            for k in ("sector", "exchange", "country", "assetType", "sort", "order"):
                if obj.get(k, None) is not None and not isinstance(obj.get(k), str):
                    return None
            return obj
        except Exception:
            return None

    def _make_cursor(i, params_obj):
        obj = {"v": 1, "tool": "getAvailableIndustries", "i": i}
        for k in ("sector", "exchange", "country", "assetType", "sort", "order"):
            if params_obj.get(k) is not None:
                obj[k] = params_obj[k]
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.perf_counter()
    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")

    # Ambient auth: choose an active key that can serve request (status active, quota allows).
    # No explicit credential parameter, so we search for any active key that is within quotas.
    now = datetime.datetime.utcnow()
    window_minute_start = now - datetime.timedelta(seconds=60)
    window_day_start = now - datetime.timedelta(days=1)

    def _dt_parse(x):
        if not isinstance(x, str):
            return None
        try:
            # accept Z or offsetless isoformat
            if x.endswith("Z"):
                return datetime.datetime.fromisoformat(x[:-1])
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    def _count_requests_for_key(key_id):
        minute = 0
        day = 0
        inflight = 0
        for r in req_logs:
            if r.get("api_key_id") != key_id:
                continue
            ca = _dt_parse(r.get("created_at"))
            if not ca:
                continue
            if ca >= window_day_start:
                day += 1
