    selected_key = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        if not isinstance(k.get("minute_request_quota"), int) or not isinstance(k.get("daily_request_quota"), int):
            continue
        minute_used, day_used = _count_requests_for_key(k.get("id"))
        if minute_used + 1 > k["minute_request_quota"] or day_used + 1 > k["daily_request_quota"]:
            continue
        selected_key = k
        break

    # Validate schema
    validated_params = {}
    err = None
    http_status = 200

    if not isinstance(symbol, str) or not symbol.strip():
        http_status = 400
        err = _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    elif period not in ["annual", "quarter"]:
        http_status = 400
        err = _err("VALIDATION_ERROR", "period must be 'annual' or 'quarter'")
    else:
        sym_norm = symbol.strip().upper()
        if page is None:
            page_v = 0
        else:
            if not (isinstance(page, int) or isinstance(page, float)) or isinstance(page, bool):
                http_status = 400
                err = _err("VALIDATION_ERROR", "page must be a number")
                page_v = None
            else:
                page_v = int(page)
                if page_v < 0:
                    http_status = 400
                    err = _err("VALIDATION_ERROR", "page must be >= 0")
        if err is None:
            if limit is None:
                limit_v = 10
