    result = None
    result_count = None

    if err is None:
        instruments = _load("instruments.json")
        content = _load("content_items.json")

        # Resolve instrument by normalized_symbol (exchange variants possible; return all matching, like FMP often does)
        matching_instruments = [i for i in instruments if i.get("normalized_symbol") == sym_norm]
        if not matching_instruments:
            # read returning empty, not error
            rows = []
        else:
            inst_ids = {i.get("id") for i in matching_instruments if isinstance(i.get("id"), str)}
