    log_row = {
        "id": _gen_id("req"),
        "api_key_id": (selected_key.get("id") if selected_key else "unknown"),
        "tool_name": "getAnalystEstimates",
        "params": validated_params if err is None else {k: v for k, v in {"symbol": symbol, "period": period, "page": page, "limit": limit}.items() if v is not None},
        "http_status": int(http_status),
        "cache_status": "bypass",
        "duration_ms": max(0, duration_ms),
        "result_count": result_count,
        "error_code": (err["error"]["code"] if err else None),
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    req_logs.append(log_row)
    _save("request_logs.json", req_logs)

    if selected_key and err is None and 200 <= http_status <= 299:
        for k in api_keys:
            if k.get("id") == selected_key.get("id"):
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                break
        _save("api_keys.json", api_keys)

    if err:
        return err
    return result

