                    err = _err("VALIDATION_ERROR", "limit must be >= 0")
                elif limit_v > 1000:
                    http_status = 400
                    err = _err("VALIDATION_ERROR", "limit must be <= 1000")
        if err is None:
            validated_params = {"symbol": symbol}
            if limit is not None:
                validated_params["limit"] = limit_v

    if selected_key is None:
        any_active = any(k.get("status") == "active" for k in api_keys)
        if any_active:
            http_status = 429
            err = _err("RATE_LIMIT", "Request quota exceeded")
        else:
            http_status = 401
            err = _err("UNAUTHORIZED", "Missing or invalid API key")

    result = None
    result_count = None

    if err is None:
        sym_norm = symbol.strip().upper()
