                payload = it.get("payload")
                if isinstance(payload, dict):
                    rows.append(payload)

        # Prefer most recent by as_of_date / updated_at / created_at (descending)
        def _keyp(r):
            d = r.get("date") or r.get("asOfDate") or r.get("as_of_date") or ""
            return d

        rows.sort(key=_keyp, reverse=True)
        rows = rows[:limit_v]
        result = {"data": rows, "meta": {"total": len(rows), "limit": limit_v}}
        result_count = len(rows)

    duration_ms = int((time.perf_counter() - t0) * 1000)
    log_row = {
        "id": _gen_id("req"),
        "api_key_id": (selected_key.get("id") if selected_key else "unknown"),
        "tool_name": "getRatingsSnapshot",
