        "http_status": int(http_status),
        "cache_status": "bypass",
        "duration_ms": max(0, duration_ms),
        "result_count": result_count,
        "error_code": (err["error"]["code"] if err else None),
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    req_logs.append(log_row)
    _save("request_logs.json", req_logs)

    if selected_key and err is None and 200 <= http_status <= 299:
        for k in api_keys:
            if k.get("id") == selected_key.get("id"):
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                break
        _save("api_keys.json", api_keys)

    if err:
        return err
    return result

def getHistoricalRatings(symbol, limit=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_limit(x, default, maxv):
        if x is None:
            return default
        if isinstance(x, bool):
            return None
        if isinstance(x, (int, float)):
            if isinstance(x, float) and (x != int(x)):
                return None
            x = int(x)
            if x < 1 or x > maxv:
                return None
            return x
        return None

    def _norm_symbol(s):
        return s.strip().upper()

    def _validate_params():
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
        lim = _parse_limit(limit, default=1, maxv=10000)
        if lim is None:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 10000")
        return {"symbol": _norm_symbol(symbol), "limit": lim}

    def _log_request(api_key_id, tool_name, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        now = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _authenticate_and_enforce_quota(tool_name, params_obj):
        api_keys = _load("api_keys.json")
        active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active_keys:
            return None, _err("UNAUTHORIZED", "No active API key available to authenticate request")

        # Choose a key that can accept the request under rolling quotas
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        for k in active_keys:
            kid = k.get("id")
            if not isinstance(kid, str) or not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or not isinstance(day_q, int) or min_q < 0 or day_q < 0:
                continue

            # Count all requests in windows (including failed), as backend typically does for quota.
            min_count = 0
            day_count = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ts = _parse_ts(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= day_ago:
                    day_count += 1
                    if ts >= minute_ago:
                        min_count += 1

            if (min_q == 0 and min_count >= 0) or (day_q == 0 and day_count >= 0):
                # If quota is 0, any request exceeds.
                continue

            if min_count + 1 > min_q:
                continue
            if day_count + 1 > day_q:
                continue

            return k, None

        # If at least one active key exists but all exceed quotas, return quota exceeded.
        return None, _err("QUOTA_EXCEEDED", "Request quota exceeded")

    start = time.time()
    tool = "getHistoricalRatings"

    params_validated = _validate_params()
    if isinstance(params_validated, dict) and "error" in params_validated:
        # Log attempt with some active key if exists, else synthetic placeholder
        api_keys = _load("api_keys.json")
        ak = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")), None)
        api_key_id = ak.get("id") if ak else "unauth"
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, tool, {"symbol": symbol, "limit": limit} if isinstance(symbol, str) else {"symbol": symbol, "limit": limit}, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return params_validated

    auth_key, auth_err = _authenticate_and_enforce_quota(tool, params_validated)
    if auth_err is not None:
        duration_ms = int((time.time() - start) * 1000)
        http_status = 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429
        api_key_id = "unauth"
        # If quota exceeded, use some active key id for accurate attribution
        if auth_err["error"]["code"] == "QUOTA_EXCEEDED":
            api_keys = _load("api_keys.json")
            ak = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")), None)
            api_key_id = ak.get("id") if ak else "unauth"
        _log_request(api_key_id, tool, params_validated, http_status, "bypass", duration_ms, result_count=None, error_code=auth_err["error"]["code"])
        return auth_err

    api_key_id = auth_key["id"]

    instruments = _load("instruments.json")
    sym = params_validated["symbol"]
    inst = next((i for i in instruments if isinstance(i, dict) and i.get("normalized_symbol") == sym), None)
    if inst is None:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, tool, params_validated, 404, "miss", duration_ms, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Symbol not found in catalog")

    # Entitlements
    allowed_asset_types = auth_key.get("allowed_asset_types")
    if allowed_asset_types is not None:
        if not isinstance(allowed_asset_types, list) or inst.get("asset_type") not in allowed_asset_types:
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, tool, params_validated, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not entitled for this asset type")
    allowed_exchanges = auth_key.get("allowed_exchanges")
    if allowed_exchanges is not None:
        if not isinstance(allowed_exchanges, list) or inst.get("exchange") not in allowed_exchanges:
            duration_ms = int((time.time() - start) * 1000)
            _log_request(api_key_id, tool, params_validated, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not entitled for this exchange")

    content = _load("content_items.json")
    rows = []
    for it in content:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "ratings":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        payload = it.get("payload")
        if isinstance(payload, dict):
            rows.append(payload)
        else:
            rows.append({"payload": payload})

    if not rows:
        duration_ms = int((time.time() - start) * 1000)
        _log_request(api_key_id, tool, params_validated, 404, "miss", duration_ms, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No historical ratings available for this symbol")

    def _date_key(r):
        d = None
        if isinstance(r, dict):
            d = r.get("date") or r.get("asOfDate") or r.get("as_of_date")
        if isinstance(d, str):
            return d
        return ""

    rows.sort(key=_date_key, reverse=True)
    rows = rows[: params_validated["limit"]]

    # Update api_key last_used_at on successful authenticated request
    api_keys = _load("api_keys.json")
    now_iso = _now_iso()
    changed = False
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            changed = True
            break
    if changed:
        _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - start) * 1000)
    _log_request(api_key_id, tool, params_validated, 200, "miss", duration_ms, result_count=len(rows), error_code=None)
    return {"symbol": sym, "data": rows, "count": len(rows)}

