            summary = p
            break

    if summary is None:
        # Compute averages by timeframe if the payload contains e.g. "timeframe" and "priceTarget"
        buckets = {}
        for p in pts:
            tf = p.get("timeframe") or p.get("period") or p.get("horizon")
            val = p.get("priceTarget") if "priceTarget" in p else p.get("targetPrice")
            if not isinstance(tf, str) or not tf:
                continue
            if not isinstance(val, (int, float)) or isinstance(val, bool):
                continue
            buckets.setdefault(tf, []).append(float(val))
        computed = {}
        for tf, arr in buckets.items():
            if arr:
                computed[tf] = {
                    "average": sum(arr) / len(arr),
                    "count": len(arr),
                    "min": min(arr),
                    "max": max(arr),
                }
        if not computed:
            duration_ms = int((time.time() - start) * 1000)
