                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _coerce_int(x, name):
        if x is None:
            return None
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        return None

    def _pick_active_key_and_enforce_quota(tool_name, params_obj):
        api_keys = _load("api_keys.json")
        logs = _load("request_logs.json")

        active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active_keys:
            return None, logs, _err("UNAUTHORIZED", "No active API key is available for this request.")

        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        # Choose a key that still has quota for this request (search working combination).
        for k in active_keys:
            kid = k.get("id")
            if not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue

            recent_min = 0
            recent_day = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ts = _parse_ts(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= minute_ago:
                    recent_min += 1
                if ts >= day_ago:
                    recent_day += 1

            if recent_min + 1 > min_q or recent_day + 1 > day_q:
                continue
            return k, logs, None

        # If none can serve, treat as quota exceeded (prefer minute if any key is minute-exceeded, else daily).
        return None, logs, _err("QUOTA_EXCEEDED", "API key quota exceeded.")

    def _log_request(logs, api_key_id, tool_name, params_obj, http_status, duration_ms, result_count=None, error_code=None, cache_status="bypass"):
        now_iso = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    tool = "getPriceTargetLatestNews"

    # Validate params (JSON schema: only page, limit allowed)
    params_obj = {}
    page_i = _coerce_int(page, "page")
    limit_i = _coerce_int(limit, "limit")
    if page is not None and page_i is None:
        # log after auth decision (but we still must auth+quota first per rules)
        page_i = "INVALID"
    if limit is not None and limit_i is None:
        limit_i = "INVALID"

    # Defaults
    if page is None:
        page_i = 0
    if limit is None:
        limit_i = 10

    # Authenticate + quota (ambient)
    key, logs, auth_err = _pick_active_key_and_enforce_quota(tool, {"page": page if page is not None else 0, "limit": limit if limit is not None else 10})
    if auth_err:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, None, tool, {"page": page if page is not None else 0, "limit": limit if limit is not None else 10}, 401, duration_ms, result_count=None, error_code=auth_err["error"]["code"], cache_status="bypass")
        return auth_err

    # Now strict validate page/limit bounds
    if not isinstance(page_i, int) or page_i < 0 or page_i > 100:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("VALIDATION_ERROR", "Invalid 'page'. Must be an integer between 0 and 100.", field="page")
        _log_request(logs, key["id"], tool, {"page": page, "limit": limit}, 400, duration_ms, result_count=None, error_code=err["error"]["code"], cache_status="bypass")
        return err

    if not isinstance(limit_i, int) or limit_i <= 0 or limit_i > 1000:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("VALIDATION_ERROR", "Invalid 'limit'. Must be an integer between 1 and 1000.", field="limit")
        _log_request(logs, key["id"], tool, {"page": page, "limit": limit}, 400, duration_ms, result_count=None, error_code=err["error"]["code"], cache_status="bypass")
        return err

    # Fetch content: content_type='price_target'
    items = _load("content_items.json")
    instruments = _load("instruments.json")

    # Build symbol lookup for equity instruments
    inst_by_id = {}
    for ins in instruments:
        if isinstance(ins, dict) and ins.get("id"):
            inst_by_id[ins["id"]] = ins

    rows = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "price_target":
            continue
        iid = it.get("instrument_id")
        ins = inst_by_id.get(iid) if iid else None
        if not ins:
            continue
        if ins.get("asset_type") != "equity":
            continue
        # Keep provider-like payload row; do not fabricate.
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue
        rows.append(payload)

    # Sort by payload date/timestamp fields if present; fallback to content_items.created_at.
    def _sort_key(idx_payload_pair):
        p, created = idx_payload_pair
        # common FMP fields: publishedDate/date
        for k in ("publishedDate", "date", "updatedAt", "createdAt"):
            v = p.get(k)
            if isinstance(v, str) and v:
                return v
        return created

    # Pair each payload with parent created_at for fallback
    pairs = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active" or it.get("content_type") != "price_target":
            continue
        iid = it.get("instrument_id")
        ins = inst_by_id.get(iid) if iid else None
        if not ins or ins.get("asset_type") != "equity":
            continue
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue
        pairs.append((payload, it.get("created_at") or ""))

    pairs.sort(key=_sort_key, reverse=True)
    rows_sorted = [p for (p, _c) in pairs]

    total = len(rows_sorted)
    start = page_i * limit_i
    end = start + limit_i
    page_rows = rows_sorted[start:end]

    if not page_rows:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("NOT_FOUND", "No price-target news items available for the requested page.")
        _log_request(logs, key["id"], tool, {"page": page_i, "limit": limit_i}, 404, duration_ms, result_count=0, error_code=err["error"]["code"], cache_status="bypass")
        return err

    # Update key last_used_at on successful authenticated request
    now_iso = _now_iso()
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - t0) * 1000)
    _log_request(logs, key["id"], tool, {"page": page_i, "limit": limit_i}, 200, duration_ms, result_count=len(page_rows), error_code=None, cache_status="bypass")

    return {
        "data": page_rows,
        "meta": {
            "page": page_i,
            "limit": limit_i,
            "total": total,
            "has_more": end < total
        }
    }

def getStockGrades(symbol, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_active_key_and_enforce_quota(tool_name, params_obj):
        api_keys = _load("api_keys.json")
        logs = _load("request_logs.json")

        active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active_keys:
            return None, logs, _err("UNAUTHORIZED", "No active API key is available for this request.")

        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        for k in active_keys:
            kid = k.get("id")
            if not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue

            recent_min = 0
            recent_day = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ts = _parse_ts(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= minute_ago:
                    recent_min += 1
                if ts >= day_ago:
                    recent_day += 1

            if recent_min + 1 > min_q or recent_day + 1 > day_q:
                continue
            return k, logs, None

        return None, logs, _err("QUOTA_EXCEEDED", "API key quota exceeded.")

    def _log_request(logs, api_key_id, tool_name, params_obj, http_status, duration_ms, result_count=None, error_code=None, cache_status="bypass"):
        now_iso = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    tool = "getStockGrades"

    # Authenticate + quota
    key, logs, auth_err = _pick_active_key_and_enforce_quota(tool, {"symbol": symbol})
    if auth_err:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, None, tool, {"symbol": symbol}, 401, duration_ms, result_count=None, error_code=auth_err["error"]["code"], cache_status="bypass")
        return auth_err

    # Validate symbol
    if symbol is None or not isinstance(symbol, str) or not symbol.strip():
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("VALIDATION_ERROR", "Missing or empty 'symbol'.", field="symbol")
        _log_request(logs, key["id"], tool, {"symbol": symbol}, 400, duration_ms, result_count=None, error_code=err["error"]["code"], cache_status="bypass")
        return err

    sym_norm = symbol.strip().upper()

    # Resolve instrument
    instruments = _load("instruments.json")
    inst = None
    for ins in instruments:
        if isinstance(ins, dict) and ins.get("normalized_symbol") == sym_norm:
            # For symbol-only tools, match normalized_symbol with exchange uniqueness semantics:
            # if multiple exchanges exist, FMP typically returns whichever is in catalog; we choose active equity with exchange not null preferred.
            if ins.get("asset_type") != "equity":
                continue
            if inst is None:
                inst = ins
            else:
                # prefer active over inactive/delisted; prefer with exchange over null
                rank = {"active": 2, "inactive": 1, "delisted": 0}
                cur = rank.get(inst.get("status"), 0)
                nxt = rank.get(ins.get("status"), 0)
                if nxt > cur:
                    inst = ins
                elif nxt == cur:
                    if inst.get("exchange") is None and ins.get("exchange") is not None:
                        inst = ins

    if not inst:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("NOT_FOUND", "Symbol not found in instrument catalog.", symbol=sym_norm)
        _log_request(logs, key["id"], tool, {"symbol": sym_norm}, 404, duration_ms, result_count=0, error_code=err["error"]["code"], cache_status="bypass")
        return err

    # Fetch latest grades for this symbol from content_items content_type='grade'
    items = _load("content_items.json")
    candidates = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "grade":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        payload = it.get("payload")
        if isinstance(payload, dict):
            candidates.append((payload, it.get("created_at") or ""))

    if not candidates:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("NOT_FOUND", "No grade records available for this symbol.", symbol=sym_norm)
        _log_request(logs, key["id"], tool, {"symbol": sym_norm}, 404, duration_ms, result_count=0, error_code=err["error"]["code"], cache_status="bypass")
        return err

    # Determine "latest actions": return those on the most recent date present (payload.date / publishedDate), else most recent created_at.
    def _date_of(p):
        if not isinstance(p, dict):
            return ""
        for k in ("date", "publishedDate", "updatedAt", "createdAt"):
            v = p.get(k)
            if isinstance(v, str) and v:
                return v
        return ""

    candidates.sort(key=lambda x: (_date_of(x[0]), x[1]), reverse=True)
    latest_date = _date_of(candidates[0][0]) or candidates[0][1]
    latest = [p for (p, c) in candidates if (_date_of(p) or c) == latest_date]

    # Update key last_used_at
    now_iso = _now_iso()
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - t0) * 1000)
    _log_request(logs, key["id"], tool, {"symbol": sym_norm}, 200, duration_ms, result_count=len(latest), error_code=None, cache_status="bypass")

    return {"data": latest}

def getHistoricalStockGrades(symbol, limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _coerce_int(x):
        if x is None:
            return None
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        return None

    def _pick_active_key_and_enforce_quota(tool_name, params_obj):
        api_keys = _load("api_keys.json")
        logs = _load("request_logs.json")

        active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active_keys:
            return None, logs, _err("UNAUTHORIZED", "No active API key is available for this request.")

        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        for k in active_keys:
            kid = k.get("id")
            if not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue

            recent_min = 0
            recent_day = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ts = _parse_ts(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= minute_ago:
                    recent_min += 1
                if ts >= day_ago:
                    recent_day += 1

            if recent_min + 1 > min_q or recent_day + 1 > day_q:
                continue
            return k, logs, None

        return None, logs, _err("QUOTA_EXCEEDED", "API key quota exceeded.")

    def _log_request(logs, api_key_id, tool_name, params_obj, http_status, duration_ms, result_count=None, error_code=None, cache_status="bypass"):
        now_iso = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    tool = "getHistoricalStockGrades"

    # Defaults
    lim_i = _coerce_int(limit)
    if limit is None:
        lim_i = 100

    # Authenticate + quota
    key, logs, auth_err = _pick_active_key_and_enforce_quota(tool, {"symbol": symbol, "limit": lim_i})
    if auth_err:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, None, tool, {"symbol": symbol, "limit": limit}, 401, duration_ms, result_count=None, error_code=auth_err["error"]["code"], cache_status="bypass")
        return auth_err

    # Validate symbol
    if symbol is None or not isinstance(symbol, str) or not symbol.strip():
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("VALIDATION_ERROR", "Missing or empty 'symbol'.", field="symbol")
        _log_request(logs, key["id"], tool, {"symbol": symbol, "limit": lim_i}, 400, duration_ms, result_count=None, error_code=err["error"]["code"], cache_status="bypass")
        return err

    # Validate limit bounds
    if not isinstance(lim_i, int) or lim_i <= 0 or lim_i > 1000:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("VALIDATION_ERROR", "Invalid 'limit'. Must be an integer between 1 and 1000.", field="limit")
        _log_request(logs, key["id"], tool, {"symbol": symbol.strip().upper(), "limit": limit}, 400, duration_ms, result_count=None, error_code=err["error"]["code"], cache_status="bypass")
        return err

    sym_norm = symbol.strip().upper()

    # Resolve instrument
    instruments = _load("instruments.json")
    inst = None
    for ins in instruments:
        if isinstance(ins, dict) and ins.get("normalized_symbol") == sym_norm and ins.get("asset_type") == "equity":
            if inst is None:
                inst = ins
            else:
                rank = {"active": 2, "inactive": 1, "delisted": 0}
                if rank.get(ins.get("status"), 0) > rank.get(inst.get("status"), 0):
                    inst = ins

    if not inst:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("NOT_FOUND", "Symbol not found in instrument catalog.", symbol=sym_norm)
        _log_request(logs, key["id"], tool, {"symbol": sym_norm, "limit": lim_i}, 404, duration_ms, result_count=0, error_code=err["error"]["code"], cache_status="bypass")
        return err

    # Fetch grade history
    items = _load("content_items.json")
    history = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "grade":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        payload = it.get("payload")
        if isinstance(payload, dict):
            history.append((payload, it.get("created_at") or ""))

    if not history:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("NOT_FOUND", "No grade history available for this symbol.", symbol=sym_norm)
        _log_request(logs, key["id"], tool, {"symbol": sym_norm, "limit": lim_i}, 404, duration_ms, result_count=0, error_code=err["error"]["code"], cache_status="bypass")
        return err

    def _date_of(p, created):
        for k in ("date", "publishedDate", "updatedAt", "createdAt"):
            v = p.get(k)
            if isinstance(v, str) and v:
                return v
        return created

    history.sort(key=lambda x: _date_of(x[0], x[1]), reverse=True)
    out = [p for (p, _c) in history[:lim_i]]

    # Update key last_used_at
    now_iso = _now_iso()
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - t0) * 1000)
    _log_request(logs, key["id"], tool, {"symbol": sym_norm, "limit": lim_i}, 200, duration_ms, result_count=len(out), error_code=None, cache_status="bypass")

    return {"data": out, "meta": {"limit": lim_i, "returned": len(out)}}

def getStockGradeSummary(symbol, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
