        if not active_keys:
            return None, logs, _err("UNAUTHORIZED", "No active API key is available for this request.")

        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        for k in active_keys:
            kid = k.get("id")
            if not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue

            recent_min = 0
            recent_day = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ts = _parse_ts(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= minute_ago:
                    recent_min += 1
                if ts >= day_ago:
                    recent_day += 1

            if recent_min + 1 > min_q or recent_day + 1 > day_q:
                continue
            return k, logs, None

        return None, logs, _err("QUOTA_EXCEEDED", "API key quota exceeded.")

    def _log_request(logs, api_key_id, tool_name, params_obj, http_status, duration_ms, result_count=None, error_code=None, cache_status="bypass"):
        now_iso = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    tool = "getStockGradeSummary"

    # Authenticate + quota
    key, logs, auth_err = _pick_active_key_and_enforce_quota(tool, {"symbol": symbol})
    if auth_err:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, None, tool, {"symbol": symbol}, 401, duration_ms, result_count=None, error_code=auth_err["error"]["code"], cache_status="bypass")
        return auth_err

    # Validate symbol
    if symbol is None or not isinstance(symbol, str) or not symbol.strip():
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("VALIDATION_ERROR", "Missing or empty 'symbol'.", field="symbol")
        _log_request(logs, key["id"], tool, {"symbol": symbol}, 400, duration_ms, result_count=None, error_code=err["error"]["code"], cache_status="bypass")
        return err

    sym_norm = symbol.strip().upper()

    # Resolve instrument
    instruments = _load("instruments.json")
    inst = None
    for ins in instruments:
        if isinstance(ins, dict) and ins.get("normalized_symbol") == sym_norm and ins.get("asset_type") == "equity":
            if inst is None:
                inst = ins
            else:
                rank = {"active": 2, "inactive": 1, "delisted": 0}
                if rank.get(ins.get("status"), 0) > rank.get(inst.get("status"), 0):
                    inst = ins

    if not inst:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("NOT_FOUND", "Symbol not found in instrument catalog.", symbol=sym_norm)
        _log_request(logs, key["id"], tool, {"symbol": sym_norm}, 404, duration_ms, result_count=0, error_code=err["error"]["code"], cache_status="bypass")
        return err

    # Prefer precomputed summary content_type='scores' (if present), else compute from latest grade actions date.
    items = _load("content_items.json")
    summary_payloads = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "scores":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        payload = it.get("payload")
        if isinstance(payload, dict):
            summary_payloads.append((payload, it.get("created_at") or ""))

    if summary_payloads:
        # Use the most recent summary payload
        summary_payloads.sort(key=lambda x: x[1], reverse=True)
        out = summary_payloads[0][0]

        now_iso = _now_iso()
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key["id"]:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, key["id"], tool, {"symbol": sym_norm}, 200, duration_ms, result_count=1, error_code=None, cache_status="bypass")
        return {"data": out}

    # Compute summary from grade history (latest date bucket), mapping to rating buckets if possible.
    grade_rows = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "grade":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        payload = it.get("payload")
        if isinstance(payload, dict):
            grade_rows.append((payload, it.get("created_at") or ""))

    if not grade_rows:
        duration_ms = int((time.time() - t0) * 1000)
        err = _err("NOT_FOUND", "No grade summary available for this symbol.", symbol=sym_norm)
        _log_request(logs, key["id"], tool, {"symbol": sym_norm}, 404, duration_ms, result_count=0, error_code=err["error"]["code"], cache_status="bypass")
        return err

    def _grade_date(p, created):
        for k in ("date", "publishedDate", "updatedAt", "createdAt"):
            v = p.get(k)
            if isinstance(v, str) and v:
                return v
        return created

    grade_rows.sort(key=lambda x: _grade_date(x[0], x[1]), reverse=True)
    latest_d = _grade_date(grade_rows[0][0], grade_rows[0][1])
    latest_actions = [p for (p, c) in grade_rows if _grade_date(p, c) == latest_d]

    # Bucket mapping based on common FMP grade fields: "gradingCompany", "newGrade", "previousGrade", "gradingScale"/"rating"
    def _bucket(val):
        if not isinstance(val, str):
            return "unknown"
        v = val.strip().lower()
        if not v:
            return "unknown"
        # common buckets
        if "strong buy" in v or v in ("outperform", "overweight", "buy"):
            if "strong buy" in v:
                return "strong_buy"
            if v == "buy":
                return "buy"
            return "buy"
        if "hold" in v or v in ("neutral", "market perform", "equal-weight", "equal weight"):
            return "hold"
        if "sell" in v or v in ("underweight", "underperform"):
            if "strong sell" in v:
                return "strong_sell"
            return "sell"
        return "unknown"

    counts = {"strong_buy": 0, "buy": 0, "hold": 0, "sell": 0, "strong_sell": 0, "unknown": 0}
    for p in latest_actions:
        # choose the most representative grade field
        g = None
        for k in ("newGrade", "grade", "rating", "recommendation"):
            if isinstance(p.get(k), str) and p.get(k).strip():
                g = p.get(k)
                break
        b = _bucket(g)
        if b not in counts:
            b = "unknown"
        counts[b] += 1

    out = {
        "symbol": sym_norm,
        "asOf": latest_d,
        "counts": counts,
        "total": len(latest_actions),
    }

    # Update key last_used_at
    now_iso = _now_iso()
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - t0) * 1000)
