    next_cursor = str(page_i + 1) if has_more else None

    _log(key["id"], 200, params_obj, result_count=len(out), error_code=None, cache_status="miss")
    return {"data": out, "meta": {"page": page_i, "limit": limit_i, "total": total, "has_more": has_more, "next_cursor": next_cursor}}

