            if _within(rdt, 86400):
                d_cnt += 1
        if (minute_quota == 0 and day_quota == 0):
            # 0 means no requests allowed per constraints? Treat as hard limit of 0.
            continue
        if minute_quota and m_cnt + 1 > minute_quota:
