    # Order newest-first by as_of_date then created_at as tie-break
    def _key(o):
        d = o.get("date") or o.get("calendarDate")
        d2 = _parse_iso_date(d) or "0000-00-00"
        return (d2,)

    rows.sort(key=_key, reverse=True)
