            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    duration = (time.time() - started) * 1000
    _log(api_key_id, {"symbol": symbol, "limit": limit_i}, 200, "miss", duration, result_count=len(rows), error_code=None)
    return rows

