def getStockSplits(symbol, limit=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        now = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota(api_key_id, minute_quota, daily_quota):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        one_min = now - datetime.timedelta(minutes=1)
        one_day = now - datetime.timedelta(days=1)

        def _parse_ts(x):
            if not isinstance(x, str):
                return None
            try:
                if x.endswith("Z"):
                    x = x[:-1]
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None

        minute_count = 0
        day_count = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= one_day:
                day_count += 1
                if ts >= one_min:
                    minute_count += 1

        if isinstance(minute_quota, int) and minute_quota >= 0 and minute_count + 1 > minute_quota:
            return _err("RATE_LIMIT", "Minute request quota exceeded.")
        if isinstance(daily_quota, int) and daily_quota >= 0 and day_count + 1 > daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    # Validate
    if not isinstance(symbol, str) or not symbol.strip():
        k = _pick_active_key()
        api_key_id = k["id"] if k else "unknown"
        _log(api_key_id, "getStockSplits", {"symbol": symbol, "limit": limit}, 422, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing or blank 'symbol'.")

    if limit is None:
        lim = 100
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            k = _pick_active_key()
            api_key_id = k["id"] if k else "unknown"
            _log(api_key_id, "getStockSplits", {"symbol": symbol, "limit": limit}, 422, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "'limit' must be a number.")
        lim = int(limit)
    if lim < 1 or lim > 1000:
        k = _pick_active_key()
        api_key_id = k["id"] if k else "unknown"
        _log(api_key_id, "getStockSplits", {"symbol": symbol, "limit": limit}, 422, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'limit' must be between 1 and 1000.")

    sym_norm = symbol.strip().upper()

    # Auth
    key = _pick_active_key()
    if not key:
        _log("unknown", "getStockSplits", {"symbol": sym_norm, "limit": lim}, 401, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is missing/invalid or not active.")

    quota_err = _enforce_quota(key["id"], key.get("minute_request_quota"), key.get("daily_request_quota"))
    if quota_err:
        _log(key["id"], "getStockSplits", {"symbol": sym_norm, "limit": lim}, 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code=quota_err["error"]["code"])
        return quota_err

    # Resolve instrument (normalized_symbol match)
    instruments = _load("instruments.json")
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("normalized_symbol") == sym_norm:
            inst = r
            break
    if not inst:
        _log(key["id"], "getStockSplits", {"symbol": sym_norm, "limit": lim}, 404, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Symbol not found.")

    # Enforce allowed_asset_types/exchanges if configured
    allowed_ex = key.get("allowed_exchanges")
    if allowed_ex is not None:
        if inst.get("exchange") not in allowed_ex:
            _log(key["id"], "getStockSplits", {"symbol": sym_norm, "limit": lim}, 403, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not permitted for this exchange.")
    allowed_at = key.get("allowed_asset_types")
    if allowed_at is not None:
        if inst.get("asset_type") not in allowed_at:
            _log(key["id"], "getStockSplits", {"symbol": sym_norm, "limit": lim}, 403, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not permitted for this asset type.")

    # Query stock_split_event content items for this instrument
    items = _load("content_items.json")
    res = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "stock_split_event":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
        out = dict(payload) if isinstance(payload, dict) else {}
        # normalize date field
        as_of = it.get("as_of_date")
        if isinstance(as_of, str) and "date" not in out and "splitDate" not in out:
            out["date"] = as_of
        if "symbol" not in out:
            out["symbol"] = inst.get("symbol")
        res.append(out)

    # newest-first by date
    def _d(x):
        return x.get("date") or x.get("splitDate") or ""
    res.sort(key=_d, reverse=True)
    res = res[:lim]

    # Update last_used_at on success
    keys = _load("api_keys.json")
    now = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    _log(key["id"], "getStockSplits", {"symbol": sym_norm, "limit": lim}, 200, "miss", (time.time() - _t0) * 1000, result_count=len(res), error_code=None)
    return {"data": res}

