    _log_request(request_logs, key_id, params_obj, 200, "miss", dur, result_count=len(out), error_code=None)
    return out

def getIntradayChart(symbol, interval, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_date(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.date.fromisoformat(s)
        except ValueError:
            return None

    def _mk_log_id():
        return "rlog_" + uuid.uuid4().hex

    def _http_status_for_error(code):
        if code in ("UNAUTHORIZED",):
            return 401
        if code in ("RATE_LIMIT", "QUOTA_EXCEEDED"):
            return 429
        if code in ("NOT_FOUND",):
            return 404
        if code in ("CONFLICT", "INVALID_TRANSITION", "VALIDATION_ERROR"):
            return 400
        return 400

    def _authenticate_active_key(api_keys_rows):
        # Ambient auth: pick any active key that can serve the request.
        # If no keys exist or none are active, request is unauthorized.
        for k in api_keys_rows:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota(api_key_id, minute_quota, daily_quota, request_logs_rows, now_dt):
        # Rolling windows based on request_logs.created_at timestamps.
        # Count all attempts (successful or not) as requests (common provider behavior).
        # minute_quota/daily_quota are >=0; if 0, no requests allowed.
        if not isinstance(minute_quota, int) or not isinstance(daily_quota, int):
            return _err("VALIDATION_ERROR", "API key quotas are misconfigured.")

        if minute_quota == 0 or daily_quota == 0:
            return _err("QUOTA_EXCEEDED", "Request quota exceeded.")

        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(row):
            ts = row.get("created_at")
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except ValueError:
                return None

        per_min = 0
        per_day = 0
        for r in request_logs_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r)
            if dt is None:
                continue
            if dt >= day_ago and dt <= now_dt:
                per_day += 1
                if dt >= minute_ago:
                    per_min += 1

        if per_min + 1 > minute_quota:
            return _err("RATE_LIMIT", "Minute request quota exceeded.")
        if per_day + 1 > daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    t0 = time.perf_counter()
    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")

    # Validate request schema: only allowed properties exist (additionalProperties=false).
    # Tool signature already constrains, but still validate types/rules.
    params = {"symbol": symbol, "interval": interval}
    if from_ is not None:
        params["from"] = from_
    if to is not None:
        params["to"] = to

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)

    api_key = _authenticate_active_key(api_keys)
    if api_key is None:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": (api_keys[0]["id"] if api_keys and isinstance(api_keys[0], dict) and "id" in api_keys[0] else "unknown"),
            "tool_name": "getIntradayChart",
            "params": params,
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "API key is missing, inactive, suspended, or revoked.")

    quota_err = _enforce_quota(api_key["id"], api_key.get("minute_request_quota", 0), api_key.get("daily_request_quota", 0), req_logs, now_dt)
    if quota_err is not None:
        http_status = _http_status_for_error(quota_err["error"]["code"])
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getIntradayChart",
            "params": params,
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": quota_err["error"]["code"],
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return quota_err

    # Validate inputs
    if not isinstance(symbol, str) or not symbol.strip():
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getIntradayChart",
            "params": params,
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")

    allowed_intervals = {"1min", "5min", "15min", "30min", "1hour", "4hour"}
    if not isinstance(interval, str) or interval not in allowed_intervals:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getIntradayChart",
            "params": params,
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "interval is not supported.", allowed=list(sorted(allowed_intervals)))

    d_from = None
    d_to = None
    if from_ is not None:
        d_from = _parse_iso_date(from_)
        if d_from is None:
            duration_ms = int((time.perf_counter() - t0) * 1000)
            log_row = {
                "id": _mk_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getIntradayChart",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            req_logs.append(log_row)
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "from must be a valid ISO date YYYY-MM-DD.")
    if to is not None:
        d_to = _parse_iso_date(to)
        if d_to is None:
            duration_ms = int((time.perf_counter() - t0) * 1000)
            log_row = {
                "id": _mk_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getIntradayChart",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            req_logs.append(log_row)
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "to must be a valid ISO date YYYY-MM-DD.")
    if d_from is not None and d_to is not None and d_from > d_to:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getIntradayChart",
            "params": params,
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "from must be <= to.")

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")

    norm_symbol = symbol.strip().upper()

    # Symbol lookup with uniqueness semantics:
    # - If multiple instruments share normalized_symbol across different exchanges, accept all;
    #   intraday chart is symbol-based (no exchange param), so aggregate by symbol.
    # Authorization allowlists
    allowed_asset_types = api_key.get("allowed_asset_types")
    allowed_exchanges = api_key.get("allowed_exchanges")

    inst_matches = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("normalized_symbol") != norm_symbol:
            continue
        if inst.get("status") not in ("active", "inactive", "delisted"):
            continue
        if allowed_asset_types is not None:
            if inst.get("asset_type") not in set(allowed_asset_types):
                continue
        if allowed_exchanges is not None:
            ex = inst.get("exchange")
            if ex not in set(allowed_exchanges):
                continue
        inst_matches.append(inst)

    if not inst_matches:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getIntradayChart",
            "params": params,
            "http_status": 404,
            "cache_status": "miss",
            "duration_ms": duration_ms,
            "result_count": 0,
            "error_code": "NOT_FOUND",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "Symbol not found or not permitted for this API key.", symbol=norm_symbol)

    # Collect datapoints for all matching instruments (typical provider returns per symbol;
    # our store may have multiple exchange variants; merge by timestamp).
    timeframe = interval
    # Intraday charts are unadjusted, regular session by default.
    adjustment_type = "unadjusted"
    session = "regular"

    inst_ids = {i.get("id") for i in inst_matches if isinstance(i.get("id"), str)}
    rows = []
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") not in inst_ids:
            continue
        if r.get("timeframe") != timeframe:
            continue
        if r.get("adjustment_type") != adjustment_type:
            continue
        if r.get("session") != session:
            continue
        td = r.get("trade_date")
        if d_from is not None or d_to is not None:
            if not isinstance(td, str):
                continue
            d_td = _parse_iso_date(td)
            if d_td is None:
                continue
            if d_from is not None and d_td < d_from:
                continue
            if d_to is not None and d_td > d_to:
                continue
        rows.append(r)

    # Sort by timestamp ascending
    def _parse_ts_sort(v):
        ts = v.get("ts")
        if not isinstance(ts, str):
            return ""
        return ts

    rows.sort(key=_parse_ts_sort)

    # Server-side max rows per response (policy). FMP typically caps; enforce a safe cap.
    MAX_ROWS = 10000
    if len(rows) > MAX_ROWS:
        rows = rows[-MAX_ROWS:]

    # Shape response similar to FMP chart: list of bars with date + OHLCV
    out = []
    for r in rows:
        out.append({
            "date": r.get("ts"),
            "open": r.get("open"),
            "high": r.get("high"),
            "low": r.get("low"),
            "close": r.get("close"),
            "volume": r.get("volume"),
            "vwap": r.get("vwap"),
        })

    # Update last_used_at on success (authenticated request)
    api_key["last_used_at"] = _now_iso()
    api_key["updated_at"] = _now_iso()
    for idx, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            api_keys[idx] = api_key
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.perf_counter() - t0) * 1000)
    log_row = {
        "id": _mk_log_id(),
        "api_key_id": api_key["id"],
        "tool_name": "getIntradayChart",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(out),
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    req_logs.append(log_row)
    _save("request_logs.json", req_logs)

    return {
        "symbol": norm_symbol,
        "interval": timeframe,
        "from": from_,
        "to": to,
        "count": len(out),
        "data": out,
    }

