                        "updated_at": _now_iso(),
                    }
                )
                _save("request_logs.json", req_logs)
                return _err("UNAUTHORIZED", "API key not entitled for this exchange.")

    # Latest snapshot if symbol exists
    snap = None
    if inst is not None:
        md = _load("market_data_points.json")
        for r in md:
            if r.get("instrument_id") == inst.get("id") and r.get("timeframe") == "1day" and r.get("adjustment_type") == "unadjusted" and r.get("session") == "regular" and r.get("is_latest_snapshot") is True:
