        "instrumentStatus": inst.get("status") if inst else None,
    }
    if snap:
        profile.update(
            {
                "price": snap.get("close"),
                "changes": snap.get("change"),
                "changesPercentage": snap.get("change_percent"),
                "timestamp": snap.get("ts"),
                "volume": snap.get("volume"),
            }
        )

    # Update last_used_at on success
    for k in api_keys:
        if k.get("id") == active_key.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    req_logs.append(
        {
            "id": _mk_id("req"),
            "api_key_id": active_key["id"],
            "tool_name": tool_name,
            "params": {"cik": cik},
            "http_status": 200,
            "cache_status": "miss",
            "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
            "result_count": 1,
            "error_code": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
    )
    _save("request_logs.json", req_logs)

    return {"data": profile}

def getCompanyNotes(symbol, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mk_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_iso_z(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    t0 = time.perf_counter()
    tool_name = "getCompanyNotes"

    if not isinstance(symbol, str):
        api_keys = _load("api_keys.json")
        req_logs = _load("request_logs.json")
        active_key = next((k for k in api_keys if k.get("status") == "active"), None)
        status = 401 if active_key is None else 400
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": active_key["id"] if active_key else "unknown",
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": status,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": None,
                "error_code": "UNAUTHORIZED" if active_key is None else "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        if active_key is None:
            return _err("UNAUTHORIZED", "Missing/invalid API key.")
        return _err("VALIDATION_ERROR", "symbol must be a string.")

    sym = symbol.strip()
    if sym == "":
        api_keys = _load("api_keys.json")
        req_logs = _load("request_logs.json")
        active_key = next((k for k in api_keys if k.get("status") == "active"), None)
        status = 401 if active_key is None else 400
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": active_key["id"] if active_key else "unknown",
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": status,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": None,
                "error_code": "UNAUTHORIZED" if active_key is None else "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        if active_key is None:
            return _err("UNAUTHORIZED", "Missing/invalid API key.")
        return _err("VALIDATION_ERROR", "symbol must not be blank.")

    normalized_symbol = sym.upper()

    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")
    now = datetime.datetime.utcnow()

    def _within(dt, seconds):
        return dt is not None and 0 <= (now - dt).total_seconds() <= seconds

    def _count_logs_for_key(key_id, window_seconds):
        c = 0
        for r in req_logs:
            if r.get("api_key_id") != key_id:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if _within(dt, window_seconds):
                c += 1
        return c

    active_key = next((k for k in api_keys if k.get("status") == "active"), None)
    if active_key is None:
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": "unknown",
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": 401,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": None,
                "error_code": "UNAUTHORIZED",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "Missing/invalid API key.")

    minute_quota = active_key.get("minute_request_quota")
    daily_quota = active_key.get("daily_request_quota")
    if minute_quota == 0 or (isinstance(minute_quota, int) and _count_logs_for_key(active_key["id"], 60) >= minute_quota):
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": active_key["id"],
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": 429,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": None,
                "error_code": "RATE_LIMIT",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        return _err("RATE_LIMIT", "Minute request quota exceeded.")
    if daily_quota == 0 or (isinstance(daily_quota, int) and _count_logs_for_key(active_key["id"], 86400) >= daily_quota):
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": active_key["id"],
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": 429,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": None,
                "error_code": "QUOTA_EXCEEDED",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    instruments = _load("instruments.json")
    equities = [i for i in instruments if i.get("normalized_symbol") == normalized_symbol and i.get("asset_type") == "equity"]
    inst = None
    if equities:
        active = [i for i in equities if i.get("status") == "active"]
        primary = [i for i in active if i.get("primary_listing_symbol_id") is None]
        inst = (primary or active or equities)[0]

    if inst is None:
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": active_key["id"],
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": 404,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": 0,
                "error_code": "NOT_FOUND",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "Symbol not found.")

    # Enforce allowlists
    if isinstance(active_key.get("allowed_asset_types"), list) and active_key["allowed_asset_types"]:
        if inst.get("asset_type") not in active_key["allowed_asset_types"]:
            req_logs.append(
                {
                    "id": _mk_id("req"),
                    "api_key_id": active_key["id"],
                    "tool_name": tool_name,
                    "params": {"symbol": symbol},
                    "http_status": 403,
                    "cache_status": "bypass",
                    "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                    "result_count": None,
                    "error_code": "UNAUTHORIZED",
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                }
            )
            _save("request_logs.json", req_logs)
            return _err("UNAUTHORIZED", "API key not entitled for this asset type.")
    if isinstance(active_key.get("allowed_exchanges"), list) and active_key["allowed_exchanges"]:
        ex = inst.get("exchange")
        if ex is not None and ex not in active_key["allowed_exchanges"]:
            req_logs.append(
                {
                    "id": _mk_id("req"),
                    "api_key_id": active_key["id"],
                    "tool_name": tool_name,
                    "params": {"symbol": symbol},
                    "http_status": 403,
                    "cache_status": "bypass",
                    "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                    "result_count": None,
                    "error_code": "UNAUTHORIZED",
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                }
            )
            _save("request_logs.json", req_logs)
            return _err("UNAUTHORIZED", "API key not entitled for this exchange.")

    entities = _load("entities.json")
    ent = None
    if isinstance(inst.get("entity_id"), str):
        ent = next((e for e in entities if e.get("id") == inst.get("entity_id")), None)

    # Notes: stored as content_items of type 'note'
    content = _load("content_items.json")
    notes = []
    for c in content:
        if c.get("content_type") != "note":
            continue
        if c.get("status") != "active":
            continue
        # associate by instrument_id or entity_id
        if c.get("instrument_id") == inst.get("id") or (ent and c.get("entity_id") == ent.get("id")):
            notes.append(c)

    if not notes:
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": active_key["id"],
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": 404,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": 0,
                "error_code": "NOT_FOUND",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "No notes found for symbol.")

    # sort most recent first by as_of_date then created_at
    def _date_key(item):
        d = item.get("as_of_date")
        try:
            dd = datetime.date.fromisoformat(d) if isinstance(d, str) else None
        except Exception:
            dd = None
        ca = _parse_iso_z(item.get("created_at"))
        return (dd or datetime.date.min, ca or datetime.datetime.min)

    notes.sort(key=_date_key, reverse=True)

    out = []
    for c in notes:
        out.append(
            {
                "symbol": inst.get("symbol"),
                "exchange": inst.get("exchange"),
                "cik": ent.get("cik") if ent else None,
                "title": c.get("title"),
                "date": c.get("as_of_date"),
                "url": c.get("url"),
                "payload": c.get("payload"),
            }
        )

    # Update last_used_at
    for k in api_keys:
        if k.get("id") == active_key.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    req_logs.append(
        {
            "id": _mk_id("req"),
            "api_key_id": active_key["id"],
            "tool_name": tool_name,
            "params": {"symbol": symbol},
            "http_status": 200,
            "cache_status": "miss",
            "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
            "result_count": len(out),
            "error_code": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
    )
    _save("request_logs.json", req_logs)

    return {"data": out}

