    if isinstance(active_key.get("allowed_exchanges"), list) and active_key["allowed_exchanges"]:
        ex = inst.get("exchange")
        if ex is not None and ex not in active_key["allowed_exchanges"]:
            req_logs.append(
                {
                    "id": _mk_id("req"),
                    "api_key_id": active_key["id"],
                    "tool_name": tool_name,
                    "params": {"symbol": symbol},
                    "http_status": 403,
                    "cache_status": "bypass",
                    "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                    "result_count": None,
                    "error_code": "UNAUTHORIZED",
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                }
            )
            _save("request_logs.json", req_logs)
            return _err("UNAUTHORIZED", "API key not entitled for this exchange.")

    # Peer set: stored in content_items as content_type 'peers' in payload.
    # Since schema enum doesn't include 'peers', we model this using an existing type that can carry peer sets.
    # Use content_type 'scores' with identifier_1='peers' (deterministic convention) and instrument_id match.
    content = _load("content_items.json")
    peer_item = None
    for c in content:
        if c.get("status") != "active":
            continue
        if c.get("instrument_id") != inst.get("id"):
            continue
        if c.get("content_type") == "scores" and c.get("identifier_1") == "peers":
            peer_item = c
            break

    peers = None
    if peer_item and isinstance(peer_item.get("payload"), dict):
        peers = peer_item["payload"].get("peers")

    # Fallback: compute simple peers by same exchange + same sector (if no stored peer set)
    if not isinstance(peers, list) or not peers:
        ex = inst.get("exchange")
        sector = inst.get("sector")
        candidates = []
        for i in instruments:
            if i.get("asset_type") != "equity":
                continue
            if i.get("status") != "active":
                continue
            if ex is not None and i.get("exchange") != ex:
                continue
            if sector is not None and i.get("sector") != sector:
                continue
            if i.get("normalized_symbol") != inst.get("normalized_symbol"):
                candidates.append(i.get("symbol"))
        # cap peers
        candidates = [s for s in candidates if isinstance(s, str)]
        candidates = list(dict.fromkeys(candidates))[:50]
        peers = candidates

    if not peers:
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": active_key["id"],
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": 404,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": 0,
                "error_code": "NOT_FOUND",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "No peer set available for symbol.")

    # Normalize output to list of tickers excluding itself, unique
    out = []
    seen = set()
    for p in peers:
        if not isinstance(p, str):
            continue
        ps = p.strip()
        if not ps:
            continue
        if ps.upper() == normalized_symbol:
            continue
        if ps.upper() in seen:
            continue
        seen.add(ps.upper())
        out.append(ps.upper())

    if not out:
        req_logs.append(
            {
                "id": _mk_id("req"),
                "api_key_id": active_key["id"],
                "tool_name": tool_name,
                "params": {"symbol": symbol},
                "http_status": 404,
                "cache_status": "bypass",
                "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
                "result_count": 0,
                "error_code": "NOT_FOUND",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
        )
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "No peer set available for symbol.")

    # Update last_used_at
    for k in api_keys:
        if k.get("id") == active_key.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    req_logs.append(
        {
            "id": _mk_id("req"),
            "api_key_id": active_key["id"],
            "tool_name": tool_name,
            "params": {"symbol": symbol},
            "http_status": 200,
            "cache_status": "miss",
            "duration_ms": max(0, int((time.perf_counter() - t0) * 1000)),
            "result_count": len(out),
            "error_code": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
    )
    _save("request_logs.json", req_logs)

    return {"data": out}

def getDelistedCompanies(page=None, limit=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "getDelistedCompanies"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_num_int(x):
        if x is None:
            return None
        if isinstance(x, bool):
            return None
        if isinstance(x, (int, float)):
            if isinstance(x, float) and (math.isnan(x) or math.isinf(x)):
                return None
            if float(x).is_integer():
                return int(x)
            return None
        return None

    # Validate params (additionalProperties already prevented by signature)
    v_page = 0 if page is None else _parse_num_int(page)
    v_limit = 100 if limit is None else _parse_num_int(limit)
    if v_page is None or v_page < 0:
        # log (unauth/quotas still need auth; but validation happens first; still must log with an api key attempt)
        v_page = page
        v_limit = limit
        # proceed to auth selection for logging
        pass
    if v_limit is None or v_limit <= 0 or v_limit > 100:
        pass

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    # authenticate ambient: choose any active key that can serve (quota not exceeded)
    now = datetime.datetime.utcnow()

    def _dt_parse(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _count_in_window(key_id, delta):
        start = now - delta
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            dt = _dt_parse(r.get("created_at"))
            if dt is None:
                continue
            if dt >= start:
                c += 1
        return c

    def _pick_key():
        candidates = [k for k in api_keys if k.get("status") == "active"]
        # Prefer keys under quota; deterministic by id
        candidates.sort(key=lambda x: x.get("id", ""))
        for k in candidates:
            kid = k.get("id")
            if not kid:
                continue
            minute_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(minute_q, int) or minute_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue
            if _count_in_window(kid, datetime.timedelta(minutes=1)) >= minute_q:
                continue
            if _count_in_window(kid, datetime.timedelta(days=1)) >= day_q:
                continue
            return k
        # if there are active keys but all over quota, return sentinel
        if candidates:
            return "OVER_QUOTA"
        return None

    key = _pick_key()
    # Determine outcome, then log exactly once
    status = 200
    cache_status = "bypass"
    error_code = None
    result = None
    result_count = None

    # finalize validation properly now
    validation_errors = []
    vp = 0 if page is None else _parse_num_int(page)
    vl = 100 if limit is None else _parse_num_int(limit)
    if vp is None or vp < 0:
        validation_errors.append({"field": "page", "message": "page must be an integer >= 0"})
    if vl is None or vl <= 0 or vl > 100:
        validation_errors.append({"field": "limit", "message": "limit must be an integer between 1 and 100"})
    if validation_errors:
        status = 400
        error_code = "VALIDATION_ERROR"
        result = _err("VALIDATION_ERROR", "Invalid parameters.", details=validation_errors)
    else:
        if key is None:
            status = 401
            error_code = "UNAUTHORIZED"
            result = _err("UNAUTHORIZED", "Missing/invalid API key.")
        elif key == "OVER_QUOTA":
            status = 429
            error_code = "QUOTA_EXCEEDED"
            result = _err("QUOTA_EXCEEDED", "API key quota exceeded.")
        else:
            # query delisted instruments (companies -> equity instruments)
            instruments = _load("instruments.json")
            # Delisted companies: US exchanges
            rows = []
            for inst in instruments:
                if inst.get("asset_type") != "equity":
                    continue
                if inst.get("is_delisted") is not True and inst.get("status") != "delisted":
                    continue
                country = inst.get("country")
                if country is not None and isinstance(country, str) and country.upper() != "US":
                    continue
                exchange = inst.get("exchange")
                # "US exchanges": require exchange not null and not empty
                if exchange is None or (isinstance(exchange, str) and exchange.strip() == ""):
                    continue
                rows.append(inst)
            # deterministic ordering: most recently updated/created first then symbol
            def _ts_key(r):
                u = _dt_parse(r.get("updated_at")) or _dt_parse(r.get("created_at")) or datetime.datetime.min
                return u
            rows.sort(key=lambda r: (_ts_key(r), r.get("normalized_symbol") or ""), reverse=True)

            total = len(rows)
            start = vp * vl
            end = start + vl
            page_rows = rows[start:end] if start < total else []
            result_count = len(page_rows)
            # shape response like list
            result = {
                "data": [
                    {
                        "symbol": r.get("symbol"),
                        "companyName": r.get("name"),
                        "exchange": r.get("exchange"),
                        "country": r.get("country"),
                        "isDelisted": bool(r.get("is_delisted")),
                        "status": r.get("status"),
                        "updatedAt": r.get("updated_at"),
                    }
                    for r in page_rows
                ],
                "meta": {
                    "page": vp,
                    "limit": vl,
                    "total": total,
                    "has_more": end < total,
                    "next_page": (vp + 1) if end < total else None,
                }
            }
            # update key last_used_at on successful authenticated request
            for k in api_keys:
                if k.get("id") == key.get("id"):
                    k["last_used_at"] = _iso_now()
                    k["updated_at"] = _iso_now()
                    _save("api_keys.json", api_keys)
                    break

    # write request log (always exactly one)
    api_key_id_for_log = None
    if isinstance(key, dict):
        api_key_id_for_log = key.get("id")
    else:
        # if no active key exists, still must log attempt; pick any key id if exists else synthetic
        if api_keys and isinstance(api_keys, list):
            api_key_id_for_log = api_keys[0].get("id") or "unknown"
        else:
            api_key_id_for_log = "unknown"

    # params must conform to schema: only page, limit
    log_params = {}
    if page is not None:
        log_params["page"] = page
    if limit is not None:
        log_params["limit"] = limit

    rid = "req_" + uuid.uuid4().hex
    created = _iso_now()
    duration_ms = max(0, int((time.time() - _t0) * 1000))
    request_logs.append({
        "id": rid,
        "api_key_id": api_key_id_for_log,
        "tool_name": tool_name,
        "params": log_params,
        "http_status": int(status),
        "cache_status": cache_status,
        "duration_ms": int(duration_ms),
        "result_count": result_count,
        "error_code": error_code,
        "created_at": created,
        "updated_at": created,
    })
    _save("request_logs.json", request_logs)

    return result

