def getMarketCap(symbol, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "getMarketCap"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    now = datetime.datetime.utcnow()

    def _dt_parse(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _count_in_window(key_id, delta):
        start = now - delta
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            dt = _dt_parse(r.get("created_at"))
            if dt is None:
                continue
            if dt >= start:
                c += 1
        return c

    def _pick_key():
        candidates = [k for k in api_keys if k.get("status") == "active"]
        candidates.sort(key=lambda x: x.get("id", ""))
        for k in candidates:
            kid = k.get("id")
            if not kid:
                continue
            minute_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(minute_q, int) or minute_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue
            if _count_in_window(kid, datetime.timedelta(minutes=1)) >= minute_q:
                continue
            if _count_in_window(kid, datetime.timedelta(days=1)) >= day_q:
                continue
            return k
        if candidates:
            return "OVER_QUOTA"
        return None

    key = _pick_key()

    status = 200
    cache_status = "bypass"
    error_code = None
    result = None
    result_count = None

    # validate
    if not isinstance(symbol, str) or symbol.strip() == "":
        status = 400
        error_code = "VALIDATION_ERROR"
        result = _err("VALIDATION_ERROR", "Invalid parameters.", details=[{"field": "symbol", "message": "symbol must be a non-empty string"}])
    else:
        if key is None:
            status = 401
            error_code = "UNAUTHORIZED"
            result = _err("UNAUTHORIZED", "Missing/invalid API key.")
        elif key == "OVER_QUOTA":
            status = 429
            error_code = "QUOTA_EXCEEDED"
            result = _err("QUOTA_EXCEEDED", "API key quota exceeded.")
        else:
            norm = symbol.strip().upper()
            instruments = _load("instruments.json")
            inst = None
            for r in instruments:
                if r.get("normalized_symbol") == norm:
                    inst = r
                    break
            if inst is None:
                status = 404
                error_code = "NOT_FOUND"
                result = _err("NOT_FOUND", "Unknown symbol.")
            else:
                content = _load("content_items.json")
                points = []
                for it in content:
                    if it.get("status") != "active":
                        continue
                    if it.get("instrument_id") != inst.get("id"):
                        continue
                    payload = it.get("payload")
                    if not isinstance(payload, dict):
                        continue
                    mc = payload.get("marketCap")
                    if mc is None:
                        mc = payload.get("marketCapitalization")
                    if mc is None:
                        continue
                    date = payload.get("date") or it.get("as_of_date") or payload.get("asOfDate")
                    points.append({
                        "symbol": inst.get("symbol"),
                        "date": date,
                        "marketCap": mc,
                        "source": payload.get("source") or it.get("content_type"),
                    })
                if not points:
                    status = 404
                    error_code = "NOT_FOUND"
                    result = _err("NOT_FOUND", "No market-cap data found for symbol.")
                else:
                    points.sort(key=lambda x: (x.get("date") or ""), reverse=True)
                    result_count = len(points)
                    result = {"data": points, "meta": {"returned": result_count}}
                    for k in api_keys:
                        if k.get("id") == key.get("id"):
                            k["last_used_at"] = _iso_now()
                            k["updated_at"] = _iso_now()
                            _save("api_keys.json", api_keys)
                            break

    api_key_id_for_log = None
    if isinstance(key, dict):
        api_key_id_for_log = key.get("id")
    else:
        api_key_id_for_log = (api_keys[0].get("id") if api_keys else None) or "unknown"

    log_params = {"symbol": symbol}

    rid = "req_" + uuid.uuid4().hex
    created = _iso_now()
    duration_ms = max(0, int((time.time() - _t0) * 1000))
    request_logs.append({
        "id": rid,
        "api_key_id": api_key_id_for_log,
        "tool_name": tool_name,
        "params": log_params,
        "http_status": int(status),
        "cache_status": cache_status,
        "duration_ms": int(duration_ms),
        "result_count": result_count,
        "error_code": error_code,
        "created_at": created,
        "updated_at": created,
    })
    _save("request_logs.json", request_logs)

    return result

def getBatchMarketCap(symbols, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getBatchMarketCap"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    def _iso_now_z(dt=None):
        dt = dt or datetime.datetime.now(datetime.timezone.utc)
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                base = s[:-1]
                dt = datetime.datetime.fromisoformat(base)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        seed = hashlib.sha1((str(time.time()) + "|" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{seed}"

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        now_iso = _iso_now_z(now_dt)
        duration_ms = int((time.time() - t0) * 1000)
        if duration_ms < 0:
            duration_ms = 0
        row = {
            "id": _new_id("fmp_req"),
            "api_key_id": api_key_id if isinstance(api_key_id, str) else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status) if isinstance(http_status, int) or (isinstance(http_status, float) and http_status.is_integer()) else 500,
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (int(result_count) if isinstance(result_count, int) and result_count >= 0 else (None if result_count is None else None)),
            "error_code": error_code if isinstance(error_code, str) else None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _select_active_key_for_request():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None, _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _count_for(kid):
            m = d = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                dt = _parse_dt_any(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= minute_ago:
                    m += 1
                if dt >= day_ago:
                    d += 1
            return m, d

        best = None
        best_headroom = None
        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            kid = k["id"]
            m, d = _count_for(kid)
            # If quotas are 0, treat as no allowance.
            if min_q and m + 1 > min_q:
                continue
            if day_q and d + 1 > day_q:
                continue
            headroom = (min_q - (m + 1) if min_q else 10**18) + (day_q - (d + 1) if day_q else 10**18)
            if best is None or headroom > best_headroom:
                best = k
                best_headroom = headroom

        if best is None:
            # decide which quota exceeded (minute takes precedence)
            for k in active:
                min_q = k.get("minute_request_quota")
                day_q = k.get("daily_request_quota")
                if not isinstance(min_q, int) or min_q < 0:
                    min_q = 0
                if not isinstance(day_q, int) or day_q < 0:
                    day_q = 0
                m, d = _count_for(k["id"])
                if min_q and m + 1 > min_q:
                    return None, _err("RATE_LIMIT", "Request quota exceeded.", reason="quota_minute_exceeded", http_status=429)
                if day_q and d + 1 > day_q:
                    return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", reason="quota_daily_exceeded", http_status=429)
            return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)
        return best, None

    # Validate inputs
    params_obj = {"symbols": symbols}
    if not isinstance(symbols, str) or not symbols.strip():
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`symbols` must be a non-empty comma-separated string.", http_status=400)
        _log(kid, params_obj, err["error"]["http_status"], result_count=None, error_code="validation_error")
        return err

    # Parse symbols
    raw = [s.strip() for s in symbols.split(",")]
    norm_syms = []
    seen = set()
    for s in raw:
        if not s:
            continue
        ns = s.upper()
        if ns not in seen:
            seen.add(ns)
            norm_syms.append(ns)
    if not norm_syms:
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`symbols` must contain at least one symbol.", http_status=400)
        _log(kid, params_obj, err["error"]["http_status"], result_count=None, error_code="validation_error")
        return err
    if len(norm_syms) > 100:
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "Too many symbols requested (max 100).", http_status=400)
        _log(kid, params_obj, err["error"]["http_status"], result_count=None, error_code="validation_error")
        return err

    key, kerr = _select_active_key_for_request()
    if kerr:
        kid = "unknown"
        _log(kid, params_obj, kerr["error"].get("http_status", 401), result_count=None, error_code=kerr["error"].get("reason") or kerr["error"]["code"].lower())
        return kerr
    kid = key["id"]

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")
    if not isinstance(instruments, list):
        instruments = []
    if not isinstance(mdp, list):
        mdp = []

    # map symbol -> instrument_id list (FMP uniqueness semantics: exchange variants possible)
    sym_to_insts = {}
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        ns = ins.get("normalized_symbol")
        if isinstance(ns, str) and ns in norm_syms:
            sym_to_insts.setdefault(ns, []).append(ins)

    # allowed filters enforcement if present on key
    allowed_exchanges = key.get("allowed_exchanges")
    if not (allowed_exchanges is None or isinstance(allowed_exchanges, list)):
        allowed_exchanges = None
    allowed_asset_types = key.get("allowed_asset_types")
    if not (allowed_asset_types is None or isinstance(allowed_asset_types, list)):
        allowed_asset_types = None

    def _asset_to_key_asset(asset_type):
        # map datastore asset_type to createApiKey allowed_asset_types vocabulary
        if asset_type == "equity":
            return "stock"
        if asset_type == "etf":
            return "etf"
        if asset_type == "mutual_fund":
            return "fund"
        if asset_type == "forex":
            return "forex"
        if asset_type == "crypto":
            return "crypto"
        if asset_type == "commodity":
            return "commodity"
        if asset_type == "index":
            return "index"
        return asset_type

    # pick latest market cap from content_items if available, else approximate from mdp.payload if present
    content = _load("content_items.json")
    if not isinstance(content, list):
        content = []

    results = []
    for sym in norm_syms:
        insts = sym_to_insts.get(sym, [])
        # apply entitlement filters: exchange and asset types
        filtered_insts = []
        for ins in insts:
            ex = ins.get("exchange")
            at = ins.get("asset_type")
            if allowed_exchanges is not None and ex is not None and ex not in allowed_exchanges:
                continue
            if allowed_asset_types is not None:
                mapped = _asset_to_key_asset(at)
                if mapped not in allowed_asset_types:
                    continue
            filtered_insts.append(ins)

        # for each instrument variant, try find market cap series in content_items content_type 'key_metrics'/'ratios'/'financial_report' etc.
        for ins in filtered_insts:
            ins_id = ins.get("id")
            if not isinstance(ins_id, str):
                continue
            # gather all content items about market cap
            rows = []
            for ci in content:
                if not isinstance(ci, dict) or ci.get("instrument_id") != ins_id:
                    continue
                payload = ci.get("payload")
                if not isinstance(payload, dict):
                    continue
                # accept if payload has marketCap and a date-like field
                mc = payload.get("marketCap")
                if mc is None:
                    mc = payload.get("marketcap")
                if mc is None:
                    continue
                asof = ci.get("as_of_date") or payload.get("date") or payload.get("asOfDate")
                if not isinstance(asof, str):
                    asof = None
                rows.append({
                    "symbol": ins.get("symbol") or sym,
                    "date": asof,
                    "marketCap": mc,
                    "exchange": ins.get("exchange"),
                    "currency": ins.get("currency"),
                })
            # fallback: if no content rows, provide snapshot from latest quote row if it carries marketCap
            if not rows:
                latest = None
                for r in mdp:
                    if not isinstance(r, dict) or r.get("instrument_id") != ins_id:
                        continue
                    if r.get("timeframe") != "1day" or r.get("session") != "regular" or r.get("adjustment_type") != "unadjusted" or r.get("is_latest_snapshot") is not True:
                        continue
                    latest = r
                    break
                if latest and isinstance(latest.get("change"), (int, float)):  # arbitrary signal; try payload-like fields not present; keep minimal
                    # no true marketCap in mdp schema; return empty for this instrument
                    rows = []
            # sort rows by date desc if date available
            def _date_key(x):
                d = x.get("date")
                try:
                    return datetime.date.fromisoformat(d) if isinstance(d, str) and len(d) == 10 else datetime.date.min
                except Exception:
                    return datetime.date.min
            rows.sort(key=_date_key, reverse=True)
            results.extend(rows)

    if not results:
        err = _err("NOT_FOUND", "None of the requested symbols have market cap data.", http_status=404)
        _log(kid, {"symbols": symbols}, 404, result_count=0, error_code="symbol_not_found")
        return err

    # Update last_used_at on successful authenticated request
    keys_all = _load("api_keys.json")
    if isinstance(keys_all, list):
        changed = False
        for k in keys_all:
            if isinstance(k, dict) and k.get("id") == kid:
                k["last_used_at"] = _iso_now_z(now_dt)
                k["updated_at"] = _iso_now_z(now_dt)
                changed = True
                break
        if changed:
            _save("api_keys.json", keys_all)

    _log(kid, {"symbols": symbols}, 200, result_count=len(results), error_code=None)
    return {"data": results, "meta": {"requested": len(norm_syms), "returned": len(results)}}

def getHistoricalMarketCap(symbol, limit=None, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_date(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.date.fromisoformat(s)
        except ValueError:
            return None

    def _mk_log_id():
        return "rlog_" + uuid.uuid4().hex

    def _http_status_for_error(code):
        if code in ("UNAUTHORIZED",):
            return 401
        if code in ("RATE_LIMIT", "QUOTA_EXCEEDED"):
            return 429
        if code in ("NOT_FOUND",):
            return 404
        if code in ("CONFLICT", "INVALID_TRANSITION", "VALIDATION_ERROR"):
            return 400
        return 400

    def _authenticate_active_key(api_keys_rows):
        for k in api_keys_rows:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota(api_key_id, minute_quota, daily_quota, request_logs_rows, now_dt):
        if not isinstance(minute_quota, int) or not isinstance(daily_quota, int):
            return _err("VALIDATION_ERROR", "API key quotas are misconfigured.")
        if minute_quota == 0 or daily_quota == 0:
            return _err("QUOTA_EXCEEDED", "Request quota exceeded.")

        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(row):
            ts = row.get("created_at")
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except ValueError:
                return None

        per_min = 0
        per_day = 0
        for r in request_logs_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r)
            if dt is None:
                continue
            if dt >= day_ago and dt <= now_dt:
                per_day += 1
                if dt >= minute_ago:
                    per_min += 1

        if per_min + 1 > minute_quota:
            return _err("RATE_LIMIT", "Minute request quota exceeded.")
        if per_day + 1 > daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    t0 = time.perf_counter()
    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")

    params = {"symbol": symbol}
    if limit is not None:
        params["limit"] = limit
    if from_ is not None:
        params["from"] = from_
    if to is not None:
        params["to"] = to

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)

    api_key = _authenticate_active_key(api_keys)
    if api_key is None:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": (api_keys[0]["id"] if api_keys and isinstance(api_keys[0], dict) and "id" in api_keys[0] else "unknown"),
            "tool_name": "getHistoricalMarketCap",
            "params": params,
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "API key is missing, inactive, suspended, or revoked.")

    quota_err = _enforce_quota(api_key["id"], api_key.get("minute_request_quota", 0), api_key.get("daily_request_quota", 0), req_logs, now_dt)
    if quota_err is not None:
        http_status = _http_status_for_error(quota_err["error"]["code"])
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getHistoricalMarketCap",
            "params": params,
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": quota_err["error"]["code"],
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return quota_err

    # Validate inputs
    if not isinstance(symbol, str) or not symbol.strip():
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getHistoricalMarketCap",
            "params": params,
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")

    if limit is None:
        limit_i = 100
    else:
        # schema says number; accept int-like floats but enforce integer semantics
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            duration_ms = int((time.perf_counter() - t0) * 1000)
            log_row = {
                "id": _mk_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getHistoricalMarketCap",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            req_logs.append(log_row)
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "limit must be a number.")
        if int(limit) != limit:
            # don't allow non-integer limits
            duration_ms = int((time.perf_counter() - t0) * 1000)
            log_row = {
                "id": _mk_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getHistoricalMarketCap",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            req_logs.append(log_row)
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        limit_i = int(limit)

    if limit_i < 1 or limit_i > 5000:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getHistoricalMarketCap",
            "params": params,
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 5000.")

    d_from = None
    d_to = None
    if from_ is not None:
        d_from = _parse_iso_date(from_)
        if d_from is None:
            duration_ms = int((time.perf_counter() - t0) * 1000)
            log_row = {
                "id": _mk_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getHistoricalMarketCap",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            req_logs.append(log_row)
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "from must be a valid ISO date YYYY-MM-DD.")
    if to is not None:
        d_to = _parse_iso_date(to)
        if d_to is None:
            duration_ms = int((time.perf_counter() - t0) * 1000)
            log_row = {
                "id": _mk_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getHistoricalMarketCap",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            req_logs.append(log_row)
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "to must be a valid ISO date YYYY-MM-DD.")
    if d_from is not None and d_to is not None and d_from > d_to:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getHistoricalMarketCap",
            "params": params,
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "from must be <= to.")

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")

    norm_symbol = symbol.strip().upper()

    allowed_asset_types = api_key.get("allowed_asset_types")
    allowed_exchanges = api_key.get("allowed_exchanges")

    inst_matches = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("normalized_symbol") != norm_symbol:
            continue
        if allowed_asset_types is not None and inst.get("asset_type") not in set(allowed_asset_types):
            continue
        if allowed_exchanges is not None:
            if inst.get("exchange") not in set(allowed_exchanges):
                continue
        inst_matches.append(inst)

    if not inst_matches:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getHistoricalMarketCap",
            "params": params,
            "http_status": 404,
            "cache_status": "miss",
            "duration_ms": duration_ms,
            "result_count": 0,
            "error_code": "NOT_FOUND",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "Symbol not found or not permitted for this API key.", symbol=norm_symbol)

    inst_ids = {i.get("id") for i in inst_matches if isinstance(i.get("id"), str)}

    # Compute market cap time series from 1day unadjusted regular close and payload sharesOut
    # Store does not have separate market-cap rows; derive from content_items key_metrics payload.
    content_items = _load("content_items.json")

    # Map (instrument_id, as_of_date)->shares_outstanding if present
    shares_by_inst_date = {}
    for ci in content_items:
        if not isinstance(ci, dict):
            continue
        if ci.get("status") != "active":
            continue
        if ci.get("content_type") != "key_metrics":
            continue
        iid = ci.get("instrument_id")
        if iid not in inst_ids:
            continue
        as_of = ci.get("as_of_date")
        if not isinstance(as_of, str):
            continue
        payload = ci.get("payload")
        if not isinstance(payload, dict):
            continue
        # Common fields: sharesOutstanding / shares_outstanding
        so = payload.get("sharesOutstanding")
        if so is None:
            so = payload.get("shares_outstanding")
        if isinstance(so, (int, float)) and not isinstance(so, bool) and so >= 0:
            shares_by_inst_date[(iid, as_of)] = float(so)

    # Gather 1day close prices and join shares
    points = []
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") not in inst_ids:
            continue
        if r.get("timeframe") != "1day":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        trade_date = r.get("trade_date")
        if not isinstance(trade_date, str):
            continue
        if d_from is not None or d_to is not None:
            d_td = _parse_iso_date(trade_date)
            if d_td is None:
                continue
            if d_from is not None and d_td < d_from:
                continue
            if d_to is not None and d_td > d_to:
                continue
        close = r.get("close")
        if close is None or not isinstance(close, (int, float)) or isinstance(close, bool) or close < 0:
            continue
        so = shares_by_inst_date.get((r.get("instrument_id"), trade_date))
        if so is None:
            # no shares -> cannot compute market cap for this date
            continue
        market_cap = float(close) * float(so)
        points.append({
            "symbol": norm_symbol,
            "date": trade_date,
            "marketCap": market_cap
        })

    # Deduplicate by date: if multiple exchange variants, pick max market cap for that date (arbitrary but deterministic)
    by_date = {}
    for p in points:
        d = p["date"]
        if d not in by_date or p["marketCap"] > by_date[d]["marketCap"]:
            by_date[d] = p
    points = list(by_date.values())

    # Sort by date descending (typical market cap history)
    points.sort(key=lambda x: x["date"], reverse=True)

    # Apply limit
    points = points[:limit_i]

    if not points:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": _mk_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getHistoricalMarketCap",
            "params": params,
            "http_status": 404,
            "cache_status": "miss",
            "duration_ms": duration_ms,
            "result_count": 0,
            "error_code": "NOT_FOUND",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "No market-cap history found for symbol with given filters.", symbol=norm_symbol)

    # Update last_used_at on success
    api_key["last_used_at"] = _now_iso()
    api_key["updated_at"] = _now_iso()
    for idx, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            api_keys[idx] = api_key
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.perf_counter() - t0) * 1000)
    log_row = {
        "id": _mk_log_id(),
        "api_key_id": api_key["id"],
        "tool_name": "getHistoricalMarketCap",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(points),
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    req_logs.append(log_row)
    _save("request_logs.json", req_logs)

    return {
        "symbol": norm_symbol,
        "from": from_,
        "to": to,
        "limit": limit_i,
        "count": len(points),
        "data": points,
    }

def getShareFloat(symbol, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    params_obj = {"symbol": symbol}

    def _log(req_api_key_id, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        now = _now()
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "api_key_id": req_api_key_id,
            "tool_name": "getShareFloat",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)

    if not isinstance(symbol, str) or not symbol.strip():
        keys = _load("api_keys.json")
        active = next((k for k in keys if k.get("status") == "active"), None)
        kid = active["id"] if active else "anonymous"
        _log(kid, 400, "bypass", (time.time() - t0) * 1000, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`symbol` must be a non-empty string.")

    # authenticate + quota
    keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow()

    def _parse_ts(ts):
        try:
            if isinstance(ts, str) and ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1])
            if isinstance(ts, str):
                return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None
        return None

    def _check_key(k):
        if k.get("status") != "active":
            return (False, "UNAUTHORIZED", 403)
        minute_q = k.get("minute_request_quota")
        daily_q = k.get("daily_request_quota")
        if not isinstance(minute_q, int) or minute_q < 0 or not isinstance(daily_q, int) or daily_q < 0:
            return (False, "VALIDATION_ERROR", 400)
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if r.get("api_key_id") != k.get("id"):
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                m += 1
            if ts >= day_ago:
                d += 1
        if minute_q == 0 or daily_q == 0:
            return (False, "QUOTA_EXCEEDED", 429)
        if m + 1 > minute_q or d + 1 > daily_q:
            return (False, "QUOTA_EXCEEDED", 429)
        return (True, None, 200)

    chosen = None
    quota_failure = None
    for k in keys:
        ok, ecode, http = _check_key(k)
        if ok:
            chosen = k
            break
        if ecode in ("QUOTA_EXCEEDED", "RATE_LIMIT"):
            quota_failure = (ecode, http)

    if not chosen:
        http_status = 403
        error_code = "UNAUTHORIZED"
        if quota_failure:
            error_code, http_status = quota_failure
        kid = (keys[0]["id"] if keys else "anonymous")
        _log(kid, http_status, "bypass", (time.time() - t0) * 1000, None, error_code)
        return _err(error_code, "API key unauthorized or over quota.")

    norm_sym = symbol.strip().upper()

    instruments = _load("instruments.json")
    insts = [i for i in instruments if i.get("normalized_symbol") == norm_sym]
    if not insts:
        _log(chosen["id"], 404, "miss", (time.time() - t0) * 1000, 0, "NOT_FOUND")
        return _err("NOT_FOUND", "Unknown symbol.")

    inst = next((i for i in insts if i.get("exchange") is None), insts[0])

    # allowlists
    allowed_ex = chosen.get("allowed_exchanges")
    allowed_at = chosen.get("allowed_asset_types")
    if allowed_ex is not None and isinstance(allowed_ex, list):
        ex = inst.get("exchange")
        if ex is None or ex not in allowed_ex:
            _log(chosen["id"], 403, "bypass", (time.time() - t0) * 1000, None, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not permitted for this exchange.")
    if allowed_at is not None and isinstance(allowed_at, list):
        at = inst.get("asset_type")
        if at not in allowed_at:
            _log(chosen["id"], 403, "bypass", (time.time() - t0) * 1000, None, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not permitted for this asset type.")

    # Share float data: schema doesn't include a dedicated type, so serve from latest active content_item
    # whose payload contains float/outstanding fields.
    content = _load("content_items.json")

    candidates = []
    for ci in content:
        if ci.get("status") != "active":
            continue
        if ci.get("instrument_id") != inst.get("id"):
            continue
        payload = ci.get("payload")
        if not isinstance(payload, dict):
            continue
        has_any = any(k in payload for k in (
            "freeFloat", "floatShares", "outstandingShares", "sharesOutstanding",
            "shortFloat", "insiderOwnership", "institutionalOwnership"
        ))
        if not has_any:
            continue
        # prefer by as_of_date then updated_at
        asof = ci.get("as_of_date") or payload.get("date") or payload.get("asOfDate")
        asof_s = asof if isinstance(asof, str) else None
        asof_key = asof_s[:10] if asof_s and len(asof_s) >= 10 else None
        candidates.append((asof_key or "0000-00-00", ci.get("updated_at") or "", ci))

    if not candidates:
        _log(chosen["id"], 404, "miss", (time.time() - t0) * 1000, 0, "NOT_FOUND")
        return _err("NOT_FOUND", "No share-float data for this symbol.")

    candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
    ci = candidates[0][2]
    payload = ci.get("payload") if isinstance(ci.get("payload"), dict) else {}

    record = {
        "symbol": inst.get("symbol"),
        "date": (ci.get("as_of_date") or payload.get("date") or payload.get("asOfDate") or None),
        "freeFloat": payload.get("freeFloat"),
        "floatShares": payload.get("floatShares"),
        "outstandingShares": payload.get("outstandingShares") if payload.get("outstandingShares") is not None else payload.get("sharesOutstanding"),
        "shortFloat": payload.get("shortFloat"),
        "insiderOwnership": payload.get("insiderOwnership"),
        "institutionalOwnership": payload.get("institutionalOwnership")
    }

    # success: update last_used_at
    chosen["last_used_at"] = _now()
    chosen["updated_at"] = _now()
    for idx, k in enumerate(keys):
        if k.get("id") == chosen.get("id"):
            keys[idx] = chosen
            break
    _save("api_keys.json", keys)

    _log(chosen["id"], 200, "miss", (time.time() - t0) * 1000, 1, None)
    return {"data": [record], "meta": {"result_count": 1}}

