        minute_q = k.get("minute_request_quota")
        daily_q = k.get("daily_request_quota")
        if not isinstance(minute_q, int) or minute_q < 0 or not isinstance(daily_q, int) or daily_q < 0:
            return (False, "VALIDATION_ERROR", 400)
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if r.get("api_key_id") != k.get("id"):
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                m += 1
            if ts >= day_ago:
                d += 1
        if minute_q == 0 or daily_q == 0:
            return (False, "QUOTA_EXCEEDED", 429)
        if m + 1 > minute_q or d + 1 > daily_q:
            return (False, "QUOTA_EXCEEDED", 429)
        return (True, None, 200)

    chosen = None
    quota_failure = None
    for k in keys:
        ok, ecode, http = _check_key(k)
        if ok:
            chosen = k
            break
        if ecode in ("QUOTA_EXCEEDED", "RATE_LIMIT"):
            quota_failure = (ecode, http)

    if not chosen:
        http_status = 403
        error_code = "UNAUTHORIZED"
        if quota_failure:
            error_code, http_status = quota_failure
        kid = (keys[0]["id"] if keys else "anonymous")
        _log(kid, http_status, "bypass", (time.time() - t0) * 1000, None, error_code)
        return _err(error_code, "API key unauthorized or over quota.")

    # Build share-float table from latest per instrument where payload has float/outstanding fields.
    instruments = _load("instruments.json")
    content = _load("content_items.json")

    # index instruments by id
    inst_by_id = {i.get("id"): i for i in instruments if isinstance(i.get("id"), str)}

    # choose latest candidate per instrument
    latest_by_inst = {}

    def _asof_key(ci):
        payload = ci.get("payload") if isinstance(ci.get("payload"), dict) else {}
        asof = ci.get("as_of_date") or payload.get("date") or payload.get("asOfDate")
        if isinstance(asof, str) and len(asof) >= 10:
            return asof[:10]
        return "0000-00-00"

    for ci in content:
        if ci.get("status") != "active":
            continue
        iid = ci.get("instrument_id")
        if iid is None or iid not in inst_by_id:
            continue
        payload = ci.get("payload")
        if not isinstance(payload, dict):
            continue
        has_any = any(k in payload for k in (
            "freeFloat", "floatShares", "outstandingShares", "sharesOutstanding",
            "shortFloat", "insiderOwnership", "institutionalOwnership"
        ))
        if not has_any:
            continue
        key = (_asof_key(ci), ci.get("updated_at") or "")
        prev = latest_by_inst.get(iid)
        if prev is None or key > prev[0]:
            latest_by_inst[iid] = (key, ci)

    # apply allowlists: filter instruments not allowed for this key
    allowed_ex = chosen.get("allowed_exchanges")
    allowed_at = chosen.get("allowed_asset_types")
    allow_ex_list = allowed_ex if isinstance(allowed_ex, list) else None
    allow_at_list = allowed_at if isinstance(allowed_at, list) else None

    all_rows = []
    for iid, (_, ci) in latest_by_inst.items():
        inst = inst_by_id.get(iid)
        if not inst:
            continue
        if allow_ex_list is not None:
            ex = inst.get("exchange")
            if ex is None or ex not in allow_ex_list:
                continue
        if allow_at_list is not None:
            at = inst.get("asset_type")
            if at not in allow_at_list:
                continue

        payload = ci.get("payload") if isinstance(ci.get("payload"), dict) else {}
        all_rows.append({
            "symbol": inst.get("symbol"),
            "date": (ci.get("as_of_date") or payload.get("date") or payload.get("asOfDate") or None),
            "freeFloat": payload.get("freeFloat"),
            "floatShares": payload.get("floatShares"),
            "outstandingShares": payload.get("outstandingShares") if payload.get("outstandingShares") is not None else payload.get("sharesOutstanding"),
            "shortFloat": payload.get("shortFloat"),
            "insiderOwnership": payload.get("insiderOwnership"),
            "institutionalOwnership": payload.get("institutionalOwnership")
        })

    # deterministic ordering
    all_rows.sort(key=lambda r: (str(r.get("symbol") or ""), str(r.get("date") or "")), reverse=False)

    total = len(all_rows)
    start = pg * lim
    end = start + lim
    page_rows = all_rows[start:end] if start < total else []

    # success even if empty page (beyond available) per rule: reads return empty set not error
    chosen["last_used_at"] = _now()
    chosen["updated_at"] = _now()
    for idx, k in enumerate(keys):
        if k.get("id") == chosen.get("id"):
            keys[idx] = chosen
            break
    _save("api_keys.json", keys)

    has_more = end < total
    _log(chosen["id"], 200, "miss", (time.time() - t0) * 1000, len(page_rows), None)
    return {
        "data": page_rows,
        "meta": {
            "page": pg,
            "limit": lim,
            "total": total,
            "has_more": has_more
        }
    }

