        ca = row.get("created_at")
        return (aod if isinstance(aod, str) else "", ca if isinstance(ca, str) else "")
    executive_items.sort(key=_sort_key, reverse=True)

    executives = []
    if executive_items:
        payload = executive_items[0].get("payload", {})
        if isinstance(payload, dict):
            if isinstance(payload.get("executives"), list):
                executives = payload.get("executives")
            elif isinstance(payload.get("officers"), list):
                executives = payload.get("officers")
            elif isinstance(payload.get("data"), list):
                executives = payload.get("data")

    if not isinstance(executives, list) or len(executives) == 0:
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _log_and_return(404, _err("NOT_FOUND", "No executive records available for this symbol."), error_code="NOT_FOUND", result_count=0)

    # Apply active filter if the dataset supports it (look for keys like isActive/active/status)
    if active_filter is not None:
        filtered = []
        for ex in executives:
            if not isinstance(ex, dict):
                continue
            v = None
            if "isActive" in ex:
                v = ex.get("isActive")
            elif "active" in ex:
                v = ex.get("active")
            elif "status" in ex and isinstance(ex.get("status"), str):
                v = ex.get("status").strip().lower() in ("active", "current")
            if isinstance(v, bool):
                if v == active_filter:
                    filtered.append(ex)
            else:
                # If no active field exists, treat as unsupported by dataset -> VALIDATION_ERROR per tool description.
                return _log_and_return(400, _err("VALIDATION_ERROR", "'active' filter is not supported by the available executive dataset."), error_code="VALIDATION_ERROR")
        executives = filtered

    if len(executives) == 0:
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _log_and_return(404, _err("NOT_FOUND", "No executive records matched the requested filter."), error_code="NOT_FOUND", result_count=0)

    api_key_row["last_used_at"] = now_iso
    api_key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    body = {"data": executives, "meta": {"symbol": norm, "instrument_id": instrument_id, "count": len(executives)}}
    return _log_and_return(200, body, result_count=len(executives), error_code=None)

def getExecutiveCompensation(symbol, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.perf_counter()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    instruments = _load("instruments.json")
    content_items = _load("content_items.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    api_key_row = active_keys[0] if active_keys else None
    api_key_id = api_key_row.get("id") if api_key_row else None

    def _log_and_return(http_status, body, result_count=None, error_code=None, cache_status="bypass"):
        duration_ms = int((time.perf_counter() - _t0) * 1000)
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id if api_key_id else "unknown",
            "tool_name": "getExecutiveCompensation",
            "params": {"symbol": symbol},
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": max(0, int(duration_ms)),
            "result_count": result_count,
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return body

    if not api_key_row:
        return _log_and_return(401, _err("UNAUTHORIZED", "No active API key available for this request."), error_code="UNAUTHORIZED")

    if not isinstance(symbol, str):
        return _log_and_return(400, _err("VALIDATION_ERROR", "'symbol' must be a string."), error_code="VALIDATION_ERROR")
    sym = symbol.strip()
    if not sym:
        return _log_and_return(400, _err("VALIDATION_ERROR", "'symbol' is required and must not be empty."), error_code="VALIDATION_ERROR")
    norm = sym.upper()

    # Quota enforcement
    minute_quota = api_key_row.get("minute_request_quota")
    daily_quota = api_key_row.get("daily_request_quota")
    if not isinstance(minute_quota, int) or minute_quota < 0:
        minute_quota = 0
    if not isinstance(daily_quota, int) or daily_quota < 0:
        daily_quota = 0

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    win_minute_start = now - datetime.timedelta(minutes=1)
    win_day_start = now - datetime.timedelta(days=1)

    used_minute = 0
    used_day = 0
    for r in request_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        ts = _parse_ts(r.get("created_at"))
        if ts is None:
            continue
        if ts >= win_minute_start:
            used_minute += 1
        if ts >= win_day_start:
            used_day += 1

    if minute_quota == 0 or daily_quota == 0:
        return _log_and_return(429, _err("QUOTA_EXCEEDED", "API key quota is exhausted."), error_code="QUOTA_EXCEEDED")
    if used_minute + 1 > minute_quota or used_day + 1 > daily_quota:
        return _log_and_return(429, _err("QUOTA_EXCEEDED", "API key quota exceeded."), error_code="QUOTA_EXCEEDED")

    inst_matches = [i for i in instruments if isinstance(i, dict) and i.get("normalized_symbol") == norm]
    if not inst_matches:
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _log_and_return(404, _err("NOT_FOUND", "Unknown symbol."), error_code="NOT_FOUND", result_count=0)

    inst = None
    for cand in inst_matches:
        if cand.get("status") == "active":
            inst = cand
            break
    if inst is None:
        inst = inst_matches[0]
    instrument_id = inst.get("id")

    # Compensation records: stored in content_items; we accept content_type='sec_filing'/'financial_report'
    # when payload includes an executive compensation section or identifier_1 marks it.
    comp_sources = []
    for c in content_items:
        if not isinstance(c, dict) or c.get("status") != "active":
            continue
        if c.get("instrument_id") != instrument_id:
            continue
        ct = c.get("content_type")
        if ct not in ("sec_filing", "financial_report", "financial_statement", "news_article", "press_release", "fmp_article"):
            # allow any, but keep signal-to-noise; schema has no dedicated type
            pass
        payload = c.get("payload")
        if not isinstance(payload, dict):
            continue
        if c.get("identifier_1") in ("executive_compensation", "exec_comp", "compensation") or "executiveCompensation" in payload or "compensation" in payload:
            comp_sources.append(c)

    def _sort_key(row):
        aod = row.get("as_of_date")
        yr = row.get("year")
        ca = row.get("created_at")
        return (aod if isinstance(aod, str) else "", yr if isinstance(yr, int) else -1, ca if isinstance(ca, str) else "")
    comp_sources.sort(key=_sort_key, reverse=True)

    records = []
    for src in comp_sources:
        payload = src.get("payload", {})
        if not isinstance(payload, dict):
            continue
        cand = None
        if isinstance(payload.get("executiveCompensation"), list):
            cand = payload.get("executiveCompensation")
        elif isinstance(payload.get("compensation"), list):
            cand = payload.get("compensation")
        elif isinstance(payload.get("data"), list) and src.get("identifier_1") in ("executive_compensation", "exec_comp", "compensation"):
            cand = payload.get("data")
        if isinstance(cand, list) and cand:
            for r in cand:
                if isinstance(r, dict):
                    # attach filing metadata when present
                    out = dict(r)
                    for mk in ("as_of_date", "year", "quarter", "period", "identifier_2", "url", "title"):
                        if src.get(mk) is not None:
                            out.setdefault(mk, src.get(mk))
                    records.append(out)

    if not records:
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _log_and_return(404, _err("NOT_FOUND", "No executive compensation filings are available for this symbol."), error_code="NOT_FOUND", result_count=0)

    api_key_row["last_used_at"] = now_iso
    api_key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    body = {"data": records, "meta": {"symbol": norm, "instrument_id": instrument_id, "count": len(records)}}
    return _log_and_return(200, body, result_count=len(records), error_code=None)

def getExecutiveCompensationBenchmark(year=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- auth (ambient) ---
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    api_key = active_keys[0] if active_keys else None

    # request params must conform (additionalProperties=false)
    params = {}
    if year is not None:
        params["year"] = year

    request_logs = _load("request_logs.json")
    def _new_log_id():
        return "rql_" + hashlib.sha256(f"{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    def _quota_ok(k):
        if not k:
            return True, None
        try:
            minute_q = int(k.get("minute_request_quota", 0))
            daily_q = int(k.get("daily_request_quota", 0))
            if minute_q < 0 or daily_q < 0:
                # treat as misconfigured; deny rather than allow unlimited
                return False, ("QUOTA_EXCEEDED", 429, "API key quota misconfigured.")
        except Exception:
            return False, ("QUOTA_EXCEEDED", 429, "API key quota misconfigured.")
        if minute_q == 0 and daily_q == 0:
            # 0 means no requests allowed
            return False, ("QUOTA_EXCEEDED", 429, "Request quota exceeded.")

        now_dt = datetime.datetime.utcnow()
        win_min = now_dt - datetime.timedelta(minutes=1)
        win_day = now_dt - datetime.timedelta(days=1)

        def _parse_dt(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                else:
                    s2 = s
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                return None

        used_min = 0
        used_day = 0
        kid = k.get("id")
        for r in request_logs if isinstance(request_logs, list) else []:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != kid:
                continue
            dt = _parse_dt(r.get("created_at"))
            if not dt:
                continue
            if dt >= win_day:
                used_day += 1
            if dt >= win_min:
                used_min += 1

        if minute_q > 0 and used_min + 1 > minute_q:
            return False, ("RATE_LIMIT", 429, "Minute request quota exceeded.")
        if daily_q > 0 and used_day + 1 > daily_q:
            return False, ("QUOTA_EXCEEDED", 429, "Daily request quota exceeded.")
        return True, None

    # auth failure still logs attempt with 401/403
    if not api_key:
        duration_ms = max(0, int((time.time() - t0) * 1000))
        log_row = {
            "id": _new_log_id(),
            "api_key_id": "__unauthorized__",
            "tool_name": "getExecutiveCompensationBenchmark",
            "params": params,
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": now,
            "updated_at": now,
        }
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key missing or invalid.")

    # enforce quota before doing work; still log
    ok, qerr = _quota_ok(api_key)
    if not ok:
        code, http_status, msg = qerr
        duration_ms = max(0, int((time.time() - t0) * 1000))
        log_row = {
            "id": _new_log_id(),
            "api_key_id": api_key["id"],
            "tool_name": "getExecutiveCompensationBenchmark",
            "params": params,
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": code,
            "created_at": now,
            "updated_at": now,
        }
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return _err(code, msg)

    # --- validate inputs ---
    y = None
    if year is not None:
        if not isinstance(year, str):
            duration_ms = max(0, int((time.time() - t0) * 1000))
            log_row = {
                "id": _new_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getExecutiveCompensationBenchmark",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": now,
                "updated_at": now,
            }
            request_logs.append(log_row)
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "year must be a string.")
        if not re.fullmatch(r"\d{4}", year.strip()):
            duration_ms = max(0, int((time.time() - t0) * 1000))
            log_row = {
                "id": _new_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getExecutiveCompensationBenchmark",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": now,
                "updated_at": now,
            }
            request_logs.append(log_row)
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "year must be a 4-digit year string (YYYY).")
        y = int(year)
        if y < 1900 or y > 2200:
            duration_ms = max(0, int((time.time() - t0) * 1000))
            log_row = {
                "id": _new_log_id(),
                "api_key_id": api_key["id"],
                "tool_name": "getExecutiveCompensationBenchmark",
                "params": params,
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": now,
                "updated_at": now,
            }
            request_logs.append(log_row)
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "year out of supported range (1900-2200).")

    # --- serve from content_items ---
    content_items = _load("content_items.json")

    bench_type = "executive_compensation_benchmark"
    candidates = []
    for it in content_items if isinstance(content_items, list) else []:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "economic_indicator":
            continue
        if (it.get("identifier_1") or "") != bench_type:
            continue
        if it.get("year") is None:
            continue
        try:
            iy = int(it.get("year"))
        except Exception:
            continue
        candidates.append((iy, it))

    chosen = None
    if y is not None:
        for iy, it in candidates:
            if iy == y:
                chosen = it
                break
    else:
        # latest available year
        if candidates:
            chosen = sorted(candidates, key=lambda t: t[0], reverse=True)[0][1]

    result = []
    if chosen and isinstance(chosen.get("payload"), dict):
        payload = chosen["payload"]
        # Prefer explicit dataset list
        if isinstance(payload.get("data"), list):
            result = payload.get("data")
        elif isinstance(payload.get("benchmarks"), list):
            result = payload.get("benchmarks")
        else:
            # if payload itself is the dataset, keep as single-element dataset for consistency
            result = [payload]

    # update last_used_at only for successful authenticated request (regardless of empty data)
    api_key["last_used_at"] = now
    api_key["updated_at"] = api_key.get("updated_at") or now
    # persist api_keys update
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    duration_ms = max(0, int((time.time() - t0) * 1000))
    log_row = {
        "id": _new_log_id(),
        "api_key_id": api_key["id"],
        "tool_name": "getExecutiveCompensationBenchmark",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(result) if isinstance(result, list) else None,
        "error_code": None,
        "created_at": now,
        "updated_at": now,
    }
    request_logs.append(log_row)
    _save("request_logs.json", request_logs)

    # Not found isn't specified; return empty dataset if missing
    return {
        "data": result,
        "meta": {
            "year": chosen.get("year") if chosen else (y if y is not None else None),
            "available": True if chosen else False,
        },
    }

def getCOTReports(symbol, from_=None, to=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getCOTReports"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    def _iso_now_z(dt=None):
        dt = dt or datetime.datetime.now(datetime.timezone.utc)
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _parse_date(d, field):
        if d is None:
            return None, None
        if not isinstance(d, str):
            return None, _err("VALIDATION_ERROR", f"`{field}` must be a string in YYYY-MM-DD.", http_status=400)
        s = d.strip()
        try:
            if len(s) != 10:
                raise ValueError("badlen")
            datetime.date.fromisoformat(s)
            return s, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"`{field}` must be a valid ISO date (YYYY-MM-DD).", http_status=400)

    def _new_id(prefix):
        seed = hashlib.sha1((str(time.time()) + "|" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{seed}"

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        now_iso = _iso_now_z(now_dt)
        duration_ms = int((time.time() - t0) * 1000)
        if duration_ms < 0:
            duration_ms = 0
        logs.append({
            "id": _new_id("fmp_req"),
            "api_key_id": api_key_id if isinstance(api_key_id, str) else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status) if isinstance(http_status, int) or (isinstance(http_status, float) and http_status.is_integer()) else 500,
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (int(result_count) if isinstance(result_count, int) and result_count >= 0 else None),
            "error_code": error_code if isinstance(error_code, str) else None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)

    def _select_active_key_for_request():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None, _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _count_for(kid):
            m = d = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                dt = _parse_dt_any(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= minute_ago:
                    m += 1
                if dt >= day_ago:
                    d += 1
            return m, d

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                continue
            if day_q and d + 1 > day_q:
                continue
            return k, None

        # decide which quota exceeded
        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                return None, _err("RATE_LIMIT", "Request quota exceeded.", reason="quota_minute_exceeded", http_status=429)
            if day_q and d + 1 > day_q:
                return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", reason="quota_daily_exceeded", http_status=429)
        return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

    params_obj = {"symbol": symbol, "from": from_, "to": to}

    # validate
    if not isinstance(symbol, str) or not symbol.strip():
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`symbol` must be a non-empty string.", http_status=400)
        _log(kid, params_obj, 400, result_count=None, error_code="validation_error")
        return err
    sym = symbol.strip().upper()

    from_s, ferr = _parse_date(from_, "from")
    if ferr:
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        _log(kid, params_obj, ferr["error"].get("http_status", 400), error_code="validation_error")
        return ferr
    to_s, terr = _parse_date(to, "to")
    if terr:
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        _log(kid, params_obj, terr["error"].get("http_status", 400), error_code="validation_error")
        return terr
    if from_s and to_s:
        if from_s > to_s:
            key, kerr = _select_active_key_for_request()
            kid = key["id"] if key else "unknown"
            err = _err("VALIDATION_ERROR", "`from` must be <= `to`.", http_status=400)
            _log(kid, params_obj, 400, error_code="validation_error")
            return err

    key, kerr = _select_active_key_for_request()
    if kerr:
        _log("unknown", params_obj, kerr["error"].get("http_status", 401), error_code=kerr["error"].get("reason") or kerr["error"]["code"].lower())
        return kerr
    kid = key["id"]

    # Find in content_items: prefer content_type 'technical_indicator' with identifier_1 == 'cot_report' or 'cot'
    content = _load("content_items.json")
    if not isinstance(content, list):
        content = []

    rows = []
    for ci in content:
        if not isinstance(ci, dict):
            continue
        ctype = ci.get("content_type")
        if ctype not in ("technical_indicator", "economic_indicator"):
            continue
        ident = ci.get("identifier_1")
        if isinstance(ident, str) and ident.lower() not in ("cot", "cot_report", "commitment_of_traders"):
            continue
        # symbol match in identifier_2 or payload.symbol
        payload = ci.get("payload")
        if not isinstance(payload, dict):
            continue
        psym = payload.get("symbol") or payload.get("ticker") or ci.get("identifier_2")
        if isinstance(psym, str) and psym.strip().upper() != sym:
            continue
        # reports could be a list in payload
        rep_list = payload.get("reports") or payload.get("data") or payload.get("items")
        if isinstance(rep_list, list):
            for r in rep_list:
                if isinstance(r, dict):
                    rows.append(r)
        elif isinstance(payload.get("reportDate"), str) or isinstance(payload.get("date"), str):
            rows.append(payload)

    # Filter date range
    def _get_date(obj):
        if not isinstance(obj, dict):
            return None
        d = obj.get("reportDate") or obj.get("date") or obj.get("asOfDate")
        if not isinstance(d, str):
            return None
        d = d.strip()
        if len(d) >= 10:
            d10 = d[:10]
            try:
                datetime.date.fromisoformat(d10)
                return d10
            except Exception:
                return None
        return None

    filtered = []
    for r in rows:
        d = _get_date(r)
        if d is None:
            continue
        if from_s and d < from_s:
            continue
        if to_s and d > to_s:
            continue
        rr = dict(r)
        rr.setdefault("symbol", sym)
        rr["date"] = d
        filtered.append(rr)

    filtered.sort(key=lambda x: x.get("date") or "", reverse=False)

    if not filtered:
        err = _err("NOT_FOUND", "No COT reports available for this symbol.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="symbol_not_found")
        return err

    # update last_used_at
    keys_all = _load("api_keys.json")
    if isinstance(keys_all, list):
        for k in keys_all:
            if isinstance(k, dict) and k.get("id") == kid:
                k["last_used_at"] = _iso_now_z(now_dt)
                k["updated_at"] = _iso_now_z(now_dt)
                _save("api_keys.json", keys_all)
                break

    _log(kid, params_obj, 200, result_count=len(filtered))
    return {"data": filtered, "meta": {"symbol": sym, "count": len(filtered)}}

def getCOTAnalysis(symbol, from_=None, to=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getCOTAnalysis"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    def _iso_now_z(dt=None):
        dt = dt or datetime.datetime.now(datetime.timezone.utc)
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _parse_date(d, field):
        if d is None:
            return None, None
        if not isinstance(d, str):
            return None, _err("VALIDATION_ERROR", f"`{field}` must be a string in YYYY-MM-DD.", http_status=400)
        s = d.strip()
        try:
            if len(s) != 10:
                raise ValueError("badlen")
            datetime.date.fromisoformat(s)
            return s, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"`{field}` must be a valid ISO date (YYYY-MM-DD).", http_status=400)

    def _new_id(prefix):
        seed = hashlib.sha1((str(time.time()) + "|" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{seed}"

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        now_iso = _iso_now_z(now_dt)
        duration_ms = int((time.time() - t0) * 1000)
        if duration_ms < 0:
            duration_ms = 0
        logs.append({
            "id": _new_id("fmp_req"),
            "api_key_id": api_key_id if isinstance(api_key_id, str) else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status) if isinstance(http_status, int) or (isinstance(http_status, float) and http_status.is_integer()) else 500,
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (int(result_count) if isinstance(result_count, int) and result_count >= 0 else None),
            "error_code": error_code if isinstance(error_code, str) else None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)

    def _select_active_key_for_request():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None, _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _count_for(kid):
            m = d = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                dt = _parse_dt_any(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= minute_ago:
                    m += 1
                if dt >= day_ago:
                    d += 1
            return m, d

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                continue
            if day_q and d + 1 > day_q:
                continue
            return k, None

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                return None, _err("RATE_LIMIT", "Request quota exceeded.", reason="quota_minute_exceeded", http_status=429)
            if day_q and d + 1 > day_q:
                return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", reason="quota_daily_exceeded", http_status=429)
        return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

    params_obj = {"symbol": symbol, "from": from_, "to": to}

    if not isinstance(symbol, str) or not symbol.strip():
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`symbol` must be a non-empty string.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err
    sym = symbol.strip().upper()

    from_s, ferr = _parse_date(from_, "from")
    if ferr:
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        _log(kid, params_obj, ferr["error"].get("http_status", 400), error_code="validation_error")
        return ferr
    to_s, terr = _parse_date(to, "to")
    if terr:
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        _log(kid, params_obj, terr["error"].get("http_status", 400), error_code="validation_error")
        return terr
    if from_s and to_s and from_s > to_s:
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`from` must be <= `to`.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err

    key, kerr = _select_active_key_for_request()
    if kerr:
        _log("unknown", params_obj, kerr["error"].get("http_status", 401), error_code=kerr["error"].get("reason") or kerr["error"]["code"].lower())
        return kerr
    kid = key["id"]

    # Pull underlying COT reports from content_items
    content = _load("content_items.json")
    if not isinstance(content, list):
        content = []
    reports = []
    for ci in content:
        if not isinstance(ci, dict):
            continue
        ctype = ci.get("content_type")
        if ctype not in ("technical_indicator", "economic_indicator"):
            continue
        ident = ci.get("identifier_1")
        if isinstance(ident, str) and ident.lower() not in ("cot", "cot_report", "commitment_of_traders"):
            continue
        payload = ci.get("payload")
        if not isinstance(payload, dict):
            continue
        psym = payload.get("symbol") or payload.get("ticker") or ci.get("identifier_2")
        if not (isinstance(psym, str) and psym.strip().upper() == sym):
            continue
        rep_list = payload.get("reports") or payload.get("data") or payload.get("items")
        if isinstance(rep_list, list):
            for r in rep_list:
                if isinstance(r, dict):
                    reports.append(r)
        elif isinstance(payload.get("reportDate"), str) or isinstance(payload.get("date"), str):
            reports.append(payload)

    def _d10(r):
        d = r.get("reportDate") or r.get("date") or r.get("asOfDate")
        if not isinstance(d, str):
            return None
        d = d.strip()
        if len(d) < 10:
            return None
        d = d[:10]
        try:
            datetime.date.fromisoformat(d)
            return d
        except Exception:
            return None

    # filter reports and sort ascending
    rep2 = []
    for r in reports:
        if not isinstance(r, dict):
            continue
        d = _d10(r)
        if d is None:
            continue
        if from_s and d < from_s:
            continue
        if to_s and d > to_s:
            continue
        rr = dict(r)
        rr["_date"] = d
        rep2.append(rr)
    rep2.sort(key=lambda x: x["_date"])

    if not rep2:
        err = _err("NOT_FOUND", "No COT coverage available for this symbol.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="symbol_not_found")
        return err

    # compute a simple net-position and z-score over a rolling window (if enough points)
    # Use common fields when present, otherwise skip: nonCommercialLong/nonCommercialShort etc.
    def _num(x):
        return x if isinstance(x, (int, float)) else None

    points = []
    net_series = []
    for r in rep2:
        long_v = _num(r.get("nonCommercialLong")) or _num(r.get("long")) or _num(r.get("nonCommLong"))
        short_v = _num(r.get("nonCommercialShort")) or _num(r.get("short")) or _num(r.get("nonCommShort"))
        if long_v is None or short_v is None:
            # still provide a point, but without net
            points.append({"symbol": sym, "date": r["_date"], "net": None, "sentiment": None})
            net_series.append(None)
        else:
            net = long_v - short_v
            points.append({"symbol": sym, "date": r["_date"], "net": net, "sentiment": ("bullish" if net > 0 else ("bearish" if net < 0 else "neutral"))})
            net_series.append(net)

    # z-score over last 26 valid points
    win = 26
    for i, p in enumerate(points):
        vals = [v for v in net_series[max(0, i - win + 1):i + 1] if isinstance(v, (int, float))]
        if len(vals) >= 5:
            mean = sum(vals) / len(vals)
            var = sum((v - mean) ** 2 for v in vals) / len(vals)
            sd = var ** 0.5
            p["net_zscore"] = (p["net"] - mean) / sd if (isinstance(p.get("net"), (int, float)) and sd > 0) else None
        else:
            p["net_zscore"] = None

    # update last_used_at
    keys_all = _load("api_keys.json")
    if isinstance(keys_all, list):
        for k in keys_all:
            if isinstance(k, dict) and k.get("id") == kid:
                k["last_used_at"] = _iso_now_z(now_dt)
                k["updated_at"] = _iso_now_z(now_dt)
                _save("api_keys.json", keys_all)
                break

    _log(kid, params_obj, 200, result_count=len(points))
    return {"data": points, "meta": {"symbol": sym, "count": len(points)}}

