        if isinstance(sym, str):
            sym_u = sym.strip().upper()
        else:
            continue
        if not sym_u:
            continue
        if sym_u in seen:
            continue
        # search filter
        if q:
            hay = (sym_u + " " + (name or "")).lower()
            if q not in hay:
                continue
        seen.add(sym_u)
        out.append({"symbol": sym_u, "name": name})
        if len(out) >= lim:
            break

    api_key["last_used_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    duration_ms = max(0, int((time.time() - t0) * 1000))
    request_logs.append({
        "id": _new_log_id(),
        "api_key_id": api_key["id"],
        "tool_name": "getCOTList",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(out),
        "error_code": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("request_logs.json", request_logs)

    return {"data": out, "meta": {"count": len(out), "limit": lim, "search": q}}

def getESGDisclosures(symbol, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_date(s):
        try:
            datetime.date.fromisoformat(s)
            return True
        except Exception:
            return False

    def _norm_symbol(s):
        return (s or "").strip().upper()

    def _compute_key_hash(plaintext):
        # Service stores only a hash; tools here have no explicit credential parameter.
        # We therefore authenticate by selecting an active key that can serve the request.
        return hashlib.sha256(plaintext.encode("utf-8")).hexdigest()

    def _select_active_key(api_keys):
        # Ambient auth: pick an active key. Prefer higher plans.
        plan_rank = {"free": 0, "starter": 1, "pro": 2, "enterprise": 3}
        candidates = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None
        candidates.sort(key=lambda k: (plan_rank.get(k.get("plan"), -1), k.get("updated_at") or "", k.get("created_at") or ""), reverse=True)
        return candidates[0]

    def _log_request(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        ts = _now()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _count_logs(logs, api_key_id, since_dt):
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str):
                continue
            # created_at is ISO Z; parse defensively
            try:
                dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= since_dt:
                c += 1
        return c

    t0 = time.time()
    tool = "getESGDisclosures"
    params = {"symbol": symbol}

    api_keys = _load("api_keys.json")
    key = _select_active_key(api_keys)

    # Validate request first (but still must auth+log attempt; business rule says all invocations must authenticate)
    sym = _norm_symbol(symbol) if isinstance(symbol, str) else None
    if sym is None or sym == "":
        # auth outcome
        if not key:
            duration_ms = int((time.time() - t0) * 1000)
            _log_request("unknown", tool, params, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Missing or invalid API key.")
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(key["id"], tool, params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.")

    # Authenticate
    if not key:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request("unknown", tool, {"symbol": sym}, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    # Quota enforcement (rolling windows)
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    minute_since = now_dt - datetime.timedelta(minutes=1)
    day_since = now_dt - datetime.timedelta(days=1)
    used_minute = _count_logs(logs, key["id"], minute_since)
    used_day = _count_logs(logs, key["id"], day_since)
    if used_minute >= int(key.get("minute_request_quota", 0)) or used_day >= int(key.get("daily_request_quota", 0)):
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(key["id"], tool, {"symbol": sym}, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Request quota exceeded.", minute_used=used_minute, minute_quota=key.get("minute_request_quota"), daily_used=used_day, daily_quota=key.get("daily_request_quota"))

    # Plan enforcement: free/starter do not include ESG disclosures
    if key.get("plan") in ("free", "starter"):
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(key["id"], tool, {"symbol": sym}, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Your plan does not include ESG disclosures.")

    instruments = _load("instruments.json")
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("normalized_symbol") == sym:
            inst = r
            break
    if not inst:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(key["id"], tool, {"symbol": sym}, 404, "miss", duration_ms, result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Symbol not found.")

    content = _load("content_items.json")
    # Prefer newest active esg_disclosure
    matches = []
    for c in content:
        if not isinstance(c, dict):
            continue
        if c.get("content_type") != "esg_disclosure":
            continue
        if c.get("status") != "active":
            continue
        if c.get("instrument_id") != inst.get("id"):
            continue
        matches.append(c)

    if not matches:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(key["id"], tool, {"symbol": sym}, 404, "miss", duration_ms, result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No ESG disclosures available for this symbol.")

    def _sort_key(c):
        # as_of_date is primary; then updated_at
        a = c.get("as_of_date") or ""
        u = c.get("updated_at") or c.get("created_at") or ""
        return (a, u)

    matches.sort(key=_sort_key, reverse=True)
    item = matches[0]

    # Update last_used_at only on successful authenticated request
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = _now()
            k["updated_at"] = _now()
            break
    _save("api_keys.json", api_keys)

    # Response: single record (payload + some metadata)
    resp = {
        "symbol": sym,
        "instrument": {
            "id": inst.get("id"),
            "symbol": inst.get("symbol"),
            "name": inst.get("name"),
            "exchange": inst.get("exchange"),
            "asset_type": inst.get("asset_type"),
        },
        "asOfDate": item.get("as_of_date"),
        "disclosure": item.get("payload"),
        "source": {
            "content_item_id": item.get("id"),
            "created_at": item.get("created_at"),
            "updated_at": item.get("updated_at"),
        },
    }

    duration_ms = int((time.time() - t0) * 1000)
    _log_request(key["id"], tool, {"symbol": sym}, 200, "miss", duration_ms, result_count=1, error_code=None)
    return resp

