def getTreasuryRates(from_=None, to=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _select_active_key(api_keys):
        plan_rank = {"free": 0, "starter": 1, "pro": 2, "enterprise": 3}
        candidates = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None
        candidates.sort(key=lambda k: (plan_rank.get(k.get("plan"), -1), k.get("updated_at") or "", k.get("created_at") or ""), reverse=True)
        return candidates[0]

    def _log_request(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        ts = _now()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _count_logs(logs, api_key_id, since_dt):
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= since_dt:
                c += 1
        return c

    def _is_iso_date(s):
        try:
            datetime.date.fromisoformat(s)
            return True
        except Exception:
            return False

    def _to_date(s):
        return datetime.date.fromisoformat(s)

    t0 = time.time()
    tool = "getTreasuryRates"

    # Tool parameter names include "from" which is reserved in python; vendor param is "from".
    # We map python param from_ -> request param "from".
    params = {}
    if from_ is not None:
        params["from"] = from_
    if to is not None:
        params["to"] = to

    api_keys = _load("api_keys.json")
    key = _select_active_key(api_keys)

    # Validate dates (format and ordering)
    f_date = None
    t_date = None
    if from_ is not None:
        if not isinstance(from_, str) or from_.strip() == "" or not _is_iso_date(from_.strip()):
            if not key:
                duration_ms = int((time.time() - t0) * 1000)
                _log_request("unknown", tool, params, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Missing or invalid API key.")
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(key["id"], tool, params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "from must be a valid ISO date (YYYY-MM-DD).")
        f_date = _to_date(from_.strip())
        params["from"] = from_.strip()

    if to is not None:
        if not isinstance(to, str) or to.strip() == "" or not _is_iso_date(to.strip()):
            if not key:
                duration_ms = int((time.time() - t0) * 1000)
                _log_request("unknown", tool, params, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Missing or invalid API key.")
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(key["id"], tool, params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "to must be a valid ISO date (YYYY-MM-DD).")
        t_date = _to_date(to.strip())
        params["to"] = to.strip()

    if f_date is not None and t_date is not None and f_date > t_date:
        if not key:
            duration_ms = int((time.time() - t0) * 1000)
            _log_request("unknown", tool, params, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Missing or invalid API key.")
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(key["id"], tool, params, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be <= to.")

    # Authenticate
    if not key:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request("unknown", tool, params, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    # Quota enforcement
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    minute_since = now_dt - datetime.timedelta(minutes=1)
    day_since = now_dt - datetime.timedelta(days=1)
    used_minute = _count_logs(logs, key["id"], minute_since)
    used_day = _count_logs(logs, key["id"], day_since)
    if used_minute >= int(key.get("minute_request_quota", 0)) or used_day >= int(key.get("daily_request_quota", 0)):
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(key["id"], tool, params, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Request quota exceeded.", minute_used=used_minute, minute_quota=key.get("minute_request_quota"), daily_used=used_day, daily_quota=key.get("daily_request_quota"))

    # Plan enforcement: macro/treasury not in free
    if key.get("plan") == "free":
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(key["id"], tool, params, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Your plan does not include Treasury rates.")

    content = _load("content_items.json")
    items = []
    for c in content:
        if not isinstance(c, dict):
            continue
        if c.get("content_type") != "treasury_rate":
            continue
        if c.get("status") != "active":
            continue
        as_of = c.get("as_of_date")
        if not isinstance(as_of, str) or not _is_iso_date(as_of):
            continue
        d = _to_date(as_of)
        if f_date is not None and d < f_date:
            continue
        if t_date is not None and d > t_date:
            continue
        items.append(c)

    # Group by date, merge maturities
    # Expect each payload to contain maturity fields; we aggregate as a dict keyed by maturity.
    by_date = {}
    for it in items:
        d = it.get("as_of_date")
        payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
        if d not in by_date:
            by_date[d] = {"date": d, **payload}
        else:
            # merge, later rows override
            for k2, v2 in payload.items():
                by_date[d][k2] = v2

    out = list(by_date.values())
    out.sort(key=lambda r: r.get("date") or "")

    # Update last_used_at only on success (even if empty result set, it's still success)
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = _now()
            k["updated_at"] = _now()
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - t0) * 1000)
    _log_request(key["id"], tool, params, 200, "miss", duration_ms, result_count=len(out), error_code=None)
    return {"data": out, "count": len(out)}

def getEconomicIndicators(name, from_=None, to=None, **_extra):
