    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # --- validate params (JSON schema: additionalProperties=false) ---
    if name is None or not isinstance(name, str) or not name.strip():
        # still must log attempt
        status = 400
        # auth + log handled below
        pass_validation_error = True
    else:
        pass_validation_error = False

    def _parse_iso_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__error__", _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format"))
        try:
            # strict YYYY-MM-DD
            dt = datetime.datetime.strptime(s, "%Y-%m-%d").date()
            return dt
        except ValueError:
            return ("__error__", _err("VALIDATION_ERROR", f"{field} must be in YYYY-MM-DD format"))

    d_from = _parse_iso_date(from_, "from")
