        pass_validation_error = True
        validation_err = d_to[1]

    if not pass_validation_error and d_from and d_to and d_from > d_to:
        pass_validation_error = True
        validation_err = _err("VALIDATION_ERROR", "from must be <= to")

    if pass_validation_error and 'validation_err' not in locals():
        validation_err = _err("VALIDATION_ERROR", "name is required")

    # --- authenticate (ambient) and enforce quotas ---
    api_keys = _load("api_keys.json")
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # choose an active key that can serve; "ambient auth" => any active key
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    api_key_row = active_keys[0] if active_keys else None

    request_logs = _load("request_logs.json")

    def _within_window(ts_iso, seconds):
        try:
            if not isinstance(ts_iso, str):
                return False
            s = ts_iso[:-1] if ts_iso.endswith("Z") else ts_iso
            dt = datetime.datetime.fromisoformat(s)
            return (datetime.datetime.utcnow() - dt).total_seconds() <= seconds
        except Exception:
            return False

    def _count_requests(key_id, seconds):
        c = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            ca = r.get("created_at")
            if _within_window(ca, seconds):
                c += 1
        return c

    # Decide response, but ensure exactly one log row is written for every call.
    http_status = 200
    cache_status = "bypass"
    result = None
    error_code = None
    result_count = None

    if api_key_row is None:
        http_status = 401
        result = _err("UNAUTHORIZED", "Missing/invalid API key")
        error_code = "UNAUTHORIZED"
    else:
        key_id = api_key_row.get("id")
        # Quota enforcement (rolling minute/day)
        minute_quota = api_key_row.get("minute_request_quota")
        daily_quota = api_key_row.get("daily_request_quota")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            minute_quota = 0
        if not isinstance(daily_quota, int) or daily_quota < 0:
            daily_quota = 0

        used_min = _count_requests(key_id, 60)
        used_day = _count_requests(key_id, 86400)

        if (minute_quota >= 0 and used_min >= minute_quota) or (daily_quota >= 0 and used_day >= daily_quota):
            http_status = 429
            result = _err("QUOTA_EXCEEDED", "Request quota exceeded")
            error_code = "QUOTA_EXCEEDED"
        elif pass_validation_error:
            http_status = 400
            result = validation_err
            error_code = "VALIDATION_ERROR"
