            # Recognized indicator names come from content_items where content_type='economic_indicator'
            content_items = _load("content_items.json")
            nm = name.strip().lower()
            recognized = set()
            for it in content_items:
                if isinstance(it, dict) and it.get("content_type") == "economic_indicator":
                    i1 = it.get("identifier_1")
                    if isinstance(i1, str) and i1.strip():
                        recognized.add(i1.strip().lower())

            if nm not in recognized:
                http_status = 404
                result = _err("NOT_FOUND", "Indicator name not recognized", name=name)
