                    except ValueError:
                        continue
                    if d_from and as_dt < d_from:
                        continue
                    if d_to and as_dt > d_to:
                        continue
                    payload = it.get("payload")
                    if not isinstance(payload, dict):
                        payload = {}
                    # Return datapoint in a provider-like shape: include date + payload fields.
                    out = {"date": as_of}
                    for k, v in payload.items():
                        if k not in out:
                            out[k] = v
                    # include name if absent
                    if "name" not in out:
                        out["name"] = name.strip()
                    rows.append(out)

                rows.sort(key=lambda x: x.get("date") or "")
                result_count = len(rows)
                result = {"data": rows, "meta": {"count": len(rows)}}

                # Update last_used_at on successful authenticated request
                api_key_row["last_used_at"] = now
                api_key_row["updated_at"] = now
                # persist api_keys update
                for i, k in enumerate(api_keys):
                    if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                        api_keys[i] = api_key_row
                        break
                _save("api_keys.json", api_keys)

    # --- write request log exactly once ---
    # Params must conform, with no additionalProperties: only name/from/to
    logged_params = {}
    if name is not None:
        logged_params["name"] = name
    if from_ is not None:
        logged_params["from"] = from_
    if to is not None:
        logged_params["to"] = to

    duration_ms = int(max(0, (time.time() - t0) * 1000))
    log_row = {
        "id": "rl_" + uuid.uuid4().hex,
        "api_key_id": (api_key_row.get("id") if isinstance(api_key_row, dict) else "unknown"),
        "tool_name": "getEconomicIndicators",
        "params": logged_params,
        "http_status": int(http_status),
        "cache_status": cache_status,
        "duration_ms": int(duration_ms),
        "result_count": result_count,
        "error_code": error_code,
        "created_at": now,
        "updated_at": now,
    }
    request_logs.append(log_row)
    _save("request_logs.json", request_logs)

    return result

