    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers ---
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _pick_active_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        for k in keys:
            try:
                if k.get("status") == "active":
                    # basic constraints
                    if isinstance(k.get("daily_request_quota"), int) and k["daily_request_quota"] >= 0 and \
                       isinstance(k.get("minute_request_quota"), int) and k["minute_request_quota"] >= 0 and \
                       isinstance(k.get("concurrency_limit"), int) and k["concurrency_limit"] >= 0:
                        return k
            except Exception:
                continue
        return None

    def _enforce_quota_and_log(api_key_row, http_status, result_count=None, error_code=None, validated_params=None):
        # Always write exactly one request_logs row before returning.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        duration_ms = max(0, int((time.time() - t0) * 1000))

        # If authenticated key, enforce quotas before finalizing response (but still log attempt).
        if api_key_row is not None:
            key_id = api_key_row.get("id")
            # rolling windows based on request_logs created_at timestamps
            def _parse_ts(s):
                if not isinstance(s, str):
                    return None
                try:
                    if s.endswith("Z"):
                        s2 = s[:-1]
                    else:
                        s2 = s
                    return datetime.datetime.fromisoformat(s2)
                except Exception:
                    return None

            now_dt = datetime.datetime.utcnow()
            minute_ago = now_dt - datetime.timedelta(minutes=1)
            day_ago = now_dt - datetime.timedelta(days=1)

            minute_count = 0
            day_count = 0
            for r in logs:
                if r.get("api_key_id") != key_id:
                    continue
                ts = _parse_ts(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= minute_ago:
                    minute_count += 1
                if ts >= day_ago:
                    day_count += 1

            # the current request would increment counts by 1
            if api_key_row.get("minute_request_quota") is not None and minute_count + 1 > api_key_row["minute_request_quota"]:
                http_status = 429
                error_code = "QUOTA_EXCEEDED"
                result_count = None
            if api_key_row.get("daily_request_quota") is not None and day_count + 1 > api_key_row["daily_request_quota"]:
                http_status = 429
                error_code = "QUOTA_EXCEEDED"
                result_count = None

        log_row = {
            "id": _new_id("req"),
            "api_key_id": (api_key_row.get("id") if api_key_row else "unauthorized"),
            "tool_name": "getLeveredDCFValuation",
            "params": validated_params if isinstance(validated_params, dict) else {},
            "http_status": int(http_status),
            "cache_status": "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (int(result_count) if result_count is not None else None),
            "error_code": (str(error_code) if error_code is not None else None),
            "created_at": now,
            "updated_at": now
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

        # update last_used_at only on successful authenticated request (2xx)
        if api_key_row is not None and 200 <= int(http_status) <= 299:
            keys = _load("api_keys.json")
            if isinstance(keys, list):
                for k in keys:
                    if k.get("id") == api_key_row.get("id"):
                        k["last_used_at"] = now
                        k["updated_at"] = now
                        break
                _save("api_keys.json", keys)

        return http_status, error_code

    # --- validate params (additionalProperties is handled by signature; still validate types) ---
    if not isinstance(symbol, str) or not symbol.strip():
        api_key = _pick_active_key()
        http_status, error_code = _enforce_quota_and_log(api_key, 400, error_code="VALIDATION_ERROR", validated_params={"symbol": symbol} if isinstance(symbol, str) else {})
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")

    normalized_symbol = symbol.strip().upper()
    validated_params = {"symbol": symbol}

    # --- authenticate (ambient) ---
    api_key = _pick_active_key()
    if api_key is None:
        _enforce_quota_and_log(None, 401, error_code="UNAUTHORIZED", validated_params=validated_params)
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    # --- quota check + compute result (but ensure quotas enforced before returning) ---
    # Resolve instrument
    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    inst = None
    for r in instruments:
        if r.get("normalized_symbol") == normalized_symbol and r.get("exchange") is None:
            inst = r
            break
    if inst is None:
        # could be exchange-specific rows; for this tool, pick any matching normalized_symbol
        for r in instruments:
            if r.get("normalized_symbol") == normalized_symbol:
                inst = r
                break
    if inst is None:
        http_status, errc = _enforce_quota_and_log(api_key, 404, error_code="NOT_FOUND", validated_params=validated_params)
        if errc == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", "Request quota exceeded")
        return _err("NOT_FOUND", "Unknown symbol")

    # enforce key allowlists
    if api_key.get("allowed_asset_types") is not None:
        if not isinstance(api_key.get("allowed_asset_types"), list) or inst.get("asset_type") not in api_key["allowed_asset_types"]:
            http_status, errc = _enforce_quota_and_log(api_key, 403, error_code="UNAUTHORIZED", validated_params=validated_params)
            if errc == "QUOTA_EXCEEDED":
                return _err("QUOTA_EXCEEDED", "Request quota exceeded")
            return _err("UNAUTHORIZED", "API key not permitted for this asset type")
    if api_key.get("allowed_exchanges") is not None:
        if not isinstance(api_key.get("allowed_exchanges"), list) or inst.get("exchange") not in api_key["allowed_exchanges"]:
            http_status, errc = _enforce_quota_and_log(api_key, 403, error_code="UNAUTHORIZED", validated_params=validated_params)
            if errc == "QUOTA_EXCEEDED":
                return _err("QUOTA_EXCEEDED", "Request quota exceeded")
            return _err("UNAUTHORIZED", "API key not permitted for this exchange")

    # Find latest levered DCF snapshot (represented as content_item with content_type=key_metrics/ratios/etc not suitable;
    # we'll use content_type='key_metrics' if payload has 'leveredDCF', else any 'financial_report' with levered DCF block.
    items = _load("content_items.json")
