            continue
        # accept a few common shapes
        if it.get("content_type") in ("key_metrics", "ratios", "financial_report", "fmp_article", "financial_statement"):
            if "leveredDCF" in payload or "levered_dcf" in payload or payload.get("type") == "levered_dcf" or "leveredDCFValuation" in payload:
                candidates.append(it)
    def _sort_key(it):
        # prefer as_of_date then created_at
        asof = it.get("as_of_date")
        created = it.get("created_at")
        return (asof or "", created or "")
    candidates.sort(key=_sort_key, reverse=True)

