    rev_growth = float(input.get("revenueGrowthPct", 5.0)) / 100.0
    ebitda_margin = float(input.get("ebitdaPct", 15.0)) / 100.0
    tax_rate = float(input.get("taxRate", 21.0)) / 100.0
