    # discount rate: prefer costOfEquity if present else CAPM using beta/rfr/mrp
    if input.get("costOfEquity") is not None:
        discount = float(input["costOfEquity"]) / 100.0
    else:
        beta = float(input.get("beta", 1.0))
        rfr = float(input.get("riskFreeRate", 3.0)) / 100.0
        mrp = float(input.get("marketRiskPremium", 5.0)) / 100.0
        discount = rfr + beta * mrp
    discount = max(0.0001, discount)

    # base revenue proxy: use payload from key_metrics if available, else infer from price
    base_revenue = 1_000_000_000.0
    items = _load("content_items.json")
    if isinstance(items, list):
        km = None
        for it in items:
            if it.get("status") == "active" and it.get("instrument_id") == inst.get("id") and it.get("content_type") in ("key_metrics", "financial_report"):
