                    break
    if price is not None and base_revenue <= 0:
        base_revenue = max(1.0, price) * 1_000_000.0

    years = 5
    fcfs = []
    revenue = base_revenue
    for y in range(1, years + 1):
        revenue *= (1.0 + rev_growth)
        ebitda = revenue * ebitda_margin
        da = revenue * da_pct
        ebit = max(0.0, ebitda - da)
        nopat = ebit * (1.0 - tax_rate)
        capex = revenue * capex_pct
        fcf = nopat + da - capex
        fcfs.append(fcf)

    pv = 0.0
    for i, f in enumerate(fcfs, start=1):
        pv += f / ((1.0 + discount) ** i)

    terminal = 0.0
    if discount > ltg:
        terminal_fcf = fcfs[-1] * (1.0 + ltg)
        terminal = terminal_fcf / (discount - ltg)
        pv += terminal / ((1.0 + discount) ** years)

    result = {
        "symbol": inst.get("symbol"),
        "asOfDate": (latest.get("trade_date") if latest else None),
        "assumptions": {
            "revenueGrowthPct": rev_growth * 100.0,
            "ebitdaPct": ebitda_margin * 100.0,
            "taxRate": tax_rate * 100.0,
