        if net_debt > 0:
            fcf -= (net_debt * cod) * (1.0 - tax_rate)
        fcfs.append(fcf)

    pv = 0.0
    for i, f in enumerate(fcfs, start=1):
        pv += f / ((1.0 + discount) ** i)

    terminal = 0.0
    if discount > ltg:
        terminal_fcf = fcfs[-1] * (1.0 + ltg)
        terminal = terminal_fcf / (discount - ltg)
        pv += terminal / ((1.0 + discount) ** years)

    enterprise_value = pv
    equity_value = enterprise_value - net_debt

    result = {
        "symbol": inst.get("symbol"),
        "asOfDate": (latest.get("trade_date") if latest else None),
        "assumptions": {
            "revenueGrowthPct": rev_growth * 100.0,
            "ebitdaPct": ebitda_margin * 100.0,
            "taxRate": tax_rate * 100.0,
            "capitalExpenditurePct": capex_pct * 100.0,
            "depreciationAndAmortizationPct": da_pct * 100.0,
            "longTermGrowthRate": ltg * 100.0,
            "costOfEquityPct": coe * 100.0,
            "costOfDebtPct": cod * 100.0,
            "discountRatePct": discount * 100.0
        },
        "projectionYears": years,
        "projectedFreeCashFlowsAfterDebtCost": fcfs,
        "presentValueOfCashFlows": enterprise_value,
        "terminalValue": terminal,
        "enterpriseValue": enterprise_value,
        "netDebt": net_debt,
        "equityValue": equity_value,
        "marketPrice": price
    }

    http_status, errc = _enforce_quota_and_log(api_key, 200, result_count=1, validated_params=validated_params)
    if errc == "QUOTA_EXCEEDED":
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")
    return [result]

def getFundHoldings(symbol, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        for k in keys:
            try:
                if k.get("status") == "active" and isinstance(k.get("daily_request_quota"), int) and isinstance(k.get("minute_request_quota"), int):
                    return k
            except Exception:
                continue
        return None

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _enforce_quota_and_log(api_key_row, http_status, result_count=None, error_code=None, validated_params=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        duration_ms = max(0, int((time.time() - t0) * 1000))

        if api_key_row is not None:
            key_id = api_key_row.get("id")
            now_dt = datetime.datetime.utcnow()
            minute_ago = now_dt - datetime.timedelta(minutes=1)
            day_ago = now_dt - datetime.timedelta(days=1)
            minute_count = 0
            day_count = 0
            for r in logs:
                if r.get("api_key_id") != key_id:
                    continue
                ts = _parse_ts(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= minute_ago:
                    minute_count += 1
                if ts >= day_ago:
                    day_count += 1
            if minute_count + 1 > int(api_key_row.get("minute_request_quota", 0)):
                http_status = 429
                error_code = "QUOTA_EXCEEDED"
                result_count = None
            if day_count + 1 > int(api_key_row.get("daily_request_quota", 0)):
                http_status = 429
                error_code = "QUOTA_EXCEEDED"
                result_count = None

        log_row = {
            "id": _new_id("req"),
            "api_key_id": (api_key_row.get("id") if api_key_row else "unauthorized"),
            "tool_name": "getFundHoldings",
            "params": validated_params if isinstance(validated_params, dict) else {},
            "http_status": int(http_status),
            "cache_status": "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (int(result_count) if result_count is not None else None),
            "error_code": (str(error_code) if error_code is not None else None),
            "created_at": now,
            "updated_at": now
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

        if api_key_row is not None and 200 <= int(http_status) <= 299:
            keys = _load("api_keys.json")
            if isinstance(keys, list):
                for k in keys:
                    if k.get("id") == api_key_row.get("id"):
                        k["last_used_at"] = now
                        k["updated_at"] = now
                        break
                _save("api_keys.json", keys)

        return http_status, error_code

    if not isinstance(symbol, str) or not symbol.strip():
        api_key = _pick_active_key()
        _enforce_quota_and_log(api_key, 400, error_code="VALIDATION_ERROR", validated_params={"symbol": symbol} if isinstance(symbol, str) else {})
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    normalized_symbol = symbol.strip().upper()
    validated_params = {"symbol": symbol}

    api_key = _pick_active_key()
    if api_key is None:
        _enforce_quota_and_log(None, 401, error_code="UNAUTHORIZED", validated_params=validated_params)
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    inst = None
    for r in instruments:
        if r.get("normalized_symbol") == normalized_symbol and r.get("exchange") is None:
            inst = r
            break
    if inst is None:
        for r in instruments:
            if r.get("normalized_symbol") == normalized_symbol:
                inst = r
                break
    if inst is None:
        http_status, errc = _enforce_quota_and_log(api_key, 404, error_code="NOT_FOUND", validated_params=validated_params)
        if errc == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", "Request quota exceeded")
        return _err("NOT_FOUND", "Unknown symbol")

    if inst.get("asset_type") not in ("etf", "mutual_fund"):
        http_status, errc = _enforce_quota_and_log(api_key, 404, error_code="NOT_FOUND", validated_params=validated_params)
        if errc == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", "Request quota exceeded")
        return _err("NOT_FOUND", "Symbol is not an ETF or mutual fund")

    if api_key.get("allowed_asset_types") is not None:
        if not isinstance(api_key.get("allowed_asset_types"), list) or inst.get("asset_type") not in api_key["allowed_asset_types"]:
            http_status, errc = _enforce_quota_and_log(api_key, 403, error_code="UNAUTHORIZED", validated_params=validated_params)
            if errc == "QUOTA_EXCEEDED":
                return _err("QUOTA_EXCEEDED", "Request quota exceeded")
            return _err("UNAUTHORIZED", "API key not permitted for this asset type")
    if api_key.get("allowed_exchanges") is not None:
        if not isinstance(api_key.get("allowed_exchanges"), list) or inst.get("exchange") not in api_key["allowed_exchanges"]:
            http_status, errc = _enforce_quota_and_log(api_key, 403, error_code="UNAUTHORIZED", validated_params=validated_params)
            if errc == "QUOTA_EXCEEDED":
                return _err("QUOTA_EXCEEDED", "Request quota exceeded")
            return _err("UNAUTHORIZED", "API key not permitted for this exchange")

    items = _load("content_items.json")
    if not isinstance(items, list):
        items = []

    # Latest holdings list: content_type='etf_holding' or 'fund_disclosure' with holdings in payload
    candidates = []
    for it in items:
        if it.get("status") != "active":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        if it.get("content_type") not in ("etf_holding", "fund_disclosure"):
            continue
        p = it.get("payload")
        if not isinstance(p, dict):
            continue
        if isinstance(p.get("holdings"), list) or isinstance(p.get("positions"), list) or isinstance(p.get("data"), list):
            candidates.append(it)

    def _sort_key(it):
        return (it.get("as_of_date") or "", it.get("created_at") or "")
    candidates.sort(key=_sort_key, reverse=True)

    if not candidates:
        http_status, errc = _enforce_quota_and_log(api_key, 404, error_code="NOT_FOUND", validated_params=validated_params)
        if errc == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", "Request quota exceeded")
        return _err("NOT_FOUND", "No fund holdings available for this symbol")

    chosen = candidates[0]
    p = chosen.get("payload", {})
    holdings = None
    if isinstance(p.get("holdings"), list):
        holdings = p["holdings"]
    elif isinstance(p.get("positions"), list):
        holdings = p["positions"]
    elif isinstance(p.get("data"), list):
        holdings = p["data"]
    else:
        holdings = []

    if not isinstance(holdings, list):
        holdings = []

    http_status, errc = _enforce_quota_and_log(api_key, 200, result_count=len(holdings), validated_params=validated_params)
    if errc == "QUOTA_EXCEEDED":
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")
    return holdings

