    tool_name = "getFundInfo"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _norm_symbol(s):
        return re.sub(r"\s+", "", s).upper()

    def _log(api_key_id, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        now = _now_iso()
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": None if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate input (JSON schema: only symbol)
    if not isinstance(symbol, str) or not symbol.strip():
        # authenticate best-effort for logging: pick any api key if exists else placeholder
        keys = _load("api_keys.json")
        any_id = keys[0]["id"] if keys else "unknown"
        _log(any_id, {"symbol": symbol}, 400, "bypass", (time.time() - t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")

    params = {"symbol": symbol}
    norm = _norm_symbol(symbol)
    if not norm:
        keys = _load("api_keys.json")
        any_id = keys[0]["id"] if keys else "unknown"
        _log(any_id, params, 400, "bypass", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol is invalid")

    # Ambient authentication: choose an active key that can serve request (quota/rate)
    keys = _load("api_keys.json")
    active_keys = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        api_key_id = keys[0]["id"] if keys else "unknown"
        _log(api_key_id, params, 401, "bypass", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key missing/invalid or not active")

    logs = _load("request_logs.json")
    now = datetime.datetime.utcnow()

    def _within_window(ts_iso, seconds):
        try:
            dt = datetime.datetime.fromisoformat(ts_iso.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return False
        return (now - dt).total_seconds() <= seconds

    chosen = None
    quota_error = None
    for k in active_keys:
        kid = k.get("id")
        if not isinstance(kid, str) or not kid:
            continue
        minute_quota = k.get("minute_request_quota")
        daily_quota = k.get("daily_request_quota")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            quota_error = _err("VALIDATION_ERROR", "API key minute_request_quota is invalid in datastore")
            continue
        if not isinstance(daily_quota, int) or daily_quota < 0:
            quota_error = _err("VALIDATION_ERROR", "API key daily_request_quota is invalid in datastore")
            continue

        kid_logs = [r for r in logs if isinstance(r, dict) and r.get("api_key_id") == kid]
        # Count all requests (success/fail) in rolling windows, like real quota enforcement
        min_count = sum(1 for r in kid_logs if isinstance(r.get("created_at"), str) and _within_window(r["created_at"], 60))
        day_count = sum(1 for r in kid_logs if isinstance(r.get("created_at"), str) and _within_window(r["created_at"], 86400))

        if minute_quota != 0 and (min_count + 1) > minute_quota:
            continue
        if daily_quota != 0 and (day_count + 1) > daily_quota:
            continue

        chosen = k
        break

    if chosen is None:
        # log against first active key for observability
        api_key_id = active_keys[0]["id"]
        _log(api_key_id, params, 429, "bypass", (time.time() - t0) * 1000, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    api_key_id = chosen["id"]

    # Key allowlists (asset types / exchanges) enforced
    instruments = _load("instruments.json")
    inst = None
    # exchange uniqueness: if no exchange specified, match normalized_symbol across all, prefer exchange null then any
    candidates = [i for i in instruments if isinstance(i, dict) and i.get("normalized_symbol") == norm]
    if candidates:
        # prefer exchange is null (canonical) else first
        inst = next((i for i in candidates if i.get("exchange") is None), candidates[0])

    if not inst:
        _log(api_key_id, {"symbol": symbol}, 404, "miss", (time.time() - t0) * 1000, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Fund symbol not found")

    if inst.get("asset_type") not in ("etf", "mutual_fund"):
        _log(api_key_id, {"symbol": symbol}, 404, "miss", (time.time() - t0) * 1000, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Symbol is not a fund")

    allowed_asset_types = chosen.get("allowed_asset_types")
    if allowed_asset_types is not None:
        if not isinstance(allowed_asset_types, list) or any(not isinstance(x, str) for x in allowed_asset_types):
            _log(api_key_id, params, 500, "bypass", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "API key allowed_asset_types is invalid in datastore")
        if inst.get("asset_type") not in allowed_asset_types:
            _log(api_key_id, params, 403, "bypass", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not permitted for this asset type")

    allowed_exchanges = chosen.get("allowed_exchanges")
    if allowed_exchanges is not None:
        if not isinstance(allowed_exchanges, list) or any(not isinstance(x, str) for x in allowed_exchanges):
            _log(api_key_id, params, 500, "bypass", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "API key allowed_exchanges is invalid in datastore")
        exch = inst.get("exchange")
        if exch is not None and exch not in allowed_exchanges:
            _log(api_key_id, params, 403, "bypass", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not permitted for this exchange")

    # Fetch latest fund info from content_items (fund_disclosure expected)
    content = _load("content_items.json")
    fund_items = [
        c for c in content
        if isinstance(c, dict)
        and c.get("status") == "active"
        and c.get("content_type") == "fund_disclosure"
        and c.get("instrument_id") == inst.get("id")
    ]
    if not fund_items:
        _log(api_key_id, {"symbol": symbol}, 404, "miss", (time.time() - t0) * 1000, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No fund info available for this symbol")

    def _item_sort_key(c):
        # prefer as_of_date then created_at
        asof = c.get("as_of_date")
        created = c.get("created_at")
        return (
            asof if isinstance(asof, str) else "",
            created if isinstance(created, str) else "",
        )

    latest = sorted(fund_items, key=_item_sort_key, reverse=True)[0]
    payload = latest.get("payload")
    if not isinstance(payload, dict):
        _log(api_key_id, {"symbol": symbol}, 500, "bypass", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Stored fund payload is invalid")

    # Build response as a single record: merge instrument reference fields + payload
    result = {
        "symbol": inst.get("symbol"),
        "name": inst.get("name"),
        "assetType": inst.get("asset_type"),
        "exchange": inst.get("exchange"),
        "currency": inst.get("currency"),
        "country": inst.get("country"),
        "asOfDate": latest.get("as_of_date"),
    }
    # Include entire payload (FMP-like)
    for k, v in payload.items():
        if k not in result:
            result[k] = v

    # Update key last_used_at
    keys2 = _load("api_keys.json")
    nowiso = _now_iso()
    for row in keys2:
        if isinstance(row, dict) and row.get("id") == api_key_id:
            row["last_used_at"] = nowiso
            row["updated_at"] = nowiso
            break
    _save("api_keys.json", keys2)

    _log(api_key_id, {"symbol": symbol}, 200, "miss", (time.time() - t0) * 1000, result_count=1, error_code=None)
    return {"data": result}

