    content = _load("content_items.json")

    # Latest disclosures: content_type='fund_disclosure', filter by instrument_id if known; otherwise by payload symbol if present
    rows = []
    for it in content:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "fund_disclosure":
            continue
        if inst and it.get("instrument_id") == inst.get("id"):
            rows.append(it)
        elif not inst:
            payload = it.get("payload")
            if isinstance(payload, dict) and _norm_symbol(payload.get("symbol")) == sym_n:
                rows.append(it)

    # Order by as_of_date desc then created_at desc
    def _key(r):
        return (
            (r.get("as_of_date") or ""),
            (r.get("created_at") or ""),
        )

    rows.sort(key=_key, reverse=True)

    # "Latest" => return latest group (best-effort): keep only most recent as_of_date if present
    if rows:
        top_date = rows[0].get("as_of_date")
        if top_date:
            rows = [r for r in rows if r.get("as_of_date") == top_date]

    # Update key last_used_at for successful authenticated request
    key_row["last_used_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()
    for idx, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            api_keys[idx] = key_row
            break
    _save("api_keys.json", api_keys)

    duration_ms = max(0, int((time.time() - started) * 1000))
    log_row = {
        "id": "req_" + uuid.uuid4().hex,
        "api_key_id": key_row["id"],
        "tool_name": "getDisclosure",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(rows),
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    logs.append(log_row)
    _save("request_logs.json", logs)

    return {"data": rows, "meta": {"result_count": len(rows)}}

def searchFundDisclosures(name, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_name(s):
        s = (s or "").strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    def _find_active_key(api_keys):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _quota_check(logs, key_row, now):
        minute_q = key_row.get("minute_request_quota")
        daily_q = key_row.get("daily_request_quota")
        if not isinstance(minute_q, int) or minute_q < 0:
            minute_q = 0
        if not isinstance(daily_q, int) or daily_q < 0:
            daily_q = 0

        def _parse(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        if minute_q == 0 or daily_q == 0:
            return False, "QUOTA_EXCEEDED"

        cutoff_min = now - datetime.timedelta(minutes=1)
        cutoff_day = now - datetime.timedelta(days=1)

        min_count = 0
        day_count = 0
        kid = key_row.get("id")
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != kid:
                continue
            t = _parse(r.get("created_at"))
            if not t:
                continue
            if t >= cutoff_day:
                day_count += 1
                if t >= cutoff_min:
                    min_count += 1

        if min_count + 1 > minute_q or day_count + 1 > daily_q:
            return False, "RATE_LIMIT"
        return True, None

    started = time.time()
    now_dt = datetime.datetime.utcnow()

    if name is None or not isinstance(name, str) or not name.strip():
        api_keys = _load("api_keys.json")
        logs = _load("request_logs.json")
        key_row = _find_active_key(api_keys)
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": key_row["id"] if key_row else "unknown",
            "tool_name": "searchFundDisclosures",
            "params": {"name": name},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": max(0, int((time.time() - started) * 1000)),
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string")

    params = {"name": name}

    api_keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    key_row = _find_active_key(api_keys)

    if not key_row:
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": "unknown",
            "tool_name": "searchFundDisclosures",
            "params": params,
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": max(0, int((time.time() - started) * 1000)),
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key is missing/invalid or not active")

    ok, qerr = _quota_check(logs, key_row, now_dt)
    if not ok:
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": key_row["id"],
            "tool_name": "searchFundDisclosures",
            "params": params,
            "http_status": 429,
            "cache_status": "bypass",
            "duration_ms": max(0, int((time.time() - started) * 1000)),
            "result_count": None,
            "error_code": qerr,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err(qerr, "Request quota/rate limit exceeded")

    if key_row.get("plan") not in ("starter", "pro", "enterprise"):
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": key_row["id"],
            "tool_name": "searchFundDisclosures",
            "params": params,
            "http_status": 403,
            "cache_status": "bypass",
            "duration_ms": max(0, int((time.time() - started) * 1000)),
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "Key is not entitled to this dataset")

    q = _norm_name(name)

    entities = _load("entities.json")
    # Search fund disclosure entities by name (entity_type fund/company, but allow any) using normalized_name substring
    # Return list (not paged). Server default cap: 100.
    limit = 100

    hits = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("status") != "active":
            continue
        nn = e.get("normalized_name")
        if not isinstance(nn, str) or not nn:
            continue
        if q in nn:
            hits.append(e)

    # Rank: prefix match first, then shorter name, then stable by id
    def _rank(e):
        nn = e.get("normalized_name") or ""
        return (0 if nn.startswith(q) else 1, len(nn), e.get("id") or "")

    hits.sort(key=_rank)
    hits = hits[:limit]

    # Map to an identifier-focused response
    out = []
    for e in hits:
        out.append(
            {
                "entity_id": e.get("id"),
                "name": e.get("name"),
                "cik": e.get("cik"),
                "entity_type": e.get("entity_type"),
                "country": e.get("country"),
                "sic_code": e.get("sic_code"),
                "sic_industry_title": e.get("sic_industry_title"),
            }
        )

    key_row["last_used_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()
    for idx, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            api_keys[idx] = key_row
            break
    _save("api_keys.json", api_keys)

    log_row = {
        "id": "req_" + uuid.uuid4().hex,
        "api_key_id": key_row["id"],
        "tool_name": "searchFundDisclosures",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": max(0, int((time.time() - started) * 1000)),
        "result_count": len(out),
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    logs.append(log_row)
    _save("request_logs.json", logs)

    return {"data": out, "meta": {"result_count": len(out), "limit": limit}}

