    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_intish(x):
        if isinstance(x, bool):
            return False
        if isinstance(x, int):
            return True
        if isinstance(x, float):
            return x.is_integer()
        return False

    def _parse_intish(x, field):
        if x is None:
            return None, None
        if not _is_intish(x):
            return None, _err("VALIDATION_ERROR", f"{field} must be an integer")
        return int(x), None

    def _norm_cik(c):
        if c is None:
            return None, None
        if not isinstance(c, str):
            return None, _err("VALIDATION_ERROR", "cik must be a string")
        s = c.strip()
        if s == "":
            return None, _err("VALIDATION_ERROR", "cik must not be blank")
        if not re.fullmatch(r"\d{1,10}", s):
            return None, _err("VALIDATION_ERROR", "cik must be 1-10 digits")
        return s.zfill(10), None

    def _log(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("rlog"),
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _quota_check(api_key_id, minute_quota, daily_quota):
        logs = _load("request_logs.json")
        now_dt = datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_dt(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                else:
                    s2 = s
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                return None

        minute_count = 0
        daily_count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                daily_count += 1
                if dt >= minute_ago:
                    minute_count += 1

        if isinstance(minute_quota, int) and minute_quota >= 0 and minute_count >= minute_quota:
            return _err("RATE_LIMIT", "Per-minute request quota exceeded"), 429
        if isinstance(daily_quota, int) and daily_quota >= 0 and daily_count >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Per-day request quota exceeded"), 429
        return None, None

    # Validate params (schema: page/limit numbers, cik string; no additionalProperties enforced by signature)
    ipage, e = _parse_intish(page, "page")
    if e:
        # auth+log attempt per business rule
        k = _pick_active_key()
        api_key_id = k["id"] if k else "unknown"
        dur = (time.time() - _t0) * 1000
        _log(api_key_id if k else "unknown", "getLatestEquityOfferings", {"page": page, "limit": limit, "cik": cik}, 400, "bypass", dur, result_count=None, error_code=e["error"]["code"])
        return e
    ilimit, e = _parse_intish(limit, "limit")
    if e:
        k = _pick_active_key()
        api_key_id = k["id"] if k else "unknown"
        dur = (time.time() - _t0) * 1000
        _log(api_key_id if k else "unknown", "getLatestEquityOfferings", {"page": page, "limit": limit, "cik": cik}, 400, "bypass", dur, result_count=None, error_code=e["error"]["code"])
        return e

    if ipage is None:
        ipage = 0
    if ilimit is None:
        ilimit = 10

    if ipage < 0:
        k = _pick_active_key()
        dur = (time.time() - _t0) * 1000
        _log(k["id"] if k else "unknown", "getLatestEquityOfferings", {"page": ipage, "limit": ilimit, "cik": cik}, 400, "bypass", dur, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be >= 0")
    if ilimit < 1 or ilimit > 1000:
        k = _pick_active_key()
        dur = (time.time() - _t0) * 1000
        _log(k["id"] if k else "unknown", "getLatestEquityOfferings", {"page": ipage, "limit": ilimit, "cik": cik}, 400, "bypass", dur, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")

    ncik, e = _norm_cik(cik)
    if e:
        k = _pick_active_key()
        dur = (time.time() - _t0) * 1000
        _log(k["id"] if k else "unknown", "getLatestEquityOfferings", {"page": ipage, "limit": ilimit, "cik": cik}, 400, "bypass", dur, error_code="VALIDATION_ERROR")
        return e

    # Authenticate (ambient): require some active key exists
    api_key = _pick_active_key()
    if not api_key:
        dur = (time.time() - _t0) * 1000
        _log("unknown", "getLatestEquityOfferings", {"page": ipage, "limit": ilimit, "cik": cik}, 401, "bypass", dur, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key")

    # Entitlement: equity_offering dataset (mapped to content_type 'equity_offering')
    # Assume free plan not entitled.
    if api_key.get("plan") == "free":
        dur = (time.time() - _t0) * 1000
        _log(api_key["id"], "getLatestEquityOfferings", {"page": ipage, "limit": ilimit, "cik": cik}, 403, "bypass", dur, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key not entitled to equity offerings dataset")

    # Quota
    qerr, http = _quota_check(api_key["id"], api_key.get("minute_request_quota", 0), api_key.get("daily_request_quota", 0))
    if qerr:
        dur = (time.time() - _t0) * 1000
        _log(api_key["id"], "getLatestEquityOfferings", {"page": ipage, "limit": ilimit, "cik": cik}, http, "bypass", dur, error_code=qerr["error"]["code"])
        return qerr

    # Query content_items
    items = _load("content_items.json")
    entities = _load("entities.json")
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and e.get("id")}

    filtered = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("content_type") != "equity_offering":
            continue
        if it.get("status") != "active":
            continue
        if ncik is not None:
            ent = ent_by_id.get(it.get("entity_id"))
            if not ent:
                continue
            if ent.get("cik") != ncik:
                continue
        filtered.append(it)

    # Order "latest": by as_of_date desc then created_at desc as a pragmatic provider-like ordering
    def _key(it):
        a = it.get("as_of_date") or ""
        c = it.get("created_at") or ""
        return (a, c)

    filtered.sort(key=_key, reverse=True)

    total = len(filtered)
    start = ipage * ilimit
    end = start + ilimit
    page_rows = filtered[start:end]

    # Update last_used_at on success
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            k["last_used_at"] = now
