    _save("api_keys.json", keys)

    dur = (time.time() - _t0) * 1000
    _log(api_key["id"], "getLatestEquityOfferings", {"page": ipage, "limit": ilimit, "cik": cik}, 200, "miss", dur, result_count=len(page_rows), error_code=None)

    return {
        "data": page_rows,
        "meta": {
            "page": ipage,
            "limit": ilimit,
            "total": total,
            "has_more": end < total,
            "next_cursor": None
        }
    }

