def getCryptocurrency1HourData(symbol, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return (False, _err("VALIDATION_ERROR", f"'{field}' must be a string in YYYY-MM-DD format."))
        try:
            datetime.datetime.strptime(s, "%Y-%m-%d")
            return s
        except ValueError:
            return (False, _err("VALIDATION_ERROR", f"'{field}' must be in YYYY-MM-DD format."))

    def _log_request(api_key_id, params_obj, http_status, cache_status, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        now = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": "getCryptocurrency1HourData",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": max(0, int((time.time() - _t0) * 1000)),
            "result_count": result_count,
            "error_code": error_code,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_active_key_and_enforce_quota(params_obj):
        keys = _load("api_keys.json")
        nowdt = datetime.datetime.utcnow()
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return (False, None, _err("UNAUTHORIZED", "No active API key available to authenticate this request."))
        logs = _load("request_logs.json")

        def _within_window(created_at, seconds):
            if not isinstance(created_at, str):
                return False
            s = created_at
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return False
            return (nowdt - dt).total_seconds() < seconds

        for k in active:
            kid = k.get("id")
            if not isinstance(kid, str) or not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            conc = k.get("concurrency_limit")
            if not (isinstance(min_q, int) and min_q >= 0 and isinstance(day_q, int) and day_q >= 0 and isinstance(conc, int) and conc >= 0):
                continue

            # Concurrency: approximate in-flight as last 30s with no way to see completion; treat as duration window.
            inflight = 0
            minute_used = 0
            day_used = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ca = r.get("created_at")
                if _within_window(ca, 30):
                    inflight += 1
                if _within_window(ca, 60):
                    minute_used += 1
                if _within_window(ca, 86400):
                    day_used += 1

            if conc > 0 and inflight >= conc:
                continue
            if min_q >= 0 and minute_used >= min_q:
                continue
            if day_q >= 0 and day_used >= day_q:
                continue

            return (True, k, None)

        # If we had active keys but all exceeded quota -> 429; else unauthorized
        # Determine whether quota exceeded for at least one active key.
        quota_exceeded = False
        for k in active:
            kid = k.get("id")
            if not isinstance(kid, str) or not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not (isinstance(min_q, int) and isinstance(day_q, int)):
                continue
            minute_used = 0
            day_used = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ca = r.get("created_at")
                if _within_window(ca, 60):
                    minute_used += 1
                if _within_window(ca, 86400):
                    day_used += 1
            if (min_q >= 0 and minute_used >= min_q) or (day_q >= 0 and day_used >= day_q):
                quota_exceeded = True
                break
        if quota_exceeded:
            return (False, active[0], _err("RATE_LIMIT", "Request quota exceeded."))
        return (False, None, _err("UNAUTHORIZED", "No active API key available to authenticate this request."))

    # Validate params object conforms to schema (no additionalProperties)
    if symbol is None or not isinstance(symbol, str) or not symbol.strip():
        # attempt to log with any available key context
        ok, k, auth_err = _pick_active_key_and_enforce_quota({"symbol": symbol, "from": from_, "to": to})
        api_key_id = (k or {}).get("id") if isinstance(k, dict) else "unknown"
        _log_request(api_key_id, {"symbol": symbol, "from": from_, "to": to}, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'symbol' is required and must be a non-empty string.")

    # dates validation
    pf = _parse_iso_date(from_, "from")
    if isinstance(pf, tuple) and pf and pf[0] is False:
        ok, k, _ = _pick_active_key_and_enforce_quota({"symbol": symbol, "from": from_, "to": to})
        api_key_id = (k or {}).get("id") if isinstance(k, dict) else "unknown"
        _log_request(api_key_id, {"symbol": symbol, "from": from_, "to": to}, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR")
        return pf[1]
    pt = _parse_iso_date(to, "to")
    if isinstance(pt, tuple) and pt and pt[0] is False:
        ok, k, _ = _pick_active_key_and_enforce_quota({"symbol": symbol, "from": from_, "to": to})
        api_key_id = (k or {}).get("id") if isinstance(k, dict) else "unknown"
        _log_request(api_key_id, {"symbol": symbol, "from": from_, "to": to}, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR")
        return pt[1]

    from_s = pf if isinstance(pf, str) else None
    to_s = pt if isinstance(pt, str) else None
    if from_s and to_s and from_s > to_s:
        ok, k, _ = _pick_active_key_and_enforce_quota({"symbol": symbol, "from": from_, "to": to})
        api_key_id = (k or {}).get("id") if isinstance(k, dict) else "unknown"
        _log_request(api_key_id, {"symbol": symbol, "from": from_, "to": to}, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'from' must be on or before 'to'.")

    params_obj = {"symbol": symbol, "from": from_s, "to": to_s}

    # Auth + quota
    ok, key, auth_or_quota_err = _pick_active_key_and_enforce_quota(params_obj)
    if not ok:
        api_key_id = (key or {}).get("id") if isinstance(key, dict) else "unknown"
        http_status = 429 if (auth_or_quota_err and auth_or_quota_err.get("error", {}).get("code") in ("RATE_LIMIT", "QUOTA_EXCEEDED")) else 401
        _log_request(api_key_id, params_obj, http_status, "bypass", result_count=None, error_code=auth_or_quota_err.get("error", {}).get("code") if auth_or_quota_err else "UNAUTHORIZED")
        return auth_or_quota_err or _err("UNAUTHORIZED", "Unauthorized.")

    # Update last_used_at on success auth attempt (not necessarily successful data retrieval; FMP typically counts requests regardless; we set on authenticated call)
    keys = _load("api_keys.json")
    now_iso = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    # Resolve instrument (crypto)
    instruments = _load("instruments.json")
    norm_symbol = symbol.strip().upper()
    inst = None
    for r in instruments:
        if not isinstance(r, dict):
            continue
        if r.get("normalized_symbol") == norm_symbol and r.get("asset_type") == "crypto":
            # enforce allowed exchanges/asset types
            allowed_assets = key.get("allowed_asset_types")
            if allowed_assets is not None and isinstance(allowed_assets, list) and r.get("asset_type") not in allowed_assets:
                _log_request(key["id"], params_obj, 403, "bypass", result_count=None, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "API key not permitted for this asset type.")
            allowed_ex = key.get("allowed_exchanges")
            ex = r.get("exchange")
            if allowed_ex is not None and isinstance(allowed_ex, list) and ex is not None and ex not in allowed_ex:
                _log_request(key["id"], params_obj, 403, "bypass", result_count=None, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "API key not permitted for this exchange.")
            inst = r
            break
    if inst is None:
        _log_request(key["id"], params_obj, 404, "miss", result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Unknown symbol.")

    # Fetch 1hour unadjusted regular session datapoints; crypto usually regular, but session enum is required.
    md = _load("market_data_points.json")
    rows = []
    for p in md:
        if not isinstance(p, dict):
            continue
        if p.get("instrument_id") != inst.get("id"):
            continue
        if p.get("timeframe") != "1hour":
            continue
        if p.get("adjustment_type") != "unadjusted":
            continue
        if p.get("session") != "regular":
            continue
        td = p.get("trade_date")
        if not isinstance(td, str):
            continue
        if from_s and td < from_s:
            continue
        if to_s and td > to_s:
            continue
        rows.append(p)

    if not rows:
        _log_request(key["id"], params_obj, 404, "miss", result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No 1-hour data available for the requested window.")

    def _ts_key(p):
        ts = p.get("ts")
        if isinstance(ts, str):
            return ts
        return ""
    rows.sort(key=_ts_key)

    # Server-side max rows per response safeguard
    MAX_ROWS = 5000
    if len(rows) > MAX_ROWS:
        rows = rows[-MAX_ROWS:]

    out = []
    for p in rows:
        out.append({
            "date": p.get("ts"),
            "open": p.get("open"),
            "high": p.get("high"),
            "low": p.get("low"),
            "close": p.get("close"),
            "volume": p.get("volume"),
            "vwap": p.get("vwap")
        })

    _log_request(key["id"], params_obj, 200, "miss", result_count=len(out), error_code=None)
    return out

