    if search is not None and not isinstance(search, str):
        # log below with 400
        validation_error = _err("VALIDATION_ERROR", "search must be a string")
        http_status = 400
        # will log after auth resolution attempt
        pass
    else:
        validation_error = None
        http_status = None

    if exchange is not None and not isinstance(exchange, str):
        validation_error = _err("VALIDATION_ERROR", "exchange must be a string")
        http_status = 400

    if limit is None:
        limit_val = 500
