        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            validation_error = _err("VALIDATION_ERROR", "limit must be a number")
            http_status = 400
            limit_val = None
        else:
            if int(limit) != limit:
                validation_error = _err("VALIDATION_ERROR", "limit must be an integer")
                http_status = 400
                limit_val = None
            else:
                limit_val = int(limit)
                if limit_val < 0:
                    validation_error = _err("VALIDATION_ERROR", "limit must be >= 0")
                    http_status = 400
                if limit_val > 10000:
                    validation_error = _err("VALIDATION_ERROR", "limit must be <= 10000")
                    http_status = 400

    # Ambient auth: choose any active key that can serve the call (quota/rate)
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
