        m_quota = key_row.get("minute_request_quota")
        d_quota = key_row.get("daily_request_quota")
        try:
            m_quota = int(m_quota)
            d_quota = int(d_quota)
        except Exception:
            return (True, "UNAUTHORIZED", 403, "API key is misconfigured")
        if m_quota < 0 or d_quota < 0:
            return (True, "UNAUTHORIZED", 403, "API key is misconfigured")

