            if rl.get("api_key_id") != kid:
                continue
            ts = _parse_ts(rl.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                m_count += 1
            if ts >= day_ago:
                d_count += 1
        if m_quota == 0 or m_count + 1 > m_quota:
            return (True, "RATE_LIMIT", 429, "Minute request quota exceeded")
        if d_quota == 0 or d_count + 1 > d_quota:
            return (True, "QUOTA_EXCEEDED", 429, "Daily request quota exceeded")
