    quota_block = None  # (code, http_status, msg)
    for k in api_keys:
        exceeds, code, hs, msg = _would_exceed(k)
        if not exceeds:
            chosen_key = k
            break
        # Prefer quota/rate errors over unauthorized if all fail
        if code in ("RATE_LIMIT", "QUOTA_EXCEEDED"):
            quota_block = (code, hs, msg)

    # Determine final auth error if no key works
    auth_error = None
    auth_http_status = None
    if chosen_key is None:
