                if search is not None:
                    q = search.strip().lower()
                    if q:
                        def _match(r):
                            sym = (r.get("symbol") or "")
                            nm = (r.get("name") or "")
                            return q in sym.lower() or q in nm.lower()
                        rows = [r for r in rows if _match(r)]

                # Stable sort by symbol then exchange
