                    })

                result_count = len(out)
                result = {"data": out, "meta": {"count": result_count, "limit": limit_val}}
                status = 200
                error_code = None

                # Update key last_used_at on success
                chosen_key["last_used_at"] = now
                chosen_key["updated_at"] = now
                _save("api_keys.json", api_keys)
    except Exception as e:
        result = _err("CONFLICT", "Internal error", detail=str(e))
        status = 409
        error_code = "CONFLICT"

    duration_ms = max(0, int((time.time() - t0) * 1000))

    # Write request log exactly once
    try:
        log_id = "rl_" + uuid.uuid4().hex
        api_key_id = chosen_key.get("id") if chosen_key else (api_keys[0].get("id") if api_keys else "unknown")
        # params must conform: only tool params, validated types as received
        params_obj = {}
