        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return (False, None, _err("UNAUTHORIZED", "No active API key available to authenticate this request."))
        logs = _load("request_logs.json")

        def _within_window(created_at, seconds):
            if not isinstance(created_at, str):
                return False
            s = created_at
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return False
            return (nowdt - dt).total_seconds() < seconds

        for k in active:
            kid = k.get("id")
            if not isinstance(kid, str) or not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            conc = k.get("concurrency_limit")
            if not (isinstance(min_q, int) and min_q >= 0 and isinstance(day_q, int) and day_q >= 0 and isinstance(conc, int) and conc >= 0):
                continue

            inflight = 0
            minute_used = 0
            day_used = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ca = r.get("created_at")
                if _within_window(ca, 30):
                    inflight += 1
                if _within_window(ca, 60):
                    minute_used += 1
                if _within_window(ca, 86400):
                    day_used += 1

            if conc > 0 and inflight >= conc:
                continue
            if min_q >= 0 and minute_used >= min_q:
                continue
            if day_q >= 0 and day_used >= day_q:
                continue
            return (True, k, None)

        quota_exceeded = False
        for k in active:
            kid = k.get("id")
            if not isinstance(kid, str) or not kid:
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not (isinstance(min_q, int) and isinstance(day_q, int)):
                continue
            minute_used = 0
            day_used = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ca = r.get("created_at")
                if _within_window(ca, 60):
                    minute_used += 1
                if _within_window(ca, 86400):
                    day_used += 1
            if (min_q >= 0 and minute_used >= min_q) or (day_q >= 0 and day_used >= day_q):
                quota_exceeded = True
                break
        if quota_exceeded:
            return (False, active[0], _err("RATE_LIMIT", "Request quota exceeded."))
        return (False, None, _err("UNAUTHORIZED", "No active API key available to authenticate this request."))

    # Validate symbol
    if symbol is None or not isinstance(symbol, str) or not symbol.strip():
