        return _err("VALIDATION_ERROR", "'symbol' is required and must be a non-empty string.")

    pf = _parse_iso_date(from_, "from")
    if isinstance(pf, tuple) and pf and pf[0] is False:
        ok, k, _ = _pick_active_key_and_enforce_quota({"symbol": symbol, "from": from_, "to": to})
        api_key_id = (k or {}).get("id") if isinstance(k, dict) else "unknown"
        _log_request(api_key_id, {"symbol": symbol, "from": from_, "to": to}, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR")
        return pf[1]
    pt = _parse_iso_date(to, "to")
    if isinstance(pt, tuple) and pt and pt[0] is False:
        ok, k, _ = _pick_active_key_and_enforce_quota({"symbol": symbol, "from": from_, "to": to})
        api_key_id = (k or {}).get("id") if isinstance(k, dict) else "unknown"
        _log_request(api_key_id, {"symbol": symbol, "from": from_, "to": to}, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR")
        return pt[1]

    from_s = pf if isinstance(pf, str) else None
    to_s = pt if isinstance(pt, str) else None
    if from_s and to_s and from_s > to_s:
        ok, k, _ = _pick_active_key_and_enforce_quota({"symbol": symbol, "from": from_, "to": to})
        api_key_id = (k or {}).get("id") if isinstance(k, dict) else "unknown"
        _log_request(api_key_id, {"symbol": symbol, "from": from_, "to": to}, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'from' must be on or before 'to'.")

    params_obj = {"symbol": symbol, "from": from_s, "to": to_s}

    ok, key, auth_or_quota_err = _pick_active_key_and_enforce_quota(params_obj)
    if not ok:
        api_key_id = (key or {}).get("id") if isinstance(key, dict) else "unknown"
        http_status = 429 if (auth_or_quota_err and auth_or_quota_err.get("error", {}).get("code") in ("RATE_LIMIT", "QUOTA_EXCEEDED")) else 401
        _log_request(api_key_id, params_obj, http_status, "bypass", result_count=None, error_code=auth_or_quota_err.get("error", {}).get("code") if auth_or_quota_err else "UNAUTHORIZED")
        return auth_or_quota_err or _err("UNAUTHORIZED", "Unauthorized.")

    # Touch last_used_at
    keys = _load("api_keys.json")
    now_iso = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    instruments = _load("instruments.json")
    norm_symbol = symbol.strip().upper()
    inst = None
    for r in instruments:
        if not isinstance(r, dict):
            continue
        if r.get("normalized_symbol") == norm_symbol and r.get("asset_type") == "forex":
            allowed_assets = key.get("allowed_asset_types")
            if allowed_assets is not None and isinstance(allowed_assets, list) and r.get("asset_type") not in allowed_assets:
                _log_request(key["id"], params_obj, 403, "bypass", result_count=None, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "API key not permitted for this asset type.")
            allowed_ex = key.get("allowed_exchanges")
            ex = r.get("exchange")
            if allowed_ex is not None and isinstance(allowed_ex, list) and ex is not None and ex not in allowed_ex:
                _log_request(key["id"], params_obj, 403, "bypass", result_count=None, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "API key not permitted for this exchange.")
            inst = r
            break
    if inst is None:
        _log_request(key["id"], params_obj, 404, "miss", result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Unknown forex symbol.")

    md = _load("market_data_points.json")
    rows = []
    for p in md:
        if not isinstance(p, dict):
            continue
        if p.get("instrument_id") != inst.get("id"):
            continue
        if p.get("timeframe") != "1day":
            continue
        if p.get("adjustment_type") != "unadjusted":
            continue
        if p.get("session") != "regular":
            continue
        td = p.get("trade_date")
        if not isinstance(td, str):
            continue
        if from_s and td < from_s:
            continue
        if to_s and td > to_s:
            continue
        rows.append(p)

    if not rows:
        _log_request(key["id"], params_obj, 404, "miss", result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No historical data available for the requested window.")

    rows.sort(key=lambda p: p.get("ts") if isinstance(p.get("ts"), str) else "")

    MAX_ROWS = 10000
    if len(rows) > MAX_ROWS:
        rows = rows[-MAX_ROWS:]

    out = []
    for p in rows:
        out.append({
            "date": p.get("trade_date"),
            "open": p.get("open"),
            "high": p.get("high"),
            "low": p.get("low"),
            "close": p.get("close")
        })

    _log_request(key["id"], params_obj, 200, "miss", result_count=len(out), error_code=None)
    return out

