        # Rolling windows based on request_logs.created_at timestamps.
        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            # expecting ISO with Z
            try:
                if ts.endswith("Z"):
                    ts2 = ts[:-1]
                else:
                    ts2 = ts
                return datetime.datetime.fromisoformat(ts2)
            except Exception:
                return None

        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
