        if inst.get("asset_type") not in allowed_asset_types:
            duration_ms = (time.time() - _t0) * 1000.0
            _log(api_key["id"], params_obj, 403, duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is not permitted for this asset type.")

    allowed_exchanges = api_key.get("allowed_exchanges")
    if allowed_exchanges is not None:
        if not isinstance(allowed_exchanges, list) or any(not isinstance(x, str) for x in allowed_exchanges):
            duration_ms = (time.time() - _t0) * 1000.0
            _log(api_key["id"], params_obj, 403, duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key exchange permissions are misconfigured.")
        ex = inst.get("exchange")
