            continue
        if from_d is not None and td < from_d.isoformat():
            continue
        if to_d is not None and td > to_d.isoformat():
            continue
        rows.append(p)

    # Default window if from/to omitted: most recent 1000 bars
    # Also enforce a server-side max rows
    MAX_ROWS = 1000
    # sort by ts ascending
    def _ts_key(x):
        ts = x.get("ts")
        if not isinstance(ts, str):
            return ""
        return ts
    rows.sort(key=_ts_key)

    if from_d is None and to_d is None:
        if len(rows) > MAX_ROWS:
            rows = rows[-MAX_ROWS:]
    else:
