        if ci.get("status") == "deleted":
            continue
        if period is not None and ci.get("period") is not None and ci.get("period") != period:
            continue
        payload = ci.get("payload")
        if not isinstance(payload, dict):
            continue
        st = payload.get("statementType") or payload.get("type")
        if isinstance(st, str) and st.lower() not in ("cash_flow", "cashflow", "cash_flow_statement", "cash flow"):
            continue
        # prefer a canonical date
        d = ci.get("as_of_date") or payload.get("date") or payload.get("fillingDate") or payload.get("filingDate")
        rows.append({
            "symbol": inst.get("symbol") or sym,
            "date": d,
            "period": ci.get("period"),
            "year": ci.get("year"),
            "quarter": ci.get("quarter"),
            **payload
        })

    # If provider stored the statement rows directly in payload.rows (bulk-like), expand
    expanded = []
    for r in rows:
        if isinstance(r.get("rows"), list):
            for item in r["rows"]:
                if isinstance(item, dict):
                    rr = dict(item)
                    rr.setdefault("symbol", r.get("symbol") or sym)
                    if r.get("period") is not None:
                        rr.setdefault("period", r.get("period"))
                    expanded.append(rr)
        else:
            expanded.append(r)

