    key, pre_err, http_status, api_keys, req_logs = _pick_active_key_and_enforce_quota(validated_params)
    if pre_err:
        api_key_id = _fallback_key_id(api_keys)
        if api_key_id:
            req_logs.append(_make_log(api_key_id, validated_params, http_status, "bypass", (time.time() - _t0) * 1000, None, pre_err))
