        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "Symbol not found", symbol=norm_symbol)

    # Prefer active instrument if multiple
    inst = None
    for cand in matched:
        if cand.get("status") == "active":
            inst = cand
            break
    if inst is None:
        inst = matched[0]
    inst_id = inst.get("id")

    # Read content items of type financial_statement where payload indicates income statement TTM
    content = _load("content_items.json")
    rows = []
    for it in content:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "financial_statement":
            continue
        if it.get("instrument_id") != inst_id:
            continue
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue
        # Accept common keys that might indicate TTM income statement
        stype = payload.get("statementType") or payload.get("statement_type") or payload.get("type")
        is_ttm = payload.get("isTTM")
        period = it.get("period") or payload.get("period")
        if (is_ttm is True) or (isinstance(period, str) and period.upper() == "TTM"):
            if stype is None or str(stype).lower() in ("income", "income_statement", "incomestatement", "is"):
                rows.append(payload)
        else:
            # Some datasets store income-statement TTM as content_type=financial_statement with identifier_1 marker
            ident = it.get("identifier_1")
            if isinstance(ident, str) and ident.lower() in ("income_ttm", "income-statement-ttm", "income_statement_ttm"):
                rows.append(payload)

    # Sort by a date field if present
    def _date_key(p):
        if not isinstance(p, dict):
            return ""
        return p.get("date") or p.get("calendarYear") or p.get("asOfDate") or p.get("reportedDate") or ""
    rows.sort(key=_date_key, reverse=True)

    if not rows:
        api_key_id = key["id"]
        req_logs = _load("request_logs.json")
        req_logs.append(_make_log(api_key_id, validated_params, 404, "bypass", (time.time() - _t0) * 1000, None, "NOT_FOUND"))
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "TTM income statements not found for symbol", symbol=norm_symbol)

    out = rows[:limit_i]

    # Update last_used_at on success
    api_key_id = key["id"]
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = _now
            k["updated_at"] = _now
            break
    _save("api_keys.json", api_keys)

    # Log request
    req_logs = _load("request_logs.json")
    req_logs.append(_make_log(api_key_id, validated_params, 200, "miss", (time.time() - _t0) * 1000, result_count=len(out), error_code=None))
    _save("request_logs.json", req_logs)

    return {"data": out, "meta": {"symbol": norm_symbol, "limit": limit_i, "returned": len(out)}}

def getBalanceSheetStatementTTM(symbol, limit=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getBalanceSheetStatementTTM"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    def _iso_now_z(dt=None):
        dt = dt or datetime.datetime.now(datetime.timezone.utc)
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        seed = hashlib.sha1((str(time.time()) + "|" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{seed}"

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        now_iso = _iso_now_z(now_dt)
        duration_ms = int((time.time() - t0) * 1000)
        if duration_ms < 0:
            duration_ms = 0
        logs.append({
            "id": _new_id("fmp_req"),
            "api_key_id": api_key_id if isinstance(api_key_id, str) else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status) if isinstance(http_status, int) or (isinstance(http_status, float) and http_status.is_integer()) else 500,
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (int(result_count) if isinstance(result_count, int) and result_count >= 0 else None),
            "error_code": error_code if isinstance(error_code, str) else None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)

    def _select_active_key_for_request():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None, _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _count_for(kid):
            m = d = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                dt = _parse_dt_any(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= minute_ago:
                    m += 1
                if dt >= day_ago:
                    d += 1
            return m, d

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                continue
            if day_q and d + 1 > day_q:
                continue
            return k, None

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                return None, _err("RATE_LIMIT", "Request quota exceeded.", reason="quota_minute_exceeded", http_status=429)
            if day_q and d + 1 > day_q:
                return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", reason="quota_daily_exceeded", http_status=429)
        return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

    params_obj = {"symbol": symbol, "limit": limit}

    if not isinstance(symbol, str) or not symbol.strip():
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`symbol` must be a non-empty string.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err
    sym = symbol.strip().upper()

    if limit is None:
        lim = 100
    else:
        if not isinstance(limit, (int, float)) or (isinstance(limit, float) and not limit.is_integer()):
            key, kerr = _select_active_key_for_request()
            kid = key["id"] if key else "unknown"
            err = _err("VALIDATION_ERROR", "`limit` must be a number.", http_status=400)
            _log(kid, params_obj, 400, error_code="validation_error")
            return err
        lim = int(limit)
    if lim < 1 or lim > 1000:
        key, kerr = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`limit` must be between 1 and 1000.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err

    key, kerr = _select_active_key_for_request()
    if kerr:
        _log("unknown", params_obj, kerr["error"].get("http_status", 401), error_code=kerr["error"].get("reason") or kerr["error"]["code"].lower())
        return kerr
    kid = key["id"]

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    inst = None
    for ins in instruments:
        if isinstance(ins, dict) and ins.get("normalized_symbol") == sym:
            inst = ins
            break
    if inst is None:
        err = _err("NOT_FOUND", "Symbol not found.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="symbol_not_found")
        return err

    content = _load("content_items.json")
    if not isinstance(content, list):
        content = []

    # locate TTM balance sheet observations
    rows = []
    for ci in content:
        if not isinstance(ci, dict):
            continue
        if ci.get("status") == "deleted":
            continue
        if ci.get("instrument_id") != inst.get("id"):
            continue
        if ci.get("content_type") not in ("financial_statement", "financial_report", "key_metrics", "ratios"):
            continue
        payload = ci.get("payload")
        if not isinstance(payload, dict):
            continue
        # heuristics: payload.period == 'TTM' or payload.isTTM
        pper = payload.get("period") or payload.get("calendarPeriod")
        if isinstance(payload.get("isTTM"), bool) and payload.get("isTTM") is True:
            is_ttm = True
        else:
            is_ttm = isinstance(pper, str) and pper.upper() == "TTM"
        st = payload.get("statementType") or payload.get("type")
        if isinstance(st, str) and st.lower() not in ("balance_sheet", "balancesheet", "balance_sheet_statement", "balance sheet"):
            # allow key_metrics/ratios that carry balance-sheet-like fields under ttm
            if ci.get("content_type") not in ("key_metrics", "ratios"):
                continue
        if not is_ttm:
            continue
        d = ci.get("as_of_date") or payload.get("date")
        row = {"symbol": inst.get("symbol") or sym, "date": d, **payload}
        rows.append(row)

    def _sort_key(x):
        d = x.get("date")
        if isinstance(d, str) and len(d) >= 10:
            d10 = d[:10]
            try:
                return datetime.date.fromisoformat(d10)
            except Exception:
                return datetime.date.min
        return datetime.date.min

    rows.sort(key=_sort_key, reverse=True)
    out = rows[:lim]

    if not out:
        err = _err("NOT_FOUND", "No TTM balance sheet data available for this symbol.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="symbol_not_found")
        return err

    keys_all = _load("api_keys.json")
    if isinstance(keys_all, list):
        for k in keys_all:
            if isinstance(k, dict) and k.get("id") == kid:
                k["last_used_at"] = _iso_now_z(now_dt)
                k["updated_at"] = _iso_now_z(now_dt)
                _save("api_keys.json", keys_all)
                break

    _log(kid, params_obj, 200, result_count=len(out))
    return {"data": out, "meta": {"symbol": sym, "count": len(out), "limit": lim}}

