            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "getIncomeStatementGrowth"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mklogid():
        return "req_" + uuid.uuid4().hex

    def _norm_symbol(s):
        return s.strip().upper()

    def _find_active_key(api_keys):
        # Ambient auth: pick any api_key that can serve the request (active + within quotas).
        for k in api_keys:
            if k.get("status") == "active":
                return k
        return None

    def _rolling_counts(request_logs, api_key_id, now):
        one_min_ago = now - datetime.timedelta(minutes=1)
        one_day_ago = now - datetime.timedelta(days=1)
        m = 0
        d = 0
        inflight = 0  # not observable in offline store; keep for compatibility
        for r in request_logs:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= one_min_ago:
                m += 1
