    tool_name = "getBalanceSheetStatementGrowth"
    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id():
        return f"fmp_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(os.urandom(16)).hexdigest()[:18]}"

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_id(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rolling_counts(api_key_id, now_dt):
        logs = _load("request_logs.json")
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                d += 1
                if dt >= minute_ago:
                    m += 1
        return m, d

    def _resolve_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota(keyrow):
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        minute_q = keyrow.get("minute_request_quota")
        daily_q = keyrow.get("daily_request_quota")
        if not isinstance(minute_q, int) or minute_q < 0:
            minute_q = 0
        if not isinstance(daily_q, int) or daily_q < 0:
            daily_q = 0
        m, d = _rolling_counts(keyrow["id"], now_dt)
        if m + 1 > minute_q:
            return False, "quota_minute_exceeded"
        if d + 1 > daily_q:
            return False, "quota_daily_exceeded"
        return True, None

