        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_quota=key.get("daily_request_quota"), daily_used=used_day)

    instruments = _load("instruments.json")
    inst = None
    for r in instruments:
        if r.get("normalized_symbol") == sym:
            inst = r
            break

    allowed_ex = key.get("allowed_exchanges", None)
    allowed_at = key.get("allowed_asset_types", None)
    if inst is not None:
        if allowed_ex is not None:
            if not isinstance(allowed_ex, list) or (inst.get("exchange") not in allowed_ex):
                _log_attempt(request_logs, key["id"], params_obj, 403, (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
