                _save("request_logs.json", request_logs)
                return _err("UNAUTHORIZED", "API key not authorized for this asset type.")

    # Consolidated growth: merge income/balance/cashflow for same period/date if present.
    content_items = _load("content_items.json")
    merged = {}  # key -> dict
    order_keys = []  # to sort later

    def _bucket_key(ci):
        # Prefer as_of_date; include period for clarity; fallback to year/quarter.
        return (
            ci.get("as_of_date") or "",
            ci.get("period") or "",
            ci.get("year") or 0,
            ci.get("quarter") or 0,
        )

    def _kind(ci):
        id1 = ci.get("identifier_1")
        if not isinstance(id1, str) or not id1:
            return None
        v = id1.lower()
        if v in ("income", "income_statement", "income-statement"):
            return "income"
        if v in ("balance", "balance_sheet", "balance-sheet", "balance_sheet_statement"):
            return "balance"
        if v in ("cashflow", "cash_flow", "cash-flow", "cash_flow_statement"):
            return "cashflow"
        return None

    if inst is not None:
        iid = inst.get("id")
        for ci in content_items:
            if ci.get("status") != "active":
                continue
            if ci.get("content_type") != "financial_statement_growth":
                continue
            if ci.get("instrument_id") != iid:
                continue
            if period is not None and ci.get("period") != period:
                continue

            knd = _kind(ci)
            # If statement type not tagged, include it but don't namespace (best effort)
            payload = ci.get("payload")
            p = dict(payload) if isinstance(payload, dict) else {}
            p.setdefault("symbol", sym)
            if ci.get("period") is not None and "period" not in p:
                p["period"] = ci.get("period")
            if ci.get("as_of_date") is not None and "date" not in p:
                p["date"] = ci.get("as_of_date")
            if ci.get("year") is not None and "calendarYear" not in p:
                p["calendarYear"] = str(ci.get("year"))
            if ci.get("quarter") is not None and "quarter" not in p:
                p["quarter"] = ci.get("quarter")

            bk = _bucket_key(ci)
            if bk not in merged:
                merged[bk] = {"symbol": sym}
                order_keys.append(bk)

            if knd is None:
                # merge flat (may overwrite)
                merged[bk].update(p)
            else:
                # namespace to reduce collisions: incomeGrowth.*, balanceGrowth.*, cashflowGrowth.*
                prefix = {"income": "incomeGrowth", "balance": "balanceGrowth", "cashflow": "cashFlowGrowth"}[knd]
                merged[bk].setdefault(prefix, {})
                if isinstance(merged[bk][prefix], dict):
                    merged[bk][prefix].update(p)

                # also promote common timeline fields
                for fld in ("date", "period", "calendarYear", "quarter"):
                    if fld in p and fld not in merged[bk]:
                        merged[bk][fld] = p[fld]

    # sort reverse-chronological
    order_keys.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
    out_rows = [merged[k] for k in order_keys[::-1]]
    if lim:
        out_rows = out_rows[:lim]

    nowiso = _now_iso()
    for k in api_keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = nowiso
            k["updated_at"] = nowiso
            break
    _save("api_keys.json", api_keys)

    _log_attempt(request_logs, key["id"], params_obj, 200, (time.time() - t0) * 1000, result_count=len(out_rows))
    _save("request_logs.json", request_logs)
    return out_rows

def getFinancialReportsDates(symbol, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_symbol(s):
        return s.strip().upper()

    def _mkid(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _hash_key_presented(v):
        # Authenticate against stored key_hash by hashing the presented plaintext value
        # (store never contains plaintext; comparing plaintext to ciphertext would never work).
        return hashlib.sha256(v.encode("utf-8")).hexdigest()

    def _find_api_key(api_keys):
        # Ambient auth: choose an active key that can serve this call (plan-based).
        # If caller provided anything in _extra, treat it as explicit credential if available.
        presented = None
        for k in ("api_key", "apikey", "key", "token", "apiKey"):
            if k in _extra and isinstance(_extra.get(k), str) and _extra.get(k).strip():
                presented = _extra.get(k).strip()
                break
        if presented is not None:
            h = _hash_key_presented(presented)
            for r in api_keys:
                if r.get("status") == "active" and (r.get("id") == presented or r.get("key_hash") == h):
                    return r
            return None
        # No explicit credential parameter: pick any active key (service-side context).
        for r in api_keys:
            if r.get("status") == "active":
                return r
        return None

    def _quota_check(logs, key_row, now):
        minute_q = key_row.get("minute_request_quota")
        daily_q = key_row.get("daily_request_quota")
        try:
            minute_q = int(minute_q)
            daily_q = int(daily_q)
        except Exception:
            return _err("VALIDATION_ERROR", "API key quota configuration is invalid.")

        if minute_q < 0 or daily_q < 0:
            return _err("VALIDATION_ERROR", "API key quota configuration is invalid.")

        now_ts = now.timestamp()
        minute_ago = now_ts - 60
        day_ago = now_ts - 86400

        def _parse_ts(x):
            if not isinstance(x, str):
                return None
            try:
                if x.endswith("Z"):
                    x = x[:-1]
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None

        m = 0
        d = 0
        kid = key_row.get("id")
        for row in logs:
            if row.get("api_key_id") != kid:
                continue
            t = _parse_ts(row.get("created_at"))
            if not t:
                continue
            ts = t.replace(tzinfo=None).timestamp()
            if ts >= day_ago:
                d += 1
                if ts >= minute_ago:
                    m += 1

        if minute_q == 0 or m >= minute_q:
            return _err("RATE_LIMIT", "Minute request quota exceeded.", limit=minute_q, window_seconds=60)
        if daily_q == 0 or d >= daily_q:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=daily_q, window_seconds=86400)
        return None

    t0 = time.time()
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    instruments = _load("instruments.json")
    content_items = _load("content_items.json")

    now_dt = datetime.datetime.utcnow()
    key_row = _find_api_key(api_keys)

    # Validate params (additionalProperties already enforced by signature)
    params_obj = {"symbol": symbol}
    if not isinstance(symbol, str) or not symbol.strip():
        # log attempt (unauth is evaluated after validation? vendor says validation error for missing/blank symbol)
        http_status = 400
        api_key_id = key_row.get("id") if key_row else "unknown"
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": _mkid("req"),
            "api_key_id": api_key_id,
            "tool_name": "getFinancialReportsDates",
            "params": {"symbol": symbol} if isinstance(symbol, str) else {"symbol": None},
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.")

    if not key_row:
        http_status = 401
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": _mkid("req"),
            "api_key_id": "unknown",
            "tool_name": "getFinancialReportsDates",
            "params": {"symbol": symbol},
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    # Quota enforcement before servicing
    qerr = _quota_check(request_logs, key_row, now_dt)
    if qerr:
        http_status = 429
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": _mkid("req"),
            "api_key_id": key_row.get("id"),
            "tool_name": "getFinancialReportsDates",
            "params": params_obj,
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": qerr["error"]["code"],
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return qerr

    # Plan permissions: financial_report dataset requires paid (starter+)
    if key_row.get("plan") not in ("starter", "pro", "enterprise"):
        http_status = 403
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": _mkid("req"),
            "api_key_id": key_row.get("id"),
            "tool_name": "getFinancialReportsDates",
            "params": params_obj,
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Forbidden: your plan does not include access to financial reports.")

    norm = _norm_symbol(symbol)

    inst = None
    for r in instruments:
        if r.get("normalized_symbol") == norm and r.get("status") in ("active", "inactive", "delisted"):
            inst = r
            break
    if not inst:
        http_status = 404
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": _mkid("req"),
            "api_key_id": key_row.get("id"),
            "tool_name": "getFinancialReportsDates",
            "params": params_obj,
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": 0,
            "error_code": "NOT_FOUND",
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Symbol not found.")

    # allowed exchanges / asset types enforcement
    if isinstance(key_row.get("allowed_asset_types"), list) and inst.get("asset_type") not in key_row.get("allowed_asset_types"):
        http_status = 403
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": _mkid("req"),
            "api_key_id": key_row.get("id"),
            "tool_name": "getFinancialReportsDates",
            "params": params_obj,
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Forbidden: asset type not allowed for this API key.")
    if isinstance(key_row.get("allowed_exchanges"), list):
        ex = inst.get("exchange")
        if ex is not None and ex not in key_row.get("allowed_exchanges"):
            http_status = 403
            duration_ms = max(0, int((time.time() - t0) * 1000))
            request_logs.append({
                "id": _mkid("req"),
                "api_key_id": key_row.get("id"),
                "tool_name": "getFinancialReportsDates",
                "params": params_obj,
                "http_status": http_status,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "UNAUTHORIZED",
                "created_at": _now_iso(),
                "updated_at": _now_iso()
            })
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Forbidden: exchange not allowed for this API key.")

    # Collect available dates for content_type financial_report for that instrument.
    dates = set()
    for it in content_items:
        if it.get("content_type") != "financial_report":
            continue
        if it.get("status") != "active":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        d = it.get("as_of_date") or it.get("payload", {}).get("date") or it.get("payload", {}).get("filingDate")
        if isinstance(d, str) and len(d) >= 10:
            dates.add(d[:10])

    out = sorted(dates, reverse=True)

    # update last_used_at on success
    for r in api_keys:
        if r.get("id") == key_row.get("id"):
            r["last_used_at"] = _now_iso()
            r["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    http_status = 200
    duration_ms = max(0, int((time.time() - t0) * 1000))
    request_logs.append({
        "id": _mkid("req"),
        "api_key_id": key_row.get("id"),
        "tool_name": "getFinancialReportsDates",
        "params": params_obj,
        "http_status": http_status,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(out),
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso()
    })
    _save("request_logs.json", request_logs)

    return {"symbol": norm, "dates": out, "count": len(out)}

