        if it.get("year") != year_i:
            continue
        if it.get("period") != period:
            continue
        report_row = it
        break

    if not report_row:
        http_status = 404
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": _mkid("req"),
            "api_key_id": key_row.get("id"),
            "tool_name": "getFinancialReportXLSX",
            "params": {"symbol": norm, "year": year_i, "period": period},
            "http_status": http_status,
            "cache_status": "miss",
            "duration_ms": duration_ms,
            "result_count": 0,
            "error_code": "NOT_FOUND",
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Financial report not found for the requested symbol/year/period.")

    # Produce an XLSX-like binary if present in payload; otherwise return a deterministic CSV-as-bytes (since store is offline).
    payload = report_row.get("payload") or {}
    x = payload.get("xlsx_base64")
    if isinstance(x, str) and x.strip():
        try:
            file_bytes = base64.b64decode(x.encode("utf-8"), validate=False)
        except Exception:
            file_bytes = None
    else:
        file_bytes = None

    if file_bytes is None:
        # Minimal spreadsheet-friendly export (CSV) from common payload patterns.
        # We return as "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" but the data is CSV bytes
        # when no true xlsx is stored; this mirrors an offline datastore limitation but is still an effectful response.
        rows = payload.get("rows")
        if not isinstance(rows, list):
            rows = []
        # flatten dict rows -> header union
        header = []
        if rows and all(isinstance(r, dict) for r in rows):
            keys = []
            seen = set()
            for r in rows:
                for k in r.keys():
                    if k not in seen:
                        seen.add(k)
                        keys.append(k)
            header = keys
            csv_lines = [",".join(str(h).replace(",", " ") for h in header)]
            for r in rows:
                csv_lines.append(",".join(str(r.get(h, "")).replace(",", " ") for h in header))
            csv_text = "\n".join(csv_lines)
        else:
            csv_text = "report\n" + json.dumps(payload, ensure_ascii=False)
        file_bytes = csv_text.encode("utf-8")

    for r in api_keys:
        if r.get("id") == key_row.get("id"):
            r["last_used_at"] = _now_iso()
            r["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    b64 = base64.b64encode(file_bytes).decode("ascii")
    filename = f"{norm}_{year_i}_{period}.xlsx"

    http_status = 200
    duration_ms = max(0, int((time.time() - t0) * 1000))
    request_logs.append({
        "id": _mkid("req"),
        "api_key_id": key_row.get("id"),
        "tool_name": "getFinancialReportXLSX",
        "params": {"symbol": norm, "year": year_i, "period": period},
        "http_status": http_status,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": 1,
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso()
    })
    _save("request_logs.json", request_logs)

    return {
        "symbol": norm,
        "year": year_i,
        "period": period,
        "filename": filename,
        "content_type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "file_base64": b64,
        "size_bytes": len(file_bytes)
    }

