                "updated_at": _now_iso()
            })
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Forbidden: exchange not allowed for this API key.")

    # Pull segmentation items from content_items; map to an expected output list.
    # We store these as content_type='financial_report' or 'financial_statement' with payload carrying segmentation.
    items = []
    for it in content_items:
        if it.get("status") != "active":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        if it.get("content_type") not in ("financial_report", "financial_statement"):
            continue
        p = it.get("payload") or {}
        seg = p.get("revenueProductSegmentation") or p.get("revenue_product_segmentation") or p.get("productSegmentation")
        if not seg:
            continue
        # period filter: prefer it.period when present; fallback to payload periodType
        per = it.get("period")
        if per is None:
            per = p.get("period") or p.get("periodType")
        if period is not None:
            # "annual" / "quarter" mapped from content_items.period often "annual"/"quarter"
            if per != period:
                continue
        as_of = it.get("as_of_date") or p.get("date") or p.get("asOfDate")
        if isinstance(seg, list):
            for row in seg:
                if isinstance(row, dict):
                    out_row = dict(row)
                    out_row.setdefault("symbol", norm)
                    if as_of:
                        out_row.setdefault("date", as_of)
                    if per:
                        out_row.setdefault("period", per)
                    items.append(out_row)
        elif isinstance(seg, dict):
            out_row = dict(seg)
            out_row.setdefault("symbol", norm)
            if as_of:
                out_row.setdefault("date", as_of)
            if per:
                out_row.setdefault("period", per)
            items.append(out_row)

    # structure=flat is the only supported; already flat list.
    # Sort by date desc if date present
    def _date_key(r):
        d = r.get("date")
        return d if isinstance(d, str) else ""
    items.sort(key=_date_key, reverse=True)

    for r in api_keys:
        if r.get("id") == key_row.get("id"):
            r["last_used_at"] = _now_iso()
            r["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    http_status = 200
    duration_ms = max(0, int((time.time() - t0) * 1000))
