        "http_status": http_status,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(items),
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso()
    })
    _save("request_logs.json", request_logs)

    return {"symbol": norm, "period": period, "structure": structure or "flat", "data": items, "count": len(items)}

