def getIncomeStatementAsReported(symbol, limit=None, period=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    if period is not None:
        if not isinstance(period, str) or period not in ("annual", "quarter"):
            return _err("VALIDATION_ERROR", "period must be one of: annual, quarter")
    if limit is None:
        limit_i = 100
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be a number")
        if int(limit) != limit:
            return _err("VALIDATION_ERROR", "limit must be an integer")
        limit_i = int(limit)
    if limit_i < 1 or limit_i > 1000:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")

    params_obj = {"symbol": symbol}
    if limit is not None:
        params_obj["limit"] = limit_i
    if period is not None:
        params_obj["period"] = period

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = _parse_ts(_now) or datetime.datetime.utcnow().replace(microsecond=0)

    def _count_requests_for_key(key_id, window_seconds):
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                c += 1
        return c

    chosen_key = None
    quota_violation = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        key_id = k.get("id")
        if not isinstance(key_id, str) or not key_id:
            continue
        minute_q = k.get("minute_request_quota")
        daily_q = k.get("daily_request_quota")
        if not isinstance(minute_q, int) or minute_q < 0:
            continue
        if not isinstance(daily_q, int) or daily_q < 0:
            continue
        minute_used = _count_requests_for_key(key_id, 60)
        daily_used = _count_requests_for_key(key_id, 86400)
        if (minute_used + 1) > minute_q:
            quota_violation = ("RATE_LIMIT", "minute request quota exceeded")
            continue
        if (daily_used + 1) > daily_q:
            quota_violation = ("QUOTA_EXCEEDED", "daily request quota exceeded")
            continue
        chosen_key = k
        break

    def _log_and_return(http_status, body, result_count=None, error_code=None):
        duration_ms = int(max(0, round((time.time() - _t0) * 1000)))
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": (chosen_key.get("id") if chosen_key else "unknown"),
            "tool_name": "getIncomeStatementAsReported",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": result_count,
            "error_code": error_code,
            "created_at": _now,
            "updated_at": _now,
        }
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        if chosen_key and 200 <= http_status <= 299:
            kid = chosen_key.get("id")
            for kk in api_keys:
                if kk.get("id") == kid:
                    kk["last_used_at"] = _now
                    kk["updated_at"] = _now
                    break
            _save("api_keys.json", api_keys)
        return body

    if chosen_key is None:
        if quota_violation:
            code, msg = quota_violation
            body = _err(code, msg)
            return _log_and_return(429, body, error_code=code)
        body = _err("UNAUTHORIZED", "missing or invalid API key")
        return _log_and_return(401, body, error_code="UNAUTHORIZED")

    instruments = _load("instruments.json")
    sym_norm = symbol.strip().upper()
    inst = None
    for row in instruments:
        if row.get("normalized_symbol") == sym_norm:
            inst = row
            break
    if inst is None:
        body = _err("NOT_FOUND", "symbol not found")
        return _log_and_return(404, body, error_code="NOT_FOUND")

    # allowlists
    allowed_ex = chosen_key.get("allowed_exchanges")
    if allowed_ex is not None:
        if not isinstance(allowed_ex, list) or inst.get("exchange") not in allowed_ex:
            body = _err("UNAUTHORIZED", "API key not allowed for this exchange")
            return _log_and_return(403, body, error_code="UNAUTHORIZED")
    allowed_at = chosen_key.get("allowed_asset_types")
    if allowed_at is not None:
        if not isinstance(allowed_at, list) or inst.get("asset_type") not in allowed_at:
            body = _err("UNAUTHORIZED", "API key not allowed for this asset type")
            return _log_and_return(403, body, error_code="UNAUTHORIZED")

    # Plan permissions (as-reported filings treated as paid for starter+)
    plan = chosen_key.get("plan")
    if plan not in ("starter", "pro", "enterprise"):
        body = _err("UNAUTHORIZED", "insufficient plan permissions")
        return _log_and_return(403, body, error_code="UNAUTHORIZED")

    content_items = _load("content_items.json")
    rows = []
    for ci in content_items:
        if ci.get("status") != "active":
            continue
        if ci.get("instrument_id") != inst.get("id"):
            continue
        if ci.get("content_type") != "financial_statement":
            continue
        if ci.get("identifier_1") != "income_statement_as_reported":
            continue
        if period is not None and ci.get("period") != period:
            continue
        payload = ci.get("payload")
        if isinstance(payload, list):
            rows.extend(payload)
        else:
            rows.append(payload)

    # deterministic ordering: newest first when possible (as_of_date desc, then year/quarter desc)
    def _key(ci_payload):
        if isinstance(ci_payload, dict):
            aod = ci_payload.get("date") or ci_payload.get("asOfDate") or ci_payload.get("as_of_date")
            yr = ci_payload.get("year")
            qr = ci_payload.get("quarter")
            return (aod or "", int(yr) if isinstance(yr, int) else -1, int(qr) if isinstance(qr, int) else -1)
        return ("", -1, -1)

    rows_sorted = sorted(rows, key=_key, reverse=True)[:limit_i]
    return _log_and_return(200, rows_sorted, result_count=len(rows_sorted), error_code=None)

def getBalanceSheetStatementAsReported(symbol, limit=None, period=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getBalanceSheetStatementAsReported"
    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id():
        return f"fmp_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(os.urandom(16)).hexdigest()[:18]}"

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_id(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rolling_counts(api_key_id, now_dt):
        logs = _load("request_logs.json")
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                d += 1
                if dt >= minute_ago:
                    m += 1
        return m, d

    def _resolve_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota(keyrow):
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        minute_q = keyrow.get("minute_request_quota")
        daily_q = keyrow.get("daily_request_quota")
        if not isinstance(minute_q, int) or minute_q < 0:
            minute_q = 0
        if not isinstance(daily_q, int) or daily_q < 0:
            daily_q = 0
        m, d = _rolling_counts(keyrow["id"], now_dt)
        if m + 1 > minute_q:
            return False, "quota_minute_exceeded"
        if d + 1 > daily_q:
            return False, "quota_daily_exceeded"
        return True, None

    # Validate
    if not isinstance(symbol, str) or not symbol.strip():
        key = _resolve_active_key()
        _log(key["id"] if key else "unauthenticated", {"symbol": symbol, "limit": limit, "period": period}, 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    sym = symbol.strip().upper()

    if period is not None:
        if not isinstance(period, str) or period not in ("annual", "quarter"):
            key = _resolve_active_key()
            _log(key["id"] if key else "unauthenticated", {"symbol": sym, "limit": limit, "period": period}, 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "period must be one of: annual, quarter")

    if limit is None:
        limit_i = 100
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)) or (isinstance(limit, float) and not limit.is_integer()):
            key = _resolve_active_key()
            _log(key["id"] if key else "unauthenticated", {"symbol": sym, "limit": limit, "period": period}, 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        limit_i = int(limit)
    if limit_i < 1 or limit_i > 1000:
        key = _resolve_active_key()
        _log(key["id"] if key else "unauthenticated", {"symbol": sym, "limit": limit_i, "period": period}, 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")

    params_obj = {"symbol": sym, "limit": limit_i}
    if period is not None:
        params_obj["period"] = period

    key = _resolve_active_key()
    if not key:
        _log("unauthenticated", params_obj, 401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.")
    ok, qerr = _enforce_quota(key)
    if not ok:
        _log(key["id"], params_obj, 429, error_code=qerr)
        return _err("RATE_LIMIT", "Request quota exceeded.", reason=qerr)

    instruments = _load("instruments.json")
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("normalized_symbol") == sym:
            inst = r
            break
    if inst is None:
        _log(key["id"], params_obj, 404, error_code="symbol_not_found")
        return _err("NOT_FOUND", "Symbol not found.")

    content = _load("content_items.json")
    rows = []
    for r in content:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        if r.get("content_type") != "financial_statement":
            continue
        if r.get("instrument_id") != inst.get("id"):
            continue
        if r.get("identifier_1") not in (None, "balance_sheet_as_reported", "balance_sheet"):
            continue
        # As-reported tools commonly use period values annual/quarter in this schema.
        if period is not None and r.get("period") != period:
            continue
        payload = r.get("payload")
        if isinstance(payload, dict):
            rows.append(payload)
        else:
            rows.append({"payload": payload})

    def _sort_key(x):
        if isinstance(x, dict):
            d = x.get("date") or x.get("acceptedDate") or x.get("fillingDate") or x.get("asOfDate")
            if isinstance(d, str):
                return d
        return ""
    rows.sort(key=_sort_key, reverse=True)
    rows = rows[:limit_i]

    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    _log(key["id"], params_obj, 200, result_count=len(rows), cache_status="miss")
    return {"data": rows, "meta": {"symbol": sym, "count": len(rows)}}

