        if period not in ("annual", "quarter"):
            body = _err("VALIDATION_ERROR", "period must be one of: annual, quarter.", field="period")
            return _finish(api_key, params_obj, 400, body, error_code="VALIDATION_ERROR")

    # entitlement filters (asset/exchange) via api_key allowlists
    instruments = _load("instruments.json")
