        except Exception:
            qv = 0
        return f"{yv:04d}-{qv:02d}-00"

    rows.sort(key=_sort_key, reverse=True)
    rows = rows[:limit_i]

    return _finish(api_key, params_obj, 200, {"symbol": sym_norm, "data": rows}, result_count=len(rows))

