def getKeyMetricsTTM(symbol, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_working_api_key():
        keys = _load("api_keys.json")
        for r in keys:
            if r.get("status") == "active":
                return r
        return None

    def _rolling_count(logs, api_key_id, window_seconds):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_seconds)
        c = 0
        for row in logs:
            if row.get("api_key_id") != api_key_id:
                continue
            ts = row.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                c += 1
        return c

    def _log_request(api_key_id, tool_name, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id if api_key_id is not None else "unauthenticated",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _finish(api_key_row, params_obj, http_status, body, result_count=None, error_code=None):
        duration_ms = int((time.time() - t0) * 1000)
        api_key_id = api_key_row.get("id") if isinstance(api_key_row, dict) else None
        _log_request(api_key_id, "getKeyMetricsTTM", params_obj, http_status, "miss", duration_ms, result_count, error_code)
        if isinstance(api_key_row, dict) and 200 <= http_status <= 299:
            keys = _load("api_keys.json")
            for k in keys:
                if k.get("id") == api_key_row.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    _save("api_keys.json", keys)
                    break
        return body

    params_obj = {"symbol": symbol}

    api_key = _find_working_api_key()
    if not api_key:
        body = _err("UNAUTHORIZED", "Missing or invalid API key.")
        return _finish(None, params_obj, 401, body, error_code="UNAUTHORIZED")

    # quotas
    try:
        minute_quota = int(api_key.get("minute_request_quota", 0))
        daily_quota = int(api_key.get("daily_request_quota", 0))
        if minute_quota < 0 or daily_quota < 0:
            body = _err("UNAUTHORIZED", "API key misconfigured.")
            return _finish(api_key, params_obj, 403, body, error_code="UNAUTHORIZED")
    except Exception:
        body = _err("UNAUTHORIZED", "API key misconfigured.")
        return _finish(api_key, params_obj, 403, body, error_code="UNAUTHORIZED")

    logs = _load("request_logs.json")
    if minute_quota == 0 or daily_quota == 0:
        body = _err("QUOTA_EXCEEDED", "Request quota exceeded.")
        return _finish(api_key, params_obj, 429, body, error_code="QUOTA_EXCEEDED")
    if _rolling_count(logs, api_key["id"], 60) + 1 > minute_quota:
        body = _err("RATE_LIMIT", "Per-minute request limit exceeded.")
        return _finish(api_key, params_obj, 429, body, error_code="RATE_LIMIT")
    if _rolling_count(logs, api_key["id"], 86400) + 1 > daily_quota:
        body = _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return _finish(api_key, params_obj, 429, body, error_code="QUOTA_EXCEEDED")

    # validate
    if symbol is None or not isinstance(symbol, str) or not symbol.strip():
        body = _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.", field="symbol")
        return _finish(api_key, params_obj, 400, body, error_code="VALIDATION_ERROR")
    sym_norm = symbol.strip().upper()

    # instrument and entitlement
    instruments = _load("instruments.json")
    candidates = [r for r in instruments if r.get("normalized_symbol") == sym_norm]
    inst = None
    if candidates:
        primary = [r for r in candidates if r.get("exchange") is None]
        inst = primary[0] if primary else candidates[0]
    if not inst:
        body = _err("NOT_FOUND", "Unknown symbol.")
        return _finish(api_key, params_obj, 404, body, error_code="NOT_FOUND")

    allowed_ex = api_key.get("allowed_exchanges", None)
    if allowed_ex is not None and inst.get("exchange") not in allowed_ex:
        body = _err("UNAUTHORIZED", "API key not permitted for this exchange.")
        return _finish(api_key, params_obj, 403, body, error_code="UNAUTHORIZED")
    allowed_at = api_key.get("allowed_asset_types", None)
    if allowed_at is not None and inst.get("asset_type") not in allowed_at:
        body = _err("UNAUTHORIZED", "API key not permitted for this asset type.")
        return _finish(api_key, params_obj, 403, body, error_code="UNAUTHORIZED")

    # latest TTM key metrics: stored as content_items content_type=key_metrics, period='FY' or identifier_1='TTM' depending on dataset.
    items = _load("content_items.json")
    candidates = []
    for it in items:
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "key_metrics":
            continue
        if it.get("instrument_id") != inst.get("id"):
            continue
        # Heuristics for TTM: identifier_1 == 'TTM' OR period == 'FY' with payload marking ttm OR payload has 'ttm' flag.
        ident1 = it.get("identifier_1")
        payload = it.get("payload")
        is_ttm = False
        if isinstance(ident1, str) and ident1.upper() == "TTM":
            is_ttm = True
        if isinstance(payload, dict):
            if payload.get("ttm") is True or payload.get("isTTM") is True:
                is_ttm = True
            # Some datasets may use 'period'='TTM' inside payload even if column period differs
            pper = payload.get("period")
            if isinstance(pper, str) and pper.upper() == "TTM":
                is_ttm = True
        if not is_ttm:
            continue
        candidates.append(it)

    if not candidates:
        body = _err("NOT_FOUND", "No TTM key metrics available for this symbol.")
        return _finish(api_key, params_obj, 404, body, error_code="NOT_FOUND")

    def _item_sort_key(it):
        payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
        d = payload.get("date") or it.get("as_of_date") or payload.get("asOfDate")
        if isinstance(d, str):
            return d
        y = it.get("year") or payload.get("calendarYear") or payload.get("year")
        q = it.get("quarter") or payload.get("quarter")
        try:
            yv = int(y) if y is not None else -1
        except Exception:
            yv = -1
        try:
            qv = int(q) if q is not None else 0
        except Exception:
            qv = 0
        return f"{yv:04d}-{qv:02d}-00"

    candidates.sort(key=_item_sort_key, reverse=True)
    chosen = candidates[0].get("payload") if isinstance(candidates[0].get("payload"), dict) else {}
    if not isinstance(chosen, dict) or not chosen:
        body = _err("NOT_FOUND", "No TTM key metrics available for this symbol.")
        return _finish(api_key, params_obj, 404, body, error_code="NOT_FOUND")

    return _finish(api_key, params_obj, 200, {"symbol": sym_norm, "data": chosen}, result_count=1)

