    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_cik(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s == "":
            return ""
        digits = "".join(ch for ch in s if ch.isdigit())
        if digits == "":
            return ""
        return digits.zfill(10)

    def _parse_int(v, name):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
        if isinstance(v, int):
            return v, None
        if isinstance(v, float):
            if int(v) != v:
                return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
            return int(v), None
        if isinstance(v, str):
            s = v.strip()
            if s == "":
                return None, _err("VALIDATION_ERROR", f"{name} is required")
            try:
                if "." in s:
                    f = float(s)
                    if int(f) != f:
                        return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
                    return int(f), None
                return int(s), None
            except ValueError:
                return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
        return None, _err("VALIDATION_ERROR", f"{name} must be an integer")

    def _pick_active_key(api_keys):
