    key = _pick_active_key(api_keys)
    logs = _load("request_logs.json")
    if not key:
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id="unknown", tool_name="getForm13FFilingDates", params_obj=params, http_status=401, duration_ms=dur, error_code="UNAUTHORIZED")
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key is missing/invalid or not active")

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    minute_ct, day_ct = _rolling_counts(logs, key["id"], now_dt)
    if minute_ct + 1 > int(key.get("minute_request_quota", 0)) or day_ct + 1 > int(key.get("daily_request_quota", 0)):
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getForm13FFilingDates", params_obj={"cik": cik_norm if cik_norm is not None else cik}, http_status=429, duration_ms=dur, error_code="QUOTA_EXCEEDED")
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    if cik_norm is None or cik_norm == "":
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getForm13FFilingDates", params_obj={"cik": cik}, http_status=400, duration_ms=dur, error_code="VALIDATION_ERROR")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "cik is required")

    entities = _load("entities.json")
    ent = None
    for e in entities:
        if isinstance(e, dict) and (e.get("cik") or "").strip() == cik_norm:
            ent = e
            break
    if not ent:
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getForm13FFilingDates", params_obj={"cik": cik_norm}, http_status=404, duration_ms=dur, result_count=0, error_code="NOT_FOUND")
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "CIK is unknown or has no recorded 13F filing dates")

    items = _load("content_items.json")
    dates = set()
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "institutional_filing_extract":
            continue
        if it.get("entity_id") != ent.get("id"):
            continue
        as_of = it.get("as_of_date")
        if isinstance(as_of, str) and len(as_of) == 10:
            dates.add(as_of)
        else:
            # derive from payload if present
            payload = it.get("payload")
            if isinstance(payload, dict):
                for kdate in ("date", "filingDate", "acceptedDate", "reportDate"):
                    v = payload.get(kdate)
                    if isinstance(v, str) and len(v) >= 10:
                        dates.add(v[:10])
                        break

    if not dates:
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getForm13FFilingDates", params_obj={"cik": cik_norm}, http_status=404, duration_ms=dur, result_count=0, error_code="NOT_FOUND")
