        return _err("NOT_FOUND", "CIK is unknown or has no recorded 13F filing dates")

    out = sorted(dates, reverse=True)
    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    dur = int((time.time() - _t0) * 1000)
    _log_request(logs, api_key_id=key["id"], tool_name="getForm13FFilingDates", params_obj={"cik": cik_norm}, http_status=200, duration_ms=dur, result_count=len(out))
    _save("request_logs.json", logs)

    return {"data": [{"date": d} for d in out], "meta": {"cik": cik_norm, "total": len(out)}}

