def getHolderPerformanceSummary(cik, page=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_cik(v):
        if v is None or not isinstance(v, str):
            return None
        s = v.strip()
        if s == "":
            return ""
        digits = "".join(ch for ch in s if ch.isdigit())
        if digits == "":
            return ""
        return digits.zfill(10)

    def _parse_int(v, name):
        if v is None:
            return None, None
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
        if isinstance(v, int):
            return v, None
        if isinstance(v, float):
            if int(v) != v:
                return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
            return int(v), None
        if isinstance(v, str):
            s = v.strip()
            if s == "":
                return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
            try:
                if "." in s:
                    f = float(s)
                    if int(f) != f:
                        return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
                    return int(f), None
                return int(s), None
            except ValueError:
                return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
        return None, _err("VALIDATION_ERROR", f"{name} must be an integer")

    def _pick_active_key(api_keys):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _rolling_counts(logs, api_key_id, now_dt):
        day_ago = now_dt - datetime.timedelta(days=1)
        min_ago = now_dt - datetime.timedelta(minutes=1)
        day = 0
        minute = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str) or not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1] if ts.endswith("Z") else ts)
            except ValueError:
                continue
            if dt >= day_ago:
                day += 1
            if dt >= min_ago:
                minute += 1
        return minute, day

    def _log_request(logs, api_key_id, tool_name, params_obj, http_status, duration_ms, result_count=None, error_code=None, cache_status="bypass"):
        rid = "rl_" + uuid.uuid4().hex
        now = _now_iso()
        logs.append({
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(max(0, result_count)),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        })

    if page is None:
        page = 0

    params = {"cik": cik, "page": page}
    cik_norm = _norm_cik(cik)

    api_keys = _load("api_keys.json")
    key = _pick_active_key(api_keys)
    logs = _load("request_logs.json")
    if not key:
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id="unknown", tool_name="getHolderPerformanceSummary", params_obj=params, http_status=401, duration_ms=dur, error_code="UNAUTHORIZED")
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key is missing/invalid or not active")

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    minute_ct, day_ct = _rolling_counts(logs, key["id"], now_dt)
    if minute_ct + 1 > int(key.get("minute_request_quota", 0)) or day_ct + 1 > int(key.get("daily_request_quota", 0)):
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getHolderPerformanceSummary", params_obj={"cik": cik_norm if cik_norm is not None else cik, "page": page}, http_status=429, duration_ms=dur, error_code="QUOTA_EXCEEDED")
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    if cik_norm is None or cik_norm == "":
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getHolderPerformanceSummary", params_obj=params, http_status=400, duration_ms=dur, error_code="VALIDATION_ERROR")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "cik is required")

    p, e = _parse_int(page, "page")
    if e:
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getHolderPerformanceSummary", params_obj=params, http_status=400, duration_ms=dur, error_code="VALIDATION_ERROR")
        _save("request_logs.json", logs)
        return e
    if p is None:
        p = 0
    if p < 0:
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getHolderPerformanceSummary", params_obj={"cik": cik_norm, "page": p}, http_status=400, duration_ms=dur, error_code="VALIDATION_ERROR")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "page must be >= 0")

    entities = _load("entities.json")
    ent = None
    for e2 in entities:
        if isinstance(e2, dict) and (e2.get("cik") or "").strip() == cik_norm:
            ent = e2
            break
    if not ent:
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getHolderPerformanceSummary", params_obj={"cik": cik_norm, "page": p}, http_status=404, duration_ms=dur, result_count=0, error_code="NOT_FOUND")
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "CIK is unknown or no performance summary is available")

    # Page size (server-defined)
    PAGE_SIZE = 50

    items = _load("content_items.json")
    series = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "institutional_filing_extract":
            continue
        if it.get("entity_id") != ent.get("id"):
            continue
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue

        # attempt to read precomputed summary series from payload if present
        perf = payload.get("performanceSummary") or payload.get("performance") or payload.get("summary")
        if isinstance(perf, list):
            for pt in perf:
                if isinstance(pt, dict):
                    series.append(pt)
            continue

        # else synthesize one data point per extract from holdings aggregate
        holdings = None
        for k in ("holdings", "positions", "securities", "items", "data"):
            v = payload.get(k)
            if isinstance(v, list):
                holdings = v
                break
        if not isinstance(holdings, list):
            continue

        total_value = 0.0
        npos = 0
        for h in holdings:
            if not isinstance(h, dict):
                continue
            v = None
            for vk in ("value", "marketValue", "market_value", "holdingValue", "positionValue"):
                vv = h.get(vk)
                if isinstance(vv, (int, float)) and not isinstance(vv, bool):
                    v = float(vv); break
                if isinstance(vv, str):
                    try:
                        v = float(vv.replace(",", "").strip()); break
                    except ValueError:
                        pass
            if v is None:
                continue
            total_value += v
            npos += 1

        point = {
            "year": it.get("year"),
            "quarter": it.get("quarter"),
            "date": it.get("as_of_date") or payload.get("filingDate") or payload.get("date"),
            "totalValue": total_value,
            "positionCount": npos,
        }
        series.append(point)

    if not series:
        dur = int((time.time() - _t0) * 1000)
        _log_request(logs, api_key_id=key["id"], tool_name="getHolderPerformanceSummary", params_obj={"cik": cik_norm, "page": p}, http_status=404, duration_ms=dur, result_count=0, error_code="NOT_FOUND")
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "CIK is unknown or no performance summary is available")

    # sort newest first: year desc, quarter desc, date desc
    def _date_key(s):
        if isinstance(s, str) and len(s) >= 10:
            return s[:10]
        return ""
    series.sort(key=lambda r: (
        r.get("year") if isinstance(r.get("year"), int) else -1,
        r.get("quarter") if isinstance(r.get("quarter"), int) else -1,
        _date_key(r.get("date"))
    ), reverse=True)

    total = len(series)
    start = p * PAGE_SIZE
    end = start + PAGE_SIZE
    page_rows = series[start:end] if start < total else []

    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    dur = int((time.time() - _t0) * 1000)
    _log_request(logs, api_key_id=key["id"], tool_name="getHolderPerformanceSummary", params_obj={"cik": cik_norm, "page": p}, http_status=200, duration_ms=dur, result_count=len(page_rows))
    _save("request_logs.json", logs)

    return {"data": page_rows, "meta": {"cik": cik_norm, "page": p, "page_size": PAGE_SIZE, "total": total, "has_more": end < total}}

def getHolderIndustryBreakdown(cik, year, quarter, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "getHolderIndustryBreakdown"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _json_params():
        # additionalProperties=false; keep exact keys
        return {"cik": cik, "year": year, "quarter": quarter}

    def _parse_int(val, name):
        if isinstance(val, bool):
            return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
        if isinstance(val, int):
            return val, None
        if isinstance(val, float):
            if int(val) != val:
                return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
            return int(val), None
        if isinstance(val, str):
            s = val.strip()
            if s == "":
                return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
            if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
                try:
                    return int(s), None
                except Exception:
                    return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
        return None, _err("VALIDATION_ERROR", f"{name} must be an integer")

    def _normalize_cik(x):
        if not isinstance(x, str):
            return None
        s = x.strip()
        if s == "":
            return None
        # Accept digits; normalize to no leading/trailing spaces; keep as digits string.
        if not all(ch.isdigit() for ch in s):
            return None
        return s

    def _pick_active_key(api_keys):
        # Ambient auth: choose an active key that can serve requests (quota may still block)
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _rolling_counts(logs, api_key_id, now):
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        m = 0
        d = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if t >= day_ago:
                d += 1
                if t >= minute_ago:
                    m += 1
        return m, d

