        # log attempt with 401/403; choose any key id if exists else unknown
        api_key_id = api_keys[0]["id"] if api_keys else "unknown"
        _log_request(api_key_id, 401, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is missing, suspended, or revoked")

    # Quota enforcement using rolling windows; reject if would exceed
    logs = _load("request_logs.json")
    now = datetime.datetime.utcnow()
    m_cnt, d_cnt = _rolling_counts(logs, key_row["id"], now)
    if m_cnt + 1 > int(key_row.get("minute_request_quota", 0)):
        _log_request(key_row["id"], 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Minute request quota exceeded")
    if d_cnt + 1 > int(key_row.get("daily_request_quota", 0)):
        _log_request(key_row["id"], 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Resolve holder entity by CIK
    entities = _load("entities.json")
    holder = None
    for ent in entities:
        if isinstance(ent, dict) and ent.get("cik") == cik_n:
            holder = ent
            break
    # If no holder, return empty breakdown (read tool: empty result set allowed)
    content = _load("content_items.json")
    # Use institutional_filing_extract snapshot for holdings
    # Match by entity_id and year/quarter
    items = []
    if holder:
        for it in content:
            if not isinstance(it, dict):
                continue
            if it.get("status") != "active":
                continue
            if it.get("content_type") != "institutional_filing_extract":
                continue
            if it.get("entity_id") != holder.get("id"):
                continue
            if it.get("year") != y or it.get("quarter") != q:
                continue
            items.append(it)

    instruments = _load("instruments.json")
    inst_by_id = {i.get("id"): i for i in instruments if isinstance(i, dict) and isinstance(i.get("id"), str)}

    sector_totals = {}
    industry_totals = {}

    def _add(bucket, key, mv, cnt):
        if key is None or (isinstance(key, str) and key.strip() == ""):
            key = "Unknown"
        if key not in bucket:
            bucket[key] = {"marketValue": 0.0, "holdingCount": 0}
        bucket[key]["marketValue"] += float(mv or 0.0)
        bucket[key]["holdingCount"] += int(cnt or 0)

    # Parse holdings from payload; expected shapes vary; handle common keys
    for it in items:
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue
        holdings = None
        for k in ("holdings", "positions", "data", "items"):
            if isinstance(payload.get(k), list):
                holdings = payload.get(k)
                break
        if holdings is None:
            continue
        for h in holdings:
            if not isinstance(h, dict):
                continue
            inst_id = h.get("instrument_id") or h.get("instrumentId")
            sym = h.get("symbol") or h.get("ticker")
            mv = h.get("marketValue") or h.get("market_value") or h.get("value")
            cnt = 1
            sector = h.get("sector")
            industry = h.get("industry")

            inst = None
            if isinstance(inst_id, str):
                inst = inst_by_id.get(inst_id)
            if inst is None and isinstance(sym, str):
                ns = sym.strip().upper()
                # could be multiple exchanges; pick any matching symbol
                for inst2 in instruments:
                    if isinstance(inst2, dict) and inst2.get("normalized_symbol") == ns:
                        inst = inst2
                        break
            if inst:
                if sector is None:
                    sector = inst.get("sector")
                if industry is None:
                    industry = inst.get("industry")
            _add(sector_totals, sector, mv, cnt)
            _add(industry_totals, industry, mv, cnt)

    sector_breakdown = []
    for k, v in sorted(sector_totals.items(), key=lambda kv: (-kv[1]["marketValue"], kv[0])):
        sector_breakdown.append({"sector": k, "marketValue": v["marketValue"], "holdingCount": v["holdingCount"]})

    industry_breakdown = []
    for k, v in sorted(industry_totals.items(), key=lambda kv: (-kv[1]["marketValue"], kv[0])):
        industry_breakdown.append({"industry": k, "marketValue": v["marketValue"], "holdingCount": v["holdingCount"]})

    body = {
        "cik": cik_n,
        "year": y,
        "quarter": q,
        "entity": (None if not holder else {"id": holder.get("id"), "name": holder.get("name"), "entity_type": holder.get("entity_type")}),
        "sectorBreakdown": sector_breakdown,
        "industryBreakdown": industry_breakdown,
        "meta": {"sources": len(items)},
    }

    # Update last_used_at on success
    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row["id"], 200, "miss", (time.time() - _t0) * 1000, result_count=(len(sector_breakdown) + len(industry_breakdown)), error_code=None)
    return {"data": body}

