        k = _pick_active_key(api_keys)
        api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
        _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "year must be between 1900 and 2200")
    if q < 1 or q > 4:
        api_keys = _load("api_keys.json")
        k = _pick_active_key(api_keys)
        api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
        _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "quarter must be between 1 and 4")

    # Auth
    api_keys = _load("api_keys.json")
    key_row = _pick_active_key(api_keys)
    if not key_row:
        api_key_id = api_keys[0]["id"] if api_keys else "unknown"
        _log_request(api_key_id, 401, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is missing, suspended, or revoked")

    # Quota
    logs = _load("request_logs.json")
    now = datetime.datetime.utcnow()
    m_cnt, d_cnt = _rolling_counts(logs, key_row["id"], now)
    if m_cnt + 1 > int(key_row.get("minute_request_quota", 0)):
        _log_request(key_row["id"], 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Minute request quota exceeded")
    if d_cnt + 1 > int(key_row.get("daily_request_quota", 0)):
        _log_request(key_row["id"], 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Resolve instrument (equity expected, but accept any matching symbol)
    instruments = _load("instruments.json")
    inst = None
    for i in instruments:
        if isinstance(i, dict) and i.get("normalized_symbol") == norm_sym:
            inst = i
            break

    # Aggregate across institutional_filing_extract items for the period.
    content = _load("content_items.json")
    holders = set()
    total_shares = 0.0
    total_value = 0.0

    # Some payloads may be per-holder filing extract containing positions list.
    for it in content:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "institutional_filing_extract":
            continue
        if it.get("year") != y or it.get("quarter") != q:
            continue
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue
        positions = None
        for k in ("holdings", "positions", "data", "items"):
            if isinstance(payload.get(k), list):
                positions = payload.get(k)
                break
        if positions is None:
            continue

        holder_id = it.get("entity_id")  # reporting holder entity
        if isinstance(holder_id, str) and holder_id:
            holders.add(holder_id)

        for p in positions:
            if not isinstance(p, dict):
                continue
            sym = p.get("symbol") or p.get("ticker")
            if not isinstance(sym, str) or sym.strip().upper() != norm_sym:
                continue
            sh = p.get("shares") or p.get("share") or p.get("sharesNumber")
            mv = p.get("marketValue") or p.get("market_value") or p.get("value")
            try:
                if sh is not None:
                    total_shares += float(sh)
            except Exception:
                pass
            try:
                if mv is not None:
                    total_value += float(mv)
            except Exception:
                pass

    summary = {
        "symbol": norm_sym,
        "year": y,
        "quarter": q,
        "instrument": (None if not inst else {"id": inst.get("id"), "name": inst.get("name"), "exchange": inst.get("exchange"), "asset_type": inst.get("asset_type")}),
        "reportingHolders": len(holders),
        "totalShares": total_shares,
        "totalMarketValue": total_value,
        # period-over-period change not computable without prior-period data; include nulls
        "change": {
            "reportingHolders": None,
            "totalShares": None,
            "totalMarketValue": None,
        },
    }

    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row["id"], 200, "miss", (time.time() - _t0) * 1000, result_count=1, error_code=None)
    return {"data": summary}

