        _log_request(key_row["id"], 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Prefer dedicated content items if present: content_type='industry_performance' by year/quarter
    content = _load("content_items.json")
    perf_items = [
        it for it in content
        if isinstance(it, dict)
        and it.get("status") == "active"
        and it.get("content_type") == "industry_performance"
        and it.get("year") == y
        and it.get("quarter") == q
    ]

    results = []
    if perf_items:
        # Combine payload rows; payload may hold list under 'data'/'items'/'industries'
        for it in perf_items:
            payload = it.get("payload")
            if not isinstance(payload, dict):
                continue
            rows = None
            for k in ("industries", "data", "items", "rows"):
                if isinstance(payload.get(k), list):
                    rows = payload.get(k)
                    break
            if rows is None and isinstance(payload.get("industry"), (str, type(None))):
                # single row payload
                rows = [payload]
            if rows is None:
                continue
            for r in rows:
                if isinstance(r, dict):
                    results.append(r)
    else:
        # Fallback: aggregate from institutional filings positions by instrument industry.
        instruments = _load("instruments.json")
        inst_by_symbol = {i.get("normalized_symbol"): i for i in instruments if isinstance(i, dict) and isinstance(i.get("normalized_symbol"), str)}
        buckets = {}
        for it in content:
            if not isinstance(it, dict):
                continue
            if it.get("status") != "active" or it.get("content_type") != "institutional_filing_extract":
                continue
            if it.get("year") != y or it.get("quarter") != q:
                continue
            payload = it.get("payload")
            if not isinstance(payload, dict):
                continue
            positions = None
            for k in ("holdings", "positions", "data", "items"):
                if isinstance(payload.get(k), list):
                    positions = payload.get(k)
                    break
            if positions is None:
                continue
            for p in positions:
                if not isinstance(p, dict):
                    continue
                sym = p.get("symbol") or p.get("ticker")
                if not isinstance(sym, str):
                    continue
                inst = inst_by_symbol.get(sym.strip().upper())
                industry = (p.get("industry") if isinstance(p.get("industry"), str) else None) or (inst.get("industry") if inst else None) or "Unknown"
                mv = p.get("marketValue") or p.get("market_value") or p.get("value")
                try:
                    mv = float(mv or 0.0)
                except Exception:
                    mv = 0.0
                if industry not in buckets:
                    buckets[industry] = {"industry": industry, "totalMarketValue": 0.0, "positionCount": 0}
                buckets[industry]["totalMarketValue"] += mv
                buckets[industry]["positionCount"] += 1
        results = sorted(buckets.values(), key=lambda r: (-float(r.get("totalMarketValue", 0.0)), str(r.get("industry", ""))))

    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row["id"], 200, "miss", (time.time() - _t0) * 1000, result_count=len(results), error_code=None)
    return {"data": {"year": y, "quarter": q, "industries": results}}

def getIndexList(search=None, exchange=None, country=None, limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "getIndexList"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _json_params():
        return {"search": search, "exchange": exchange, "country": country, "limit": limit}

    def _pick_active_key(api_keys):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _rolling_counts(logs, api_key_id, now):
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        m = 0
        d = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if t >= day_ago:
                d += 1
                if t >= minute_ago:
                    m += 1
        return m, d

    def _log_request(api_key_id, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        log_id = "rl_" + uuid.uuid4().hex
        now_iso = _now_iso()
        row = {
            "id": log_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": _json_params(),
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate limit
    if limit is None:
        lim = 500
    else:
        if isinstance(limit, bool):
            api_keys = _load("api_keys.json")
            k = _pick_active_key(api_keys)
            api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
            _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a positive integer")
        if isinstance(limit, (int, float)):
            if int(limit) != limit:
                api_keys = _load("api_keys.json")
                k = _pick_active_key(api_keys)
                api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
                _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "limit must be a positive integer")
            lim = int(limit)
        elif isinstance(limit, str):
            s = limit.strip()
            if not s.isdigit():
                api_keys = _load("api_keys.json")
                k = _pick_active_key(api_keys)
                api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
                _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "limit must be a positive integer")
            lim = int(s)
        else:
            api_keys = _load("api_keys.json")
            k = _pick_active_key(api_keys)
            api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
            _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a positive integer")

    if lim <= 0:
        api_keys = _load("api_keys.json")
        k = _pick_active_key(api_keys)
        api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
        _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be positive")

    # Server-side max for this tool; enforce a hard cap (per typical FMP max 5000; tool default 500)
    max_limit = 5000
    if lim > max_limit:
        api_keys = _load("api_keys.json")
        k = _pick_active_key(api_keys)
        api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
        _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"limit must not exceed {max_limit}")

    # Validate optional filters
    if search is not None and not isinstance(search, str):
        api_keys = _load("api_keys.json")
        k = _pick_active_key(api_keys)
        api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
        _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search must be a string")
    if exchange is not None and not isinstance(exchange, str):
        api_keys = _load("api_keys.json")
        k = _pick_active_key(api_keys)
        api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
        _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "exchange must be a string")
    if country is not None and not isinstance(country, str):
        api_keys = _load("api_keys.json")
        k = _pick_active_key(api_keys)
        api_key_id = k["id"] if k else (api_keys[0]["id"] if api_keys else "unknown")
        _log_request(api_key_id, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "country must be a string")

    s_norm = (search or "").strip().lower()
    ex_norm = exchange.strip() if isinstance(exchange, str) and exchange.strip() != "" else None
    c_norm = country.strip().upper() if isinstance(country, str) and country.strip() != "" else None

    # Auth
    api_keys = _load("api_keys.json")
    key_row = _pick_active_key(api_keys)
    if not key_row:
        api_key_id = api_keys[0]["id"] if api_keys else "unknown"
        _log_request(api_key_id, 401, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is missing, suspended, or revoked")

    # Quota
    logs = _load("request_logs.json")
    now = datetime.datetime.utcnow()
    m_cnt, d_cnt = _rolling_counts(logs, key_row["id"], now)
    if m_cnt + 1 > int(key_row.get("minute_request_quota", 0)):
        _log_request(key_row["id"], 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Minute request quota exceeded")
    if d_cnt + 1 > int(key_row.get("daily_request_quota", 0)):
        _log_request(key_row["id"], 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Allowed exchange/asset type entitlements (optional allowlists)
    allowed_exchanges = key_row.get("allowed_exchanges")
    allowed_assets = key_row.get("allowed_asset_types")

    instruments = _load("instruments.json")
    out = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("asset_type") != "index":
            continue
        if inst.get("status") not in ("active", "inactive", "delisted"):
            continue

        inst_ex = inst.get("exchange")
        inst_country = inst.get("country")

        if allowed_assets is not None:
            if not isinstance(allowed_assets, list) or "index" not in allowed_assets:
                continue
        if allowed_exchanges is not None:
            if not isinstance(allowed_exchanges, list):
                continue
            # null exchange treated as allowed only if allowlist contains None or special token; default: exclude
            if inst_ex is None or inst_ex not in allowed_exchanges:
                continue

        if ex_norm is not None and inst_ex != ex_norm:
            continue
        if c_norm is not None:
            if not isinstance(inst_country, str) or inst_country.strip().upper() != c_norm:
                continue
        if s_norm:
            sym = (inst.get("symbol") or "").strip().lower()
            nm = (inst.get("name") or "").strip().lower()
            if s_norm not in sym and s_norm not in nm:
                continue

        out.append({
            "symbol": inst.get("symbol"),
            "name": inst.get("name"),
            "exchange": inst.get("exchange"),
            "currency": inst.get("currency"),
            "country": inst.get("country"),
            "id": inst.get("id"),
        })
        if len(out) >= lim:
            break

    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row["id"], 200, "miss", (time.time() - _t0) * 1000, result_count=len(out), error_code=None)
    return {"data": out, "meta": {"limit": lim, "returned": len(out)}}

def getIndexQuote(symbol, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    params = {"symbol": symbol}

    def _log(api_key_id, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        log_row = {
            "id": "rlog_" + uuid.uuid4().hex,
            "api_key_id": api_key_id if api_key_id else "unknown",
            "tool_name": "getIndexQuote",
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms),
            "result_count": result_count if result_count is not None else None,
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)

    def _pick_active_key():
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _rolling_counts(api_key_id):
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1))
        day_ago = (datetime.datetime.utcnow() - datetime.timedelta(days=1))
        m = 0
        d = 0
        for r in req_logs:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                rt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rt >= minute_ago: m += 1
            if rt >= day_ago: d += 1
        return m, d

    def _check_quota(keyrow):
        api_key_id = keyrow.get("id")
        minute_quota = keyrow.get("minute_request_quota")
        daily_quota = keyrow.get("daily_request_quota")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            minute_quota = 0
        if not isinstance(daily_quota, int) or daily_quota < 0:
            daily_quota = 0
        m, d = _rolling_counts(api_key_id)
        if minute_quota == 0:
            return False, "RATE_LIMIT", {"window": "minute", "limit": minute_quota, "used": m}
        if daily_quota == 0:
            return False, "QUOTA_EXCEEDED", {"window": "day", "limit": daily_quota, "used": d}
        if m + 1 > minute_quota:
            return False, "RATE_LIMIT", {"window": "minute", "limit": minute_quota, "used": m}
        if d + 1 > daily_quota:
            return False, "QUOTA_EXCEEDED", {"window": "day", "limit": daily_quota, "used": d}
        return True, None, None

    # Validate
    if not isinstance(symbol, str) or not symbol.strip():
        duration = (time.time() - t0) * 1000
        keyrow = _pick_active_key()
        _log(keyrow["id"] if keyrow else None, 400, "bypass", duration, result_count=0, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    sym_norm = symbol.strip().upper()

    # Authenticate (ambient)
    keyrow = _pick_active_key()
    if not keyrow:
        duration = (time.time() - t0) * 1000
        _log(None, 401, "bypass", duration, result_count=0, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this request")

    # Plan permission for quote data (treat free as forbidden)
    if keyrow.get("plan") == "free":
        duration = (time.time() - t0) * 1000
        _log(keyrow["id"], 403, "bypass", duration, result_count=0, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key plan is not permitted for real-time/quote data", http_status=403)

    ok, qcode, qmeta = _check_quota(keyrow)
    if not ok:
        duration = (time.time() - t0) * 1000
        _log(keyrow["id"], 429, "bypass", duration, result_count=0, error_code=qcode)
        return _err(qcode, "Request quota exceeded", http_status=429, **(qmeta or {}))

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")

    inst = None
    for row in instruments:
        if not isinstance(row, dict):
            continue
        if row.get("normalized_symbol") == sym_norm and row.get("asset_type") == "index":
            inst = row
            break

    if not inst:
        duration = (time.time() - t0) * 1000
        _log(keyrow["id"], 404, "miss", duration, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Index symbol not found")

    inst_id = inst.get("id")
    snap = None
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != inst_id:
            continue
        if r.get("timeframe") != "1day":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        if r.get("is_latest_snapshot") is True:
            snap = r
            break
    if not snap:
        # fall back to latest by ts if no snapshot flag
        best = None
        best_ts = None
        for r in mdp:
            if not isinstance(r, dict):
                continue
            if r.get("instrument_id") != inst_id:
                continue
            if r.get("timeframe") != "1day" or r.get("adjustment_type") != "unadjusted" or r.get("session") != "regular":
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if best is None or dt > best_ts:
                best = r
                best_ts = dt
        snap = best

    if not snap:
        duration = (time.time() - t0) * 1000
        _log(keyrow["id"], 404, "miss", duration, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No quote data available for this index")

    # Update key last_used_at (successful authenticated request)
    keyrow_id = keyrow.get("id")
    if isinstance(keyrow_id, str):
        changed = False
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == keyrow_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)

    quote = {
        "symbol": inst.get("symbol"),
        "name": inst.get("name"),
        "price": snap.get("close"),
        "open": snap.get("open"),
        "dayHigh": snap.get("high"),
        "dayLow": snap.get("low"),
        "volume": snap.get("volume"),
        "previousClose": None,
        "change": snap.get("change"),
        "changesPercentage": snap.get("change_percent"),
        "timestamp": snap.get("ts"),
        "currency": inst.get("currency"),
        "exchange": inst.get("exchange"),
        "isActivelyTrading": inst.get("is_actively_trading"),
    }

    duration = (time.time() - t0) * 1000
    _log(keyrow["id"], 200, "miss", duration, result_count=1, error_code=None)
    return quote

