        api_key_id = keyrow.get("id")
        minute_quota = keyrow.get("minute_request_quota")
        daily_quota = keyrow.get("daily_request_quota")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            minute_quota = 0
        if not isinstance(daily_quota, int) or daily_quota < 0:
            daily_quota = 0
        m, d = _rolling_counts(api_key_id)
        if minute_quota == 0:
            return False, "RATE_LIMIT", {"window": "minute", "limit": minute_quota, "used": m}
        if daily_quota == 0:
            return False, "QUOTA_EXCEEDED", {"window": "day", "limit": daily_quota, "used": d}
        if m + 1 > minute_quota:
            return False, "RATE_LIMIT", {"window": "minute", "limit": minute_quota, "used": m}
        if d + 1 > daily_quota:
            return False, "QUOTA_EXCEEDED", {"window": "day", "limit": daily_quota, "used": d}
        return True, None, None

    if not isinstance(symbol, str) or not symbol.strip():
        duration = (time.time() - t0) * 1000
        keyrow = _pick_active_key()
        _log(keyrow["id"] if keyrow else None, 400, "bypass", duration, result_count=0, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    sym_norm = symbol.strip().upper()

    keyrow = _pick_active_key()
    if not keyrow:
        duration = (time.time() - t0) * 1000
        _log(None, 401, "bypass", duration, result_count=0, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this request")

    if keyrow.get("plan") == "free":
        duration = (time.time() - t0) * 1000
        _log(keyrow["id"], 403, "bypass", duration, result_count=0, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key plan is not permitted for real-time/quote data", http_status=403)

    ok, qcode, qmeta = _check_quota(keyrow)
    if not ok:
        duration = (time.time() - t0) * 1000
        _log(keyrow["id"], 429, "bypass", duration, result_count=0, error_code=qcode)
        return _err(qcode, "Request quota exceeded", http_status=429, **(qmeta or {}))

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")

    inst = None
    for row in instruments:
        if not isinstance(row, dict):
            continue
        if row.get("normalized_symbol") == sym_norm and row.get("asset_type") == "index":
            inst = row
            break

    if not inst:
        duration = (time.time() - t0) * 1000
        _log(keyrow["id"], 404, "miss", duration, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Index symbol not found")

    inst_id = inst.get("id")
    snap = None
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != inst_id:
            continue
        if r.get("timeframe") == "1day" and r.get("adjustment_type") == "unadjusted" and r.get("session") == "regular" and r.get("is_latest_snapshot") is True:
            snap = r
            break

    if not snap:
        best = None
        best_ts = None
        for r in mdp:
            if not isinstance(r, dict):
                continue
            if r.get("instrument_id") != inst_id:
                continue
            if r.get("timeframe") != "1day" or r.get("adjustment_type") != "unadjusted" or r.get("session") != "regular":
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if best is None or dt > best_ts:
                best = r
                best_ts = dt
        snap = best

    if not snap:
        duration = (time.time() - t0) * 1000
        _log(keyrow["id"], 404, "miss", duration, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No quote data available for this index")

    # update last_used_at on success
    keyrow_id = keyrow.get("id")
    if isinstance(keyrow_id, str):
        changed = False
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == keyrow_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)

    out = {
        "symbol": inst.get("symbol"),
        "price": snap.get("close"),
        "change": snap.get("change"),
        "changesPercentage": snap.get("change_percent"),
        "volume": snap.get("volume"),
        "timestamp": snap.get("ts"),
    }

    duration = (time.time() - t0) * 1000
    _log(keyrow["id"], 200, "miss", duration, result_count=1, error_code=None)
    return out

def getAllIndexQuotes(short=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getAllIndexQuotes"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_req_id():
        seed = hashlib.sha1(os.urandom(16)).hexdigest()[:22]
        return "fmp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + seed

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rolling_counts(api_key_id):
        logs = _load("request_logs.json")
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                d += 1
                if dt >= minute_ago:
                    m += 1
        return m, d

    def _find_active_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        best = None
        best_score = None
        for k in active:
            if not isinstance(k.get("id"), str):
                continue
            m, d = _rolling_counts(k["id"])
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or not isinstance(day_q, int):
                continue
            score = (min_q - m, day_q - d)
            if best is None or score > best_score:
                best, best_score = k, score
        return best

    def _enforce_quota(key_row):
        m, d = _rolling_counts(key_row["id"])
        if m >= int(key_row.get("minute_request_quota", 0)):
            return False, "RATE_LIMIT", "Request quota exceeded.", "quota_minute_exceeded", 429
        if d >= int(key_row.get("daily_request_quota", 0)):
            return False, "QUOTA_EXCEEDED", "Daily request quota exceeded.", "quota_daily_exceeded", 429
        return True, None, None, None, 200

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_req_id(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    # validate
    if short is None:
        short_b = False
    else:
        if not isinstance(short, bool):
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"short": short}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`short` must be a boolean.")
        short_b = short

    params_obj = {"short": short_b}

    # auth + quota
    key = _find_active_key()
    if key is None:
        _log("unknown", params_obj, 401, error_code="unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

    ok, ecode, emsg, reason, http_status = _enforce_quota(key)
    if not ok:
        _log(key["id"], params_obj, http_status, error_code=reason)
        return _err(ecode, emsg, reason=reason, http_status=http_status)

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")

    # all index instruments
    idx = [r for r in instruments if isinstance(r, dict) and r.get("asset_type") == "index" and r.get("status") in ("active", "inactive", "delisted")]
    idx_ids = {r.get("id"): r for r in idx if isinstance(r.get("id"), str)}

    # latest snapshot per index: timeframe 1day, unadjusted, regular, is_latest_snapshot=true
    latest = {}
    for r in mdp:
        if not isinstance(r, dict):
            continue
        iid = r.get("instrument_id")
        if iid not in idx_ids:
            continue
        if r.get("timeframe") != "1day" or r.get("adjustment_type") != "unadjusted" or r.get("session") != "regular":
            continue
        if r.get("is_latest_snapshot") is not True:
            continue
        latest[iid] = r

    # build quote shapes (best-effort; store has quote-like fields in mdp)
    out = []
    for iid, inst in idx_ids.items():
        snap = latest.get(iid)
        if not snap:
            continue
        base = {
            "symbol": inst.get("symbol"),
            "name": inst.get("name"),
            "exchange": inst.get("exchange"),
            "price": snap.get("close"),
            "previousClose": None,
            "change": snap.get("change"),
            "changesPercentage": snap.get("change_percent"),
            "timestamp": snap.get("ts"),
        }
        if short_b:
            out.append({
                "symbol": base["symbol"],
                "price": base["price"],
                "change": base["change"],
                "changesPercentage": base["changesPercentage"],
                "timestamp": base["timestamp"],
            })
        else:
            out.append(base)

    # stable sort by symbol
    out.sort(key=lambda r: (r.get("symbol") or ""))

    # update last_used_at
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    _log(key["id"], params_obj, 200, result_count=len(out))
    return {"data": out, "meta": {"returned": len(out), "short": short_b}}

def getHistoricalIndexLightChart(symbol, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_date(s, field_name):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.date.fromisoformat(s)
        except Exception:
            return None

    def _normalize_symbol(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip()
        if not s2:
            return None
        return s2.upper()

    def _find_active_api_key(api_keys):
        # Ambient auth: pick any active key capable of serving the request.
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _rolling_window_counts(logs, api_key_id, now_dt):
        day_ago = now_dt - datetime.timedelta(days=1)
        minute_ago = now_dt - datetime.timedelta(minutes=1)

        day_count = 0
        minute_count = 0

        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                # stored in ISO with Z
                if ts.endswith("Z"):
                    ts_dt = datetime.datetime.fromisoformat(ts[:-1])
                else:
                    ts_dt = datetime.datetime.fromisoformat(ts)
            except Exception:
                continue

            if ts_dt >= day_ago:
                day_count += 1
                if ts_dt >= minute_ago:
                    minute_count += 1

        return minute_count, day_count

    def _log_request(request_logs, api_key_id, tool_name, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        now = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms) if duration_ms is not None else 0,
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        request_logs.append(row)

    t0 = time.time()
    tool_name = "getHistoricalIndexLightChart"

    # Validate params (no additionalProperties already ensured by signature)
    params_obj = {"symbol": symbol}
    if from_ is not None:
        params_obj["from"] = from_
    if to is not None:
        params_obj["to"] = to

    # Load auth + logs first (needed to always log)
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    api_key = _find_active_api_key(api_keys)
    if not api_key:
        duration_ms = int((time.time() - t0) * 1000)
        # Log unauthorized attempt with a placeholder api_key_id if none exists
        api_key_id = api_keys[0].get("id") if api_keys and isinstance(api_keys[0], dict) and api_keys[0].get("id") else "unknown"
        _log_request(request_logs, api_key_id, tool_name, params_obj, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is missing, inactive, suspended, or revoked.")

    # Quota enforcement (rolling windows over request_logs)
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    minute_used, day_used = _rolling_window_counts(request_logs, api_key["id"], now_dt)
    minute_quota = api_key.get("minute_request_quota", 0)
    daily_quota = api_key.get("daily_request_quota", 0)
    if not isinstance(minute_quota, int) or minute_quota < 0:
        minute_quota = 0
    if not isinstance(daily_quota, int) or daily_quota < 0:
        daily_quota = 0

    if minute_quota >= 0 and minute_used + 1 > minute_quota:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(request_logs, api_key["id"], tool_name, params_obj, 429, "bypass", duration_ms, result_count=None, error_code="RATE_LIMIT")
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Minute request quota exceeded.", limit=minute_quota, used=minute_used)

    if daily_quota >= 0 and day_used + 1 > daily_quota:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(request_logs, api_key["id"], tool_name, params_obj, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=daily_quota, used=day_used)

    norm_symbol = _normalize_symbol(symbol)
    if norm_symbol is None:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(request_logs, api_key["id"], tool_name, params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")

    from_d = _parse_iso_date(from_, "from")
    if from_ is not None and from_d is None:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(request_logs, api_key["id"], tool_name, params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "from must be a valid ISO date (YYYY-MM-DD).", field="from")

    to_d = _parse_iso_date(to, "to")
    if to is not None and to_d is None:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(request_logs, api_key["id"], tool_name, params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "to must be a valid ISO date (YYYY-MM-DD).", field="to")

    if from_d is not None and to_d is not None and from_d > to_d:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(request_logs, api_key["id"], tool_name, params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "from must be on or before to.", field="from")

    # Resolve instrument (index)
    instruments = _load("instruments.json")
    instrument = None
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("normalized_symbol") == norm_symbol and inst.get("asset_type") == "index":
            instrument = inst
            break

    # If the symbol doesn't exist, FMP typically returns empty list-like response; not an error for reads.
    if instrument is None:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(request_logs, api_key["id"], tool_name, params_obj, 200, "miss", duration_ms, result_count=0, error_code=None)
        _save("request_logs.json", request_logs)
        # Update api_key last_used_at on successful authenticated request
        now_iso = _now_iso()
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)
        return {"symbol": symbol, "historical": []}

    # Enforce key allowlists
    allowed_exchanges = api_key.get("allowed_exchanges", None)
    allowed_asset_types = api_key.get("allowed_asset_types", None)
    if allowed_asset_types is not None:
        if not isinstance(allowed_asset_types, list) or any(not isinstance(x, str) for x in allowed_asset_types):
            # treat malformed allowlist as restrictive
            allowed_asset_types = []
        if instrument.get("asset_type") not in allowed_asset_types:
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(request_logs, api_key["id"], tool_name, params_obj, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "API key is not permitted for this asset type.", asset_type=instrument.get("asset_type"))
    if allowed_exchanges is not None:
        if not isinstance(allowed_exchanges, list) or any(not isinstance(x, str) for x in allowed_exchanges):
            allowed_exchanges = []
        exch = instrument.get("exchange")
        # Null exchange is treated as not matching allowlist unless allowlist contains a wildcard-like value; none specified in schema.
        if exch is None or exch not in allowed_exchanges:
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(request_logs, api_key["id"], tool_name, params_obj, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "API key is not permitted for this exchange.", exchange=exch)

    # Read daily unadjusted regular session bars
    mdps = _load("market_data_points.json")
    rows = []
    for r in mdps:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != instrument.get("id"):
            continue
        if r.get("timeframe") != "1day":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        trade_date = r.get("trade_date")
        if not isinstance(trade_date, str):
            continue
        try:
            td = datetime.date.fromisoformat(trade_date)
        except Exception:
            continue
        if from_d is not None and td < from_d:
            continue
        if to_d is not None and td > to_d:
            continue

        item = {"date": trade_date, "close": r.get("close")}
        if r.get("volume") is not None:
            item["volume"] = r.get("volume")
        rows.append(item)

    # Sort by date ascending
    rows.sort(key=lambda x: x.get("date") or "")

    duration_ms = int((time.time() - t0) * 1000)
    _log_request(request_logs, api_key["id"], tool_name, params_obj, 200, "miss", duration_ms, result_count=len(rows), error_code=None)
    _save("request_logs.json", request_logs)

    # Update api_key last_used_at
    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {"symbol": symbol, "historical": rows}

