        return None

    def _rolling_window_counts(logs, api_key_id, now_dt):
        day_ago = now_dt - datetime.timedelta(days=1)
        minute_ago = now_dt - datetime.timedelta(minutes=1)

        day_count = 0
        minute_count = 0

        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                if ts.endswith("Z"):
                    ts_dt = datetime.datetime.fromisoformat(ts[:-1])
                else:
                    ts_dt = datetime.datetime.fromisoformat(ts)
            except Exception:
                continue

            if ts_dt >= day_ago:
                day_count += 1
                if ts_dt >= minute_ago:
                    minute_count += 1

        return minute_count, day_count

