            continue
        if from_d is not None and td < from_d:
            continue
        if to_d is not None and td > to_d:
            continue

        item = {
            "date": trade_date,
            "open": r.get("open"),
            "high": r.get("high"),
            "low": r.get("low"),
            "close": r.get("close"),
            "volume": r.get("volume"),
