    now_dt = datetime.datetime.utcnow()
    since_minute = now_dt - datetime.timedelta(minutes=1)
    since_day = now_dt - datetime.timedelta(days=1)
    minute_used = _count_requests(logs, api_key["id"], since_minute)
    day_used = _count_requests(logs, api_key["id"], since_day)

