            if _from and td < _from:
                continue
            if _to and td > _to:
                continue
        else:
            # If missing trade_date, attempt derive from ts; else include only if no date filtering
            if _from or _to:
                continue
        rows.append(r)

    # Order by ts ascending (time-ordered list)
    def _ts_key(x):
        ts = x.get("ts")
        if not isinstance(ts, str):
            return ""
        return ts
    rows.sort(key=_ts_key)

    # Server-side max rows per response (policy); intraday can be large
    MAX_ROWS = 10000
    if len(rows) > MAX_ROWS:
        rows = rows[-MAX_ROWS:]

    # Shape output like FMP-style minute bar list
    out = []
    for r in rows:
        out.append({
            "date": r.get("ts"),
            "open": r.get("open"),
            "high": r.get("high"),
            "low": r.get("low"),
            "close": r.get("close"),
            "volume": r.get("volume"),
            "vwap": r.get("vwap"),
        })

    # Update api_key last_used_at on successful authenticated request
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            k["last_used_at"] = _now
