            break
    _save("api_keys.json", api_keys)

    _log_request(api_key["id"], "getIndex1MinuteData", {"symbol": symbol, "from": from_, "to": to},
                 200, "miss", (time.time() - _t0) * 1000, result_count=len(out), error_code=None)
    return {
        "symbol": inst.get("symbol"),
        "from": _from,
        "to": _to,
        "timeframe": "1min",
        "data": out,
        "count": len(out),
    }

