        k = _pick_api_key()
        api_key_id = k["id"] if k else "unknown"
        _log_request(api_key_id, "getIndex5MinuteData", {"symbol": symbol, "from": from_, "to": to},
                     400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "to must be a valid ISO date YYYY-MM-DD")
    if _from and _to and _from > _to:
        k = _pick_api_key()
        api_key_id = k["id"] if k else "unknown"
        _log_request(api_key_id, "getIndex5MinuteData", {"symbol": symbol, "from": from_, "to": to},
                     400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be on or before to")

    # Authenticate
    api_key = _pick_api_key()
    if not api_key or api_key.get("status") != "active":
        api_key_id = api_key["id"] if api_key else "unknown"
        _log_request(api_key_id, "getIndex5MinuteData", {"symbol": symbol, "from": from_, "to": to},
                     401, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is missing, inactive, suspended, or revoked")

    # Quota
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow()
    since_minute = now_dt - datetime.timedelta(minutes=1)
    since_day = now_dt - datetime.timedelta(days=1)
    minute_used = _count_requests(logs, api_key["id"], since_minute)
    day_used = _count_requests(logs, api_key["id"], since_day)

    minute_quota = api_key.get("minute_request_quota")
    daily_quota = api_key.get("daily_request_quota")
    if not isinstance(minute_quota, int) or minute_quota < 0:
        minute_quota = 0
    if not isinstance(daily_quota, int) or daily_quota < 0:
        daily_quota = 0

    if minute_quota == 0 or minute_used + 1 > minute_quota:
        _log_request(api_key["id"], "getIndex5MinuteData", {"symbol": symbol, "from": from_, "to": to},
                     429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Minute request quota exceeded", limit=minute_quota, used=minute_used)
    if daily_quota == 0 or day_used + 1 > daily_quota:
        _log_request(api_key["id"], "getIndex5MinuteData", {"symbol": symbol, "from": from_, "to": to},
                     429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", limit=daily_quota, used=day_used)

    # Resolve index instrument
    instruments = _load("instruments.json")
    norm_sym = symbol.strip().upper()
    inst = None
    for r in instruments:
        if not isinstance(r, dict):
            continue
        if r.get("normalized_symbol") == norm_sym and r.get("asset_type") == "index":
            inst = r
            break
    if inst is None:
        _log_request(api_key["id"], "getIndex5MinuteData", {"symbol": symbol, "from": from_, "to": to},
                     404, "bypass", (time.time() - _t0) * 1000, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Unknown symbol or symbol is not an index")

    # Read 5min intraday unadjusted regular-session bars
    md = _load("market_data_points.json")
    rows = []
    for r in md:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != inst.get("id"):
            continue
        if r.get("timeframe") != "5min":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        td = r.get("trade_date")
        if _from or _to:
            if not isinstance(td, str):
                continue
            if _from and td < _from:
                continue
            if _to and td > _to:
                continue
        rows.append(r)

    # If no from/to, return most recent available bars (provider default window)
    def _ts_key(x):
        ts = x.get("ts")
        return ts if isinstance(ts, str) else ""
    rows.sort(key=_ts_key)

    MAX_ROWS = 5000
    if not _from and not _to:
        # provider default window: last 500 bars (capped by MAX_ROWS anyway)
        DEFAULT_WINDOW = 500
        if len(rows) > DEFAULT_WINDOW:
            rows = rows[-DEFAULT_WINDOW:]
    if len(rows) > MAX_ROWS:
        rows = rows[-MAX_ROWS:]

    out = []
    for r in rows:
        out.append({
            "date": r.get("ts"),
            "open": r.get("open"),
            "high": r.get("high"),
            "low": r.get("low"),
            "close": r.get("close"),
            "volume": r.get("volume"),
            "vwap": r.get("vwap"),
        })

    # Update last_used_at on success
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            k["last_used_at"] = _now
            k["updated_at"] = _now
            break
    _save("api_keys.json", api_keys)

    _log_request(api_key["id"], "getIndex5MinuteData", {"symbol": symbol, "from": from_, "to": to},
                 200, "miss", (time.time() - _t0) * 1000, result_count=len(out), error_code=None)
    return {
        "symbol": inst.get("symbol"),
        "from": _from,
        "to": _to,
        "timeframe": "5min",
        "data": out,
        "count": len(out),
    }

def getIndex1HourData(symbol, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- helpers
    def _is_iso_date(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.datetime.strptime(s, "%Y-%m-%d")
            return True
        except Exception:
            return False

    def _normalize_symbol(s):
        return s.strip().upper()

    def _make_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _hash_key_material(x):
        return hashlib.sha256(x.encode("utf-8")).hexdigest()

    def _choose_api_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, keys
        # pick the most recently used, else most recently updated, else created
        def _dt(v):
            if not v or not isinstance(v, str):
                return ""
            return v
        active.sort(key=lambda k: (_dt(k.get("last_used_at")), _dt(k.get("updated_at")), _dt(k.get("created_at"))), reverse=True)
        return active[0], keys

    def _quota_check(api_key_id, minute_quota, daily_quota):
        logs = _load("request_logs.json")
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        minute_count = 0
        day_count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                minute_count += 1
            if ts >= day_ago:
                day_count += 1

        if isinstance(minute_quota, int) and minute_quota >= 0 and minute_count >= minute_quota:
            return "minute", logs
        if isinstance(daily_quota, int) and daily_quota >= 0 and day_count >= daily_quota:
            return "daily", logs
        return None, logs

    def _log(api_key_id, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": _make_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "getIndex1HourData",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- validate input schema (no additionalProperties enforced by signature)
    params_obj = {"symbol": symbol}
    if from_ is not None:
        params_obj["from"] = from_
    if to is not None:
        params_obj["to"] = to

    # ---- authenticate ambient
    api_key, all_keys = _choose_api_key()
    if not api_key:
        duration_ms = int((time.time() - t0) * 1000)
        # Still log attempt; use placeholder api_key_id when none exists
        # but schema requires FK; if none, cannot log a valid row -> choose any existing key id if present else return without log.
        if all_keys:
            _log(all_keys[0].get("id"), params_obj, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    # key lifecycle check already active, but enforce quotas
    quota_hit, _ = _quota_check(api_key.get("id"), api_key.get("minute_request_quota"), api_key.get("daily_request_quota"))
    if quota_hit:
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", f"Request quota exceeded ({quota_hit}).")

    # validate symbol
    if not isinstance(symbol, str) or not symbol.strip():
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.")

    sym_norm = _normalize_symbol(symbol)

    # validate dates
    if from_ is not None and not _is_iso_date(from_):
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be a valid ISO date (YYYY-MM-DD).")
    if to is not None and not _is_iso_date(to):
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "to must be a valid ISO date (YYYY-MM-DD).")
    if from_ is not None and to is not None and from_ > to:
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be <= to.")

    # entitlement enforcement: allowed exchanges / asset types
    instruments = _load("instruments.json")
    inst = None
    for r in instruments:
        if not isinstance(r, dict):
            continue
        if r.get("normalized_symbol") == sym_norm:
            # index tool expects asset_type index
            if r.get("asset_type") == "index":
                inst = r
                break
    if not inst:
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 404, "bypass", duration_ms, result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Unknown index symbol.")

    allowed_asset_types = api_key.get("allowed_asset_types")
    if allowed_asset_types is not None:
        if not isinstance(allowed_asset_types, list) or any(not isinstance(x, str) for x in allowed_asset_types):
            # bad key configuration; treat as unauthorized for safety
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key configuration invalid for asset type allowlist.")
        if inst.get("asset_type") not in allowed_asset_types:
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not permitted for this asset type.")

    allowed_exchanges = api_key.get("allowed_exchanges")
    if allowed_exchanges is not None:
        if not isinstance(allowed_exchanges, list) or any(not isinstance(x, str) for x in allowed_exchanges):
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key configuration invalid for exchange allowlist.")
        exch = inst.get("exchange")
        if exch is not None and exch not in allowed_exchanges:
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 403, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not permitted for this exchange.")

    # ---- read market data
    md = _load("market_data_points.json")
    rows = []
    inst_id = inst.get("id")
    for p in md:
        if not isinstance(p, dict):
            continue
        if p.get("instrument_id") != inst_id:
            continue
        if p.get("timeframe") != "1hour":
            continue
        if p.get("adjustment_type") != "unadjusted":
            continue
        if p.get("session") != "regular":
            continue
        td = p.get("trade_date")
        if not isinstance(td, str):
            continue
        if from_ is not None and td < from_:
            continue
        if to is not None and td > to:
            continue
        rows.append(p)

    # provider-like ordering: by timestamp ascending
    def _ts_key(p):
        ts = p.get("ts")
        if not isinstance(ts, str):
            return ""
        return ts
    rows.sort(key=_ts_key)

    # default window when from/to omitted: return most recent available hourly bars (cap server-side)
    MAX_ROWS = 5000
    if from_ is None and to is None and len(rows) > MAX_ROWS:
        rows = rows[-MAX_ROWS:]

    # update api_key last_used_at on successful auth (regardless of 404? in this tool, 404 is after auth; but here we succeeded)
    api_key_id = api_key.get("id")
    for k in all_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", all_keys)

    # response mapping: return bar objects similar to FMP chart endpoints
    out = []
    for p in rows:
        out.append({
            "date": p.get("ts"),
            "open": p.get("open"),
            "high": p.get("high"),
            "low": p.get("low"),
            "close": p.get("close"),
            "volume": p.get("volume"),
        })

    duration_ms = int((time.time() - t0) * 1000)
    _log(api_key_id, params_obj, 200, "miss", duration_ms, result_count=len(out), error_code=None)
    return {"symbol": sym_norm, "timeframe": "1hour", "bars": out, "result_count": len(out)}

def getSP500Constituents(asOfDate=None, limit=None, **_extra):
    import json, os, datetime, time, uuid, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _sha256(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _is_iso_date(s):
        if not isinstance(s, str):
            return False
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
            return False
        try:
            datetime.date.fromisoformat(s)
            return True
        except ValueError:
            return False

    def _coerce_limit(x, default, max_allowed):
        if x is None:
            return default
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            v = x
        elif isinstance(x, float):
            if not x.is_integer():
                return None
            v = int(x)
        else:
            return None
        if v <= 0:
            return None
        if v > max_allowed:
            return "TOO_LARGE"
        return v

    def _resolve_api_key():
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        # Ambient auth: pick any active key that can serve (quota checked later)
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("rl"),
            "api_key_id": api_key_id if api_key_id is not None else "unauthorized",
            "tool_name": "getSP500Constituents",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": max(0, int(round((time.time() - _t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": _now,
            "updated_at": _now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _quota_ok(api_key_row):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        akid = api_key_row.get("id")
        def _parse_ts(x):
            if not isinstance(x, str):
                return None
            try:
                if x.endswith("Z"):
                    x2 = x[:-1]
                    return datetime.datetime.fromisoformat(x2)
                return datetime.datetime.fromisoformat(x)
            except ValueError:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != akid:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= day_ago:
                per_day += 1
                if ts >= minute_ago:
                    per_min += 1

        min_quota = api_key_row.get("minute_request_quota")
        day_quota = api_key_row.get("daily_request_quota")
        try:
            min_quota = int(min_quota)
            day_quota = int(day_quota)
        except Exception:
            # malformed key config => treat as unauthorized serviceable key
            return (False, "UNAUTHORIZED", 403, "Key quota configuration invalid")

        # If this request would exceed, reject
        if min_quota >= 0 and per_min + 1 > min_quota:
            return (False, "RATE_LIMIT", 429, "Minute request quota exceeded")
        if day_quota >= 0 and per_day + 1 > day_quota:
            return (False, "QUOTA_EXCEEDED", 429, "Daily request quota exceeded")
        return (True, None, None, None)

    # Validate inputs (no additional properties exist here because signature fixed)
    params = {}
    if asOfDate is not None:
        if not _is_iso_date(asOfDate):
            api_key = _resolve_api_key()
            akid = api_key.get("id") if api_key else None
            _log(akid, {"asOfDate": asOfDate, "limit": limit} if limit is not None else {"asOfDate": asOfDate}, 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "asOfDate must be YYYY-MM-DD")
        params["asOfDate"] = asOfDate

    lim = _coerce_limit(limit, default=505, max_allowed=10000)
    if lim is None or lim == "TOO_LARGE":
        api_key = _resolve_api_key()
        akid = api_key.get("id") if api_key else None
        _log(akid, {"asOfDate": asOfDate, "limit": limit} if asOfDate is not None else {"limit": limit}, 400, error_code="VALIDATION_ERROR")
        if lim == "TOO_LARGE":
            return _err("VALIDATION_ERROR", "limit exceeds maximum", max_limit=10000)
        return _err("VALIDATION_ERROR", "limit must be a positive number")
    params["limit"] = lim

    api_key = _resolve_api_key()
    if not api_key:
        _log(None, params, 401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available")

    ok, ecode, http_status, emsg = _quota_ok(api_key)
    if not ok:
        _log(api_key.get("id"), params, http_status, error_code=ecode)
        return _err(ecode, emsg)

    # Fetch constituents snapshot from content_items
    items = _load("content_items.json")
    if not isinstance(items, list):
        items = []

    # We model index constituent snapshots using content_type 'industry_performance'/'sector_performance' etc in schema,
    # but for indices we store them under content_type='symbol_change' is also not right. We'll use identifier_1 tag.
    # Real behavior: find S&P 500 constituents snapshot; here: content_type='sector_performance' with identifier_1='sp500_constituents'
    # To avoid fabrications, we only return what exists.
    target_type = "sector_performance"
    tag = "sp500_constituents"

    candidates = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != target_type:
            continue
        if it.get("identifier_1") != tag:
            continue
        # if asOfDate provided, match as_of_date
        if asOfDate is not None and it.get("as_of_date") != asOfDate:
            continue
        candidates.append(it)

    if not candidates:
        # if asOfDate not specified, try latest by as_of_date then created_at
        if asOfDate is None:
            for it in items:
                if not isinstance(it, dict):
                    continue
                if it.get("status") != "active":
                    continue
                if it.get("content_type") != target_type:
                    continue
