def getHistoricalSP500Changes(from_=None, to=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _make_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_iso_date(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.datetime.strptime(s, "%Y-%m-%d")
            return True
        except Exception:
            return False

    def _choose_api_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, keys
        def _dt(v):
            if not v or not isinstance(v, str):
                return ""
            return v
        active.sort(key=lambda k: (_dt(k.get("last_used_at")), _dt(k.get("updated_at")), _dt(k.get("created_at"))), reverse=True)
        return active[0], keys

    def _quota_check(api_key_id, minute_quota, daily_quota):
        logs = _load("request_logs.json")
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        minute_count = 0
        day_count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                minute_count += 1
            if ts >= day_ago:
                day_count += 1

        if isinstance(minute_quota, int) and minute_quota >= 0 and minute_count >= minute_quota:
            return "minute", logs
        if isinstance(daily_quota, int) and daily_quota >= 0 and day_count >= daily_quota:
            return "daily", logs
        return None, logs

    def _log(api_key_id, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": _make_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "getHistoricalSP500Changes",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # ---- validate inputs / schema
    params_obj = {}
    if from_ is not None:
        params_obj["from"] = from_
    if to is not None:
        params_obj["to"] = to
    if limit is not None:
        params_obj["limit"] = limit
    if cursor is not None:
        params_obj["cursor"] = cursor
    if sort is not None:
        params_obj["sort"] = sort
    if order is not None:
        params_obj["order"] = order

    # ---- authenticate ambient
    api_key, all_keys = _choose_api_key()
    if not api_key:
        duration_ms = int((time.time() - t0) * 1000)
        if all_keys:
            _log(all_keys[0].get("id"), params_obj, 401, "bypass", duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    quota_hit, _ = _quota_check(api_key.get("id"), api_key.get("minute_request_quota"), api_key.get("daily_request_quota"))
    if quota_hit:
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", f"Request quota exceeded ({quota_hit}).")

    # validate date filters
    if from_ is not None and not _is_iso_date(from_):
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be a valid ISO date (YYYY-MM-DD).")
    if to is not None and not _is_iso_date(to):
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "to must be a valid ISO date (YYYY-MM-DD).")
    if from_ is not None and to is not None and from_ > to:
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be <= to.")

    # validate limit
    if limit is None:
        limit_i = 100
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a number.")
        limit_i = int(limit)
        if limit_i < 1:
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be >= 1.")
    MAX_LIMIT = 1000
    if limit_i > MAX_LIMIT:
        duration_ms = int((time.time() - t0) * 1000)
        _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"limit must not exceed {MAX_LIMIT}.")

    # validate order
    if order is None:
        order_v = "desc"
    else:
        if order not in ("asc", "desc"):
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'.")
        order_v = order

    # validate sort
    allowed_sorts = {"date", "as_of_date", "created_at"}
    if sort is None:
        sort_v = "date"
    else:
        if not isinstance(sort, str) or not sort.strip():
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort must be a non-empty string.")
        sort_v = sort.strip()
        if sort_v not in allowed_sorts:
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Unsupported sort field. Allowed: {sorted(allowed_sorts)}")

    # cursor continuation
    cur = None
    if cursor is not None:
        cur = _decode_cursor(cursor)
        if not isinstance(cur, dict) or "offset" not in cur or "query" not in cur:
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        # enforce same query window/sort
        q = cur.get("query")
        expected = {"from": from_, "to": to, "sort": sort_v, "order": order_v}
        if q != expected:
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 409, "bypass", duration_ms, result_count=None, error_code="CONFLICT")
            return _err("CONFLICT", "Cursor does not match the current query parameters.")
        offset = cur.get("offset")
        if not isinstance(offset, int) or offset < 0:
            duration_ms = int((time.time() - t0) * 1000)
            _log(api_key.get("id"), params_obj, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor offset.")
    else:
        offset = 0

    # ---- fetch from content_items: content_type = 'symbol_change' with identifier_1='SP500'
    items = _load("content_items.json")
    rows = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "symbol_change":
            continue
        # try to scope to SP500 change events
        id1 = it.get("identifier_1")
        if isinstance(id1, str):
            if id1.upper() not in ("SP500", "S&P500", "S&P 500", "SPX", "SP_500"):
                continue
        else:
            # if no identifier_1, allow if payload indicates sp500
            payload = it.get("payload")
            if not isinstance(payload, dict) or str(payload.get("index", "")).upper() not in ("SP500", "S&P500", "S&P 500", "SPX"):
                continue

        d = it.get("as_of_date")
        if not isinstance(d, str) or not _is_iso_date(d):
            continue
        if from_ is not None and d < from_:
            continue
        if to is not None and d > to:
            continue
        rows.append(it)

    # sort
    def _key(it):
        if sort_v in ("date", "as_of_date"):
            return it.get("as_of_date") or ""
        if sort_v == "created_at":
            return it.get("created_at") or ""
        return it.get("as_of_date") or ""

    rows.sort(key=_key, reverse=(order_v == "desc"))

    total = len(rows)
    page = rows[offset: offset + limit_i]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"offset": next_offset, "query": {"from": from_, "to": to, "sort": sort_v, "order": order_v}}) if has_more else None

    # map to change event objects from payload; fall back to minimal fields
    out = []
    for it in page:
        payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
        out.append({
            "date": it.get("as_of_date"),
            "addedSymbol": payload.get("addedSymbol") or payload.get("added_symbol") or payload.get("added"),
            "removedSymbol": payload.get("removedSymbol") or payload.get("removed_symbol") or payload.get("removed"),
            "addedSecurity": payload.get("addedSecurity") or payload.get("added_security") or payload.get("addedName"),
            "removedSecurity": payload.get("removedSecurity") or payload.get("removed_security") or payload.get("removedName"),
            "reason": payload.get("reason"),
            "source": payload.get("source"),
            "raw": payload,
        })

    # update last_used_at
    api_key_id = api_key.get("id")
    for k in all_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", all_keys)

    duration_ms = int((time.time() - t0) * 1000)
    _log(api_key_id, params_obj, 200, "miss", duration_ms, result_count=len(out), error_code=None)
    return {
        "data": out,
        "meta": {
            "total": total,
            "limit": limit_i,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort_v,
            "order": order_v,
            "from": from_,
            "to": to,
        },
    }

def getHistoricalNasdaqChanges(from_=None, to=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- helpers
    def _parse_iso_date(s):
        if not isinstance(s, str):
            return None
        try:
            d = datetime.date.fromisoformat(s)
        except Exception:
            return None
        if d.isoformat() != s:
            return None
        return d

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha1((now_iso + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:20]}"

    def _log_request(api_key_id, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("rlog"),
            "api_key_id": api_key_id,
            "tool_name": "getHistoricalNasdaqChanges",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _select_active_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        # Choose any active key (ambient auth). Prefer highest quotas.
        def score(k):
            try:
                return (int(k.get("daily_request_quota", 0)), int(k.get("minute_request_quota", 0)))
            except Exception:
                return (0, 0)
        active.sort(key=score, reverse=True)
        return active[0]

    def _quota_allows(api_key_row):
        logs = _load("request_logs.json")
        key_id = api_key_row["id"]

        # rolling windows
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        minute_count = 0
        day_count = 0

        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= day_ago:
                day_count += 1
            if dt >= minute_ago:
                minute_count += 1

        try:
            min_quota = int(api_key_row.get("minute_request_quota", 0))
            day_quota = int(api_key_row.get("daily_request_quota", 0))
        except Exception:
            return (False, "VALIDATION_ERROR")

        if min_quota >= 0 and minute_count >= min_quota:
            return (False, "RATE_LIMIT")
        if day_quota >= 0 and day_count >= day_quota:
            return (False, "QUOTA_EXCEEDED")
        return (True, None)

    # ---- validate inputs (and build params object that conforms to schema: no extras)
    params = {}
    if from_ is not None:
        params["from"] = from_
    if to is not None:
        params["to"] = to
    if limit is not None:
        params["limit"] = limit
    if cursor is not None:
        params["cursor"] = cursor
    if sort is not None:
        params["sort"] = sort
    if order is not None:
        params["order"] = order

    # validate order
    if order is not None:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # validate limit (default 100, max server-side 1000 for this tool)
    if limit is None:
        limit_i = 100
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a number")
        if limit != int(limit) or limit < 0:
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 0")
        limit_i = int(limit)
    if limit_i > 1000:
        api_key = _select_active_key()
        api_key_id = api_key["id"] if api_key else "unknown"
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must not exceed 1000")

    # validate dates
    d_from = None
    d_to = None
    if from_ is not None:
        d_from = _parse_iso_date(from_)
        if d_from is None:
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "from must be YYYY-MM-DD")
    if to is not None:
        d_to = _parse_iso_date(to)
        if d_to is None:
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "to must be YYYY-MM-DD")
    if d_from is not None and d_to is not None and d_from > d_to:
        api_key = _select_active_key()
        api_key_id = api_key["id"] if api_key else "unknown"
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be <= to")

    # validate cursor
    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_obj = json.loads(raw.decode("utf-8"))
        except Exception:
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

        if not isinstance(cursor_obj, dict) or "offset" not in cursor_obj:
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

        # enforce that cursor matches query window/sort
        for fld, expected in (("from", from_), ("to", to), ("sort", sort), ("order", order)):
            if cursor_obj.get(fld) != expected:
                api_key = _select_active_key()
                api_key_id = api_key["id"] if api_key else "unknown"
                duration_ms = int((time.time() - t0) * 1000)
                _log_request(api_key_id, params, 409, "bypass", duration_ms, result_count=0, error_code="CONFLICT")
                return _err("CONFLICT", "cursor does not match current query parameters")

        try:
            offset = int(cursor_obj.get("offset", 0))
        except Exception:
            offset = -1
        if offset < 0:
            api_key = _select_active_key()
            api_key_id = api_key["id"] if api_key else "unknown"
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(api_key_id, params, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor offset is invalid")
    else:
        offset = 0

    # ---- authentication (ambient): must have an active api_key
    api_key = _select_active_key()
    if not api_key:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request("unknown", params, 401, "bypass", duration_ms, result_count=0, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available")

    # ---- quota check
    allowed, why = _quota_allows(api_key)
    if not allowed:
        duration_ms = int((time.time() - t0) * 1000)
        http_status = 429
        _log_request(api_key["id"], params, http_status, "bypass", duration_ms, result_count=0, error_code=why)
        return _err(why, "Request quota exceeded")

    # ---- query data: use content_items with content_type='symbol_change' and identifier_1='NASDAQ'
    items = _load("content_items.json")
    rows = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "symbol_change":
            continue
        if it.get("identifier_1") not in ("NASDAQ", "Nasdaq", "nasdaq"):
            continue
        as_of = it.get("as_of_date")
        if not isinstance(as_of, str):
