            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return None

    def _is_intish(x):
        return isinstance(x, int) and not isinstance(x, bool)

