            minute_quota = 0
        if not _is_intish(day_quota) or day_quota < 0:
            day_quota = 0

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        m = 0
        d = 0
        for r in logs:
            if r.get("api_key_id") != key_row.get("id"):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= minute_ago:
                m += 1
            if ts >= day_ago:
                d += 1

        if minute_quota == 0:
            return ("RATE_LIMIT", "Minute request quota exceeded.")
        if day_quota == 0:
            return ("QUOTA_EXCEEDED", "Daily request quota exceeded.")
