def searchInsiderTrades(symbol=None, page=None, limit=None, reportingCik=None, companyCik=None, transactionType=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "searchInsiderTrades"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_intish(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _find_active_key(api_keys):
        for k in api_keys:
            if k.get("status") == "active":
                return k
        return None

    def _quota_check(logs, key_row, now):
        minute_quota = key_row.get("minute_request_quota")
        day_quota = key_row.get("daily_request_quota")
        if not _is_intish(minute_quota) or minute_quota < 0:
            minute_quota = 0
        if not _is_intish(day_quota) or day_quota < 0:
            day_quota = 0

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        m = 0
        d = 0
        for r in logs:
            if r.get("api_key_id") != key_row.get("id"):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= minute_ago:
                m += 1
            if ts >= day_ago:
                d += 1

        if minute_quota == 0:
            return ("RATE_LIMIT", "Minute request quota exceeded.")
        if day_quota == 0:
            return ("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        if m + 1 > minute_quota:
            return ("RATE_LIMIT", "Minute request quota exceeded.", {"limit": minute_quota, "used": m})
        if d + 1 > day_quota:
            return ("QUOTA_EXCEEDED", "Daily request quota exceeded.", {"limit": day_quota, "used": d})
        return None

    def _log_request(logs, api_key_id, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        now_iso = _now_iso()
        rid = "req_" + hashlib.sha256((now_iso + tool_name + str(api_key_id)).encode("utf-8")).hexdigest()[:16]
        logs.append({
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    def _normalize_symbol(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip().upper()
        return s2 if s2 else None

    def _validate_cik(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("VALIDATION_ERROR", f"{field} must be a string CIK.")
        st = s.strip()
        # Allow left-padded digits; must be digits only, length 1..20
        if not re.fullmatch(r"\d{1,20}", st):
            return ("VALIDATION_ERROR", f"{field} must be a numeric CIK string.")
        return None

    api_keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    now = datetime.datetime.utcnow()

    key = _find_active_key(api_keys)

    params = {}
    if symbol is not None: params["symbol"] = symbol
    if page is not None: params["page"] = page
    if limit is not None: params["limit"] = limit
    if reportingCik is not None: params["reportingCik"] = reportingCik
    if companyCik is not None: params["companyCik"] = companyCik
    if transactionType is not None: params["transactionType"] = transactionType

    if key is None:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, "api_key_unauthorized", params, 401, "bypass", duration_ms, None, "UNAUTHORIZED")
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    qc = _quota_check(logs, key, now)
    if qc is not None:
        code = qc[0]; msg = qc[1]; extra = qc[2] if len(qc) > 2 else {}
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, key["id"], params, 429, "bypass", duration_ms, None, code)
        _save("request_logs.json", logs)
        return _err(code, msg, **extra)

    # Validate page/limit
    if page is None:
        page_v = 0
    else:
        if isinstance(page, bool) or not (isinstance(page, int) or isinstance(page, float)) or int(page) != page:
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(logs, key["id"], params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "page must be an integer.")
        page_v = int(page)
    if page_v < 0:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, key["id"], params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "page must be >= 0.")

    if limit is None:
        limit_v = 100
    else:
        if isinstance(limit, bool) or not (isinstance(limit, int) or isinstance(limit, float)) or int(limit) != limit:
            duration_ms = int((time.time() - t0) * 1000)
            _log_request(logs, key["id"], params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        limit_v = int(limit)
    if limit_v < 1 or limit_v > 100:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, key["id"], params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "limit must be within 1..100.")

    e = _validate_cik(reportingCik, "reportingCik")
    if e is not None:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, key["id"], params, 400, "bypass", duration_ms, None, e[0])
        _save("request_logs.json", logs)
        return _err(e[0], e[1])
    e = _validate_cik(companyCik, "companyCik")
    if e is not None:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, key["id"], params, 400, "bypass", duration_ms, None, e[0])
        _save("request_logs.json", logs)
        return _err(e[0], e[1])

    sym_norm = _normalize_symbol(symbol) if symbol is not None else None
    tx_type = transactionType.strip() if isinstance(transactionType, str) else transactionType
    if transactionType is not None and (not isinstance(transactionType, str) or not tx_type):
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(logs, key["id"], params, 400, "bypass", duration_ms, None, "VALIDATION_ERROR")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "transactionType must be a non-empty string.")

    items = _load("content_items.json")
    matched = []
    for it in items:
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "insider_trade":
            continue
        payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}

        if sym_norm is not None:
            ps = payload.get("symbol") or payload.get("ticker") or payload.get("companySymbol")
            psn = _normalize_symbol(ps) if isinstance(ps, str) else None
            if psn != sym_norm:
                continue

        if reportingCik is not None:
            pr = payload.get("reportingCik") or payload.get("reportingCIK") or payload.get("reporting_cik")
            if not isinstance(pr, str) or pr.strip() != reportingCik.strip():
                continue

        if companyCik is not None:
            pc = payload.get("companyCik") or payload.get("companyCIK") or payload.get("company_cik") or payload.get("issuerCik")
            if not isinstance(pc, str) or pc.strip() != companyCik.strip():
                continue

        if tx_type is not None:
            pt = payload.get("transactionType") or payload.get("transaction_type")
            if not isinstance(pt, str) or pt.strip() != tx_type:
                continue

        out = dict(payload)
        out.setdefault("filingDate", it.get("as_of_date"))
        out.setdefault("title", it.get("title"))
        out.setdefault("url", it.get("url"))
        matched.append((it, out))

    def _parse_iso_date(s):
        if not isinstance(s, str):
            return datetime.date.min
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return datetime.date.min

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return datetime.datetime.min
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return datetime.datetime.min

    def _stable_key(tup):
        it = tup[0]
        d = _parse_iso_date(it.get("as_of_date"))
        c = _parse_ts(it.get("created_at"))
        return (d, c, str(it.get("id") or ""))

    matched.sort(key=_stable_key, reverse=True)
    rows = [t[1] for t in matched]

    start = page_v * limit_v
    end = start + limit_v
    page_rows = rows[start:end]

    now_iso = _now_iso()
    for k in api_keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - t0) * 1000)
    _log_request(logs, key["id"], params, 200, "miss", duration_ms, result_count=len(page_rows), error_code=None)
    _save("request_logs.json", logs)

    return {
        "data": page_rows,
        "meta": {
            "page": page_v,
            "limit": limit_v,
            "total": len(rows),
            "has_more": end < len(rows)
        }
    }

def searchInsiderTradesByReportingName(name, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _iso_ms():
        # For duration measurements we use perf_counter; return ms int.
        return int((time.perf_counter() - t0) * 1000)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _normalize_name(s):
        s = s.strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    # Validate params (additionalProperties already controlled by signature)
    if not isinstance(name, str) or not name.strip():
        # Log attempt with 400 and no key
        t0 = time.perf_counter()
        logs = _load("request_logs.json")
        now = _now()
        logs.append({
            "id": _new_id("req"),
            "api_key_id": "anonymous",
            "tool_name": "searchInsiderTradesByReportingName",
            "params": {"name": name} if isinstance(name, str) else {"name": None},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": _iso_ms(),
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string")

    t0 = time.perf_counter()
    params = {"name": name}

    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        logs = _load("request_logs.json")
        now = _now()
        logs.append({
            "id": _new_id("req"),
            "api_key_id": "anonymous",
            "tool_name": "searchInsiderTradesByReportingName",
            "params": params,
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": _iso_ms(),
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No active API key available for authentication")

    # Pick an active key that is within quota; enforce rolling quotas based on request_logs
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow()

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    chosen_key = None
    for k in active_keys:
        minute_quota = k.get("minute_request_quota")
        daily_quota = k.get("daily_request_quota")
        if not (isinstance(minute_quota, int) and minute_quota >= 0 and isinstance(daily_quota, int) and daily_quota >= 0):
            continue

        key_id = k.get("id")
        if not isinstance(key_id, str) or not key_id:
            continue

        # Count in rolling windows including all attempts (success/fail), as typical quota behavior.
        min_window_start = now_dt - datetime.timedelta(minutes=1)
        day_window_start = now_dt - datetime.timedelta(days=1)

        minute_count = 0
        daily_count = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != key_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= min_window_start:
                minute_count += 1
            if ts >= day_window_start:
                daily_count += 1

        if minute_quota != 0 and minute_count >= minute_quota:
            continue
        if daily_quota != 0 and daily_count >= daily_quota:
            continue

        chosen_key = k
        break

    if chosen_key is None:
        # Quota exceeded for all active keys -> reject
        now = _now()
        logs.append({
            "id": _new_id("req"),
            "api_key_id": active_keys[0].get("id") or "anonymous",
            "tool_name": "searchInsiderTradesByReportingName",
            "params": params,
            "http_status": 429,
            "cache_status": "bypass",
            "duration_ms": _iso_ms(),
            "result_count": None,
            "error_code": "QUOTA_EXCEEDED",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    # Perform search over content_items of type insider_trade
    content = _load("content_items.json")
    qn = _normalize_name(name)

    def _match_item(it):
        if not isinstance(it, dict):
            return False
        if it.get("content_type") != "insider_trade":
            return False
        if it.get("status") != "active":
            return False
        payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
        # Try common fields; schema uses generic identifier slots too
        candidates = []
        for key in ("reportingName", "reportingPerson", "reportingOwnerName", "name", "reporting_owner_name"):
            v = payload.get(key)
            if isinstance(v, str) and v.strip():
                candidates.append(v)
        # identifier_1/2 sometimes store such strings
        for v in (it.get("identifier_1"), it.get("identifier_2"), it.get("title")):
            if isinstance(v, str) and v.strip():
                candidates.append(v)
        for c in candidates:
            if qn in _normalize_name(c):
                return True
        return False

    results = [it for it in content if _match_item(it)]

    # Update key last_used_at on successful authenticated request (even if empty result set)
    now = _now()
    key_id = chosen_key["id"]
    updated = False
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            updated = True
            break
    if updated:
        _save("api_keys.json", api_keys)

    # Log request
    logs.append({
        "id": _new_id("req"),
        "api_key_id": key_id,
        "tool_name": "searchInsiderTradesByReportingName",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": _iso_ms(),
        "result_count": len(results),
        "error_code": None,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", logs)

    return {
        "data": results,
        "meta": {"total": len(results)}
    }

