    # Aggregate from insider_trade content items for this instrument
    content = _load("content_items.json")

    txns = []
    for it in content:
        if not isinstance(it, dict):
            continue
        if it.get("content_type") != "insider_trade" or it.get("status") != "active":
            continue
        if it.get("instrument_id") != instrument_id:
            continue
        payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
        txns.append(payload)

    def _num(x):
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x.replace(",", "").strip())
            except Exception:
                return None
        return None

    total = len(txns)
    purchases = 0
    sales = 0
    other = 0
    shares_purchased = 0.0
    shares_sold = 0.0
    value_purchased = 0.0
    value_sold = 0.0

    by_code = {}  # code -> count
    by_owner = {}  # reportingName -> count

    # Heuristics: classify by "transactionType"/"transactionCode" or "acquisitionOrDisposition" A/D
    for p in txns:
        code = p.get("transactionType") or p.get("transactionCode") or p.get("code")
        code_norm = code.strip().upper() if isinstance(code, str) and code.strip() else None
        if code_norm:
            by_code[code_norm] = by_code.get(code_norm, 0) + 1

        owner = p.get("reportingName") or p.get("reportingOwnerName") or p.get("name")
        owner_norm = owner.strip() if isinstance(owner, str) and owner.strip() else None
        if owner_norm:
            by_owner[owner_norm] = by_owner.get(owner_norm, 0) + 1

        ad = p.get("acquisitionOrDisposition") or p.get("acquiredDisposed") or p.get("transactionAcquiredDisposedCode")
        ad_norm = ad.strip().upper() if isinstance(ad, str) and ad.strip() else None

        shares = _num(p.get("shares")) or _num(p.get("securitiesTransacted")) or _num(p.get("transactionShares"))
        price = _num(p.get("price")) or _num(p.get("transactionPrice")) or _num(p.get("pricePerShare"))
        value = _num(p.get("value")) or _num(p.get("transactionValue"))

        if value is None and shares is not None and price is not None:
            value = shares * price

        is_purchase = False
        is_sale = False
        if ad_norm == "A":
            is_purchase = True
        elif ad_norm == "D":
            is_sale = True
        elif code_norm:
            # Typical Form 4 codes: P (open market/purchase), S (sale), M (option exercise), etc.
            if code_norm.startswith("P"):
                is_purchase = True
            elif code_norm.startswith("S"):
                is_sale = True

        if is_purchase:
            purchases += 1
            if shares is not None:
                shares_purchased += shares
            if value is not None:
                value_purchased += value
        elif is_sale:
            sales += 1
            if shares is not None:
                shares_sold += shares
            if value is not None:
                value_sold += value
        else:
            other += 1

    # Sort breakdowns
    by_code_list = [{"code": k, "count": by_code[k]} for k in sorted(by_code.keys())]
    by_owner_list = [{"name": k, "count": by_owner[k]} for k in sorted(by_owner.keys(), key=lambda x: (-by_owner[x], x))][:50]

    # Update last_used_at
    now = _now()
    key_id = chosen_key["id"]
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Log request
    logs.append({
        "id": _new_id("req"),
        "api_key_id": key_id,
        "tool_name": "getInsiderTradeStatistics",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": _dur_ms(),
        "result_count": None,
        "error_code": None,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", logs)

    return {
        "data": {
            "symbol": normalized_symbol,
            "instrument_id": instrument_id,
            "total_transactions": total,
            "purchases": {
                "count": purchases,
                "shares": shares_purchased,
                "value": value_purchased
            },
            "sales": {
                "count": sales,
                "shares": shares_sold,
                "value": value_sold
            },
            "other": {
                "count": other
            },
            "breakdowns": {
                "by_transaction_code": by_code_list,
                "top_reporting_names": by_owner_list
            }
        }
    }

def getAcquisitionOwnership(symbol, limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.perf_counter()

    def _dur_ms():
        return int((time.perf_counter() - t0) * 1000)

    # Validate symbol
    if not isinstance(symbol, str) or not symbol.strip():
        logs = _load("request_logs.json")
        now = _now()
        logs.append({
            "id": _new_id("req"),
            "api_key_id": "anonymous",
            "tool_name": "getAcquisitionOwnership",
            "params": {"symbol": symbol, "limit": limit},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": _dur_ms(),
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")

    # Validate limit
    if limit is None:
        limit_v = 2000
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            logs = _load("request_logs.json")
            now = _now()
            logs.append({
                "id": _new_id("req"),
                "api_key_id": "anonymous",
                "tool_name": "getAcquisitionOwnership",
                "params": {"symbol": symbol, "limit": limit},
                "http_status": 400,
                "cache_status": "bypass",
                "duration_ms": _dur_ms(),
                "result_count": None,
                "error_code": "VALIDATION_ERROR",
                "created_at": now,
                "updated_at": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "limit must be a number")
        limit_v = int(limit)

    # Enforce server-side max (single list endpoint). Use 10000 as safe policy cap.
    if limit_v <= 0 or limit_v > 10000:
        logs = _load("request_logs.json")
        now = _now()
        logs.append({
            "id": _new_id("req"),
            "api_key_id": "anonymous",
            "tool_name": "getAcquisitionOwnership",
            "params": {"symbol": symbol, "limit": limit},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": _dur_ms(),
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 10000")

    params = {"symbol": symbol, "limit": limit_v}
    normalized_symbol = symbol.strip().upper()

    # Authenticate ambiently
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        logs = _load("request_logs.json")
        now = _now()
        logs.append({
            "id": _new_id("req"),
            "api_key_id": "anonymous",
            "tool_name": "getAcquisitionOwnership",
            "params": params,
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": _dur_ms(),
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No active API key available for authentication")

    logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow()

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    chosen_key = None
    for k in active_keys:
        minute_quota = k.get("minute_request_quota")
        daily_quota = k.get("daily_request_quota")
        if not (isinstance(minute_quota, int) and minute_quota >= 0 and isinstance(daily_quota, int) and daily_quota >= 0):
            continue
        key_id = k.get("id")
        if not isinstance(key_id, str) or not key_id:
            continue
        min_start = now_dt - datetime.timedelta(minutes=1)
        day_start = now_dt - datetime.timedelta(days=1)
        minute_count = 0
        daily_count = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != key_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= min_start:
                minute_count += 1
            if ts >= day_start:
                daily_count += 1
        if minute_quota != 0 and minute_count >= minute_quota:
            continue
        if daily_quota != 0 and daily_count >= daily_quota:
            continue
        chosen_key = k
        break

    if chosen_key is None:
        now = _now()
        logs.append({
            "id": _new_id("req"),
            "api_key_id": active_keys[0].get("id") or "anonymous",
            "tool_name": "getAcquisitionOwnership",
            "params": params,
            "http_status": 429,
            "cache_status": "bypass",
            "duration_ms": _dur_ms(),
            "result_count": None,
            "error_code": "QUOTA_EXCEEDED",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    instruments = _load("instruments.json")
    inst = None
    for i in instruments:
        if isinstance(i, dict) and i.get("normalized_symbol") == normalized_symbol:
            if i.get("primary_listing_symbol_id") is None:
                inst = i
                break
            if inst is None:
                inst = i
    if inst is None:
        now = _now()
        logs.append({
            "id": _new_id("req"),
            "api_key_id": chosen_key["id"],
            "tool_name": "getAcquisitionOwnership",
            "params": params,
            "http_status": 404,
            "cache_status": "bypass",
            "duration_ms": _dur_ms(),
            "result_count": None,
            "error_code": "NOT_FOUND",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Symbol not found")

    instrument_id = inst.get("id")

    # Acquisition/beneficial ownership change records live as content_type institutional_filing_extract or insider_trade, etc.
    # We will return content_items where content_type == 'institutional_filing_extract' or 'insider_trade' with payload markers.
    content = _load("content_items.json")

    items = []
    for it in content:
        if not isinstance(it, dict) or it.get("status") != "active":
            continue
        if it.get("instrument_id") != instrument_id:
            continue
        ct = it.get("content_type")
        if ct not in ("institutional_filing_extract", "insider_trade"):
            continue
        payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
        # Heuristic: keep entries that look like ownership/acquisition changes
        looks_like = False
        for k in ("beneficialOwnership", "ownership", "sharesOwned", "ownershipChange", "acquisition", "acquired", "disposed"):
            if k in payload:
                looks_like = True
                break
        if ct == "institutional_filing_extract":
            looks_like = True  # this type is commonly ownership-related
        if looks_like:
            items.append(it)

    # Sort newest first by as_of_date then created_at
    def _sort_key(it):
        asof = it.get("as_of_date")
        created = it.get("created_at")
        # Strings compare fine for YYYY-MM-DD and ISO, but guard None
        return (asof or "", created or "")
    items.sort(key=_sort_key, reverse=True)

    items = items[:limit_v]

    # Update last_used_at
    now = _now()
    key_id = chosen_key["id"]
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Log request
    logs.append({
        "id": _new_id("req"),
        "api_key_id": key_id,
        "tool_name": "getAcquisitionOwnership",
        "params": params,
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": _dur_ms(),
        "result_count": len(items),
        "error_code": None,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", logs)

    return {
        "data": items,
        "meta": {"total": len(items), "limit": limit_v}
    }

def getSectorPerformanceSnapshot(date, exchange=None, sector=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_iso_date(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.date.fromisoformat(s)
            return len(s) == 10
        except Exception:
            return False

    def _log(api_key_id, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": "getSectorPerformanceSnapshot",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate params (additionalProperties already enforced by signature)
    params_obj = {"date": date}
    if exchange is not None:
        params_obj["exchange"] = exchange
    if sector is not None:
        params_obj["sector"] = sector

    if not _is_iso_date(date):
        # auth is still required by business rules; but validation takes precedence for schema errors
        # Log attempt with some api_key_id if possible; otherwise sentinel.
        duration = (time.time() - start) * 1000
        _log("unauth", params_obj, 400, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "date must be provided in YYYY-MM-DD format")

    if exchange is not None and not isinstance(exchange, str):
        duration = (time.time() - start) * 1000
        _log("unauth", params_obj, 400, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "exchange must be a string")
    if sector is not None and (not isinstance(sector, str) or not sector.strip()):
        duration = (time.time() - start) * 1000
        _log("unauth", params_obj, 400, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sector must be a non-empty string when provided")

    # Ambient auth: find any active key that can serve this call (and within quotas)
    keys = _load("api_keys.json")
    logs = _load("request_logs.json")

    active_keys = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        duration = (time.time() - start) * 1000
        _log("unauth", params_obj, 401, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key")

    now_dt = datetime.datetime.utcnow()
    def _within_window(ts_iso, window_seconds):
        if not isinstance(ts_iso, str):
            return False
        try:
            ts = datetime.datetime.fromisoformat(ts_iso.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return False
        return (now_dt - ts).total_seconds() <= window_seconds

    chosen = None
    quota_error = True
    for k in active_keys:
        minute_q = k.get("minute_request_quota")
        daily_q = k.get("daily_request_quota")
        if not isinstance(minute_q, int) or minute_q < 0:
            continue
        if not isinstance(daily_q, int) or daily_q < 0:
            continue
        kid = k.get("id")
        if not isinstance(kid, str) or not kid:
            continue

        # rolling counts
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != kid:
                continue
            ts_iso = r.get("created_at")
            if _within_window(ts_iso, 60):
                per_min += 1
            if _within_window(ts_iso, 86400):
                per_day += 1

        if per_min < minute_q and per_day < daily_q:
            chosen = k
            quota_error = False
            break

    if chosen is None:
        duration = (time.time() - start) * 1000
        _log(active_keys[0].get("id") if isinstance(active_keys[0].get("id"), str) else "unauth",
             params_obj, 429, "bypass", duration, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    # Enforce exchange allowlist / asset type allowlist not applicable here (no instrument); only exchange allowlist if present.
    if chosen.get("allowed_exchanges") is not None and exchange is not None:
        allowed = chosen.get("allowed_exchanges")
        if not isinstance(allowed, list) or exchange not in allowed:
            duration = (time.time() - start) * 1000
            _log(chosen["id"], params_obj, 403, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not authorized for this exchange")

    # Query snapshot from content_items
    items = _load("content_items.json")
    matches = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "sector_performance":
            continue
        if it.get("as_of_date") != date:
            continue
        if exchange is not None and it.get("exchange") != exchange:
            continue
        if sector is not None and it.get("sector") != sector:
            continue
        matches.append(it)

    if not matches:
        duration = (time.time() - start) * 1000
        _log(chosen["id"], params_obj, 404, "miss", duration, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No sector performance snapshot found for the requested filters")

    # Sort deterministically by sector then exchange then id
    def _k(x):
        return (
            (x.get("sector") or ""),
            (x.get("exchange") or ""),
            x.get("id") or ""
        )
    matches.sort(key=_k)

    # Update last_used_at for successful authenticated request
    for k in keys:
        if isinstance(k, dict) and k.get("id") == chosen["id"]:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    duration = (time.time() - start) * 1000
    _log(chosen["id"], params_obj, 200, "miss", duration, result_count=len(matches), error_code=None)

    # Return payloads (FMP typically returns array of objects)
    return {
        "date": date,
        "exchange": exchange,
        "sector": sector,
        "data": [m.get("payload") for m in matches],
        "meta": {"total": len(matches)}
    }

