        try:
            ts = datetime.datetime.fromisoformat(ts_iso.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return False
        return (now_dt - ts).total_seconds() <= window_seconds

    chosen = None
    for k in active_keys:
        minute_q = k.get("minute_request_quota")
        daily_q = k.get("daily_request_quota")
        if not isinstance(minute_q, int) or minute_q < 0:
            continue
        if not isinstance(daily_q, int) or daily_q < 0:
            continue
        kid = k.get("id")
        if not isinstance(kid, str) or not kid:
            continue

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != kid:
                continue
            ts_iso = r.get("created_at")
            if _within_window(ts_iso, 60):
                per_min += 1
            if _within_window(ts_iso, 86400):
                per_day += 1

        if per_min < minute_q and per_day < daily_q:
            chosen = k
            break

    if chosen is None:
        duration = (time.time() - start) * 1000
        _log(active_keys[0].get("id") if isinstance(active_keys[0].get("id"), str) else "unauth",
             params_obj, 429, "bypass", duration, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    if chosen.get("allowed_exchanges") is not None and exchange is not None:
        allowed = chosen.get("allowed_exchanges")
        if not isinstance(allowed, list) or exchange not in allowed:
            duration = (time.time() - start) * 1000
            _log(chosen["id"], params_obj, 403, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not authorized for this exchange")

    items = _load("content_items.json")
    matches = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "industry_performance":
            continue
        if it.get("as_of_date") != date:
            continue
        if exchange is not None and it.get("exchange") != exchange:
            continue
        if industry is not None and it.get("industry") != industry:
            continue
        matches.append(it)

    if not matches:
        duration = (time.time() - start) * 1000
        _log(chosen["id"], params_obj, 404, "miss", duration, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No industry performance snapshot found for the requested filters")

    def _k(x):
        return (
            (x.get("industry") or ""),
            (x.get("exchange") or ""),
            x.get("id") or ""
        )
    matches.sort(key=_k)

    for k in keys:
        if isinstance(k, dict) and k.get("id") == chosen["id"]:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    duration = (time.time() - start) * 1000
    _log(chosen["id"], params_obj, 200, "miss", duration, result_count=len(matches), error_code=None)

    return {
        "date": date,
        "exchange": exchange,
        "industry": industry,
        "data": [m.get("payload") for m in matches],
        "meta": {"total": len(matches)}
    }

