                    "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
                    "duration_ms": duration_ms,
                    "result_count": None,
                    "error_code": "QUOTA_EXCEEDED",
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                }
                logs.append(log_row)
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Request quota exceeded.")
        # normal log write
        duration_ms = max(0, int((time.time() - _t0) * 1000))
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": "getHistoricalSectorPerformance",
            "params": params_for_log if isinstance(params_for_log, dict) else {},
            "http_status": int(http_status) if isinstance(http_status, int) else 500,
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": duration_ms,
            "result_count": result_count if (result_count is None or (isinstance(result_count, int) and result_count >= 0)) else None,
            "error_code": error_code,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        # update api key last_used_at only on successful authenticated request (2xx)
        if api_key_row and isinstance(http_status, int) and 200 <= http_status <= 299:
            keys = _load("api_keys.json")
            for k in keys:
                if k.get("id") == api_key_id:
                    k["last_used_at"] = _now_iso()
                    k["updated_at"] = _now_iso()
