    # ---- validate inputs ----
    params = {}
    # sector required and non-blank
    if not isinstance(sector, str) or not sector.strip():
        params = {"sector": sector, "from": from_, "to": to, "exchange": exchange}
        api_key = _pick_api_key()
        # log attempt even on validation error; if no api key available, treat as unauthorized
        if not api_key:
            _quota_check_and_log({"id": "unknown", "minute_request_quota": 0, "daily_request_quota": 0}, 401, "bypass",
                                 result_count=None, error_code="UNAUTHORIZED", params_for_log=params)
            return _err("UNAUTHORIZED", "Missing or invalid API key.")
        qerr = _quota_check_and_log(api_key, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR", params_for_log=params)
        if qerr:
            return qerr
        return _err("VALIDATION_ERROR", "sector is required and must be a non-empty string.", field="sector")

    if exchange is not None and not isinstance(exchange, str):
