            return _err("UNAUTHORIZED", "Missing or invalid API key.")
        qerr = _quota_check_and_log(api_key, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR", params_for_log=params)
        if qerr:
            return qerr
