        if qerr:
            return qerr
        return _err("VALIDATION_ERROR", "to must be a valid ISO date YYYY-MM-DD.", field="to")

    if isinstance(d_from, datetime.date) and isinstance(d_to, datetime.date) and d_from > d_to:
        params = {"sector": sector, "from": from_, "to": to, "exchange": exchange}
        api_key = _pick_api_key()
        if not api_key:
            _quota_check_and_log({"id": "unknown", "minute_request_quota": 0, "daily_request_quota": 0}, 401, "bypass",
                                 result_count=None, error_code="UNAUTHORIZED", params_for_log=params)
            return _err("UNAUTHORIZED", "Missing or invalid API key.")
        qerr = _quota_check_and_log(api_key, 400, "bypass", result_count=None, error_code="VALIDATION_ERROR", params_for_log=params)
        if qerr:
            return qerr
        return _err("VALIDATION_ERROR", "from must be on or before to.", field="from")

    # params must conform to schema (no additionalProperties) => only these keys
    params = {"sector": sector}
    if from_ is not None:
        params["from"] = from_
    if to is not None:
        params["to"] = to
    if exchange is not None:
        params["exchange"] = exchange

    # ---- authenticate & quota check ----
    api_key = _pick_api_key()
    if not api_key:
        _quota_check_and_log({"id": "unknown", "minute_request_quota": 0, "daily_request_quota": 0}, 401, "bypass",
                             result_count=None, error_code="UNAUTHORIZED", params_for_log=params)
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    if api_key.get("status") != "active":
        # still log attempt
        qerr = _quota_check_and_log(api_key, 403, "bypass", result_count=None, error_code="UNAUTHORIZED", params_for_log=params)
        if qerr:
            return qerr
        return _err("UNAUTHORIZED", "API key is not active.")

    qerr = _quota_check_and_log(api_key, 200, "miss", result_count=None, error_code=None, params_for_log=params)
    if qerr:
        return qerr
    # We already logged with 200 optimistically for quota accounting; if we later fail, we must correct by rewriting last log.
    # To avoid multiple logs, we will update the last log row in-place on failure/success.
    logs = _load("request_logs.json")
    last_log = logs[-1] if logs else None

    def _finalize(http_status, result_count=None, error_code=None):
        if last_log and last_log.get("id"):
            last_log["http_status"] = http_status
            last_log["result_count"] = result_count
            last_log["error_code"] = error_code
            last_log["duration_ms"] = max(0, int((time.time() - _t0) * 1000))
            last_log["updated_at"] = _now_iso()
            _save("request_logs.json", logs)
        # update last_used_at on success
        if 200 <= http_status <= 299:
            keys = _load("api_keys.json")
            for k in keys:
                if k.get("id") == api_key.get("id"):
                    k["last_used_at"] = _now_iso()
                    k["updated_at"] = _now_iso()
                    break
            _save("api_keys.json", keys)

    # ---- query ----
    items = _load("content_items.json")
    want_sector = _norm_text(sector)
    want_exchange = exchange.strip() if isinstance(exchange, str) and exchange.strip() else None

    matched = []
    sector_seen = False
    for it in items:
        if it.get("content_type") != "sector_performance":
            continue
        if it.get("status") != "active":
            continue
        sec = it.get("sector")
        if isinstance(sec, str) and _norm_text(sec) == want_sector:
            sector_seen = True
        else:
            continue

        if want_exchange:
            ex = it.get("exchange")
            if not (isinstance(ex, str) and ex.strip() == want_exchange):
                continue

        as_of = it.get("as_of_date")
        if not isinstance(as_of, str):
            continue
        try:
            as_of_d = datetime.datetime.strptime(as_of, "%Y-%m-%d").date()
        except ValueError:
            continue

        if isinstance(d_from, datetime.date) and as_of_d < d_from:
            continue
        if isinstance(d_to, datetime.date) and as_of_d > d_to:
            continue

        # Response row: use payload (provider-specific), but must be from store.
        row = it.get("payload")
        if isinstance(row, dict):
            if "date" not in row and isinstance(as_of, str):
                row = dict(row)
                row["date"] = as_of
        else:
            row = {"date": as_of}
        matched.append(row)

    if not sector_seen:
        _finalize(404, result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Unknown sector.")

    if not matched:
        _finalize(404, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No observations match the provided filters.")

    # sort by date asc when possible
    def _date_key(r):
        d = r.get("date")
        if isinstance(d, str):
            try:
                return datetime.datetime.strptime(d, "%Y-%m-%d").date()
            except ValueError:
                return datetime.date(1900, 1, 1)
        return datetime.date(1900, 1, 1)

    matched.sort(key=_date_key)

    _finalize(200, result_count=len(matched), error_code=None)
    return {"data": matched, "meta": {"count": len(matched), "sector": sector, "from": from_, "to": to, "exchange": exchange}}

