    if exchange is not None and not known_exchange:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(api_key.get("id"), tool_name, params, 404, "miss", duration_ms, result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Unknown exchange for this industry")

    out = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("content_type") != "industry_pe":
            continue
        if not (isinstance(it.get("industry"), str) and it.get("industry").strip().lower() == industry_norm):
            continue
        if exchange is not None and it.get("exchange") != exchange:
            continue
        as_of = it.get("as_of_date")
        if not isinstance(as_of, str):
            continue
        if d_from is not None and as_of < d_from:
            continue
        if d_to is not None and as_of > d_to:
            continue
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue
        row = dict(payload)
        if "date" not in row and isinstance(as_of, str):
            row["date"] = as_of
        if exchange is not None and "exchange" not in row:
            row["exchange"] = exchange
        if "industry" not in row:
            row["industry"] = industry_in
        out.append(row)

    def _key(r):
        v = r.get("date")
        return v if isinstance(v, str) else ""
    out.sort(key=_key)

    # Update last_used_at
    api_key_id = api_key.get("id")
    now_iso = _now_iso()
    updated = False
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            updated = True
            break
    if updated:
        _save("api_keys.json", keys)

    duration_ms = int((time.time() - _t0) * 1000)
    _log_request(api_key_id, tool_name, params, 200, "miss", duration_ms, result_count=len(out), error_code=None)
    return {"data": out, "meta": {"total": len(out)}}

