    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getBiggestGainers"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    def _iso_now_z(dt=None):
        dt = dt or datetime.datetime.now(datetime.timezone.utc)
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        seed = hashlib.sha1((str(time.time()) + "|" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{seed}"

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        now_iso = _iso_now_z(now_dt)
        duration_ms = int((time.time() - t0) * 1000)
        if duration_ms < 0:
            duration_ms = 0
        logs.append({
            "id": _new_id("fmp_req"),
            "api_key_id": api_key_id if isinstance(api_key_id, str) else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status) if isinstance(http_status, int) or (isinstance(http_status, float) and http_status.is_integer()) else 500,
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (int(result_count) if isinstance(result_count, int) and result_count >= 0 else None),
            "error_code": error_code if isinstance(error_code, str) else None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)

    def _select_active_key_for_request():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None, _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _count_for(kid):
            m = d = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                dt = _parse_dt_any(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= minute_ago:
                    m += 1
                if dt >= day_ago:
                    d += 1
            return m, d

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                continue
            if day_q and d + 1 > day_q:
                continue
            return k, None

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                return None, _err("RATE_LIMIT", "Request quota exceeded.", reason="quota_minute_exceeded", http_status=429)
            if day_q and d + 1 > day_q:
                return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", reason="quota_daily_exceeded", http_status=429)
        return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "`cursor` is malformed.", http_status=400)
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("o:"):
                return None, _err("VALIDATION_ERROR", "`cursor` is malformed.", http_status=400)
            off = int(s.split(":", 1)[1])
            if off < 0:
                raise ValueError("neg")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "`cursor` is malformed.", http_status=400)

    def _encode_cursor(off):
        b = f"o:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    params_obj = {"exchange": exchange, "limit": limit, "cursor": cursor}

    # validate limit/cursor
    if limit is None:
        lim = 100
    else:
        if not isinstance(limit, (int, float)) or (isinstance(limit, float) and not limit.is_integer()):
            key, _ = _select_active_key_for_request()
            kid = key["id"] if key else "unknown"
            err = _err("VALIDATION_ERROR", "`limit` must be a number.", http_status=400)
            _log(kid, params_obj, 400, error_code="validation_error")
            return err
        lim = int(limit)
    if lim <= 0 or lim > 1000:
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`limit` must be between 1 and 1000.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err

    off, cerr = _decode_cursor(cursor)
    if cerr:
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        _log(kid, params_obj, cerr["error"].get("http_status", 400), error_code="validation_error")
        return cerr

    # validate exchange if specified
    if exchange is not None:
        if not isinstance(exchange, str) or not exchange.strip():
            key, _ = _select_active_key_for_request()
            kid = key["id"] if key else "unknown"
            err = _err("VALIDATION_ERROR", "`exchange` must be a non-empty string.", http_status=400)
            _log(kid, params_obj, 400, error_code="validation_error")
            return err
        ex = exchange.strip()
    else:
        ex = None

    key, kerr = _select_active_key_for_request()
    if kerr:
        _log("unknown", params_obj, kerr["error"].get("http_status", 401), error_code=kerr["error"].get("reason") or kerr["error"]["code"].lower())
        return kerr
    kid = key["id"]

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")
    if not isinstance(instruments, list):
        instruments = []
    if not isinstance(mdp, list):
        mdp = []

    # Build latest regular 1day unadjusted snapshots by instrument_id
    latest = {}
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("is_latest_snapshot") is not True:
            continue
        if r.get("timeframe") != "1day" or r.get("session") != "regular" or r.get("adjustment_type") != "unadjusted":
            continue
        iid = r.get("instrument_id")
        if isinstance(iid, str):
            latest[iid] = r

    # filter candidate equities only (gainers/losers are stocks)
    candidates = []
    known_exchanges = set()
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        if ins.get("exchange"):
            known_exchanges.add(ins.get("exchange"))
        if ex is not None and ins.get("exchange") != ex:
            continue
        if ins.get("asset_type") != "equity":
            continue
        iid = ins.get("id")
        if not isinstance(iid, str):
            continue
        snap = latest.get(iid)
        if not snap:
            continue
        chg_pct = snap.get("change_percent")
        if not isinstance(chg_pct, (int, float)):
            continue
        candidates.append({
            "symbol": ins.get("symbol"),
            "name": ins.get("name"),
            "exchange": ins.get("exchange"),
            "price": snap.get("close"),
            "change": snap.get("change"),
            "changesPercentage": chg_pct,
            "timestamp": snap.get("ts"),
        })

    if ex is not None and ex not in known_exchanges:
        err = _err("NOT_FOUND", "Unknown exchange.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="exchange_not_found")
        return err

    candidates.sort(key=lambda x: (x.get("changesPercentage") if isinstance(x.get("changesPercentage"), (int, float)) else float("-inf")), reverse=True)

    page = candidates[off:off + lim]
    next_off = off + len(page)
    has_more = next_off < len(candidates)
    next_cursor = _encode_cursor(next_off) if has_more else None

    keys_all = _load("api_keys.json")
    if isinstance(keys_all, list):
        for k in keys_all:
            if isinstance(k, dict) and k.get("id") == kid:
                k["last_used_at"] = _iso_now_z(now_dt)
                k["updated_at"] = _iso_now_z(now_dt)
                _save("api_keys.json", keys_all)
                break

    _log(kid, params_obj, 200, result_count=len(page))
    return {"data": page, "meta": {"total": len(candidates), "has_more": has_more, "next_cursor": next_cursor}}

