    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((now_iso + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    # Validate required exchange
    if exchange is None or not isinstance(exchange, str) or not exchange.strip():
        api_keys = _load("api_keys.json")
        key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        key_id = key.get("id") if key else None
        logs = _load("request_logs.json")
        logs.append({
