            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "exchange is required and must be a non-empty string")

    exch = exchange.strip()

    # Authenticate ambient
    api_keys = _load("api_keys.json")
    active_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    key_id = active_key.get("id") if active_key else None

    params_for_log = {"exchange": exchange}
    logs = _load("request_logs.json")

    def _log_and_return(http_status, body, result_count=None, error_code=None):
        duration_ms = max(0, int((time.time() - t0) * 1000))
        logs.append({
            "id": _new_id("req"),
            "api_key_id": key_id if key_id else "unknown",
            "tool_name": "getExchangeMarketHours",
            "params": params_for_log,
            "http_status": int(http_status),
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": result_count,
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)
        return body

    if not active_key:
        return _log_and_return(401, _err("UNAUTHORIZED", "API key is missing, invalid, or inactive"), error_code="UNAUTHORIZED")

    # quota enforcement
    try:
        minute_quota = int(active_key.get("minute_request_quota", 0))
        daily_quota = int(active_key.get("daily_request_quota", 0))
    except Exception:
        minute_quota = 0
        daily_quota = 0

    one_min_ago = now - datetime.timedelta(minutes=1)
    one_day_ago = now - datetime.timedelta(days=1)

    def _parse_ts(z):
        if not isinstance(z, str):
            return None
        s = z[:-1] if z.endswith("Z") else z
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    reqs_for_key = [r for r in logs if isinstance(r, dict) and r.get("api_key_id") == key_id]
    in_min = 0
    in_day = 0
    for r in reqs_for_key:
        ts = _parse_ts(r.get("created_at"))
        if not ts:
            continue
        if ts >= one_min_ago:
            in_min += 1
        if ts >= one_day_ago:
            in_day += 1

    if minute_quota >= 0 and in_min >= minute_quota:
        return _log_and_return(429, _err("RATE_LIMIT", "Minute request quota exceeded"), error_code="RATE_LIMIT")
    if daily_quota >= 0 and in_day >= daily_quota:
        return _log_and_return(429, _err("QUOTA_EXCEEDED", "Daily request quota exceeded"), error_code="QUOTA_EXCEEDED")

    # Exchange allowlist enforcement
    if active_key.get("allowed_exchanges") is not None:
        if isinstance(active_key.get("allowed_exchanges"), list) and exch not in active_key.get("allowed_exchanges"):
            return _log_and_return(403, _err("UNAUTHORIZED", "API key not permitted for this exchange"), error_code="UNAUTHORIZED")

    # Serve from content_items where content_type='exchange_market_hours' and exchange matches
    items = _load("content_items.json")
    matches = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "exchange_market_hours":
            continue
        if it.get("exchange") != exch:
            continue
        matches.append(it)

    if not matches:
        # Unknown exchange: if no instruments exist for it AND no market hours content exists.
        instruments = _load("instruments.json")
        known = any(isinstance(i, dict) and i.get("exchange") == exch for i in instruments)
        if not known:
            return _log_and_return(404, _err("NOT_FOUND", "Unknown exchange"), error_code="NOT_FOUND")
        # Known exchange but no hours content -> treat as NOT_FOUND (no row to return)
        return _log_and_return(404, _err("NOT_FOUND", "Market hours not available for this exchange"), error_code="NOT_FOUND")

    # Choose most recently updated/created
    def _key_dt(it):
        z = it.get("updated_at") or it.get("created_at")
        ts = _parse_ts(z)
        return ts or datetime.datetime.min

    matches.sort(key=_key_dt, reverse=True)
    best = matches[0]
    payload = best.get("payload")
    if not isinstance(payload, dict):
        payload = {}

    # Update last_used_at
    active_key["last_used_at"] = now_iso
    active_key["updated_at"] = now_iso
    for idx, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_id:
            api_keys[idx] = active_key
            break
    _save("api_keys.json", api_keys)

    body = {
        "data": {
            "exchange": exch,
            "as_of_date": best.get("as_of_date"),
            "payload": payload
        }
    }
    return _log_and_return(200, body, result_count=1, error_code=None)

def getHolidaysByExchange(exchange, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "getHolidaysByExchange"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _is_iso_date(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.date.fromisoformat(s)
            return True
        except ValueError:
            return False

    def _auth_pick_key(api_keys):
        # Ambient authentication: pick any api_keys row that can serve (status='active')
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _quota_check(key_row, logs):
        # Rolling windows based on request_logs.created_at
        now = datetime.datetime.utcnow()
        minute_quota = key_row.get("minute_request_quota")
        daily_quota = key_row.get("daily_request_quota")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            minute_quota = 0
        if not isinstance(daily_quota, int) or daily_quota < 0:
            daily_quota = 0

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except ValueError:
                return None

        key_id = key_row.get("id")
        if not isinstance(key_id, str) or not key_id:
            return False, "UNAUTHORIZED", "Invalid API key context."

        minute_count = 0
        day_count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            delta = now - ts
            if delta.total_seconds() < 0:
                continue
            if delta.total_seconds() <= 60:
                minute_count += 1
            if delta.total_seconds() <= 86400:
                day_count += 1

        # Reject if this request would exceed quota
        if minute_quota == 0 or daily_quota == 0:
            # 0 means no requests allowed on this key
            return False, "QUOTA_EXCEEDED", "Request quota exceeded."
        if minute_count + 1 > minute_quota:
            return False, "RATE_LIMIT", "Rate limit exceeded."
        if day_count + 1 > daily_quota:
            return False, "QUOTA_EXCEEDED", "Daily request quota exceeded."
        return True, None, None

    def _log_request(logs, api_key_id, params_obj, http_status, duration_ms, result_count=None, error_code=None, cache_status="bypass"):
        now = _now_iso()
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate tool params (additionalProperties=false handled by signature + ignore _extra)
    params_obj = {}
    if not isinstance(exchange, str):
        params_obj = {"exchange": exchange, "from": from_, "to": to}
        api_keys = _load("api_keys.json")
        key = _auth_pick_key(api_keys)
        logs = _load("request_logs.json")
        api_key_id = key.get("id") if key else "unknown"
        dur = (time.time() - _t0) * 1000
        _log_request(logs, api_key_id, params_obj, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "exchange must be a string.")
    exchange_clean = exchange.strip()
    if not exchange_clean:
        params_obj = {"exchange": exchange, "from": from_, "to": to}
        api_keys = _load("api_keys.json")
        key = _auth_pick_key(api_keys)
        logs = _load("request_logs.json")
        api_key_id = key.get("id") if key else "unknown"
        dur = (time.time() - _t0) * 1000
        _log_request(logs, api_key_id, params_obj, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "exchange is required and cannot be blank.")

    if from_ is not None and not _is_iso_date(from_):
        params_obj = {"exchange": exchange_clean, "from": from_, "to": to}
        api_keys = _load("api_keys.json")
        key = _auth_pick_key(api_keys)
        logs = _load("request_logs.json")
        api_key_id = key.get("id") if key else "unknown"
        dur = (time.time() - _t0) * 1000
        _log_request(logs, api_key_id, params_obj, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be a valid ISO date YYYY-MM-DD.")
    if to is not None and not _is_iso_date(to):
        params_obj = {"exchange": exchange_clean, "from": from_, "to": to}
        api_keys = _load("api_keys.json")
        key = _auth_pick_key(api_keys)
        logs = _load("request_logs.json")
        api_key_id = key.get("id") if key else "unknown"
        dur = (time.time() - _t0) * 1000
        _log_request(logs, api_key_id, params_obj, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "to must be a valid ISO date YYYY-MM-DD.")
    if from_ is not None and to is not None:
        if datetime.date.fromisoformat(from_) > datetime.date.fromisoformat(to):
            params_obj = {"exchange": exchange_clean, "from": from_, "to": to}
            api_keys = _load("api_keys.json")
            key = _auth_pick_key(api_keys)
            logs = _load("request_logs.json")
            api_key_id = key.get("id") if key else "unknown"
            dur = (time.time() - _t0) * 1000
            _log_request(logs, api_key_id, params_obj, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "from must be on or before to.")

    params_obj = {"exchange": exchange_clean}
    if from_ is not None:
        params_obj["from"] = from_
    if to is not None:
        params_obj["to"] = to

    # Auth + quota
    api_keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    key = _auth_pick_key(api_keys)
    if not key:
        dur = (time.time() - _t0) * 1000
        _log_request(logs, "unknown", params_obj, 401, dur, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is missing, invalid, or inactive.")
    ok, ecode, emsg = _quota_check(key, logs)
    if not ok:
        http_status = 429 if ecode in ("RATE_LIMIT", "QUOTA_EXCEEDED") else 403
        dur = (time.time() - _t0) * 1000
        _log_request(logs, key["id"], params_obj, http_status, dur, result_count=None, error_code=ecode)
        return _err(ecode, emsg)

    # Resolve exchange existence via content_items of type exchange_holiday/market hours
    items = _load("content_items.json")
    ex_up = exchange_clean.upper()
    known_exchanges = set()
    for it in items:
        if not isinstance(it, dict):
            continue
        ex = it.get("exchange")
        if isinstance(ex, str) and ex.strip():
            known_exchanges.add(ex.strip().upper())

    if ex_up not in known_exchanges:
        dur = (time.time() - _t0) * 1000
        _log_request(logs, key["id"], params_obj, 404, dur, result_count=None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Unknown exchange code.", exchange=exchange_clean)

    # Return exchange_holiday rows for the exchange
    out = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") == "deleted":
            continue
        if it.get("content_type") != "exchange_holiday":
            continue
        ex = it.get("exchange")
        if not (isinstance(ex, str) and ex.strip().upper() == ex_up):
            continue
        as_of = it.get("as_of_date")
        if from_ is not None and isinstance(as_of, str) and _is_iso_date(as_of):
            if as_of < from_:
                continue
        if to is not None and isinstance(as_of, str) and _is_iso_date(as_of):
            if as_of > to:
                continue
        # FMP-like payload return; include indexed fields commonly returned
        payload = it.get("payload")
        if not isinstance(payload, dict):
            payload = {}
        row = dict(payload)
        # Ensure exchange/date present if absent in payload
        row.setdefault("exchange", exchange_clean)
        if isinstance(as_of, str):
            row.setdefault("date", as_of)
        row.setdefault("isClosed", True)
        out.append(row)

    # Sort by date ascending if present
    def _date_key(r):
        d = r.get("date")
        return d if isinstance(d, str) else ""
    out.sort(key=_date_key)

    # Update last_used_at on success
    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    dur = (time.time() - _t0) * 1000
    _log_request(logs, key["id"], params_obj, 200, dur, result_count=len(out), error_code=None, cache_status="bypass")
    return {"exchange": exchange_clean, "from": from_, "to": to, "data": out}

def getAllExchangeMarketHours(exchange=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getAllExchangeMarketHours"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_req_id():
        seed = hashlib.sha1(os.urandom(16)).hexdigest()[:22]
        return "fmp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + seed

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rolling_counts(api_key_id):
        logs = _load("request_logs.json")
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                d += 1
                if dt >= minute_ago:
                    m += 1
        return m, d

    def _find_active_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        best = None
        best_score = None
        for k in active:
            if not isinstance(k.get("id"), str):
                continue
            m, d = _rolling_counts(k["id"])
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or not isinstance(day_q, int):
                continue
            score = (min_q - m, day_q - d)
            if best is None or score > best_score:
                best, best_score = k, score
        return best

    def _enforce_quota(key_row):
        m, d = _rolling_counts(key_row["id"])
        if m >= int(key_row.get("minute_request_quota", 0)):
            return False, "RATE_LIMIT", "Request quota exceeded.", "quota_minute_exceeded", 429
        if d >= int(key_row.get("daily_request_quota", 0)):
            return False, "QUOTA_EXCEEDED", "Daily request quota exceeded.", "quota_daily_exceeded", 429
        return True, None, None, None, 200

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_req_id(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    # validate
    if exchange is not None and (not isinstance(exchange, str) or not exchange.strip()):
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"exchange": exchange, "limit": limit, "cursor": cursor}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`exchange` must be a non-empty string when provided.")

    if limit is None:
        limit_i = 100
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)):
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"exchange": exchange, "limit": limit, "cursor": cursor}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be a number.")
        if isinstance(limit, float) and not limit.is_integer():
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"exchange": exchange, "limit": limit, "cursor": cursor}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be an integer.")
        limit_i = int(limit)
        if limit_i <= 0:
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"exchange": exchange, "limit": limit, "cursor": cursor}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be positive.")
        if limit_i > 1000:
            limit_i = 1000

    if cursor is not None and not isinstance(cursor, str):
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"exchange": exchange, "limit": limit_i, "cursor": cursor}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`cursor` must be a string.")

    params_obj = {"exchange": exchange, "limit": limit_i, "cursor": cursor}

    # auth + quota
    key = _find_active_key()
    if key is None:
        _log("unknown", params_obj, 401, error_code="unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

    ok, ecode, emsg, reason, http_status = _enforce_quota(key)
    if not ok:
        _log(key["id"], params_obj, http_status, error_code=reason)
        return _err(ecode, emsg, reason=reason, http_status=http_status)

    # cursor decode (accept any string; invalid means exhausted)
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("mh:"):
                start = int(s.split(":", 1)[1])
            else:
                start = int(s)
            if start < 0:
                start = 0
        except Exception:
            start = 10**18

    # data source: content_items with content_type='exchange_market_hours'
    content = _load("content_items.json")
    rows = []
    for r in content:
        if not isinstance(r, dict) or r.get("status") != "active":
            continue
        if r.get("content_type") != "exchange_market_hours":
            continue
        ex = r.get("exchange")
        if exchange is not None and ex != exchange.strip():
            continue
        payload = r.get("payload")
        if isinstance(payload, dict):
            row = dict(payload)
        else:
            row = {}
        # ensure exchange code is present
        if "exchange" not in row and isinstance(ex, str):
            row["exchange"] = ex
        # filtering needs to know exchange even if payload is minimal
        rows.append(row)

    # if exchange filter provided but unknown: NOT_FOUND
    if exchange is not None:
        # unknown if no matching exchange in instruments/content_items
        exch_known = False
        instruments = _load("instruments.json")
        ex_filter = exchange.strip()
        for r in instruments:
            if isinstance(r, dict) and r.get("exchange") == ex_filter:
                exch_known = True
                break
        if not exch_known:
            for r in content:
                if isinstance(r, dict) and r.get("exchange") == ex_filter:
                    exch_known = True
                    break
        if not exch_known:
            _log(key["id"], params_obj, 404, error_code="exchange_not_found")
            return _err("NOT_FOUND", "Unknown exchange code.", reason="exchange_not_found", http_status=404)

    # stable sort by exchange
    rows.sort(key=lambda r: (r.get("exchange") or ""))

    total = len(rows)
    page_items = rows[start:start + limit_i]
    next_cursor = None
    if start + limit_i < total:
        token = f"mh:{start + limit_i}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    # update last_used_at
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    _log(key["id"], params_obj, 200, result_count=len(page_items))
    return {
        "data": page_items,
        "meta": {
            "total": total,
            "limit": limit_i,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": bool(next_cursor),
        }
    }

