        _save("request_logs.json", logs)

    # Defaults & validation
    if page is None:
        p = 0
    else:
        if not isinstance(page, (int, float)) or isinstance(page, bool):
            api_keys = _load("api_keys.json")
            active = next((k for k in api_keys if k.get("status") == "active"), None)
            api_key_id = active["id"] if active else "unknown"
            _log(api_key_id, {"page": page, "limit": limit}, 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page must be a number")
        p = int(page)
    if p < 0:
        api_keys = _load("api_keys.json")
        active = next((k for k in api_keys if k.get("status") == "active"), None)
        api_key_id = active["id"] if active else "unknown"
        _log(api_key_id, {"page": page, "limit": limit}, 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be >= 0")

    if limit is None:
        lim = 20
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            api_keys = _load("api_keys.json")
            active = next((k for k in api_keys if k.get("status") == "active"), None)
            api_key_id = active["id"] if active else "unknown"
            _log(api_key_id, {"page": page, "limit": limit}, 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a number")
        lim = int(limit)
    if lim <= 0:
        api_keys = _load("api_keys.json")
        active = next((k for k in api_keys if k.get("status") == "active"), None)
        api_key_id = active["id"] if active else "unknown"
        _log(api_key_id, {"page": page, "limit": limit}, 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be positive")
    if lim > 1000:
        api_keys = _load("api_keys.json")
        active = next((k for k in api_keys if k.get("status") == "active"), None)
        api_key_id = active["id"] if active else "unknown"
        _log(api_key_id, {"page": page, "limit": limit}, 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must not exceed 1000")

    params = {"page": p, "limit": lim}

    # Authenticate + quota
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if k.get("status") == "active"]
    if not active_keys:
        any_key = api_keys[0]["id"] if api_keys else "unknown"
        _log(any_key, params, 401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is missing, invalid, or inactive")

    logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow()
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _parse_ts(z):
        if not isinstance(z, str):
            return None
        try:
            if z.endswith("Z"):
                z = z[:-1]
            return datetime.datetime.fromisoformat(z)
        except ValueError:
            return None

    chosen = None
    for k in active_keys:
        kid = k.get("id")
        min_q = int(k.get("minute_request_quota", 0) or 0)
        day_q = int(k.get("daily_request_quota", 0) or 0)
        min_used = 0
        day_used = 0
        for r in logs:
            if r.get("api_key_id") != kid:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= minute_ago:
                min_used += 1
            if ts >= day_ago:
                day_used += 1
        if (min_used + 1 > min_q) or (day_used + 1 > day_q):
            continue
        chosen = k
        break

    if chosen is None:
        kid = active_keys[0]["id"]
        _log(kid, params, 429, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    # Read articles from content_items
    content = _load("content_items.json")
    items = [it for it in content if it.get("content_type") == "fmp_article" and it.get("status") == "active"]

    # Sort newest first using as_of_date then created_at
    def _key(it):
        return (
            (it.get("as_of_date") or ""),
            (it.get("created_at") or ""),
            (it.get("id") or "")
        )
    items.sort(key=_key, reverse=True)

    total = len(items)
    start = p * lim
    end = start + lim
    page_items = items[start:end]

    data = []
    for it in page_items:
        payload = it.get("payload")
        if isinstance(payload, dict):
            data.append(payload)
        else:
            data.append({"id": it.get("id"), "title": it.get("title"), "url": it.get("url"), "date": it.get("as_of_date")})

    has_more = end < total

    _log(chosen["id"], params, 200, result_count=len(data), error_code=None)

    for k in api_keys:
        if k.get("id") == chosen.get("id"):
            k["last_used_at"] = _now
            k["updated_at"] = _now
            break
    _save("api_keys.json", api_keys)

    return {
        "data": data,
        "page": p,
        "limit": lim,
        "total": total,
        "has_more": has_more,
    }

def getGeneralNews(from_=None, to=None, page=None, limit=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
