            return _err("VALIDATION_ERROR", "page must be a number.")
        if int(page) != page:
            params_obj = {"from": from_, "to": to, "page": page, "limit": limit}
            api_keys = _load("api_keys.json")
            key = _auth_pick_key(api_keys)
            logs = _load("request_logs.json")
            api_key_id = key.get("id") if key else "unknown"
            dur = (time.time() - _t0) * 1000
            _log_request(logs, api_key_id, params_obj, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page must be an integer (zero-based).")
        page_i = int(page)
    if page_i < 0:
