        p = it.get("payload") if isinstance(it.get("payload"), dict) else {}
        cand = p.get("publishedDate") or p.get("published_date") or p.get("publishedAt") or p.get("date") or p.get("datetime")
        for s in (cand, it.get("as_of_date"), it.get("created_at")):
