        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id if api_key_id is not None else "unauthorized",
            "tool_name": "searchPressReleases",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)

    # Validate params schema (additionalProperties=false already via signature; also validate types/ranges)
    params_obj = {"symbols": symbols}
    if from_ is not None:
        params_obj["from"] = from_
    if to is not None:
        params_obj["to"] = to
    if page is not None:
        params_obj["page"] = page
    if limit is not None:
        params_obj["limit"] = limit

    # Authentication: pick any active API key that can serve this request
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        dur = int((time.time() - _t0) * 1000)
        _log(None, params_obj, 401, "bypass", dur, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")
    # Choose a key that is not already over quota (based on logs)
    def _eligible_key():
        for k in active_keys:
            kid = k.get("id")
            if not kid:
                continue
            minute_q = k.get("minute_request_quota")
            daily_q = k.get("daily_request_quota")
            if not isinstance(minute_q, int) or minute_q < 0:
                continue
            if not isinstance(daily_q, int) or daily_q < 0:
                continue
            # rolling windows from request_logs
            one_min_ago = now - datetime.timedelta(minutes=1)
            one_day_ago = now - datetime.timedelta(days=1)
            mcnt = 0
            dcnt = 0
            for r in request_logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                # parse like 2026-01-01T00:00:00Z or without Z
                tsv = ts[:-1] if ts.endswith("Z") else ts
                try:
                    rdt = datetime.datetime.fromisoformat(tsv)
                except Exception:
                    continue
                if rdt >= one_min_ago:
                    mcnt += 1
                if rdt >= one_day_ago:
                    dcnt += 1
            if mcnt + 1 > minute_q:
                continue
            if dcnt + 1 > daily_q:
                continue
            return k, mcnt, dcnt
        return None, None, None

    api_key, _, _ = _eligible_key()
    if api_key is None:
        # Still need to log with 429
        dur = int((time.time() - _t0) * 1000)
        # attribute to first active key for logging consistency
        _log(active_keys[0].get("id"), params_obj, 429, "bypass", dur, result_count=None, error_code="QUOTA_EXCEEDED")
