        return _err("VALIDATION_ERROR", "symbols is required and must be a non-empty string.")

    # Parse and normalize symbols, enforce max list length (server policy)
    raw_syms = [s.strip() for s in symbols.split(",")]
    norm_syms = []
    seen = set()
    for s in raw_syms:
        if not s:
            continue
        ns = s.upper()
        if ns not in seen:
            seen.add(ns)
            norm_syms.append(ns)
    MAX_SYMBOLS = 50
    if len(norm_syms) == 0:
        dur = int((time.time() - _t0) * 1000)
