    to_s = to_d.isoformat() if isinstance(to_d, datetime.date) else None

    for it in content:
        if not isinstance(it, dict):
            continue
        if it.get("content_type") != "news_article":
            continue
        if it.get("status") != "active":
            continue
        iid = it.get("instrument_id")
        if iid is None or iid not in sym_to_instrument_ids:
            continue
        d = it.get("as_of_date")
        if from_s is not None:
            if not isinstance(d, str) or d < from_s:
                continue
        if to_s is not None:
            if not isinstance(d, str) or d > to_s:
                continue
        items.append(it)

    # Sort newest first by as_of_date then created_at
    def _sort_key(it):
        return (
            it.get("as_of_date") if isinstance(it.get("as_of_date"), str) else "",
            it.get("created_at") if isinstance(it.get("created_at"), str) else "",
            it.get("id") if isinstance(it.get("id"), str) else "",
        )

    items.sort(key=_sort_key, reverse=True)

    total = len(items)
    offset = page_v * limit_v
    page_items = items[offset: offset + limit_v]

    # Prepare response rows similar to FMP: return payload flattened plus some top-level fields.
    # But do not fabricate: derive from stored rows.
    out = []
    for it in page_items:
        row = dict(it.get("payload") if isinstance(it.get("payload"), dict) else {})
        # include canonical fields if missing
        if "title" not in row and it.get("title") is not None:
            row["title"] = it.get("title")
        if "url" not in row and it.get("url") is not None:
            row["url"] = it.get("url")
        # include symbol if resolvable
        sym = None
        iid = it.get("instrument_id")
        if iid:
            for inst in instruments:
                if isinstance(inst, dict) and inst.get("id") == iid:
                    sym = inst.get("symbol")
                    break
        if sym is not None and "symbol" not in row:
            row["symbol"] = sym
        if it.get("as_of_date") is not None and "date" not in row:
            row["date"] = it.get("as_of_date")
        out.append(row)

    has_more = (offset + limit_v) < total
    next_cursor = None
    if has_more:
        next_cursor = str(page_v + 1)

    # Update key last_used_at on successful authenticated request
    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    duration_ms = max(0, int((time.time() - start) * 1000))
    log_row = {
        "id": _gen_id("rlog"),
        "api_key_id": key_id,
        "tool_name": "searchCryptoNews",
        "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(out),
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    logs.append(log_row)
    _save("request_logs.json", logs)

    return {
        "data": out,
        "meta": {
            "page": page_v,
            "limit": limit_v,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

