        if s is None:
            return None
        if not isinstance(s, str):
            return ("__invalid__", _err("VALIDATION_ERROR", f"{field_name} must be a string in YYYY-MM-DD"))
        try:
            d = datetime.date.fromisoformat(s)
            return d
        except Exception:
            return ("__invalid__", _err("VALIDATION_ERROR", f"{field_name} must be a valid ISO date (YYYY-MM-DD)"))

    def _coerce_int_nonneg(x, field_name, default):
        if x is None:
            return default
        if isinstance(x, bool):
            return ("__invalid__", _err("VALIDATION_ERROR", f"{field_name} must be a number"))
        if isinstance(x, (int, float)):
            if isinstance(x, float) and not x.is_integer():
                return ("__invalid__", _err("VALIDATION_ERROR", f"{field_name} must be an integer"))
            xi = int(x)
            if xi < 0:
                return ("__invalid__", _err("VALIDATION_ERROR", f"{field_name} must be >= 0"))
            return xi
        return ("__invalid__", _err("VALIDATION_ERROR", f"{field_name} must be a number"))

