            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return from_d[1]

    to_d = _parse_iso_date(to, "to")
    if isinstance(to_d, tuple) and to_d[0] == "__invalid__":
        duration_ms = max(0, int((time.time() - start) * 1000))
        key_for_log = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                key_for_log = k
                break
        log_row = {
            "id": _gen_id("rlog"),
            "api_key_id": (key_for_log.get("id") if key_for_log else "unknown"),
            "tool_name": "searchForexNews",
            "params": {"symbols": symbols, "from": from_, "to": to, "page": page, "limit": limit},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return to_d[1]

    if isinstance(from_d, datetime.date) and isinstance(to_d, datetime.date) and from_d > to_d:
        duration_ms = max(0, int((time.time() - start) * 1000))
        key_for_log = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                key_for_log = k
                break
        log_row = {
            "id": _gen_id("rlog"),
            "api_key_id": (key_for_log.get("id") if key_for_log else "unknown"),
            "tool_name": "searchForexNews",
            "params": {"symbols": symbols, "from": from_, "to": to, "page": page, "limit": limit},
