            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "from must be <= to")

    # Authenticate (ambient): pick active key.
    active_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if isinstance(k.get("daily_request_quota"), int) and isinstance(k.get("minute_request_quota"), int):
            active_key = k
            break

    if not active_key:
        duration_ms = max(0, int((time.time() - start) * 1000))
        log_row = {
            "id": _gen_id("rlog"),
            "api_key_id": "unknown",
            "tool_name": "searchForexNews",
            "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
            "http_status": 401,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "UNAUTHORIZED",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key is missing, invalid, or not active")

    # Quotas
    now = datetime.datetime.utcnow()
    minute_ago = now - datetime.timedelta(minutes=1)
    day_ago = now - datetime.timedelta(days=1)
    inflight_cutoff = now - datetime.timedelta(seconds=30)

    def _parse_iso_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    key_id = active_key.get("id")
    minute_count = 0
    day_count = 0
    inflight_count = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_id:
            continue
        dt = _parse_iso_dt(r.get("created_at"))
        if not dt:
            continue
        if dt >= minute_ago:
            minute_count += 1
        if dt >= day_ago:
            day_count += 1
        if dt >= inflight_cutoff:
            inflight_count += 1

    if isinstance(active_key.get("concurrency_limit"), int) and active_key["concurrency_limit"] >= 0:
        if inflight_count >= active_key["concurrency_limit"] and active_key["concurrency_limit"] != 0:
            duration_ms = max(0, int((time.time() - start) * 1000))
            log_row = {
                "id": _gen_id("rlog"),
                "api_key_id": key_id,
                "tool_name": "searchForexNews",
                "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
                "http_status": 429,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "RATE_LIMIT",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            logs.append(log_row)
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Concurrency limit exceeded")

    if minute_count >= int(active_key.get("minute_request_quota", 0)):
        duration_ms = max(0, int((time.time() - start) * 1000))
        log_row = {
            "id": _gen_id("rlog"),
            "api_key_id": key_id,
            "tool_name": "searchForexNews",
            "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
