            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Minute request quota exceeded")

    if day_count >= int(active_key.get("daily_request_quota", 0)):
        duration_ms = max(0, int((time.time() - start) * 1000))
        log_row = {
            "id": _gen_id("rlog"),
            "api_key_id": key_id,
            "tool_name": "searchForexNews",
            "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
