            "result_count": None,
            "error_code": "QUOTA_EXCEEDED",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Normalize symbols, server max list length.
    raw_syms = [s.strip() for s in symbols.split(",")]
    norm_syms = []
    seen = set()
    for s in raw_syms:
        if not s:
            continue
        ns = s.upper()
        if ns not in seen:
            seen.add(ns)
            norm_syms.append(ns)

    if not norm_syms:
        duration_ms = max(0, int((time.time() - start) * 1000))
        log_row = {
            "id": _gen_id("rlog"),
            "api_key_id": key_id,
            "tool_name": "searchForexNews",
            "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "symbols must contain at least one symbol")

    MAX_SYMBOLS = 50
    if len(norm_syms) > MAX_SYMBOLS:
        duration_ms = max(0, int((time.time() - start) * 1000))
        log_row = {
            "id": _gen_id("rlog"),
            "api_key_id": key_id,
            "tool_name": "searchForexNews",
            "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
            "http_status": 400,
            "cache_status": "bypass",
            "duration_ms": duration_ms,
            "result_count": None,
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", f"symbols list too long (max {MAX_SYMBOLS})")

    # Entitlements: allowed_asset_types must allow forex when present.
    allowed_asset_types = active_key.get("allowed_asset_types")
    if allowed_asset_types is not None:
        ok = isinstance(allowed_asset_types, list) and ("forex" in allowed_asset_types)
        if not ok:
            duration_ms = max(0, int((time.time() - start) * 1000))
            log_row = {
                "id": _gen_id("rlog"),
                "api_key_id": key_id,
                "tool_name": "searchForexNews",
                "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
                "http_status": 403,
                "cache_status": "bypass",
                "duration_ms": duration_ms,
                "result_count": None,
                "error_code": "UNAUTHORIZED",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            logs.append(log_row)
            _save("request_logs.json", logs)
            return _err("UNAUTHORIZED", "API key not entitled for forex data")

    instruments = _load("instruments.json")
    content = _load("content_items.json")

    sym_to_instrument_ids = set()
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("asset_type") != "forex":
            continue
        if inst.get("normalized_symbol") in norm_syms:
            sym_to_instrument_ids.add(inst.get("id"))

    from_s = from_d.isoformat() if isinstance(from_d, datetime.date) else None
    to_s = to_d.isoformat() if isinstance(to_d, datetime.date) else None

    items = []
    for it in content:
        if not isinstance(it, dict):
            continue
        if it.get("content_type") != "news_article":
            continue
        if it.get("status") != "active":
            continue
        iid = it.get("instrument_id")
        if iid is None or iid not in sym_to_instrument_ids:
            continue
        d = it.get("as_of_date")
        if from_s is not None:
            if not isinstance(d, str) or d < from_s:
                continue
        if to_s is not None:
            if not isinstance(d, str) or d > to_s:
                continue
        items.append(it)

    def _sort_key(it):
        return (
            it.get("as_of_date") if isinstance(it.get("as_of_date"), str) else "",
            it.get("created_at") if isinstance(it.get("created_at"), str) else "",
            it.get("id") if isinstance(it.get("id"), str) else "",
        )

    items.sort(key=_sort_key, reverse=True)

    total = len(items)
    offset = page_v * limit_v
    page_items = items[offset: offset + limit_v]

    out = []
    for it in page_items:
        row = dict(it.get("payload") if isinstance(it.get("payload"), dict) else {})
        if "title" not in row and it.get("title") is not None:
            row["title"] = it.get("title")
        if "url" not in row and it.get("url") is not None:
            row["url"] = it.get("url")
        sym = None
        iid = it.get("instrument_id")
        if iid:
            for inst in instruments:
                if isinstance(inst, dict) and inst.get("id") == iid:
                    sym = inst.get("symbol")
                    break
        if sym is not None and "symbol" not in row:
            row["symbol"] = sym
        if it.get("as_of_date") is not None and "date" not in row:
            row["date"] = it.get("as_of_date")
        out.append(row)

    has_more = (offset + limit_v) < total
    next_cursor = str(page_v + 1) if has_more else None

    # Update key usage
    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    duration_ms = max(0, int((time.time() - start) * 1000))
    log_row = {
        "id": _gen_id("rlog"),
        "api_key_id": key_id,
        "tool_name": "searchForexNews",
        "params": {"symbols": symbols, "from": from_, "to": to, "page": page_v, "limit": limit_v},
        "http_status": 200,
        "cache_status": "miss",
        "duration_ms": duration_ms,
        "result_count": len(out),
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    logs.append(log_row)
    _save("request_logs.json", logs)

    return {
        "data": out,
        "meta": {
            "page": page_v,
            "limit": limit_v,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def getSMA(symbol, periodLength, timeframe, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # --- validate inputs (JSON schema: additionalProperties=false is satisfied by signature) ---
    if not isinstance(symbol, str) or not symbol.strip():
        # log attempt (auth may still be tried)
        symbol_norm = None
        validation_error = _err("VALIDATION_ERROR", "symbol must be a non-empty string")
        # proceed to auth+log below via common path
        pass
    else:
        symbol_norm = symbol.strip().upper()

    if isinstance(periodLength, bool) or not isinstance(periodLength, (int, float)):
        validation_error = _err("VALIDATION_ERROR", "periodLength must be a positive integer")
    else:
        try:
            pl_int = int(periodLength)
        except Exception:
            pl_int = None
        if pl_int is None or float(periodLength) != float(pl_int) or pl_int <= 0:
            validation_error = _err("VALIDATION_ERROR", "periodLength must be a positive integer")
        else:
            validation_error = None

    allowed_timeframes = {"1min", "5min", "15min", "30min", "1hour", "4hour", "1day"}
    if not isinstance(timeframe, str) or timeframe not in allowed_timeframes:
        validation_error = _err("VALIDATION_ERROR", "timeframe must be one of (1min, 5min, 15min, 30min, 1hour, 4hour, 1day)")
    tf = timeframe if isinstance(timeframe, str) else None

    def _parse_date(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date string YYYY-MM-DD")
        try:
            return datetime.date.fromisoformat(s), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date string YYYY-MM-DD")

    from_d, from_err = _parse_date(from_, "from")
    to_d, to_err = _parse_date(to, "to")
    if from_err:
        validation_error = from_err
    if to_err:
        validation_error = to_err
    if from_d and to_d and from_d > to_d:
        validation_error = _err("VALIDATION_ERROR", "from must be <= to")

    # --- ambient authentication + quotas computed from request_logs ---
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _resolve_active_key():
        # No explicit credential parameter; pick any active key that can serve request under quota.
        # Evaluate candidates in deterministic order (created_at then id).
        candidates = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        def _key_sort(k):
            return (k.get("created_at") or "", k.get("id") or "")
        candidates.sort(key=_key_sort)

        # compute rolling windows based on logs
        now_dt = now
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        # Pre-index logs per key for speed
        # Parse created_at as datetime when possible; ignore unparsable rows for quota counting
        per_key_counts = {}
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            kid = r.get("api_key_id")
            if not isinstance(kid, str):
                continue
            ts_s = r.get("created_at")
            if not isinstance(ts_s, str):
                continue
            try:
                ts = datetime.datetime.fromisoformat(ts_s.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            d = per_key_counts.setdefault(kid, {"minute": 0, "day": 0, "inflight": 0})
            if ts >= minute_ago:
                d["minute"] += 1
            if ts >= day_ago:
                d["day"] += 1

        for k in candidates:
            kid = k.get("id")
            if not isinstance(kid, str):
                continue
            mq = k.get("minute_request_quota")
            dq = k.get("daily_request_quota")
            cl = k.get("concurrency_limit")
            if not isinstance(mq, int) or mq < 0:
                continue
            if not isinstance(dq, int) or dq < 0:
                continue
            if not isinstance(cl, int) or cl < 0:
                continue

            counts = per_key_counts.get(kid, {"minute": 0, "day": 0, "inflight": 0})
            # concurrency: approximate using "inflight" not tracked; enforce as 0<=limit means ok.
            # To keep observable dynamics without extra state, treat concurrency as not exceeded.
            if mq >= 0 and counts["minute"] >= mq:
                continue
            if dq >= 0 and counts["day"] >= dq:
                continue
            return k, counts
        return None, None

    api_key_row, counts = _resolve_active_key()

    # Determine failure precedence: auth/quota are checked even if validation fails? real APIs typically validate after auth.
    # Business rule: must authenticate with active key; otherwise auth error and log attempt with 401/403.
    # We'll attempt auth first; if no key then UNAUTHORIZED regardless of validation.
    http_status = 200
    cache_status = "bypass"
    error_obj = None

    if api_key_row is None:
        http_status = 401
        error_obj = _err("UNAUTHORIZED", "No active API key available for this request")
    else:
        # quota already enforced in resolver; but if none found due to quota, distinguish 429
        any_active = any(isinstance(k, dict) and k.get("status") == "active" for k in api_keys)
        if any_active and api_key_row is None:
            http_status = 429
            error_obj = _err("QUOTA_EXCEEDED", "Request quota exceeded")
        elif validation_error is not None:
            http_status = 400
            error_obj = validation_error

    # If resolver failed but active keys exist, it was quota. Re-check explicitly for correct code.
    if api_key_row is None:
        any_active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if any_active:
            # compute whether quota is the reason
            # If all active keys are over either minute or day quota, return 429
            now_dt = now
            minute_ago = now_dt - datetime.timedelta(seconds=60)
            day_ago = now_dt - datetime.timedelta(days=1)

            per_key_counts = {}
            for r in request_logs:
                if not isinstance(r, dict):
                    continue
                kid = r.get("api_key_id")
                if not isinstance(kid, str):
                    continue
                ts_s = r.get("created_at")
                if not isinstance(ts_s, str):
                    continue
                try:
                    ts = datetime.datetime.fromisoformat(ts_s.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                d = per_key_counts.setdefault(kid, {"minute": 0, "day": 0})
                if ts >= minute_ago:
                    d["minute"] += 1
                if ts >= day_ago:
                    d["day"] += 1
            all_over = True
            for k in any_active:
                kid = k.get("id")
                if not isinstance(kid, str):
                    continue
                mq = k.get("minute_request_quota")
                dq = k.get("daily_request_quota")
                if not isinstance(mq, int) or not isinstance(dq, int):
                    continue
                c = per_key_counts.get(kid, {"minute": 0, "day": 0})
                if c["minute"] < mq and c["day"] < dq:
                    all_over = False
                    break
            if all_over:
                http_status = 429
                error_obj = _err("QUOTA_EXCEEDED", "Request quota exceeded")
            else:
                http_status = 401
                error_obj = _err("UNAUTHORIZED", "No active API key available for this request")

    # --- compute response if authorized and valid ---
    result = None
    result_count = None

    try:
        if error_obj is None:
            instruments = _load("instruments.json")
            mdps = _load("market_data_points.json")

            # resolve instrument by normalized_symbol uniqueness semantics
            matched = [ins for ins in instruments if isinstance(ins, dict) and ins.get("normalized_symbol") == symbol_norm]
            # If multiple across exchanges, pick active first, then earliest created_at.
            def _ins_sort(ins):
                status = ins.get("status")
                rank = 0 if status == "active" else (1 if status == "inactive" else 2)
                return (rank, ins.get("exchange") or "", ins.get("created_at") or "", ins.get("id") or "")
            matched.sort(key=_ins_sort)
            if not matched:
                # reads with filters matching nothing => empty set
                series = []
            else:
                ins = matched[0]
                # entitlement checks: exchange/asset_type allowlists
                allowed_ex = api_key_row.get("allowed_exchanges")
                allowed_at = api_key_row.get("allowed_asset_types")
                if allowed_ex is not None:
                    if not isinstance(allowed_ex, list):
                        http_status = 500
                        error_obj = _err("CONFLICT", "API key allowed_exchanges misconfigured")
                        series = None
                    else:
                        ex = ins.get("exchange")
                        if ex is not None and ex not in allowed_ex:
                            http_status = 403
                            error_obj = _err("UNAUTHORIZED", "API key not permitted for this exchange")
                            series = None
                if error_obj is None and allowed_at is not None:
                    if not isinstance(allowed_at, list):
                        http_status = 500
                        error_obj = _err("CONFLICT", "API key allowed_asset_types misconfigured")
                        series = None
                    else:
                        at = ins.get("asset_type")
                        if at not in allowed_at:
                            http_status = 403
                            error_obj = _err("UNAUTHORIZED", "API key not permitted for this asset type")
                            series = None

                if error_obj is None:
                    ins_id = ins.get("id")
                    # select datapoints for timeframe, unadjusted, regular session
                    rows = []
                    for r in mdps:
                        if not isinstance(r, dict):
                            continue
                        if r.get("instrument_id") != ins_id:
                            continue
                        if r.get("timeframe") != tf:
                            continue
                        if r.get("adjustment_type") != "unadjusted":
                            continue
                        if r.get("session") != "regular":
                            continue
                        # date filtering based on trade_date (YYYY-MM-DD)
                        td = r.get("trade_date")
                        if not isinstance(td, str):
                            continue
                        if from_d and td < from_d.isoformat():
                            continue
                        if to_d and td > to_d.isoformat():
                            continue
                        rows.append(r)

                    # sort ascending by ts (ISO string)
                    def _ts_key(r):
                        ts_s = r.get("ts")
                        return ts_s or ""
                    rows.sort(key=_ts_key)

                    # Provider default window when from/to omitted: for SMA/EMA, return last 100 points, cap at 1000.
                    max_rows = 1000
                    if from_d is None and to_d is None and len(rows) > 100:
                        rows = rows[-100:]
                    if len(rows) > max_rows:
                        rows = rows[-max_rows:]

                    closes = []
                    ts_list = []
                    for r in rows:
                        c = r.get("close")
                        if c is None:
                            closes.append(None)
                        elif isinstance(c, (int, float)) and not isinstance(c, bool) and c >= 0:
                            closes.append(float(c))
                        else:
                            closes.append(None)
                        ts_list.append(r.get("ts"))

                    series = []
                    window = []
                    window_sum = 0.0
                    valid_in_window = 0

                    for i, (c, ts_s) in enumerate(zip(closes, ts_list)):
                        # Maintain window with None values excluded; if any None in last N, SMA undefined.
                        window.append(c)
                        if c is None:
                            pass
                        else:
                            window_sum += c
                            valid_in_window += 1
                        if len(window) > pl_int:
                            old = window.pop(0)
                            if old is None:
                                pass
                            else:
                                window_sum -= old
                                valid_in_window -= 1

                        if len(window) == pl_int and valid_in_window == pl_int:
                            sma = window_sum / pl_int
                            series.append({"date": ts_s, "sma": sma})
                        # else: FMP commonly omits leading points until enough data; we do same.

            if error_obj is None:
                result = series
                result_count = len(series)
                # update api_key last_used_at
                api_key_row["last_used_at"] = now_iso
                api_key_row["updated_at"] = now_iso
                _save("api_keys.json", api_keys)

    except Exception as e:
        http_status = 500
        error_obj = _err("CONFLICT", "Internal server error", detail=str(e))

    # --- write exactly one request log row ---
    duration_ms = int((time.time() - t0) * 1000)
    # pick an api_key_id for logging even when unauthorized: if any active exists, log with that; else log with first key if exists.
    log_key_id = None
    if api_key_row is not None and isinstance(api_key_row.get("id"), str):
        log_key_id = api_key_row["id"]
    else:
        # best-effort pick: any key id for FK; if none, cannot satisfy FK. In that case, do not crash; return UNAUTHORIZED with no log? But rule says exactly one log.
        # We'll create a synthetic log only if we can reference an existing key; otherwise return error without persisting log.
        for k in api_keys:
            if isinstance(k, dict) and isinstance(k.get("id"), str):
                log_key_id = k["id"]
                break

    params_obj = {"symbol": symbol, "periodLength": periodLength, "timeframe": timeframe, "from": from_, "to": to}
    if log_key_id is not None:
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": log_key_id,
            "tool_name": "getSMA",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms),
            "result_count": result_count if error_obj is None else None,
            "error_code": (error_obj["error"]["code"] if error_obj else None),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)

    if error_obj is not None:
        return error_obj

    return {
        "symbol": symbol_norm,
        "timeframe": tf,
        "periodLength": pl_int,
        "from": from_,
        "to": to,
        "data": result,
        "meta": {"result_count": result_count}
    }

def getEMA(symbol, periodLength, timeframe, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # --- validate inputs ---
    if not isinstance(symbol, str) or not symbol.strip():
        validation_error = _err("VALIDATION_ERROR", "symbol must be a non-empty string")
        symbol_norm = None
    else:
        symbol_norm = symbol.strip().upper()
        validation_error = None

    if isinstance(periodLength, bool) or not isinstance(periodLength, (int, float)):
        validation_error = _err("VALIDATION_ERROR", "periodLength must be a positive integer")
    else:
        try:
            pl_int = int(periodLength)
        except Exception:
            pl_int = None
        if pl_int is None or float(periodLength) != float(pl_int) or pl_int <= 0:
            validation_error = _err("VALIDATION_ERROR", "periodLength must be a positive integer")

    allowed_timeframes = {"1min", "5min", "15min", "30min", "1hour", "4hour", "1day"}
    if not isinstance(timeframe, str) or timeframe not in allowed_timeframes:
        validation_error = _err("VALIDATION_ERROR", "timeframe must be one of (1min, 5min, 15min, 30min, 1hour, 4hour, 1day)")
    tf = timeframe if isinstance(timeframe, str) else None

    def _parse_date(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date string YYYY-MM-DD")
        try:
            return datetime.date.fromisoformat(s), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date string YYYY-MM-DD")

    from_d, from_err = _parse_date(from_, "from")
    to_d, to_err = _parse_date(to, "to")
    if from_err:
        validation_error = from_err
    if to_err:
        validation_error = to_err
    if from_d and to_d and from_d > to_d:
        validation_error = _err("VALIDATION_ERROR", "from must be <= to")

    # --- ambient authentication + quotas ---
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _rolling_counts(kid):
        now_dt = now
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != kid:
                continue
            ts_s = r.get("created_at")
            if not isinstance(ts_s, str):
                continue
            try:
                ts = datetime.datetime.fromisoformat(ts_s.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if ts >= minute_ago:
                m += 1
            if ts >= day_ago:
                d += 1
        return m, d

    def _resolve_active_key_under_quota():
        candidates = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        candidates.sort(key=lambda k: (k.get("created_at") or "", k.get("id") or ""))
        for k in candidates:
            kid = k.get("id")
            if not isinstance(kid, str):
                continue
            mq = k.get("minute_request_quota")
            dq = k.get("daily_request_quota")
            cl = k.get("concurrency_limit")
            if not isinstance(mq, int) or mq < 0:
                continue
            if not isinstance(dq, int) or dq < 0:
                continue
            if not isinstance(cl, int) or cl < 0:
                continue
            m, d = _rolling_counts(kid)
            if m >= mq or d >= dq:
                continue
            return k
        return None

    api_key_row = _resolve_active_key_under_quota()

    http_status = 200
    cache_status = "bypass"
    error_obj = None

    if api_key_row is None:
        # Distinguish quota vs no active key
        any_active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if any_active:
            http_status = 429
            error_obj = _err("QUOTA_EXCEEDED", "Request quota exceeded")
        else:
            http_status = 401
            error_obj = _err("UNAUTHORIZED", "No active API key available for this request")
    elif validation_error is not None:
        http_status = 400
        error_obj = validation_error

    result = None
    result_count = None

    try:
        if error_obj is None:
            instruments = _load("instruments.json")
            mdps = _load("market_data_points.json")

            matched = [ins for ins in instruments if isinstance(ins, dict) and ins.get("normalized_symbol") == symbol_norm]
            matched.sort(key=lambda ins: ((0 if ins.get("status") == "active" else 1), ins.get("exchange") or "", ins.get("created_at") or "", ins.get("id") or ""))
            if not matched:
                series = []
            else:
                ins = matched[0]

                allowed_ex = api_key_row.get("allowed_exchanges")
                allowed_at = api_key_row.get("allowed_asset_types")
                if allowed_ex is not None:
                    if not isinstance(allowed_ex, list):
                        http_status = 500
                        error_obj = _err("CONFLICT", "API key allowed_exchanges misconfigured")
                    else:
                        ex = ins.get("exchange")
                        if ex is not None and ex not in allowed_ex:
                            http_status = 403
                            error_obj = _err("UNAUTHORIZED", "API key not permitted for this exchange")
                if error_obj is None and allowed_at is not None:
                    if not isinstance(allowed_at, list):
                        http_status = 500
                        error_obj = _err("CONFLICT", "API key allowed_asset_types misconfigured")
                    else:
                        at = ins.get("asset_type")
                        if at not in allowed_at:
                            http_status = 403
                            error_obj = _err("UNAUTHORIZED", "API key not permitted for this asset type")

                series = []
                if error_obj is None:
                    ins_id = ins.get("id")
                    rows = []
                    for r in mdps:
                        if not isinstance(r, dict):
                            continue
                        if r.get("instrument_id") != ins_id:
                            continue
                        if r.get("timeframe") != tf:
                            continue
                        if r.get("adjustment_type") != "unadjusted":
                            continue
                        if r.get("session") != "regular":
                            continue
                        td = r.get("trade_date")
                        if not isinstance(td, str):
                            continue
                        if from_d and td < from_d.isoformat():
                            continue
                        if to_d and td > to_d.isoformat():
                            continue
                        rows.append(r)
                    rows.sort(key=lambda r: r.get("ts") or "")

                    max_rows = 1000
                    if from_d is None and to_d is None and len(rows) > 100:
                        rows = rows[-100:]
                    if len(rows) > max_rows:
                        rows = rows[-max_rows:]

                    closes = []
                    ts_list = []
                    for r in rows:
                        c = r.get("close")
                        if c is None:
                            closes.append(None)
                        elif isinstance(c, (int, float)) and not isinstance(c, bool) and c >= 0:
                            closes.append(float(c))
                        else:
                            closes.append(None)
                        ts_list.append(r.get("ts"))

                    # EMA: seed with SMA of first N valid points; then recursive.
                    alpha = 2.0 / (pl_int + 1.0)
                    ema = None
                    seed_window = []
                    for c, ts_s in zip(closes, ts_list):
                        if ema is None:
                            # build seed window; require contiguous valid closes
                            if c is None:
                                seed_window = []
                                continue
                            seed_window.append(c)
                            if len(seed_window) == pl_int:
                                ema = sum(seed_window) / pl_int
                                series.append({"date": ts_s, "ema": ema})
                            continue
                        else:
                            if c is None:
                                # if close missing, skip point (do not advance EMA)
                                continue
                            ema = (c - ema) * alpha + ema
                            series.append({"date": ts_s, "ema": ema})

            if error_obj is None:
                result = series
                result_count = len(series)
                api_key_row["last_used_at"] = now_iso
                api_key_row["updated_at"] = now_iso
                _save("api_keys.json", api_keys)

    except Exception as e:
        http_status = 500
        error_obj = _err("CONFLICT", "Internal server error", detail=str(e))

    duration_ms = int((time.time() - t0) * 1000)

    # log key id best-effort (must satisfy FK)
    log_key_id = None
    if api_key_row is not None and isinstance(api_key_row.get("id"), str):
        log_key_id = api_key_row["id"]
    else:
        for k in api_keys:
            if isinstance(k, dict) and isinstance(k.get("id"), str):
                log_key_id = k["id"]
                break

    params_obj = {"symbol": symbol, "periodLength": periodLength, "timeframe": timeframe, "from": from_, "to": to}
    if log_key_id is not None:
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": log_key_id,
            "tool_name": "getEMA",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms),
            "result_count": result_count if error_obj is None else None,
            "error_code": (error_obj["error"]["code"] if error_obj else None),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)

    if error_obj is not None:
        return error_obj

    return {
        "symbol": symbol_norm,
        "timeframe": tf,
        "periodLength": pl_int,
        "from": from_,
        "to": to,
        "data": result,
        "meta": {"result_count": result_count}
    }

def getWMA(symbol, periodLength, timeframe, from_=None, to=None, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_date(s):
        try:
            dt = datetime.datetime.strptime(s, "%Y-%m-%d").date()
            return dt
        except Exception:
            return None

    def _normalize_symbol(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip().upper()
        return s2 if s2 else None

    def _as_positive_intish(x):
        # periodLength is "number" in schema; treat as integer >= 1 (FMP moving average periods are integer)
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, (int, float)):
            if isinstance(x, float) and (x != x):  # NaN
                return None
            if x <= 0:
                return None
            xi = int(x)
            if abs(x - xi) > 1e-9:
                # reject non-integers to avoid ambiguous indicator definition
                return None
            return xi
        return None

    def _pick_active_key_for_call(api_keys_rows, request_logs_rows, now_dt):
        # Ambient auth: choose any api_keys row that is active and not quota-exceeded right now.
        active = [k for k in api_keys_rows if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, "UNAUTHORIZED"

        minute_start = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt - datetime.timedelta(seconds=86400)

        # Precompute counts per key for rolling windows
        per_key_min = {}
        per_key_day = {}
        for r in request_logs_rows:
            if not isinstance(r, dict):
                continue
            kid = r.get("api_key_id")
            ts = r.get("created_at")
            if not kid or not isinstance(ts, str):
                continue
            try:
                rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rdt >= minute_start:
                per_key_min[kid] = per_key_min.get(kid, 0) + 1
            if rdt >= day_start:
                per_key_day[kid] = per_key_day.get(kid, 0) + 1

        # Find a key with remaining quota
        for k in active:
            kid = k.get("id")
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue
            used_min = per_key_min.get(kid, 0)
            used_day = per_key_day.get(kid, 0)
            if used_min < min_q and used_day < day_q:
                return k, None

        # No key can serve due to quota
        return None, "QUOTA"

    def _log_request(request_logs_rows, api_key_id, tool_name, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        now = _now_iso()
        rid = "req_" + uuid.uuid4().hex
        row = {
            "id": rid,
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        request_logs_rows.append(row)
        return row

    start = time.time()
    tool = "getWMA"

    # Validate params (and enforce additionalProperties=false by not accepting anything else; _extra ignored)
    params = {"symbol": symbol, "periodLength": periodLength, "timeframe": timeframe}
    if from_ is not None:
        params["from"] = from_
    if to is not None:
        params["to"] = to

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow()

    api_key_row, auth_fail_reason = _pick_active_key_for_call(api_keys, request_logs, now_dt)

    # Validate request regardless; but auth failures must be returned and logged.
    norm_sym = _normalize_symbol(symbol)
    if norm_sym is None:
        http_status = 400
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")

    allowed_timeframes = {"1min", "5min", "15min", "30min", "1hour", "4hour", "1day"}
    if not isinstance(timeframe, str) or timeframe not in allowed_timeframes:
        http_status = 400
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "timeframe must be one of: 1min, 5min, 15min, 30min, 1hour, 4hour, 1day")

    per = _as_positive_intish(periodLength)
    if per is None:
        http_status = 400
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "periodLength must be a positive integer")

    from_d = None
    to_d = None
    if from_ is not None:
        if not isinstance(from_, str):
            http_status = 400
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "from must be a string in YYYY-MM-DD")
        from_d = _parse_iso_date(from_)
        if from_d is None:
            http_status = 400
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "from must be a valid ISO date (YYYY-MM-DD)")
    if to is not None:
        if not isinstance(to, str):
            http_status = 400
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "to must be a string in YYYY-MM-DD")
        to_d = _parse_iso_date(to)
        if to_d is None:
            http_status = 400
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "to must be a valid ISO date (YYYY-MM-DD)")
    if from_d is not None and to_d is not None and from_d > to_d:
        http_status = 400
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "from must be <= to")

    # Enforce authentication/quota after validation
    if api_key_row is None:
        if auth_fail_reason == "QUOTA":
            http_status = 429
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, "unknown", tool, params, http_status, "bypass", duration, result_count=None, error_code="QUOTA_EXCEEDED")
            _save("request_logs.json", request_logs)
            return _err("QUOTA_EXCEEDED", "Request quota exceeded")
        http_status = 401
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, "unknown", tool, params, http_status, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is missing, inactive, suspended, or revoked")

    # Allowed asset/exchange enforcement applies when instrument exists
    instruments = _load("instruments.json")
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("normalized_symbol") == norm_sym:
            # If multiple exchanges exist, pick any; this tool doesn't accept exchange.
            # Prefer active instruments.
            if inst is None:
                inst = r
            elif inst.get("status") != "active" and r.get("status") == "active":
                inst = r
    if inst is None:
        http_status = 404
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"], tool, params, http_status, "miss", duration, result_count=0, error_code="NOT_FOUND")
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Symbol not found")

    allowed_ex = api_key_row.get("allowed_exchanges")
    if allowed_ex is not None:
        if not isinstance(allowed_ex, list):
            allowed_ex = None
        else:
            ex = inst.get("exchange")
            if ex is not None and ex not in allowed_ex:
                http_status = 403
                duration = int((time.time() - start) * 1000)
                _log_request(request_logs, api_key_row["id"], tool, params, http_status, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
                _save("request_logs.json", request_logs)
                return _err("UNAUTHORIZED", "API key not entitled for this exchange")
    allowed_at = api_key_row.get("allowed_asset_types")
    if allowed_at is not None:
        if not isinstance(allowed_at, list):
            allowed_at = None
        else:
            if inst.get("asset_type") not in allowed_at:
                http_status = 403
                duration = int((time.time() - start) * 1000)
                _log_request(request_logs, api_key_row["id"], tool, params, http_status, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
                _save("request_logs.json", request_logs)
                return _err("UNAUTHORIZED", "API key not entitled for this asset type")

    # Read market data points and compute WMA over close prices
    mdps = _load("market_data_points.json")
    rows = []
    inst_id = inst.get("id")
    for r in mdps:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != inst_id:
            continue
        if r.get("timeframe") != timeframe:
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        # Filter by trade_date if from/to provided
        td = r.get("trade_date")
        if not isinstance(td, str) or len(td) != 10:
            continue
        if from_d is not None:
            d = _parse_iso_date(td)
            if d is None or d < from_d:
                continue
        if to_d is not None:
            d = _parse_iso_date(td)
            if d is None or d > to_d:
                continue
        # close must be numeric
        c = r.get("close")
        if c is None or isinstance(c, bool) or not isinstance(c, (int, float)):
            continue
        ts = r.get("ts")
        if not isinstance(ts, str):
            continue
        try:
            tsdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        rows.append((tsdt, r, float(c)))

    rows.sort(key=lambda x: x[0])

    # Compute WMA: weights 1..N applied to last N closes
    out = []
    denom = per * (per + 1) / 2.0
    closes = []
    for tsdt, r, c in rows:
        closes.append(c)
        if len(closes) < per:
            continue
        window = closes[-per:]
        wsum = 0.0
        w = 1
        for val in window:
            wsum += w * val
            w += 1
        wma = wsum / denom if denom != 0 else None
        out.append({
            "symbol": inst.get("symbol"),
            "timeframe": timeframe,
            "periodLength": per,
            "date": r.get("trade_date"),
            "timestamp": r.get("ts"),
            "wma": wma
        })

    # Update key usage timestamps only on successful authenticated request
    now_iso = _now_iso()
    api_key_row["last_used_at"] = now_iso
    api_key_row["updated_at"] = now_iso
    # persist api_keys update
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
            api_keys[i] = api_key_row
            break
    _save("api_keys.json", api_keys)

    http_status = 200
    duration = int((time.time() - start) * 1000)
    _log_request(request_logs, api_key_row["id"], tool, params, http_status, "miss", duration, result_count=len(out), error_code=None)
    _save("request_logs.json", request_logs)

    return {
        "symbol": inst.get("symbol"),
        "timeframe": timeframe,
        "periodLength": per,
        "from": from_ if from_ is not None else None,
        "to": to if to is not None else None,
        "data": out
    }

def getDEMA(symbol, periodLength, timeframe, from_=None, to=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_date(s):
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return None

    def _normalize_symbol(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip().upper()
        return s2 if s2 else None

    def _as_positive_intish(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, (int, float)):
            if isinstance(x, float) and (x != x):
                return None
            if x <= 0:
                return None
            xi = int(x)
            if abs(x - xi) > 1e-9:
                return None
            return xi
        return None

    def _pick_active_key_for_call(api_keys_rows, request_logs_rows, now_dt):
        active = [k for k in api_keys_rows if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, "UNAUTHORIZED"

        minute_start = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt - datetime.timedelta(seconds=86400)

        per_key_min = {}
        per_key_day = {}
        for r in request_logs_rows:
            if not isinstance(r, dict):
                continue
            kid = r.get("api_key_id")
            ts = r.get("created_at")
            if not kid or not isinstance(ts, str):
                continue
            try:
                rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rdt >= minute_start:
                per_key_min[kid] = per_key_min.get(kid, 0) + 1
            if rdt >= day_start:
                per_key_day[kid] = per_key_day.get(kid, 0) + 1

        for k in active:
            kid = k.get("id")
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue
            if per_key_min.get(kid, 0) < min_q and per_key_day.get(kid, 0) < day_q:
                return k, None

        return None, "QUOTA"

    def _log_request(request_logs_rows, api_key_id, tool_name, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        now = _now_iso()
        rid = "req_" + uuid.uuid4().hex
        request_logs_rows.append({
            "id": rid,
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        })

    def _ema_series(values, period):
        # Standard EMA with alpha=2/(period+1). Seed with SMA of first period.
        if period <= 0 or len(values) < period:
            return []
        alpha = 2.0 / (period + 1.0)
        sma = sum(values[:period]) / float(period)
        ema = [None] * (period - 1) + [sma]
        prev = sma
        for v in values[period:]:
            prev = (v - prev) * alpha + prev
            ema.append(prev)
        return ema

    start = time.time()
    tool = "getDEMA"

    params = {"symbol": symbol, "periodLength": periodLength, "timeframe": timeframe}
    if from_ is not None:
        params["from"] = from_
    if to is not None:
        params["to"] = to

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow()

    api_key_row, auth_fail_reason = _pick_active_key_for_call(api_keys, request_logs, now_dt)

    norm_sym = _normalize_symbol(symbol)
    if norm_sym is None:
        http_status = 400
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")

    allowed_timeframes = {"1min", "5min", "15min", "30min", "1hour", "4hour", "1day"}
    if not isinstance(timeframe, str) or timeframe not in allowed_timeframes:
        http_status = 400
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "timeframe must be one of: 1min, 5min, 15min, 30min, 1hour, 4hour, 1day")

    per = _as_positive_intish(periodLength)
    if per is None:
        http_status = 400
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "periodLength must be a positive integer")

    from_d = None
    to_d = None
    if from_ is not None:
        if not isinstance(from_, str):
            http_status = 400
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "from must be a string in YYYY-MM-DD")
        from_d = _parse_iso_date(from_)
        if from_d is None:
            http_status = 400
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "from must be a valid ISO date (YYYY-MM-DD)")
    if to is not None:
        if not isinstance(to, str):
            http_status = 400
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "to must be a string in YYYY-MM-DD")
        to_d = _parse_iso_date(to)
        if to_d is None:
            http_status = 400
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "to must be a valid ISO date (YYYY-MM-DD)")
    if from_d is not None and to_d is not None and from_d > to_d:
        http_status = 400
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"] if api_key_row else None, tool, params, http_status, "bypass", duration, result_count=None, error_code="VALIDATION_ERROR")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "from must be <= to")

    if api_key_row is None:
        if auth_fail_reason == "QUOTA":
            http_status = 429
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, "unknown", tool, params, http_status, "bypass", duration, result_count=None, error_code="QUOTA_EXCEEDED")
            _save("request_logs.json", request_logs)
            return _err("QUOTA_EXCEEDED", "Request quota exceeded")
        http_status = 401
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, "unknown", tool, params, http_status, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is missing, inactive, suspended, or revoked")

    instruments = _load("instruments.json")
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("normalized_symbol") == norm_sym:
            if inst is None:
                inst = r
            elif inst.get("status") != "active" and r.get("status") == "active":
                inst = r
    if inst is None:
        http_status = 404
        duration = int((time.time() - start) * 1000)
        _log_request(request_logs, api_key_row["id"], tool, params, http_status, "miss", duration, result_count=0, error_code="NOT_FOUND")
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Symbol not found")

    allowed_ex = api_key_row.get("allowed_exchanges")
    if allowed_ex is not None and isinstance(allowed_ex, list):
        ex = inst.get("exchange")
        if ex is not None and ex not in allowed_ex:
            http_status = 403
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"], tool, params, http_status, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "API key not entitled for this exchange")

    allowed_at = api_key_row.get("allowed_asset_types")
    if allowed_at is not None and isinstance(allowed_at, list):
        if inst.get("asset_type") not in allowed_at:
            http_status = 403
            duration = int((time.time() - start) * 1000)
            _log_request(request_logs, api_key_row["id"], tool, params, http_status, "bypass", duration, result_count=None, error_code="UNAUTHORIZED")
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "API key not entitled for this asset type")

    mdps = _load("market_data_points.json")
    inst_id = inst.get("id")
    bars = []
    for r in mdps:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != inst_id:
            continue
        if r.get("timeframe") != timeframe:
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        td = r.get("trade_date")
        if not isinstance(td, str) or len(td) != 10:
            continue
        if from_d is not None:
            d = _parse_iso_date(td)
            if d is None or d < from_d:
                continue
        if to_d is not None:
            d = _parse_iso_date(td)
            if d is None or d > to_d:
                continue
        c = r.get("close")
        if c is None or isinstance(c, bool) or not isinstance(c, (int, float)):
            continue
        ts = r.get("ts")
        if not isinstance(ts, str):
            continue
        try:
            tsdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        bars.append((tsdt, r, float(c)))

    bars.sort(key=lambda x: x[0])
    closes = [c for _, __, c in bars]

    ema1 = _ema_series(closes, per)
    ema1_values = [v for v in ema1 if v is not None]
    # Need ema2 aligned to the same bar indices; compute on ema1 values then expand with Nones
    ema2_compact = _ema_series(ema1_values, per)
    # Map compact ema2 back to original indices:
    # ema1 has (per-1) Nones then values for indices per-1..end
    ema2 = [None] * len(closes)
    # ema1_values corresponds to indices i where i >= per-1
    # ema2_compact has (per-1) Nones then values within compact space
    for j, v in enumerate(ema2_compact):
        if v is None:
            continue
        # compact index j corresponds to original index (per-1 + j)
        i = (per - 1) + j
        if 0 <= i < len(ema2):
            ema2[i] = v

    out = []
    for i, (tsdt, r, c) in enumerate(bars):
        e1 = ema1[i] if i < len(ema1) else None
        e2 = ema2[i] if i < len(ema2) else None
        if e1 is None or e2 is None:
            continue
        dema = 2.0 * e1 - e2
        out.append({
            "symbol": inst.get("symbol"),
            "timeframe": timeframe,
            "periodLength": per,
            "date": r.get("trade_date"),
            "timestamp": r.get("ts"),
            "dema": dema
        })

    now_iso = _now_iso()
    api_key_row["last_used_at"] = now_iso
    api_key_row["updated_at"] = now_iso
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
            api_keys[i] = api_key_row
            break
    _save("api_keys.json", api_keys)

    http_status = 200
    duration = int((time.time() - start) * 1000)
    _log_request(request_logs, api_key_row["id"], tool, params, http_status, "miss", duration, result_count=len(out), error_code=None)
    _save("request_logs.json", request_logs)

    return {
        "symbol": inst.get("symbol"),
        "timeframe": timeframe,
        "periodLength": per,
        "from": from_ if from_ is not None else None,
        "to": to if to is not None else None,
        "data": out
    }

def getTEMA(symbol, periodLength, timeframe, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid}_{int(time.time()*1000)}"
    uuid = hashlib.sha256(f"{time.time()}".encode("utf-8")).hexdigest()[:16]

    def _parse_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.date.fromisoformat(s)
        except Exception:
            return None

    def _validate_params():
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string", field="symbol")
        if not (isinstance(periodLength, int) or isinstance(periodLength, float)) or isinstance(periodLength, bool):
            return _err("VALIDATION_ERROR", "periodLength must be a number", field="periodLength")
        if not (periodLength > 0):
            return _err("VALIDATION_ERROR", "periodLength must be a positive number", field="periodLength")
        if not isinstance(timeframe, str):
            return _err("VALIDATION_ERROR", "timeframe must be a string", field="timeframe")
        allowed_tf = {"1min", "5min", "15min", "30min", "1hour", "4hour", "1day"}
        if timeframe not in allowed_tf:
            return _err("VALIDATION_ERROR", "Unsupported timeframe", field="timeframe", allowed=sorted(allowed_tf))
        d_from = _parse_date(from_, "from")
        if from_ is not None and d_from is None:
            return _err("VALIDATION_ERROR", "from must be a valid ISO date (YYYY-MM-DD)", field="from")
        d_to = _parse_date(to, "to")
        if to is not None and d_to is None:
            return _err("VALIDATION_ERROR", "to must be a valid ISO date (YYYY-MM-DD)", field="to")
        if d_from and d_to and d_from > d_to:
            return _err("VALIDATION_ERROR", "from must be <= to", field="from")
        return None

    def _pick_api_key_and_enforce_quota(tool_name, validated_params):
        api_keys = _load("api_keys.json")
        req_logs = _load("request_logs.json")

        # Find any active key that can serve the request.
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API key available to authenticate request")

        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _dt(s):
            if not isinstance(s, str):
                return None
            try:
                # accept Z or naive
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        # Choose a key that is not over quota.
        for k in active:
            key_id = k.get("id")
            if not isinstance(key_id, str):
                continue
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                continue
            if not isinstance(day_q, int) or day_q < 0:
                continue

            min_used = 0
            day_used = 0
            for r in req_logs:
                if not isinstance(r, dict):
                    continue
                if r.get("api_key_id") != key_id:
                    continue
                ts = _dt(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= minute_ago:
                    min_used += 1
                if ts >= day_ago:
                    day_used += 1

            if min_used + 1 > min_q:
                continue
            if day_used + 1 > day_q:
                continue

            return k, None

        return None, _err("RATE_LIMIT", "Request quota exceeded")

    def _log_request(api_key_id, tool_name, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        req_logs = _load("request_logs.json")
        now_iso = _now_iso()
        duration_ms = max(0, int((time.time() - _t0) * 1000))
        log_row = {
            "id": f"req_{hashlib.sha256((now_iso + tool_name + str(duration_ms)).encode('utf-8')).hexdigest()[:20]}",
            "api_key_id": api_key_id if isinstance(api_key_id, str) else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)

    # Validate first (schema: additionalProperties=false; function signature ensures no extras)
    v_err = _validate_params()
    validated_params = {"symbol": symbol, "periodLength": periodLength, "timeframe": timeframe}
    if from_ is not None:
        validated_params["from"] = from_
    if to is not None:
        validated_params["to"] = to

    if v_err:
        # still must log attempt with auth context; choose any key id if available else unknown
        keys = _load("api_keys.json")
        any_key_id = None
        for k in keys:
            if isinstance(k, dict) and isinstance(k.get("id"), str):
                any_key_id = k["id"]
                break
        _log_request(any_key_id, "getTEMA", validated_params, 400, result_count=None, error_code=v_err["error"]["code"], cache_status="bypass")
        return v_err

    # Authenticate + quota
    api_key, a_err = _pick_api_key_and_enforce_quota("getTEMA", validated_params)
