        _log_request(None, "getTEMA", validated_params, status, result_count=None, error_code=a_err["error"]["code"], cache_status="bypass")
        return a_err

    # Update last_used_at on successful auth (not necessarily successful data lookup)
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", api_keys)

    # Entitlement allowlists (asset_type/exchange) enforced against resolved instrument(s)
    instruments = _load("instruments.json")
    norm_sym = symbol.strip().upper()
    matching = [i for i in instruments if isinstance(i, dict) and i.get("normalized_symbol") == norm_sym]
    if not matching:
        # reads with no matches should return empty set (normal envelope)
        out = {"symbol": norm_sym, "timeframe": timeframe, "periodLength": periodLength, "data": []}
        _log_request(api_key.get("id"), "getTEMA", validated_params, 200, result_count=0, error_code=None, cache_status="miss")
        return out

    # Apply entitlement filter by choosing at least one allowed instrument
    allowed_ex = api_key.get("allowed_exchanges")
    allowed_at = api_key.get("allowed_asset_types")
    def _allowed(inst):
        if isinstance(allowed_ex, list):
            if inst.get("exchange") not in allowed_ex:
                return False
        if isinstance(allowed_at, list):
            if inst.get("asset_type") not in allowed_at:
                return False
        return True
    matching = [m for m in matching if _allowed(m)]
    if not matching:
        _log_request(api_key.get("id"), "getTEMA", validated_params, 403, result_count=None, error_code="UNAUTHORIZED", cache_status="bypass")
        return _err("UNAUTHORIZED", "API key not entitled for requested symbol/exchange/asset type")

    # Prefer active instrument
    def _rank(inst):
        st = inst.get("status")
        return 0 if st == "active" else (1 if st == "inactive" else 2)
    matching.sort(key=_rank)
    instrument = matching[0]
    instrument_id = instrument.get("id")
    if not isinstance(instrument_id, str):
        out = {"symbol": norm_sym, "timeframe": timeframe, "periodLength": periodLength, "data": []}
        _log_request(api_key.get("id"), "getTEMA", validated_params, 200, result_count=0, error_code=None, cache_status="miss")
        return out

    # Load market data points for timeframe and unadjusted regular session (indicator derived from close series)
    md = _load("market_data_points.json")
    rows = []
    d_from = _parse_date(from_, "from")
    d_to = _parse_date(to, "to")
    for r in md:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != instrument_id:
            continue
        if r.get("timeframe") != timeframe:
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        td = r.get("trade_date")
        if not isinstance(td, str):
            continue
        try:
            td_date = datetime.date.fromisoformat(td)
        except Exception:
            continue
        if d_from and td_date < d_from:
            continue
        if d_to and td_date > d_to:
            continue
        rows.append(r)

    # Sort ascending by ts
    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    rows = [r for r in rows if _parse_ts(r.get("ts")) is not None]
    rows.sort(key=lambda r: _parse_ts(r.get("ts")))

    # Compute TEMA over close values.
    # Use standard EMA with alpha = 2/(n+1), starting EMA at first close.
    n = float(periodLength)
    # treat as integer length for smoothing; vendor expects number but periods are discrete
    n_int = int(round(n))
    if n_int <= 0:
        _log_request(api_key.get("id"), "getTEMA", validated_params, 400, result_count=None, error_code="VALIDATION_ERROR", cache_status="bypass")
        return _err("VALIDATION_ERROR", "periodLength must be a positive number", field="periodLength")

    alpha = 2.0 / (n_int + 1.0)

    closes = []
    for r in rows:
        c = r.get("close")
        if c is None:
            closes.append(None)
        else:
            if isinstance(c, bool) or not (isinstance(c, int) or isinstance(c, float)):
                closes.append(None)
            else:
                closes.append(float(c))

    def _ema(series):
        out = [None] * len(series)
        ema_prev = None
        for idx, v in enumerate(series):
            if v is None:
                out[idx] = None
                continue
            if ema_prev is None:
                ema_prev = v
            else:
                ema_prev = alpha * v + (1.0 - alpha) * ema_prev
            out[idx] = ema_prev
        return out

    ema1 = _ema(closes)
    ema2 = _ema(ema1)
    ema3 = _ema(ema2)

    data = []
    for i, r in enumerate(rows):
        if ema1[i] is None or ema2[i] is None or ema3[i] is None:
            continue
        tema = 3.0 * ema1[i] - 3.0 * ema2[i] + ema3[i]
        data.append({
            "symbol": instrument.get("symbol"),
            "timeframe": timeframe,
            "timestamp": r.get("ts"),
            "date": r.get("trade_date"),
            "tema": tema
        })

    out = {
        "symbol": instrument.get("symbol"),
        "timeframe": timeframe,
        "periodLength": periodLength,
        "data": data
    }
    _log_request(api_key.get("id"), "getTEMA", validated_params, 200, result_count=len(data), error_code=None, cache_status="miss")
    return out

