        except Exception:
            continue
        if d_from and td_date < d_from:
            continue
        if d_to and td_date > d_to:
            continue
        rows.append(r)

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    rows = [r for r in rows if _parse_ts(r.get("ts")) is not None]
    rows.sort(key=lambda r: _parse_ts(r.get("ts")))

    n = float(periodLength)
    n_int = int(round(n))
    if n_int <= 0:
        _log_request(api_key.get("id"), "getRSI", validated_params, 400, result_count=None, error_code="VALIDATION_ERROR", cache_status="bypass")
        return _err("VALIDATION_ERROR", "periodLength must be a positive number", field="periodLength")

