                closes.append(None)
            else:
                closes.append(float(c))

    # Wilder's RSI: initial avg gain/loss over first n periods, then smoothed.
    data = []
    gains = []
    losses = []
    prev = None
    for v in closes:
        if v is None or prev is None:
            gains.append(None)
            losses.append(None)
            prev = v
            continue
        ch = v - prev
        gains.append(max(ch, 0.0))
        losses.append(max(-ch, 0.0))
        prev = v

    avg_gain = None
    avg_loss = None
    for i in range(len(closes)):
        if i < 1:
            continue
        if i == n_int:
            # compute initial averages using periods 1..n
            window_g = []
            window_l = []
            ok = True
            for j in range(1, n_int + 1):
                if j >= len(gains) or gains[j] is None or losses[j] is None:
                    ok = False
                    break
                window_g.append(gains[j])
                window_l.append(losses[j])
            if not ok:
                continue
            avg_gain = sum(window_g) / n_int
            avg_loss = sum(window_l) / n_int
        elif i > n_int and avg_gain is not None and avg_loss is not None:
            g = gains[i]
            l = losses[i]
            if g is None or l is None:
                continue
            avg_gain = (avg_gain * (n_int - 1) + g) / n_int
            avg_loss = (avg_loss * (n_int - 1) + l) / n_int
        else:
            continue

        if avg_gain is None or avg_loss is None:
            continue

        if avg_loss == 0.0 and avg_gain == 0.0:
            rsi = 50.0
        elif avg_loss == 0.0:
            rsi = 100.0
        else:
            rs = avg_gain / avg_loss
            rsi = 100.0 - (100.0 / (1.0 + rs))

        r = rows[i] if i < len(rows) else None
        if isinstance(r, dict):
            data.append({
                "symbol": instrument.get("symbol"),
                "timeframe": timeframe,
                "timestamp": r.get("ts"),
                "date": r.get("trade_date"),
                "rsi": rsi
            })

    out = {
        "symbol": instrument.get("symbol"),
        "timeframe": timeframe,
        "periodLength": periodLength,
        "data": data
    }
    _log_request(api_key.get("id"), "getRSI", validated_params, 200, result_count=len(data), error_code=None, cache_status="miss")
    return out

def getStandardDeviation(symbol, periodLength, timeframe, from_=None, to=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, math, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
