        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso_date(s):
        if not isinstance(s, str):
            return None
        try:
            d = datetime.date.fromisoformat(s)
        except ValueError:
            return None
        if d.isoformat() != s:
            return None
        return d

    def _norm_symbol(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip().upper()
        return s2 if s2 else None

    def _log_request(api_key_id, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        now = _now_iso()
        row = {
            "id": "rql_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": "getStandardDeviation",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(duration_ms),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _choose_api_key_and_enforce_quota():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API key available to authenticate request.")
        # choose a working key that is within rate limits
        logs = _load("request_logs.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        for k in active:
            key_id = k.get("id")
            if not isinstance(key_id, str) or not key_id:
                continue
            minute_quota = k.get("minute_request_quota")
            daily_quota = k.get("daily_request_quota")
            if not isinstance(minute_quota, int) or minute_quota < 0:
                continue
            if not isinstance(daily_quota, int) or daily_quota < 0:
                continue
            # rolling windows
            minute_ago = now - datetime.timedelta(minutes=1)
            day_ago = now - datetime.timedelta(days=1)
            minute_count = 0
            daily_count = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("api_key_id") != key_id:
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                except ValueError:
                    continue
                if dt >= minute_ago:
                    minute_count += 1
                if dt >= day_ago:
                    daily_count += 1
            if minute_quota == 0 or daily_quota == 0:
                # 0 means no requests allowed
                continue
            if minute_count + 1 > minute_quota:
                continue
            if daily_count + 1 > daily_quota:
                continue
            return k, None

        # Determine whether it is minute or daily that blocks for a representative key; return RATE_LIMIT/QUOTA_EXCEEDED
        # Prefer RATE_LIMIT if any key hits minute quota, else QUOTA_EXCEEDED if any hits daily.
        any_minute_block = False
        any_daily_block = False
        any_active = False
        now = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        logs = _load("request_logs.json")
        for k in active:
            any_active = True
            key_id = k.get("id")
            if not isinstance(key_id, str) or not key_id:
                continue
            minute_quota = k.get("minute_request_quota")
            daily_quota = k.get("daily_request_quota")
            if not isinstance(minute_quota, int) or minute_quota < 0:
                continue
            if not isinstance(daily_quota, int) or daily_quota < 0:
                continue
            minute_count = 0
            daily_count = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != key_id:
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                except ValueError:
                    continue
                if dt >= minute_ago:
                    minute_count += 1
                if dt >= day_ago:
                    daily_count += 1
            if minute_quota == 0 or minute_count + 1 > minute_quota:
                any_minute_block = True
            if daily_quota == 0 or daily_count + 1 > daily_quota:
                any_daily_block = True
        if not any_active:
            return None, _err("UNAUTHORIZED", "No active API key available to authenticate request.")
        if any_minute_block:
            return None, _err("RATE_LIMIT", "Minute request quota exceeded.")
