        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows.sort(key=_ts_key)

    # Williams %R: -100 * (highestHigh - close) / (highestHigh - lowestLow) over periodLength
    n = pl_int
    out = []
    if n > 0 and len(rows) >= n:
        # Use simple rolling scan; n is typically small.
        highs = []
        lows = []
        closes = []
        tss = []
        for r in rows:
            h = r.get("high")
            l = r.get("low")
            c = r.get("close")
            if not (isinstance(h, (int, float)) and not isinstance(h, bool)):
