            else:
                lows.append(float(l))
            if not (isinstance(c, (int, float)) and not isinstance(c, bool)):
                closes.append(None)
            else:
                closes.append(float(c))
            tss.append(r.get("ts"))

        for i in range(n - 1, len(rows)):
            window_highs = [x for x in highs[i - n + 1:i + 1] if isinstance(x, float)]
            window_lows = [x for x in lows[i - n + 1:i + 1] if isinstance(x, float)]
            c = closes[i]
            if c is None or not window_highs or not window_lows:
                wr = None
            else:
                hh = max(window_highs)
                ll = min(window_lows)
                denom = (hh - ll)
                if denom == 0:
                    wr = 0.0
                else:
                    wr = -100.0 * ((hh - c) / denom)
            out.append({
