    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getADX"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    valid_timeframes = {"1min", "5min", "15min", "30min", "1hour", "4hour", "1day"}

    def _iso_now_z(dt=None):
        dt = dt or datetime.datetime.now(datetime.timezone.utc)
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _parse_date(d, field):
        if d is None:
            return None, None
        if not isinstance(d, str):
            return None, _err("VALIDATION_ERROR", f"`{field}` must be a string in YYYY-MM-DD.", http_status=400)
        s = d.strip()
        try:
            if len(s) != 10:
                raise ValueError("badlen")
            datetime.date.fromisoformat(s)
            return s, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"`{field}` must be a valid ISO date (YYYY-MM-DD).", http_status=400)

    def _new_id(prefix):
        seed = hashlib.sha1((str(time.time()) + "|" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{seed}"

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        now_iso = _iso_now_z(now_dt)
        duration_ms = int((time.time() - t0) * 1000)
        if duration_ms < 0:
            duration_ms = 0
        logs.append({
            "id": _new_id("fmp_req"),
            "api_key_id": api_key_id if isinstance(api_key_id, str) else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status) if isinstance(http_status, int) or (isinstance(http_status, float) and http_status.is_integer()) else 500,
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (int(result_count) if isinstance(result_count, int) and result_count >= 0 else None),
            "error_code": error_code if isinstance(error_code, str) else None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)

    def _select_active_key_for_request():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None, _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _count_for(kid):
            m = d = 0
            for r in logs:
                if not isinstance(r, dict) or r.get("api_key_id") != kid:
                    continue
                dt = _parse_dt_any(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= minute_ago:
                    m += 1
                if dt >= day_ago:
                    d += 1
            return m, d

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                continue
            if day_q and d + 1 > day_q:
                continue
            return k, None

        for k in active:
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or min_q < 0:
                min_q = 0
            if not isinstance(day_q, int) or day_q < 0:
                day_q = 0
            m, d = _count_for(k["id"])
            if min_q and m + 1 > min_q:
                return None, _err("RATE_LIMIT", "Request quota exceeded.", reason="quota_minute_exceeded", http_status=429)
            if day_q and d + 1 > day_q:
                return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", reason="quota_daily_exceeded", http_status=429)
        return None, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

    params_obj = {"symbol": symbol, "periodLength": periodLength, "timeframe": timeframe, "from": from_, "to": to}

    # validate
    if not isinstance(symbol, str) or not symbol.strip():
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`symbol` must be a non-empty string.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err
    sym = symbol.strip().upper()

    if not isinstance(timeframe, str) or timeframe not in valid_timeframes:
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`timeframe` must be one of 1min, 5min, 15min, 30min, 1hour, 4hour, 1day.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err

    if not isinstance(periodLength, (int, float)) or periodLength <= 0:
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`periodLength` must be a positive number.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err
    pl = int(periodLength) if not isinstance(periodLength, bool) else 0
    if pl <= 0:
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`periodLength` must be a positive number.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err

    from_s, ferr = _parse_date(from_, "from")
    if ferr:
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        _log(kid, params_obj, ferr["error"].get("http_status", 400), error_code="validation_error")
        return ferr
    to_s, terr = _parse_date(to, "to")
    if terr:
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        _log(kid, params_obj, terr["error"].get("http_status", 400), error_code="validation_error")
        return terr
    if from_s and to_s and from_s > to_s:
        key, _ = _select_active_key_for_request()
        kid = key["id"] if key else "unknown"
        err = _err("VALIDATION_ERROR", "`from` must be <= `to`.", http_status=400)
        _log(kid, params_obj, 400, error_code="validation_error")
        return err

    key, kerr = _select_active_key_for_request()
    if kerr:
        _log("unknown", params_obj, kerr["error"].get("http_status", 401), error_code=kerr["error"].get("reason") or kerr["error"]["code"].lower())
        return kerr
    kid = key["id"]

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")
    if not isinstance(instruments, list):
        instruments = []
    if not isinstance(mdp, list):
        mdp = []

    inst = None
    for ins in instruments:
        if isinstance(ins, dict) and ins.get("normalized_symbol") == sym:
            inst = ins
            break
    if inst is None:
        err = _err("NOT_FOUND", "Symbol not found.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="symbol_not_found")
        return err

    iid = inst.get("id")
    if not isinstance(iid, str):
        err = _err("NOT_FOUND", "Symbol not found.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="symbol_not_found")
        return err

    # select bars timeframe/unadjusted/regular; apply date filters using trade_date
    bars = []
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != iid:
            continue
        if r.get("timeframe") != timeframe:
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        td = r.get("trade_date")
        if isinstance(td, str) and len(td) >= 10:
            td10 = td[:10]
        else:
            # derive from ts if possible
            dt = _parse_dt_any(r.get("ts"))
            td10 = dt.date().isoformat() if dt else None
        if td10 is None:
            continue
        if from_s and td10 < from_s:
            continue
        if to_s and td10 > to_s:
            continue
        o, h, l, c = r.get("open"), r.get("high"), r.get("low"), r.get("close")
        if not all(isinstance(x, (int, float)) for x in (h, l, c)):
            continue
        bars.append({"date": r.get("ts"), "trade_date": td10, "high": float(h), "low": float(l), "close": float(c)})

    bars.sort(key=lambda x: x.get("trade_date") or "")
    if len(bars) < pl + 1:
        err = _err("NOT_FOUND", "Not enough price history to compute ADX for the requested parameters.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="insufficient_history")
        return err

    # Compute ADX using Wilder's smoothing
    trs = []
    pdm = []
    ndm = []
    for i in range(1, len(bars)):
        high = bars[i]["high"]
        low = bars[i]["low"]
        prev_close = bars[i-1]["close"]
        prev_high = bars[i-1]["high"]
        prev_low = bars[i-1]["low"]
        tr = max(high - low, abs(high - prev_close), abs(low - prev_close))
        up_move = high - prev_high
        down_move = prev_low - low
        plus_dm = up_move if (up_move > down_move and up_move > 0) else 0.0
        minus_dm = down_move if (down_move > up_move and down_move > 0) else 0.0
        trs.append(tr)
        pdm.append(plus_dm)
        ndm.append(minus_dm)

    def _wilder(values, n):
        out = []
        if len(values) < n:
            return out
        s = sum(values[:n])
        out.append(s)
        for v in values[n:]:
            s = s - (s / n) + v
            out.append(s)
        return out

    atr = _wilder(trs, pl)
    pdi_sm = _wilder(pdm, pl)
    ndi_sm = _wilder(ndm, pl)
    if not atr or not pdi_sm or not ndi_sm:
        err = _err("NOT_FOUND", "Not enough price history to compute ADX for the requested parameters.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="insufficient_history")
        return err

    dx = []
    for i in range(len(atr)):
        if atr[i] == 0:
            dx.append(0.0)
            continue
        pdi = 100.0 * (pdi_sm[i] / atr[i])
        ndi = 100.0 * (ndi_sm[i] / atr[i])
        denom = pdi + ndi
        dx.append(0.0 if denom == 0 else (100.0 * abs(pdi - ndi) / denom))

    adx_sm = _wilder(dx, pl)
    # Align timestamps: adx_sm starts after 2*pl - 1 bars from original bars
    start_idx = 2 * pl
    series = []
    for j, val in enumerate(adx_sm):
        idx = start_idx + j
        if idx < len(bars):
            series.append({"symbol": sym, "date": bars[idx]["date"], "adx": float(val)})

    if not series:
        err = _err("NOT_FOUND", "Not enough price history to compute ADX for the requested parameters.", http_status=404)
        _log(kid, params_obj, 404, result_count=0, error_code="insufficient_history")
        return err

    keys_all = _load("api_keys.json")
    if isinstance(keys_all, list):
        for k in keys_all:
            if isinstance(k, dict) and k.get("id") == kid:
                k["last_used_at"] = _iso_now_z(now_dt)
                k["updated_at"] = _iso_now_z(now_dt)
                _save("api_keys.json", keys_all)
                break

    _log(kid, params_obj, 200, result_count=len(series))
    return {"data": series, "meta": {"symbol": sym, "timeframe": timeframe, "periodLength": pl, "count": len(series)}}

def getQuote(symbol, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    params = {"symbol": symbol}

    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")

    def _match_key(presented, row):
        if presented is None:
            return False
        if not isinstance(presented, str):
            return False
        if presented == row.get("id"):
            return True
        kh = row.get("key_hash")
        if isinstance(kh, str) and kh:
            cand = hashlib.sha256(presented.encode("utf-8")).hexdigest()
            return cand == kh
        return False

    presented_key = _extra.get("apikey", None) if "apikey" in _extra else _extra.get("api_key", None) if "api_key" in _extra else _extra.get("key", None)

    authed_key = None
    if isinstance(presented_key, str) and presented_key.strip():
        for k in api_keys:
            if _match_key(presented_key.strip(), k):
                authed_key = k
                break

    def _log_and_return(http_status, body, error_code=None, result_count=None):
        duration_ms = int(round((time.time() - t0) * 1000))
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": authed_key["id"] if authed_key else "unauthenticated",
            "tool_name": "getQuote",
            "params": params,
            "http_status": http_status,
            "cache_status": "bypass",
            "duration_ms": max(0, duration_ms),
            "result_count": result_count,
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        req_logs.append(log_row)
        _save("request_logs.json", req_logs)
        return body

    if authed_key is None or authed_key.get("status") != "active":
        return _log_and_return(401, _err("UNAUTHORIZED", "Missing/invalid API key or key is not active."), error_code="UNAUTHORIZED")

    # Quota enforcement
    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    one_min_ago = now - datetime.timedelta(minutes=1)
    one_day_ago = now - datetime.timedelta(days=1)
    minute_count = 0
    day_count = 0
    for r in req_logs:
        if r.get("api_key_id") != authed_key["id"]:
            continue
        ts = _parse_ts(r.get("created_at"))
        if ts is None:
            continue
        if ts >= one_day_ago:
            day_count += 1
            if ts >= one_min_ago:
                minute_count += 1

    if isinstance(authed_key.get("minute_request_quota"), int) and minute_count >= authed_key["minute_request_quota"]:
        return _log_and_return(
            429,
            _err("RATE_LIMIT", "Minute request quota exceeded.", limit=authed_key.get("minute_request_quota"), window_seconds=60),
            error_code="RATE_LIMIT",
        )
    if isinstance(authed_key.get("daily_request_quota"), int) and day_count >= authed_key["daily_request_quota"]:
        return _log_and_return(
            429,
            _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=authed_key.get("daily_request_quota"), window_seconds=86400),
            error_code="QUOTA_EXCEEDED",
        )

    if not isinstance(symbol, str) or not symbol.strip():
        return _log_and_return(400, _err("VALIDATION_ERROR", "symbol must be a non-empty string."), error_code="VALIDATION_ERROR")

    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")

    norm_symbol = symbol.strip().upper()
    inst = None
    for i in instruments:
        if i.get("normalized_symbol") == norm_symbol:
            allowed_ex = authed_key.get("allowed_exchanges")
            allowed_at = authed_key.get("allowed_asset_types")
            if isinstance(allowed_ex, list) and i.get("exchange") is not None and i.get("exchange") not in allowed_ex:
                continue
            if isinstance(allowed_at, list) and i.get("asset_type") not in allowed_at:
                continue
            inst = i
            break

    if inst is None:
        return _log_and_return(404, _err("NOT_FOUND", "Symbol not found."), error_code="NOT_FOUND")

    # Latest unadjusted regular-session 1day snapshot
    snap = None
    for r in mdp:
        if r.get("instrument_id") != inst.get("id"):
            continue
        if r.get("timeframe") != "1day":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        if r.get("is_latest_snapshot") is True:
            snap = r
            break

    if snap is None:
        # symbol exists but no quote snapshot
        # For getQuote doc this is not NOT_FOUND necessarily, but we'll return empty list like FMP often does.
        body = []
        # Update last_used_at on successful authenticated request (even if empty response)
        authed_key["last_used_at"] = now_iso
        authed_key["updated_at"] = now_iso
        for idx, k in enumerate(api_keys):
            if k.get("id") == authed_key.get("id"):
                api_keys[idx] = authed_key
                break
        _save("api_keys.json", api_keys)
        return _log_and_return(200, body, result_count=0)

    quote = {
        "symbol": inst.get("symbol"),
        "name": inst.get("name"),
        "price": snap.get("close"),
        "open": snap.get("open"),
        "high": snap.get("high"),
        "low": snap.get("low"),
        "previousClose": None,
        "change": snap.get("change"),
        "changesPercentage": snap.get("change_percent"),
        "volume": snap.get("volume"),
        "timestamp": snap.get("ts"),
        "exchange": inst.get("exchange"),
        "currency": inst.get("currency"),
        "country": inst.get("country"),
        "isActivelyTrading": inst.get("is_actively_trading"),
        "isETF": inst.get("is_etf"),
        "isFund": inst.get("is_fund"),
    }

    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = now_iso
    for idx, k in enumerate(api_keys):
        if k.get("id") == authed_key.get("id"):
            api_keys[idx] = authed_key
            break
    _save("api_keys.json", api_keys)

    return _log_and_return(200, [quote], result_count=1)

