def getStockPriceChange(symbol, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        ts = _now_iso()
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_active_key_for_call():
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota(api_key_row, tool_name, params):
        start = time.perf_counter()
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")

        minute_quota = api_key_row.get("minute_request_quota")
        daily_quota = api_key_row.get("daily_request_quota")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            minute_quota = 0
        if not isinstance(daily_quota, int) or daily_quota < 0:
            daily_quota = 0

        api_key_id = api_key_row["id"]

        def _parse_dt(s):
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        window_min = now - datetime.timedelta(minutes=1)
        window_day = now - datetime.timedelta(days=1)

        min_count = 0
        day_count = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= window_min:
                min_count += 1
            if dt >= window_day:
                day_count += 1

        if minute_quota == 0 or daily_quota == 0:
            duration_ms = int((time.perf_counter() - start) * 1000)
            _log_request(api_key_id, tool_name, params, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
            return False, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

        if min_count + 1 > minute_quota or day_count + 1 > daily_quota:
            duration_ms = int((time.perf_counter() - start) * 1000)
            _log_request(api_key_id, tool_name, params, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
            return False, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

        return True, None

    t0 = time.perf_counter()
    tool_name = "getStockPriceChange"

    if not isinstance(symbol, str) or not symbol.strip():
        k = _pick_active_key_for_call()
        duration_ms = int((time.perf_counter() - t0) * 1000)
        if k is not None:
            _log_request(k["id"], tool_name, {"symbol": symbol}, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter `symbol` is required and must be a non-blank string.", http_status=400)

    api_key = _pick_active_key_for_call()
    if api_key is None:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        return _err("UNAUTHORIZED", "No active API key available.", http_status=401)

    ok, quota_err = _enforce_quota(api_key, tool_name, {"symbol": symbol.strip()})
    if not ok:
        return quota_err

    sym = symbol.strip().upper()
    instruments = _load("instruments.json")
    instrument = None
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        if ins.get("normalized_symbol") == sym and ins.get("asset_type") == "equity":
            allowed_ex = api_key.get("allowed_exchanges")
            allowed_at = api_key.get("allowed_asset_types")
            if allowed_at is not None and isinstance(allowed_at, list) and ins.get("asset_type") not in allowed_at:
                continue
            if allowed_ex is not None and isinstance(allowed_ex, list):
                ex = ins.get("exchange")
                if ex not in allowed_ex:
                    continue
            instrument = ins
            break

    if instrument is None:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        _log_request(api_key["id"], tool_name, {"symbol": symbol.strip()}, 404, "miss", duration_ms, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Symbol not found.", http_status=404)

    # Pull all 1day regular unadjusted points for instrument; compute changes
    mds = _load("market_data_points.json")
    points = []
    for r in mds:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != instrument.get("id"):
            continue
        if r.get("timeframe") != "1day":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        ts = r.get("ts")
        trade_date = r.get("trade_date")
        if not isinstance(trade_date, str):
            continue
        # keep only valid ISO date rows
        try:
            datetime.date.fromisoformat(trade_date)
        except Exception:
            continue
        # use close if available else skip
        close = r.get("close")
        if close is None or not isinstance(close, (int, float)):
            continue
        points.append((trade_date, ts, float(close)))

    if not points:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        _log_request(api_key["id"], tool_name, {"symbol": symbol.strip()}, 404, "miss", duration_ms, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No price history available to compute changes.", http_status=404)

    # sort by trade_date then ts
    points.sort(key=lambda x: (x[0], x[1] if isinstance(x[1], str) else ""))

    # Build mapping date->last close that day
    daily = {}
    for d, ts, c in points:
        daily[d] = c

    dates = sorted(daily.keys())
    last_date = dates[-1]
    last_close = daily[last_date]

    def _pct(a, b):
        if b == 0:
            return None
        return (a - b) / b * 100.0

    def _get_close_on_or_before(target_date):
        # dates sorted ascending; find last <= target_date
        import bisect
        idx = bisect.bisect_right(dates, target_date) - 1
        if idx < 0:
            return None, None
        d = dates[idx]
        return d, daily[d]

    today = datetime.date.fromisoformat(last_date)
    # horizons
    horizons = [
        ("1D", today - datetime.timedelta(days=1)),
        ("1W", today - datetime.timedelta(weeks=1)),
        ("1M", today - datetime.timedelta(days=30)),
        ("3M", today - datetime.timedelta(days=90)),
        ("6M", today - datetime.timedelta(days=180)),
        ("YTD", datetime.date(today.year, 1, 1)),
        ("1Y", today - datetime.timedelta(days=365)),
        ("3Y", today - datetime.timedelta(days=365 * 3)),
        ("5Y", today - datetime.timedelta(days=365 * 5)),
        ("10Y", today - datetime.timedelta(days=365 * 10)),
        ("MAX", datetime.date.fromisoformat(dates[0])),
    ]

    out = {
        "symbol": instrument.get("symbol"),
        "asOfDate": last_date,
        "lastClose": last_close,
        "changes": {},
    }

    for label, ref_date in horizons:
        if label == "MAX":
            base_date = dates[0]
            base_close = daily[base_date]
        else:
            base_date, base_close = _get_close_on_or_before(ref_date.isoformat())
            if base_close is None:
                # insufficient history
                out["changes"][label] = None
                continue
        abs_change = last_close - base_close
        pct_change = _pct(last_close, base_close)
        out["changes"][label] = {
            "fromDate": base_date,
            "fromClose": base_close,
            "toDate": last_date,
            "toClose": last_close,
            "change": abs_change,
            "changePercent": pct_change,
        }

    # Update api key last_used_at on success
    keys = _load("api_keys.json")
    now_iso = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    duration_ms = int((time.perf_counter() - t0) * 1000)
    _log_request(api_key["id"], tool_name, {"symbol": symbol.strip()}, 200, "miss", duration_ms, result_count=1, error_code=None)
    return {"data": out}

def getBatchQuotes(symbols, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        ts = _now_iso()
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_active_key_for_call():
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota(api_key_row, tool_name, params):
        start = time.perf_counter()
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")

        minute_quota = api_key_row.get("minute_request_quota")
        daily_quota = api_key_row.get("daily_request_quota")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            minute_quota = 0
        if not isinstance(daily_quota, int) or daily_quota < 0:
            daily_quota = 0

        api_key_id = api_key_row["id"]

        def _parse_dt(s):
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        window_min = now - datetime.timedelta(minutes=1)
        window_day = now - datetime.timedelta(days=1)

        min_count = 0
        day_count = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= window_min:
                min_count += 1
            if dt >= window_day:
                day_count += 1

        if minute_quota == 0 or daily_quota == 0:
            duration_ms = int((time.perf_counter() - start) * 1000)
            _log_request(api_key_id, tool_name, params, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
            return False, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

        if min_count + 1 > minute_quota or day_count + 1 > daily_quota:
            duration_ms = int((time.perf_counter() - start) * 1000)
            _log_request(api_key_id, tool_name, params, 429, "bypass", duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
            return False, _err("QUOTA_EXCEEDED", "Request quota exceeded.", http_status=429)

        return True, None

    t0 = time.perf_counter()
    tool_name = "getBatchQuotes"

    if not isinstance(symbols, str) or not symbols.strip():
        k = _pick_active_key_for_call()
        duration_ms = int((time.perf_counter() - t0) * 1000)
        if k is not None:
            _log_request(k["id"], tool_name, {"symbols": symbols}, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter `symbols` is required and must be a non-blank comma-separated string.", http_status=400)

    # Parse comma-separated list
    parts = [p.strip() for p in symbols.split(",")]
    parts = [p for p in parts if p]
    if not parts:
        k = _pick_active_key_for_call()
        duration_ms = int((time.perf_counter() - t0) * 1000)
        if k is not None:
            _log_request(k["id"], tool_name, {"symbols": symbols}, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter `symbols` must contain at least one symbol.", http_status=400)

    # Server policy: cap list length
    MAX_LIST = 100
    norm_syms = []
    seen = set()
    for p in parts:
        s = p.upper()
        if s not in seen:
            seen.add(s)
            norm_syms.append(s)
        if len(norm_syms) > MAX_LIST:
            k = _pick_active_key_for_call()
            duration_ms = int((time.perf_counter() - t0) * 1000)
            if k is not None:
                _log_request(k["id"], tool_name, {"symbols": symbols}, 400, "bypass", duration_ms, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Too many symbols requested (max {MAX_LIST}).", http_status=400)

    api_key = _pick_active_key_for_call()
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available.", http_status=401)

    ok, quota_err = _enforce_quota(api_key, tool_name, {"symbols": symbols})
    if not ok:
        return quota_err

    instruments = _load("instruments.json")
    by_symbol = {}
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        if ins.get("asset_type") != "equity":
            continue
        ns = ins.get("normalized_symbol")
        if ns in norm_syms and ns not in by_symbol:
            allowed_ex = api_key.get("allowed_exchanges")
            allowed_at = api_key.get("allowed_asset_types")
            if allowed_at is not None and isinstance(allowed_at, list) and ins.get("asset_type") not in allowed_at:
                continue
            if allowed_ex is not None and isinstance(allowed_ex, list):
                ex = ins.get("exchange")
                if ex not in allowed_ex:
                    continue
            by_symbol[ns] = ins

    if not by_symbol:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        _log_request(api_key["id"], tool_name, {"symbols": symbols}, 404, "miss", duration_ms, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "None of the provided symbols resolved.", http_status=404)

    mds = _load("market_data_points.json")
    # Build snapshot map by instrument_id for latest regular 1day unadjusted
    snap_by_instr = {}
    for r in mds:
        if not isinstance(r, dict):
            continue
        if r.get("timeframe") != "1day" or r.get("adjustment_type") != "unadjusted" or r.get("session") != "regular":
            continue
        if r.get("is_latest_snapshot") is not True:
            continue
        iid = r.get("instrument_id")
        if iid:
            snap_by_instr[iid] = r

    results = []
    for ns in norm_syms:
        ins = by_symbol.get(ns)
        if not ins:
            continue
        snap = snap_by_instr.get(ins.get("id"))
        if not snap:
            continue
        payload = snap.get("payload") if isinstance(snap.get("payload"), dict) else {}
        quote = {
            "symbol": ins.get("symbol"),
            "name": ins.get("name"),
            "exchange": ins.get("exchange"),
            "currency": ins.get("currency"),
            "timestamp": snap.get("ts"),
            "tradeDate": snap.get("trade_date"),
            "open": snap.get("open"),
            "high": snap.get("high"),
            "low": snap.get("low"),
            "price": snap.get("close"),
            "volume": snap.get("volume"),
            "vwap": snap.get("vwap"),
            "change": snap.get("change"),
            "changesPercentage": snap.get("change_percent"),
        }
        # include additional fields if present in stored payload (no invention)
        for k in ("previousClose", "dayLow", "dayHigh", "yearHigh", "yearLow", "marketCap", "avgVolume", "eps", "pe", "earningsAnnouncement"):
            if k in payload:
                quote[k] = payload[k]
        results.append(quote)

    if not results:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        _log_request(api_key["id"], tool_name, {"symbols": symbols}, 404, "miss", duration_ms, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No quote snapshots available for the resolved symbols.", http_status=404)

    # Update api key last_used_at on success
    keys = _load("api_keys.json")
    now_iso = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    duration_ms = int((time.perf_counter() - t0) * 1000)
    _log_request(api_key["id"], tool_name, {"symbols": symbols}, 200, "miss", duration_ms, result_count=len(results), error_code=None)

    return {"data": results, "meta": {"requested": len(norm_syms), "returned": len(results)}}

