            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    # validate symbols string
    if not isinstance(symbols, str) or not symbols.strip():
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"symbols": symbols}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`symbols` must be a non-empty comma-separated string.")

    parts = [p.strip().upper() for p in symbols.split(",") if p.strip()]
    # server policy: max 100
    dedup = []
    seen = set()
    for p in parts:
        if p not in seen:
            seen.add(p)
            dedup.append(p)
    if not dedup:
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"symbols": symbols}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`symbols` must contain at least one symbol.")
    if len(dedup) > 100:
