    if any(not re.match(r"^[A-Z0-9.\-]{1,20}$", s) for s in dedup):
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"symbols": symbols}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "One or more symbols are malformed.")

    params_obj = {"symbols": symbols}

    # auth + quota
    key = _find_active_key()
    if key is None:
        _log("unknown", params_obj, 401, error_code="unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

    ok, ecode, emsg, reason, http_status = _enforce_quota(key)
    if not ok:
        _log(key["id"], params_obj, http_status, error_code=reason)
        return _err(ecode, emsg, reason=reason, http_status=http_status)

    instruments = _load("instruments.json")
    inst_by_sym = {}
    for r in instruments:
        if isinstance(r, dict) and isinstance(r.get("normalized_symbol"), str):
            inst_by_sym[r["normalized_symbol"]] = r

    mdp = _load("market_data_points.json")

    out = []
    for s in dedup:
        inst = inst_by_sym.get(s)
        if not inst:
            continue
        iid = inst.get("id")
        best = None
        best_dt = None
        for r in mdp:
            if not isinstance(r, dict):
                continue
            if r.get("instrument_id") != iid:
                continue
            if r.get("session") != "aftermarket" or r.get("adjustment_type") != "unadjusted" or r.get("timeframe") != "1min":
                continue
            dt = _parse_ts(r.get("ts"))
            if dt is None:
                continue
            if best_dt is None or dt > best_dt:
                best_dt = dt
                best = r
        if best:
            out.append({
                "symbol": s,
                "timestamp": best.get("ts"),
                "price": best.get("close"),
                "size": best.get("volume"),
            })

    if not out:
        _log(key["id"], params_obj, 404, error_code="no_aftermarket_trades")
