def getBatchAftermarketQuote(symbols, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getBatchAftermarketQuote"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_req_id():
        seed = hashlib.sha1(os.urandom(16)).hexdigest()[:22]
        return "fmp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + seed

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rolling_counts(api_key_id):
        logs = _load("request_logs.json")
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                d += 1
                if dt >= minute_ago:
                    m += 1
        return m, d

    def _find_active_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        best = None
        best_score = None
        for k in active:
            if not isinstance(k.get("id"), str):
                continue
            m, d = _rolling_counts(k["id"])
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or not isinstance(day_q, int):
                continue
            score = (min_q - m, day_q - d)
            if best is None or score > best_score:
                best, best_score = k, score
        return best

    def _enforce_quota(key_row):
        m, d = _rolling_counts(key_row["id"])
        if m >= int(key_row.get("minute_request_quota", 0)):
            return False, "RATE_LIMIT", "Request quota exceeded.", "quota_minute_exceeded", 429
        if d >= int(key_row.get("daily_request_quota", 0)):
            return False, "QUOTA_EXCEEDED", "Daily request quota exceeded.", "quota_daily_exceeded", 429
        return True, None, None, None, 200

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_req_id(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    # validate symbols string
    if not isinstance(symbols, str) or not symbols.strip():
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"symbols": symbols}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`symbols` must be a non-empty comma-separated string.")

    parts = [p.strip().upper() for p in symbols.split(",") if p.strip()]
    dedup = []
    seen = set()
    for p in parts:
        if p not in seen:
            seen.add(p)
            dedup.append(p)
    if not dedup:
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"symbols": symbols}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`symbols` must contain at least one symbol.")
    if len(dedup) > 100:
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"symbols": symbols}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "Too many symbols; maximum is 100.")
    if any(not re.match(r"^[A-Z0-9.\-]{1,20}$", s) for s in dedup):
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"symbols": symbols}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "One or more symbols are malformed.")

    params_obj = {"symbols": symbols}

    # auth + quota
    key = _find_active_key()
    if key is None:
        _log("unknown", params_obj, 401, error_code="unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

    ok, ecode, emsg, reason, http_status = _enforce_quota(key)
    if not ok:
        _log(key["id"], params_obj, http_status, error_code=reason)
        return _err(ecode, emsg, reason=reason, http_status=http_status)

    instruments = _load("instruments.json")
    inst_by_sym = {}
    for r in instruments:
        if isinstance(r, dict) and isinstance(r.get("normalized_symbol"), str):
            inst_by_sym[r["normalized_symbol"]] = r

    mdp = _load("market_data_points.json")

    out = []
    for s in dedup:
        inst = inst_by_sym.get(s)
        if not inst:
            continue
        iid = inst.get("id")

        # prefer is_latest_snapshot=true aftermarket 1min unadjusted
        snap = None
        for r in mdp:
            if not isinstance(r, dict):
                continue
            if r.get("instrument_id") != iid:
                continue
            if r.get("session") != "aftermarket" or r.get("adjustment_type") != "unadjusted" or r.get("timeframe") != "1min":
                continue
            if r.get("is_latest_snapshot") is True:
                snap = r
                break

        if snap is None:
            best_dt = None
            for r in mdp:
                if not isinstance(r, dict):
                    continue
                if r.get("instrument_id") != iid:
                    continue
                if r.get("session") != "aftermarket" or r.get("adjustment_type") != "unadjusted" or r.get("timeframe") != "1min":
                    continue
                dt = _parse_ts(r.get("ts"))
                if dt is None:
                    continue
                if best_dt is None or dt > best_dt:
                    best_dt = dt
                    snap = r

        if snap:
            out.append({
                "symbol": s,
                "timestamp": snap.get("ts"),
                "price": snap.get("close"),
                "volume": snap.get("volume"),
                "change": snap.get("change"),
                "changesPercentage": snap.get("change_percent"),
            })

    if not out:
        _log(key["id"], params_obj, 404, error_code="no_aftermarket_quotes")
        return _err("NOT_FOUND", "No aftermarket quote data found for the requested symbols.", reason="no_aftermarket_quotes", http_status=404)

    out.sort(key=lambda r: (r.get("symbol") or ""))

    # update last_used_at
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    _log(key["id"], params_obj, 200, result_count=len(out))
    return {"data": out, "meta": {"requested": len(dedup), "returned": len(out)}}

def getExchangeQuotes(exchange, short=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    instruments = _load("instruments.json")
    mdp = _load("market_data_points.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        now = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count,
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    def _select_key():
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        def _dt(v):
            if not v: return datetime.datetime(1970, 1, 1)
            try:
                if isinstance(v, str) and v.endswith("Z"):
                    return datetime.datetime.fromisoformat(v[:-1])
                return datetime.datetime.fromisoformat(v)
            except Exception:
                return datetime.datetime(1970, 1, 1)
        active.sort(key=lambda r: _dt(r.get("last_used_at")), reverse=True)
        return active[0]

    def _quota_check(key_row):
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str): return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        kid = key_row["id"]
        used_min = 0
        used_day = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != kid:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= minute_ago:
                used_min += 1
            if ts >= day_ago:
                used_day += 1

        try:
            min_q = int(key_row.get("minute_request_quota"))
            day_q = int(key_row.get("daily_request_quota"))
        except Exception:
            return _err("VALIDATION_ERROR", "API key quota fields are invalid.")
        if min_q >= 0 and used_min >= min_q:
            return _err("RATE_LIMIT", "Minute request quota exceeded.", limit=min_q, window_seconds=60)
        if day_q >= 0 and used_day >= day_q:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=day_q, window_seconds=86400)
        return None

    params = {"exchange": exchange, "short": short}
    if exchange is None or not isinstance(exchange, str) or not exchange.strip():
        key = _select_key()
        kid = key["id"] if key else "anonymous"
        _log(kid, "getExchangeQuotes", params, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`exchange` must be a non-empty string.")
    if short is not None and not isinstance(short, bool):
        key = _select_key()
        kid = key["id"] if key else "anonymous"
        _log(kid, "getExchangeQuotes", params, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`short` must be a boolean when provided.")

    key = _select_key()
    if not key or key.get("status") != "active":
        kid = key["id"] if key else "anonymous"
        _log(kid, "getExchangeQuotes", params, 401, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    qerr = _quota_check(key)
    if qerr:
        _log(key["id"], "getExchangeQuotes", params, 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code=qerr["error"]["code"])
        return qerr

    ex_req = exchange.strip()
    ex_req_u = ex_req.upper()

    allowed_ex = key.get("allowed_exchanges")
    allowed_at = key.get("allowed_asset_types")

    # Find instruments on exchange (stocks/equity)
    listed = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("asset_type") != "equity":
            continue
        ex = inst.get("exchange")
        if not ex:
            continue
        if ex.upper() != ex_req_u:
            continue
        if allowed_ex is not None and inst.get("exchange") not in allowed_ex:
            continue
        if allowed_at is not None and inst.get("asset_type") not in allowed_at:
            continue
        listed.append(inst)

    if not listed:
        _log(key["id"], "getExchangeQuotes", params, 404, "miss", (time.time() - _t0) * 1000, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Unknown exchange or no listed symbols for this exchange.")

    # latest unadjusted regular-session 1day snapshot
    latest = {}
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("timeframe") != "1day":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        if not r.get("is_latest_snapshot"):
            continue
        iid = r.get("instrument_id")
        if iid:
            latest[iid] = r

    use_short = bool(short) if short is not None else False
    out = []
    for inst in listed:
        snap = latest.get(inst.get("id"))
        if not snap:
            continue
        if use_short:
            out.append({
                "symbol": inst.get("symbol"),
                "price": snap.get("close"),
                "changesPercentage": snap.get("change_percent"),
                "change": snap.get("change"),
                "volume": snap.get("volume"),
            })
        else:
            out.append({
                "symbol": inst.get("symbol"),
                "name": inst.get("name"),
                "exchange": inst.get("exchange"),
                "price": snap.get("close"),
                "open": snap.get("open"),
                "high": snap.get("high"),
                "low": snap.get("low"),
                "previousClose": None,  # not stored; leave null
                "change": snap.get("change"),
                "changesPercentage": snap.get("change_percent"),
                "volume": snap.get("volume"),
                "timestamp": snap.get("ts"),
                "currency": inst.get("currency"),
                "country": inst.get("country"),
            })

    if not out:
        _log(key["id"], "getExchangeQuotes", params, 404, "miss", (time.time() - _t0) * 1000, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Exchange has listed symbols but no quote snapshots are available.")

    now = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now
            k["updated_at"] = k.get("updated_at") or now
            break
    _save("api_keys.json", api_keys)

    _log(key["id"], "getExchangeQuotes", params, 200, "miss", (time.time() - _t0) * 1000, result_count=len(out), error_code=None)
    return {"data": out, "meta": {"count": len(out), "exchange": ex_req}}

