            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=day_q, window_seconds=86400)
        return None

    params = {"short": short}
    if short is not None and not isinstance(short, bool):
        key = _select_key()
        kid = key["id"] if key else "anonymous"
        _log(kid, "getMutualFundQuotes", params, 400, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`short` must be a boolean when provided.")

    key = _select_key()
    if not key or key.get("status") != "active":
        kid = key["id"] if key else "anonymous"
        _log(kid, "getMutualFundQuotes", params, 401, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    qerr = _quota_check(key)
    if qerr:
        _log(key["id"], "getMutualFundQuotes", params, 429, "bypass", (time.time() - _t0) * 1000, result_count=None, error_code=qerr["error"]["code"])
        return qerr

    allowed_ex = key.get("allowed_exchanges")
    allowed_at = key.get("allowed_asset_types")

    funds = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("asset_type") != "mutual_fund":
            continue
        if allowed_ex is not None and inst.get("exchange") not in allowed_ex:
            continue
        if allowed_at is not None and inst.get("asset_type") not in allowed_at:
            continue
        funds.append(inst)

    # latest unadjusted regular-session 1day snapshot
    latest = {}
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("timeframe") != "1day":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        if not r.get("is_latest_snapshot"):
            continue
        iid = r.get("instrument_id")
        if iid:
            latest[iid] = r

    use_short = bool(short) if short is not None else False
    out = []
    for inst in funds:
        snap = latest.get(inst.get("id"))
        if not snap:
            continue
        if use_short:
            out.append({
                "symbol": inst.get("symbol"),
                "price": snap.get("close"),
                "changesPercentage": snap.get("change_percent"),
                "change": snap.get("change"),
                "volume": snap.get("volume"),
            })
        else:
            out.append({
                "symbol": inst.get("symbol"),
                "name": inst.get("name"),
                "price": snap.get("close"),
                "open": snap.get("open"),
                "high": snap.get("high"),
                "low": snap.get("low"),
                "change": snap.get("change"),
                "changesPercentage": snap.get("change_percent"),
                "volume": snap.get("volume"),
                "timestamp": snap.get("ts"),
                "currency": inst.get("currency"),
                "country": inst.get("country"),
            })

    # Mutual fund quotes: if catalog exists but no snapshots, return empty list (read tool semantics)
    now = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now
            k["updated_at"] = k.get("updated_at") or now
            break
    _save("api_keys.json", api_keys)

    _log(key["id"], "getMutualFundQuotes", params, 200, "miss", (time.time() - _t0) * 1000, result_count=len(out), error_code=None)
    return {"data": out, "meta": {"count": len(out)}}

def getAvailableTranscriptSymbols(exchange=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getAvailableTranscriptSymbols"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_req_id():
        seed = hashlib.sha1(os.urandom(16)).hexdigest()[:22]
        return "fmp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + seed

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rolling_counts(api_key_id):
        logs = _load("request_logs.json")
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                d += 1
                if dt >= minute_ago:
                    m += 1
        return m, d

    def _find_active_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        best = None
        best_score = None
        for k in active:
            if not isinstance(k.get("id"), str):
                continue
            m, d = _rolling_counts(k["id"])
            min_q = k.get("minute_request_quota")
            day_q = k.get("daily_request_quota")
            if not isinstance(min_q, int) or not isinstance(day_q, int):
                continue
            score = (min_q - m, day_q - d)
            if best is None or score > best_score:
                best, best_score = k, score
        return best

    def _enforce_quota(key_row):
        m, d = _rolling_counts(key_row["id"])
        if m >= int(key_row.get("minute_request_quota", 0)):
            return False, "RATE_LIMIT", "Request quota exceeded.", "quota_minute_exceeded", 429
        if d >= int(key_row.get("daily_request_quota", 0)):
            return False, "QUOTA_EXCEEDED", "Daily request quota exceeded.", "quota_daily_exceeded", 429
        return True, None, None, None, 200

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_req_id(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    # validate
    if exchange is not None and (not isinstance(exchange, str) or not exchange.strip()):
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"exchange": exchange, "limit": limit, "cursor": cursor}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`exchange` must be a non-empty string when provided.")

    if limit is None:
        limit_i = 100
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)):
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"exchange": exchange, "limit": limit, "cursor": cursor}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be a number.")
        if isinstance(limit, float) and not limit.is_integer():
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"exchange": exchange, "limit": limit, "cursor": cursor}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be an integer.")
        limit_i = int(limit)
        if limit_i <= 0:
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"exchange": exchange, "limit": limit, "cursor": cursor}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be positive.")
        if limit_i > 1000:
            limit_i = 1000

    if cursor is not None and not isinstance(cursor, str):
        key = _find_active_key()
        kid = key["id"] if key else "unknown"
        _log(kid, {"exchange": exchange, "limit": limit_i, "cursor": cursor}, 400, error_code="validation_error")
        return _err("VALIDATION_ERROR", "`cursor` must be a string.")

    params_obj = {"exchange": exchange, "limit": limit_i, "cursor": cursor}

    # auth + quota
    key = _find_active_key()
    if key is None:
        _log("unknown", params_obj, 401, error_code="unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

    ok, ecode, emsg, reason, http_status = _enforce_quota(key)
    if not ok:
        _log(key["id"], params_obj, http_status, error_code=reason)
        return _err(ecode, emsg, reason=reason, http_status=http_status)

    # cursor decode
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("tx:"):
                start = int(s.split(":", 1)[1])
            else:
                start = int(s)
            if start < 0:
                start = 0
        except Exception:
            start = 10**18

    # data source: content_items with content_type = 'financial_report' (transcripts)
    content = _load("content_items.json")
    instruments = _load("instruments.json")
    inst_by_id = {r.get("id"): r for r in instruments if isinstance(r, dict) and isinstance(r.get("id"), str)}

    counts = {}
    for r in content:
        if not isinstance(r, dict) or r.get("status") != "active":
            continue
        if r.get("content_type") != "financial_report":
            continue
        payload = r.get("payload")
        # heuristic to recognize transcript
        is_transcript = False
        if isinstance(payload, dict):
            if payload.get("reportType") in ("transcript", "earnings_transcript", "earnings-call-transcript"):
                is_transcript = True
            if payload.get("type") in ("transcript", "earnings_transcript"):
                is_transcript = True
        title = r.get("title")
        if not is_transcript and isinstance(title, str) and "transcript" in title.lower():
            is_transcript = True
        if not is_transcript:
            continue

        iid = r.get("instrument_id")
        inst = inst_by_id.get(iid) if isinstance(iid, str) else None
        if not inst:
            continue
        if exchange is not None and inst.get("exchange") != exchange.strip():
            continue
        sym = inst.get("normalized_symbol")
        if not isinstance(sym, str):
            continue
        counts[sym] = counts.get(sym, 0) + 1

    rows = [{"symbol": s, "count": c} for s, c in counts.items()]
    rows.sort(key=lambda x: (x.get("symbol") or ""))

    total = len(rows)
    page_items = rows[start:start + limit_i]
    next_cursor = None
    if start + limit_i < total:
        token = f"tx:{start + limit_i}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    # update last_used_at
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    _log(key["id"], params_obj, 200, result_count=len(page_items))
    return {"data": page_items, "meta": {"total": total, "limit": limit_i, "cursor": cursor, "next_cursor": next_cursor, "has_more": bool(next_cursor)}}

def getLatest8KFilings(from_, to, page=None, limit=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_date(s, field):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"'{field}' must be a string in YYYY-MM-DD format")
        try:
            d = datetime.date.fromisoformat(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"'{field}' must be a valid ISO date in YYYY-MM-DD format")
        if d.isoformat() != s:
            return None, _err("VALIDATION_ERROR", f"'{field}' must be in YYYY-MM-DD format")
        return d, None

    def _as_int(n, field, default=None):
        if n is None:
            return default, None
        if isinstance(n, bool):
            return None, _err("VALIDATION_ERROR", f"'{field}' must be a number")
        if isinstance(n, (int, float)):
            if isinstance(n, float) and (n != int(n)):
                return None, _err("VALIDATION_ERROR", f"'{field}' must be an integer")
            n = int(n)
            return n, None
        return None, _err("VALIDATION_ERROR", f"'{field}' must be a number")

    def _log_request(api_key_id, params_obj, http_status, duration_ms, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        ts = _now_iso()
        row = {
            "id": f"req_{uuid.uuid4().hex}",
            "api_key_id": api_key_id,
            "tool_name": "getLatest8KFilings",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _find_authorized_key():
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _quota_check(api_key_id, minute_quota, daily_quota):
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        last_minute = 0
        last_day = 0
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            created = r.get("created_at")
            if not isinstance(created, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(created.replace("Z", "+00:00"))
            except ValueError:
                continue
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            if dt >= minute_ago:
                last_minute += 1
            if dt >= day_ago:
                last_day += 1

        if isinstance(minute_quota, int) and minute_quota >= 0 and last_minute >= minute_quota:
            return _err("RATE_LIMIT", "Per-minute request quota exceeded")
        if isinstance(daily_quota, int) and daily_quota >= 0 and last_day >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Per-day request quota exceeded")
        return None

    started = time.time()

    # Validate params according to schema (no additionalProperties; enforced via signature + _extra)
    if _extra:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected parameters provided", unexpected=list(_extra.keys()))

    d_from, e = _parse_date(from_, "from")
    if e:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return e

    d_to, e = _parse_date(to, "to")
    if e:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return e

    if d_from > d_to:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'from' must be <= 'to'")

    page_i, e = _as_int(page, "page", default=0)
    if e:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return e
    if page_i < 0:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'page' must be >= 0")

    # Tool default and max limits (policy). Use 100 as a safe default; max 1000 for list endpoints.
    limit_i, e = _as_int(limit, "limit", default=100)
    if e:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return e
    if limit_i <= 0:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'limit' must be > 0")
    if limit_i > 1000:
        duration_ms = int((time.time() - started) * 1000)
        key = _find_authorized_key()
        api_key_id = key.get("id") if key else "unknown"
        _log_request(api_key_id, {"from": from_, "to": to, "page": page, "limit": limit}, 400, duration_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'limit' must be <= 1000")

    # Authenticate (ambient): choose an active key able to serve.
    api_key = _find_authorized_key()
    if not api_key:
        duration_ms = int((time.time() - started) * 1000)
        _log_request("unknown", {"from": from_, "to": to, "page": page_i, "limit": limit_i}, 401, duration_ms, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key missing, invalid, or not active")

    # Enforce quota/rate limit based on rolling windows of request_logs.
    qerr = _quota_check(api_key["id"], api_key.get("minute_request_quota"), api_key.get("daily_request_quota"))
    if qerr:
        duration_ms = int((time.time() - started) * 1000)
        _log_request(api_key["id"], {"from": from_, "to": to, "page": page_i, "limit": limit_i}, 429, duration_ms, error_code=qerr["error"]["code"])
        return qerr

    # Query content_items for SEC filings that are 8-K.
    items = _load("content_items.json")
    matched = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "sec_filing":
            continue

        as_of = it.get("as_of_date")
        if not isinstance(as_of, str):
            continue
        try:
            as_of_d = datetime.date.fromisoformat(as_of)
        except ValueError:
            continue
        if as_of_d < d_from or as_of_d > d_to:
            continue

        # 8-K filter: identifier_1 commonly used for formType per schema guidance
        form_type = it.get("identifier_1")
        if not isinstance(form_type, str):
            # fall back to payload.formType if present
            payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
            form_type = payload.get("formType")
        if not isinstance(form_type, str) or form_type.upper() != "8-K":
            continue

        matched.append(it)

    # Sort newest first by as_of_date, then created_at if available
    def _sort_key(it):
        as_of = it.get("as_of_date") or ""
        created = it.get("created_at") or ""
        return (as_of, created)

    matched.sort(key=_sort_key, reverse=True)

    total = len(matched)
    start = page_i * limit_i
    end = start + limit_i
    page_rows = matched[start:end]

    # Update api_key last_used_at only on successful authenticated request (even if empty list)
    keys = _load("api_keys.json")
    now_iso = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    duration_ms = int((time.time() - started) * 1000)
    _log_request(api_key["id"], {"from": from_, "to": to, "page": page_i, "limit": limit_i}, 200, duration_ms, result_count=len(page_rows), error_code=None)

    has_more = end < total
    next_cursor = (page_i + 1) if has_more else None

    return {
        "data": page_rows,
        "meta": {
            "page": page_i,
            "limit": limit_i,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

