        key_id = k.get("id")
        if not isinstance(key_id, str) or not key_id:
            continue
        minute_quota = k.get("minute_request_quota")
        daily_quota = k.get("daily_request_quota")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            continue
        if not isinstance(daily_quota, int) or daily_quota < 0:
            continue

        minute_count = 0
        day_count = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != key_id:
                continue
            ts = _dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= one_day_ago:
                day_count += 1
                if ts >= one_min_ago:
                    minute_count += 1

        if minute_count + 1 <= minute_quota and day_count + 1 <= daily_quota:
            chosen = k
            quota_blocked_all = False
            break

    if chosen is None and quota_blocked_all:
        key_id = active_keys[0].get("id") if isinstance(active_keys[0], dict) else "anonymous"
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(api_key_id=key_id or "anonymous", params_obj=params_obj, http_status=429, duration_ms=duration_ms, result_count=None, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Quota exceeded.")

    if chosen is None:
        duration_ms = int((time.time() - t0) * 1000)
        _log_request(api_key_id="anonymous", params_obj=params_obj, http_status=401, duration_ms=duration_ms, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key missing/invalid or not active.")

    api_key_id = chosen["id"]

    # ---- Resolve symbol to instrument (normalized_symbol semantics) ----
    instruments = _load("instruments.json")
    norm = symbol.strip().upper()
    matching = [ins for ins in instruments if isinstance(ins, dict) and ins.get("normalized_symbol") == norm]
    # If no instrument row exists, FMP typically returns empty filings list (not an error).
    instrument_ids = set()
    for ins in matching:
        iid = ins.get("id")
        if isinstance(iid, str) and iid:
            instrument_ids.add(iid)

    # ---- Query content_items for SEC filings ----
    items = _load("content_items.json")
    results = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("content_type") != "sec_filing":
            continue
        if it.get("status") == "deleted":
            continue
        # Prefer instrument_id match when instrument exists; if no instrument exists, fall back to payload.symbol if present.
        ok = False
        it_iid = it.get("instrument_id")
        if instrument_ids:
            if isinstance(it_iid, str) and it_iid in instrument_ids:
                ok = True
        else:
            payload = it.get("payload")
            if isinstance(payload, dict):
                ps = payload.get("symbol")
                if isinstance(ps, str) and ps.strip().upper() == norm:
                    ok = True
        if not ok:
            continue

        as_of = it.get("as_of_date")
        if not isinstance(as_of, str):
            continue
        d_as = _parse_date(as_of)
        if d_as is None:
            continue
        if d_as < d_from or d_as > d_to:
            continue
        results.append(it)

    # Order by as_of_date desc then id desc
    def _sort_key(x):
        return (x.get("as_of_date") or "", x.get("id") or "")
    results.sort(key=_sort_key, reverse=True)

    total = len(results)
    start = page_i * limit_i
    end = start + limit_i
    page_rows = results[start:end]
    has_more = end < total
    next_cursor = None
    if has_more:
        next_cursor = str(page_i + 1)

    # ---- Update key usage timestamps on successful auth ----
    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    duration_ms = int((time.time() - t0) * 1000)
    _log_request(api_key_id=api_key_id, params_obj=params_obj, http_status=200, duration_ms=duration_ms, result_count=len(page_rows), error_code=None)

    return {
        "data": page_rows,
        "meta": {
            "total": total,
            "page": page_i,
            "limit": limit_i,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

