            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("status") == "active":
                return k
        return None

    def _enforce_quota(key_row, params_obj):
        # rolling windows based on request_logs timestamps; deny BEFORE logging current call
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        api_key_id = key_row.get("id")
        minute_count = 0
        day_count = 0
        for r in logs:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= day_ago:
                day_count += 1
            if ts >= minute_ago:
                minute_count += 1

        min_quota = key_row.get("minute_request_quota")
        day_quota = key_row.get("daily_request_quota")
        if not isinstance(min_quota, int) or min_quota < 0:
            min_quota = 0
        if not isinstance(day_quota, int) or day_quota < 0:
            day_quota = 0

        if min_quota == 0 or day_quota == 0:
            # Interpret 0 as no allowance (since schema says >=0, not nullable)
            return _err("QUOTA_EXCEEDED", "API key quota exhausted.")
        if minute_count + 1 > min_quota:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if day_count + 1 > day_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    # Validate params (additionalProperties already enforced by signature)
    params_obj = {"cik": cik}
    if not isinstance(cik, str) or not cik.strip():
        # unauthenticated attempts still must be logged; resolve any key for logging if possible
        k = _pick_active_key()
        api_key_id = k.get("id") if k else "unknown"
        dur = int((time.time() - _t0) * 1000)
        _log(api_key_id, params_obj, 400, "bypass", dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cik is required and must be a non-empty string.")

    # Authenticate (ambient): must have an active api_keys record somewhere
    key = _pick_active_key()
    if not key:
        dur = int((time.time() - _t0) * 1000)
        _log("unknown", params_obj, 401, "bypass", dur, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    # Quota check
    qerr = _enforce_quota(key, params_obj)
    if qerr:
        dur = int((time.time() - _t0) * 1000)
        _log(key["id"], params_obj, 429, "bypass", dur, result_count=None, error_code=qerr["error"]["code"])
        return qerr

    # Lookup entities by exact cik match (stored as string, left-padded)
    entities = _load("entities.json")
    matches = []
    cik_val = cik.strip()
    for e in entities:
        if e.get("entity_type") != "company":
            continue
        if e.get("cik") == cik_val:
            matches.append(e)

    if not matches:
        # Log and return NOT_FOUND (per tool description)
        dur = int((time.time() - _t0) * 1000)
        _log(key["id"], params_obj, 404, "miss", dur, result_count=0, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No company found for the provided CIK.")

    # Update last_used_at on successful authenticated request
    keys = _load("api_keys.json")
    nowiso = _now_iso()
    for k in keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = nowiso
            k["updated_at"] = nowiso
            break
    _save("api_keys.json", keys)

    dur = int((time.time() - _t0) * 1000)
    _log(key["id"], params_obj, 200, "miss", dur, result_count=len(matches), error_code=None)
