        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_req_id(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    # validate pagination
    if page is None:
        page_i = 0
    else:
        if isinstance(page, bool) or not isinstance(page, (int, float)):
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"page": page, "limit": limit}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`page` must be a number.")
        if isinstance(page, float) and not page.is_integer():
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"page": page, "limit": limit}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`page` must be an integer.")
        page_i = int(page)
        if page_i < 0:
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"page": page, "limit": limit}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`page` must be >= 0.")

    if limit is None:
        limit_i = 100
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)):
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"page": page_i, "limit": limit}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be a number.")
        if isinstance(limit, float) and not limit.is_integer():
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"page": page_i, "limit": limit}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be an integer.")
        limit_i = int(limit)
        if limit_i <= 0:
            key = _find_active_key()
            kid = key["id"] if key else "unknown"
            _log(kid, {"page": page_i, "limit": limit}, 400, error_code="validation_error")
            return _err("VALIDATION_ERROR", "`limit` must be positive.")
        if limit_i > 1000:
            limit_i = 1000

    params_obj = {"page": page_i, "limit": limit_i}

    # auth + quota
    key = _find_active_key()
    if key is None:
        _log("unknown", params_obj, 401, error_code="unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

    ok, ecode, emsg, reason, http_status = _enforce_quota(key)
    if not ok:
        _log(key["id"], params_obj, http_status, error_code=reason)
        return _err(ecode, emsg, reason=reason, http_status=http_status)

    entities = _load("entities.json")
    # interpret "industry classification" as SIC code/title + company name/CIK from entities
    rows = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("entity_type") != "company":
            continue
        sic = e.get("sic_code")
        title = e.get("sic_industry_title")
        if sic is None and title is None:
            continue
        rows.append({
            "entity_id": e.get("id"),
            "name": e.get("name"),
            "cik": e.get("cik"),
            "sicCode": sic,
            "sicIndustryTitle": title,
            "country": e.get("country"),
            "status": e.get("status"),
        })

    rows.sort(key=lambda r: (r.get("sicCode") or "", r.get("name") or ""))
    total = len(rows)
    start = page_i * limit_i
    page_items = rows[start:start + limit_i]

    # update last_used_at
    keys = _load("api_keys.json")
    for k in keys:
