            return None
        try:
            if dt.endswith("Z"):
                return datetime.datetime.fromisoformat(dt[:-1])
            return datetime.datetime.fromisoformat(dt)
        except Exception:
            return None

    minute_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    day_start = datetime.datetime.utcnow() - datetime.timedelta(days=1)

    chosen = None
    for k in active_keys:
        kid = k.get("id")
        if not kid:
            continue
        min_q = k.get("minute_request_quota")
        day_q = k.get("daily_request_quota")
        if not isinstance(min_q, int) or min_q < 0:
            min_q = 0
        if not isinstance(day_q, int) or day_q < 0:
            day_q = 0
        if (min_q == 0 and day_q == 0):
            continue

        cmin = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != kid:
                continue
            d = _parse_z(r.get("created_at"))
            if d is None:
                continue
            if d >= minute_start:
                cmin += 1
            if d >= day_start:
                cday += 1
        if min_q > 0 and cmin >= min_q:
            continue
        if day_q > 0 and cday >= day_q:
            continue
        chosen = k
        break

