    out.sort(key=_sort_key, reverse=True)

    keys = _load("api_keys.json")
    nowiso = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = nowiso
            k["updated_at"] = nowiso
            break
    _save("api_keys.json", keys)

    dur = int((time.time() - t0) * 1000)
    _log(key["id"], tool, params, 200, dur, result_count=len(out), error_code=None)
    return {"data": out, "meta": {"total": len(out)}}

def getCompanyProfilesBulk(part, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{os.getpid()}"

    def _log(api_key_id, tool, params, http_status, duration_ms, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("rlog"),
            "api_key_id": api_key_id,
            "tool_name": tool,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": None if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_active_key():
        keys = _load("api_keys.json")
        actives = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not actives:
            return None
        rank = {"free": 0, "starter": 1, "pro": 2, "enterprise": 3}
        actives.sort(key=lambda k: rank.get(k.get("plan"), -1), reverse=True)
        return actives[0]

    def _enforce_quota(api_key_id, minute_quota, daily_quota):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        m = 0
        d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            t = _parse(r.get("created_at"))
            if not t:
                continue
            if t >= minute_ago:
                m += 1
            if t >= day_ago:
                d += 1
        if isinstance(minute_quota, int) and minute_quota >= 0 and m >= minute_quota:
            return _err("QUOTA_EXCEEDED", "Minute request quota exceeded.")
        if isinstance(daily_quota, int) and daily_quota >= 0 and d >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    t0 = time.time()
    tool = "getCompanyProfilesBulk"
    params = {"part": part}

    # Validate part as non-negative integer string
    if not isinstance(part, str) or not part.strip():
        key = _resolve_active_key()
        api_key_id = key["id"] if key else "unauthenticated"
        dur = int((time.time() - t0) * 1000)
        _log(api_key_id, tool, params, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'part' must be a non-empty string representing an integer partition id.")
    try:
        part_i = int(part.strip())
    except ValueError:
        key = _resolve_active_key()
        api_key_id = key["id"] if key else "unauthenticated"
        dur = int((time.time() - t0) * 1000)
        _log(api_key_id, tool, params, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'part' must be an integer (as a string).")
    if part_i < 0:
        key = _resolve_active_key()
        api_key_id = key["id"] if key else "unauthenticated"
        dur = int((time.time() - t0) * 1000)
        _log(api_key_id, tool, params, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'part' must be >= 0.")

    key = _resolve_active_key()
    if not key:
        dur = int((time.time() - t0) * 1000)
        _log("unauthenticated", tool, params, 401, dur, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    qerr = _enforce_quota(key["id"], key.get("minute_request_quota"), key.get("daily_request_quota"))
    if qerr:
        dur = int((time.time() - t0) * 1000)
        _log(key["id"], tool, params, 429, dur, result_count=None, error_code=qerr["error"]["code"])
        return qerr

    # Deterministic partitioning policy: N fixed to 10 parts (0..9)
    N = 10
    if part_i >= N:
        dur = int((time.time() - t0) * 1000)
        _log(key["id"], tool, {"part": part.strip()}, 400, dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"Invalid 'part'. Must be between 0 and {N-1}.")

    instruments = _load("instruments.json")
    entities = {e.get("id"): e for e in _load("entities.json") if isinstance(e, dict)}
    mdps = _load("market_data_points.json")
    content = _load("content_items.json")

    # Build latest unadjusted 1day regular snapshot lookup
    latest_by_instrument = {}
    for r in mdps:
        if not isinstance(r, dict):
            continue
        if r.get("is_latest_snapshot") is not True:
            continue
        if r.get("timeframe") != "1day":
            continue
        if r.get("adjustment_type") != "unadjusted":
            continue
        if r.get("session") != "regular":
            continue
        iid = r.get("instrument_id")
        if isinstance(iid, str):
            latest_by_instrument[iid] = r

    # Build "profile-like" content if present (not guaranteed in schema); use content_type='financial_report' or 'fmp_article' etc would be wrong.
    # We'll attach none; primary profile is from instruments/entities and latest snapshot.
    out = []
    for inst in instruments:
        if not isinstance(inst, dict):
            continue
        if inst.get("asset_type") != "equity":
            continue
        if inst.get("status") == "inactive":
            continue

        ns = inst.get("normalized_symbol")
        if not isinstance(ns, str) or not ns:
            continue

        # Partition by stable hash of normalized_symbol
        h = int(hashlib.sha256(ns.encode("utf-8")).hexdigest(), 16)
        if (h % N) != part_i:
            continue

        ent = entities.get(inst.get("entity_id")) if isinstance(inst.get("entity_id"), str) else None
        snap = latest_by_instrument.get(inst.get("id"))

        row = {
            "symbol": inst.get("symbol"),
            "normalized_symbol": ns,
            "companyName": inst.get("name"),
            "exchange": inst.get("exchange"),
            "currency": inst.get("currency"),
            "country": inst.get("country") or (ent.get("country") if isinstance(ent, dict) else None),
            "sector": inst.get("sector"),
            "industry": inst.get("industry"),
            "cik": (ent.get("cik") if isinstance(ent, dict) else None),
            "isActivelyTrading": inst.get("is_actively_trading"),
            "isEtf": inst.get("is_etf"),
            "isFund": inst.get("is_fund"),
            "isDelisted": inst.get("is_delisted"),
            "latestPrice": (snap.get("close") if isinstance(snap, dict) else None),
            "latestChange": (snap.get("change") if isinstance(snap, dict) else None),
            "latestChangePercent": (snap.get("change_percent") if isinstance(snap, dict) else None),
            "latestTradeDate": (snap.get("trade_date") if isinstance(snap, dict) else None),
        }
        out.append(row)

    # Stable ordering by symbol
    out.sort(key=lambda r: (r.get("normalized_symbol") or ""))

    # Update last_used_at on success
    keys = _load("api_keys.json")
    nowiso = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = nowiso
            k["updated_at"] = nowiso
            break
    _save("api_keys.json", keys)

    dur = int((time.time() - t0) * 1000)
    _log(key["id"], tool, {"part": str(part_i)}, 200, dur, result_count=len(out), error_code=None)
    return {"data": out, "meta": {"part": part_i, "parts": N, "total": len(out)}}

def getStockRatingsBulk(symbols=None, exchange=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- helpers ----
    _SYM_RE = re.compile(r"^[A-Z0-9][A-Z0-9\.\-]{0,31}$")
    def _norm_sym(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip().upper()
        return s2

    def _hash_key_material(k):
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"==")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict): 
                return None
            if obj.get("v") != 1 or obj.get("tool") != "getStockRatingsBulk":
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(offset):
        obj = {"v": 1, "tool": "getStockRatingsBulk", "offset": offset}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _log_request(api_key_id, params_obj, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        # id convention: req_<yyyymmddhhmmss>_<rand>
        rid = "req_" + now.strftime("%Y%m%d%H%M%S") + "_" + hashlib.sha1((str(time.time()) + api_key_id + str(http_status)).encode("utf-8")).hexdigest()[:12]
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": "getStockRatingsBulk",
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_active_key():
        keys = _load("api_keys.json")
        # No credential parameter in this tool; choose any key that can serve call.
        # Must be active and not over quota.
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, "UNAUTHORIZED", "No active API key available."
        return active, None, None

    def _within_rolling(logs, api_key_id, since_dt):
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                # Accept trailing Z
                if ts.endswith("Z"):
                    ts2 = ts[:-1]
                else:
                    ts2 = ts
                dt = datetime.datetime.fromisoformat(ts2)
            except Exception:
                continue
            if dt >= since_dt:
                cnt += 1
        return cnt

    def _select_key_under_quota(candidates):
        logs = _load("request_logs.json")
        minute_since = now - datetime.timedelta(minutes=1)
        day_since = now - datetime.timedelta(days=1)
        for k in candidates:
            try:
                minute_quota = int(k.get("minute_request_quota"))
                daily_quota = int(k.get("daily_request_quota"))
            except Exception:
                continue
            if minute_quota < 0 or daily_quota < 0:
                continue
            used_minute = _within_rolling(logs, k.get("id"), minute_since)
            used_day = _within_rolling(logs, k.get("id"), day_since)
            if used_minute >= minute_quota or used_day >= daily_quota:
                continue
            return k
        return None

    # ---- validate params (no additionalProperties already ensured by signature) ----
    params_obj = {}
    if symbols is not None:
        if not isinstance(symbols, list):
            params_obj = {"symbols": symbols, "exchange": exchange, "limit": limit, "cursor": cursor}
