                _log_request(candidates[0].get("id"), {"symbols": symbols, "exchange": exchange, "limit": limit, "cursor": cursor}, 429, "bypass", dur, None, "QUOTA_EXCEEDED")
                return _err("QUOTA_EXCEEDED", "Request quota exceeded.")
            dur = (time.time() - t0) * 1000
            _log_request(api_key_row.get("id"), {"symbols": symbols, "exchange": exchange, "limit": limit, "cursor": cursor}, 400, "bypass", dur, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "exchange must be a non-empty string when provided.")
