            _log_request(candidates[0].get("id"), {"symbols": symbols, "exchange": exchange, "limit": limit, "cursor": cursor}, 429, "bypass", dur, None, "QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Request quota exceeded.")
        dur = (time.time() - t0) * 1000
        _log_request(api_key_row.get("id"), {"symbols": symbols, "exchange": exchange, "limit": limit, "cursor": cursor}, 400, "bypass", dur, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000.")
    if cursor is not None and not isinstance(cursor, str):
        candidates, aerr, amsg = _pick_active_key()
        api_key_row = _select_key_under_quota(candidates) if candidates else None
        if aerr:
            dur = (time.time() - t0) * 1000
            _log_request("unknown", {"symbols": symbols, "exchange": exchange, "limit": limit, "cursor": cursor}, 401, "bypass", dur, None, aerr)
            return _err("UNAUTHORIZED", amsg)
        if not api_key_row:
            dur = (time.time() - t0) * 1000
            _log_request(candidates[0].get("id"), {"symbols": symbols, "exchange": exchange, "limit": limit, "cursor": cursor}, 429, "bypass", dur, None, "QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Request quota exceeded.")
        dur = (time.time() - t0) * 1000
        _log_request(api_key_row.get("id"), {"symbols": symbols, "exchange": exchange, "limit": limit, "cursor": cursor}, 400, "bypass", dur, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")
    if cursor is not None:
        params_obj["cursor"] = cursor
    params_obj["limit"] = limit_i if symbols is None else limit_i  # keep validated limit in params for schema conformity

    # ---- authenticate + quota ----
    candidates, aerr, amsg = _pick_active_key()
    if aerr:
        dur = (time.time() - t0) * 1000
        _log_request("unknown", params_obj, 401, "bypass", dur, None, aerr)
        return _err("UNAUTHORIZED", amsg)
    api_key_row = _select_key_under_quota(candidates)
    if not api_key_row:
        dur = (time.time() - t0) * 1000
        _log_request(candidates[0].get("id"), params_obj, 429, "bypass", dur, None, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Request quota exceeded.")

    # ---- entitlement filters from api key ----
    allowed_exchanges = api_key_row.get("allowed_exchanges")
    allowed_asset_types = api_key_row.get("allowed_asset_types")

    # ---- query data ----
    instruments = _load("instruments.json")
    content = _load("content_items.json")

    def _instrument_ok(inst):
        if not isinstance(inst, dict):
            return False
        if allowed_exchanges is not None:
            if inst.get("exchange") not in allowed_exchanges:
                return False
        if allowed_asset_types is not None:
            if inst.get("asset_type") not in allowed_asset_types:
                return False
        return True

    # index instruments by (normalized_symbol, exchange semantics)
    idx_by_norm = {}
    for inst in instruments:
        if not _instrument_ok(inst):
            continue
        ns = inst.get("normalized_symbol")
        ex = inst.get("exchange")
        if not isinstance(ns, str):
            continue
        idx_by_norm.setdefault(ns, []).append(inst)

    def _match_instruments_for_symbol(sym, ex_filter=None):
        lst = idx_by_norm.get(sym, [])
        if ex_filter is not None:
            return [i for i in lst if i.get("exchange") == ex_filter]
        # if exchange not provided: respect uniqueness semantics:
        # prefer rows with exchange is null, else return all (ambiguous) but capped later
        null_ex = [i for i in lst if i.get("exchange") is None]
        return null_ex if null_ex else lst

    # content type for ratings
    RAT_TYPE = "ratings"

    def _rating_for_instrument(inst_id):
        # pick most recent active ratings row for instrument_id (by as_of_date then updated_at/created_at)
        best = None
        best_key = None
        for it in content:
            if not isinstance(it, dict):
                continue
            if it.get("content_type") != RAT_TYPE:
                continue
            if it.get("status") != "active":
                continue
            if it.get("instrument_id") != inst_id:
                continue
            as_of = it.get("as_of_date") or ""
            upd = it.get("updated_at") or it.get("created_at") or ""
            key = (as_of, upd, it.get("id") or "")
            if best is None or key > best_key:
                best = it
                best_key = key
        return best

    results = []
    next_cursor = None
    has_more = False

    if symbols is not None:
        # server policy: max list length
        if len(symbols) > 100:
            dur = (time.time() - t0) * 1000
            _log_request(api_key_row.get("id"), params_obj, 400, "bypass", dur, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "symbols exceeds maximum allowed length (100).")
        seen = set()
        norm_syms = []
        for s in symbols:
            ns = _norm_sym(s)
            if ns is None or not _SYM_RE.match(ns):
                dur = (time.time() - t0) * 1000
                _log_request(api_key_row.get("id"), params_obj, 400, "bypass", dur, None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Malformed symbol: {s!r}")
            if ns in seen:
                continue
            seen.add(ns)
            norm_syms.append(ns)

        for ns in norm_syms:
            for inst in _match_instruments_for_symbol(ns, exchange.strip() if isinstance(exchange, str) and exchange.strip() else None):
                if exchange is not None and inst.get("exchange") != exchange.strip():
                    continue
                rat = _rating_for_instrument(inst.get("id"))
                if rat:
                    # return payload merged with common identifying fields
