                continue
            if it.get("identifier_1") not in (None, "", "dcf", "DCF", "valuation"):
                # allow generic rows; filter later by payload
                pass
            payload = it.get("payload")
            if not isinstance(payload, dict):
                continue
            # heuristic: must contain at least one typical DCF field
            if not any(k in payload for k in ("dcf", "dcfValue", "dcfPrice", "valuation", "enterpriseValue", "stockPrice", "date")):
                continue
            as_of = it.get("as_of_date") or payload.get("date") or ""
            upd = it.get("updated_at") or it.get("created_at") or ""
            key = (as_of, upd, it.get("id") or "")
            if best is None or key > best_key:
                best = it
                best_key = key
        return best

