            continue
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue
        if not any(k in payload for k in ("dcf", "dcfValue", "dcfPrice", "valuation", "enterpriseValue", "stockPrice", "date")):
            continue
        inst = inst_by_id.get(it.get("instrument_id"))
        if not inst or not _instrument_ok(inst):
            continue
        if ex_filter is not None and inst.get("exchange") != ex_filter:
            continue
        as_of = it.get("as_of_date") or payload.get("date") or ""
        sym = inst.get("normalized_symbol") or ""
        items.append((as_of, sym, it.get("id") or "", it, inst))

    items.sort()
    total = len(items)
    page_items = items[off:off + limit_i]
    for _, __, ___, it, inst in page_items:
        out = dict(it.get("payload") if isinstance(it.get("payload"), dict) else {})
        out.setdefault("symbol", inst.get("symbol"))
        out.setdefault("exchange", inst.get("exchange"))
        out.setdefault("name", inst.get("name"))
        out.setdefault("asOfDate", it.get("as_of_date"))
        results.append(out)

    new_off = off + len(page_items)
    if new_off < total:
        has_more = True
        next_cursor = _make_cursor(new_off)

    dur = (time.time() - t0) * 1000
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)
    _log_request(api_key_row.get("id"), {"symbols": None, "exchange": exchange, "limit": limit_i, "cursor": cursor}, 200, "miss", dur, len(results), None)
    return {"data": results, "meta": {"total": total, "result_count": len(results), "has_more": has_more, "next_cursor": next_cursor}}

