        null_ex = [i for i in lst if i.get("exchange") is None]
        return null_ex if null_ex else lst

    PT_TYPE = "price_target"
    def _pt_for_instrument(inst_id):
        best = None
        best_key = None
        for it in content:
            if not isinstance(it, dict):
                continue
            if it.get("content_type") != PT_TYPE:
                continue
            if it.get("status") != "active":
                continue
            if it.get("instrument_id") != inst_id:
                continue
            as_of = it.get("as_of_date") or ""
            upd = it.get("updated_at") or it.get("created_at") or ""
            key = (as_of, upd, it.get("id") or "")
            if best is None or key > best_key:
                best = it
                best_key = key
        return best

    results = []
    next_cursor = None
    has_more = False

    if symbols is not None:
        if len(symbols) > 100:
            dur = (time.time() - t0) * 1000
            _log_request(api_key_row.get("id"), params_obj, 400, "bypass", dur, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "symbols exceeds maximum allowed length (100).")
        seen = set()
        norm_syms = []
        for s in symbols:
            ns = _norm_sym(s)
            if ns is None or not _SYM_RE.match(ns):
                dur = (time.time() - t0) * 1000
                _log_request(api_key_row.get("id"), params_obj, 400, "bypass", dur, None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Malformed symbol: {s!r}")
            if ns in seen:
                continue
            seen.add(ns)
            norm_syms.append(ns)

        ex_filter = exchange.strip() if isinstance(exchange, str) and exchange.strip() else None
        for ns in norm_syms:
            for inst in _match_instruments_for_symbol(ns, ex_filter):
                it = _pt_for_instrument(inst.get("id"))
                if it:
                    out = dict(it.get("payload") if isinstance(it.get("payload"), dict) else {})
                    out.setdefault("symbol", inst.get("symbol"))
                    out.setdefault("exchange", inst.get("exchange"))
                    out.setdefault("name", inst.get("name"))
                    out.setdefault("asOfDate", it.get("as_of_date"))
                    results.append(out)

        dur = (time.time() - t0) * 1000
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", keys)
        _log_request(api_key_row.get("id"), {"symbols": symbols, "exchange": exchange, "limit": limit_i, "cursor": cursor}, 200, "miss", dur, len(results), None)
        return {"data": results, "meta": {"result_count": len(results)}}

    off = _parse_cursor(cursor)
    if off is None:
        dur = (time.time() - t0) * 1000
        _log_request(api_key_row.get("id"), params_obj, 400, "bypass", dur, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    ex_filter = exchange.strip() if isinstance(exchange, str) and exchange.strip() else None
    inst_by_id = {i.get("id"): i for i in instruments if isinstance(i, dict)}

    items = []
    for it in content:
        if not isinstance(it, dict):
            continue
        if it.get("content_type") != PT_TYPE or it.get("status") != "active":
            continue
        inst = inst_by_id.get(it.get("instrument_id"))
        if not inst or not _instrument_ok(inst):
            continue
        if ex_filter is not None and inst.get("exchange") != ex_filter:
            continue
        as_of = it.get("as_of_date") or ""
        sym = inst.get("normalized_symbol") or ""
        items.append((as_of, sym, it.get("id") or "", it, inst))

    items.sort()
    total = len(items)
    page_items = items[off:off + limit_i]
    for _, __, ___, it, inst in page_items:
        out = dict(it.get("payload") if isinstance(it.get("payload"), dict) else {})
        out.setdefault("symbol", inst.get("symbol"))
        out.setdefault("exchange", inst.get("exchange"))
        out.setdefault("name", inst.get("name"))
        out.setdefault("asOfDate", it.get("as_of_date"))
        results.append(out)

    new_off = off + len(page_items)
    if new_off < total:
        has_more = True
        next_cursor = _make_cursor(new_off)

    dur = (time.time() - t0) * 1000
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)
    _log_request(api_key_row.get("id"), {"symbols": None, "exchange": exchange, "limit": limit_i, "cursor": cursor}, 200, "miss", dur, len(results), None)
    return {"data": results, "meta": {"total": total, "result_count": len(results), "has_more": has_more, "next_cursor": next_cursor}}

def getETFHoldersBulk(part, **_extra):
