            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count if result_count is None else int(result_count),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rolling_counts(api_key_id):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        one_min = now - datetime.timedelta(minutes=1)
        one_day = now - datetime.timedelta(days=1)

        c_min = 0
        c_day = 0
        for r in logs:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= one_day:
                c_day += 1
                if dt >= one_min:
                    c_min += 1
        return c_min, c_day

    def _resolve_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("status") == "active":
                return k
        return None

    # Validate params schema (additionalProperties=false, required part)
    params_obj = {"part": part}
    if part is None or not isinstance(part, str) or part.strip() == "":
        api_key = _resolve_active_key()
        api_key_id = api_key.get("id") if api_key else "unknown"
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(api_key_id, "getETFHoldersBulk", params_obj, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "part is required and must be a non-empty string")

    part_s = part.strip()
    if not re.fullmatch(r"\d+", part_s):
        api_key = _resolve_active_key()
        api_key_id = api_key.get("id") if api_key else "unknown"
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(api_key_id, "getETFHoldersBulk", params_obj, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "part must be a non-negative integer string (e.g., '0', '1', '2')")

    # Authenticate (ambient): require at least one active key in store.
    api_key = _resolve_active_key()
    if not api_key:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request("unknown", "getETFHoldersBulk", params_obj, 401, "bypass", duration_ms, result_count=0, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available")

    api_key_id = api_key["id"]

    # Quota enforcement (rolling windows)
    minute_quota = api_key.get("minute_request_quota")
    daily_quota = api_key.get("daily_request_quota")
    if not isinstance(minute_quota, int) or minute_quota < 0 or not isinstance(daily_quota, int) or daily_quota < 0:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(api_key_id, "getETFHoldersBulk", params_obj, 403, "bypass", duration_ms, result_count=0, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key quotas are not configured")

    c_min, c_day = _rolling_counts(api_key_id)
    if (minute_quota >= 0 and c_min + 1 > minute_quota) or (daily_quota >= 0 and c_day + 1 > daily_quota):
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(api_key_id, "getETFHoldersBulk", params_obj, 429, "bypass", duration_ms, result_count=0, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Request quota exceeded")

    # Read bulk ETF holdings from content_items where content_type='etf_holding'
    # Deterministic partition: use N=10, part in [0..9]
    part_i = int(part_s)
    N = 10
    if part_i < 0 or part_i >= N:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(api_key_id, "getETFHoldersBulk", params_obj, 400, "bypass", duration_ms, result_count=0, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"part must be between 0 and {N-1} (server partitions)")

    items = _load("content_items.json")
    results = []
    for it in items:
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "etf_holding":
            continue
        payload = it.get("payload")
        if not isinstance(payload, dict):
            continue

        # Partition key: instrument symbol if possible, else content id
        inst_id = it.get("instrument_id")
        key = inst_id if isinstance(inst_id, str) and inst_id else it.get("id")
        if not isinstance(key, str) or not key:
            continue
        h = int(hashlib.sha256(key.encode("utf-8")).hexdigest(), 16)
        if (h % N) != part_i:
            continue

        # Return payload rows if payload contains list under common keys, else the item itself
        if isinstance(payload.get("holdings"), list):
            for r in payload["holdings"]:
                if isinstance(r, dict):
                    results.append(r)
        elif isinstance(payload.get("data"), list):
            for r in payload["data"]:
                if isinstance(r, dict):
                    results.append(r)
        else:
            # Fallback: return the content item payload with identifiers
            out = {"contentItemId": it.get("id"), "instrumentId": inst_id, "payload": payload}
            results.append(out)

    # Update key last_used_at on successful authenticated request
    keys = _load("api_keys.json")
    now = _now_iso()
    for k in keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    duration_ms = int((time.time() - _t0) * 1000)
    _log_request(api_key_id, "getETFHoldersBulk", params_obj, 200, "miss", duration_ms, result_count=len(results), error_code=None)

    return {"data": results, "meta": {"part": part_s, "partitions": N, "count": len(results)}}

