                    minute_count += 1
        if minute_count >= int(api_key_row.get("minute_request_quota", 0)):
            return _err("RATE_LIMIT", "Minute request quota exceeded.")
        if day_count >= int(api_key_row.get("daily_request_quota", 0)):
