            _log(key["id"], "getStockPeersBulk", params, 400, "bypass", dur, result_count=None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit exceeds maximum of 1000.")
        limit_v = limit

    if sort is None:
        sort_v = "symbol"
    else:
