    if symbol is not None and instrumentId is not None:
        dur = (time.time() - _t0) * 1000
        _log(key["id"], "getStockPeersBulk", params, 400, "bypass", dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Provide either symbol or instrumentId, not both.")

    # Parse cursor (opaque)
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 2048:
            dur = (time.time() - _t0) * 1000
            _log(key["id"], "getStockPeersBulk", params, 400, "bypass", dur, result_count=None, error_code="VALIDATION_ERROR")
