    allowed_ex = key.get("allowed_exchanges", None)
    allowed_at = key.get("allowed_asset_types", None)

    instruments = _load("instruments.json")
    content = _load("content_items.json")

    # Resolve single instrument if requested
    target_instrument = None
    if instrumentId is not None:
        for ins in instruments:
            if isinstance(ins, dict) and ins.get("id") == instrumentId:
                target_instrument = ins
                break
        if not target_instrument:
