    def _instrument_allowed(ins):
        if not isinstance(ins, dict):
            return False
        if ins.get("asset_type") != "equity":
            return False
        if allowed_at is not None and ins.get("asset_type") not in allowed_at:
            return False
        if allowed_ex is not None:
            exv = ins.get("exchange")
            if exv is None or exv not in allowed_ex:
                return False
        return True

    # Build peer mappings from content_items of type 'scores' or 'ratings' isn't correct;
    # This server uses content_items payload for peers when present:
    # content_type='key_metrics' with identifier_1='stock_peers' (vendor-specific store convention)
