    peer_items = []
    for ci in content:
        if not isinstance(ci, dict):
            continue
        if ci.get("status") != "active":
            continue
        if ci.get("content_type") != "key_metrics":
            continue
        if ci.get("identifier_1") != "stock_peers":
            continue
