            continue
        peers = payload.get("peers")
        if not isinstance(peers, list):
            continue

        # Normalize peer symbols for output; only include those that exist as equity instruments
        out_peers = []
        seen = set()
        for p in peers:
            if not isinstance(p, str):
                continue
            ps = p.strip().upper()
            if not ps or ps in seen:
                continue
            seen.add(ps)
            out_peers.append(ps)

        peer_items.append({
            "instrumentId": iid,
            "symbol": ins.get("symbol"),
            "exchange": ins.get("exchange"),
            "sector": ins.get("sector"),
            "industry": ins.get("industry"),
            "country": ins.get("country"),
            "peers": out_peers,
            "updatedAt": ci.get("updated_at")
        })

    # Sort
    reverse = False
    keyfn = None
    if sort_v == "symbol":
        keyfn = lambda r: ("" if r.get("symbol") is None else str(r.get("symbol")).upper(), r.get("instrumentId") or "")
    elif sort_v == "-symbol":
        reverse = True
        keyfn = lambda r: ("" if r.get("symbol") is None else str(r.get("symbol")).upper(), r.get("instrumentId") or "")
    elif sort_v == "updatedAt":
        keyfn = lambda r: ("" if r.get("updatedAt") is None else str(r.get("updatedAt")), r.get("instrumentId") or "")
    elif sort_v == "-updatedAt":
