        return _err("VALIDATION_ERROR", "Invalid sort value.")

    peer_items.sort(key=keyfn, reverse=reverse)

    total = len(peer_items)
    page_items = peer_items[start:start + limit_v] if limit_v is not None else peer_items[start:]
    next_cursor = None
    has_more = False
    if start + len(page_items) < total:
        has_more = True
        nxt = {"v": 1, "o": start + len(page_items)}
        next_cursor = base64.urlsafe_b64encode(json.dumps(nxt, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    # Update last_used_at only on successful authenticated request
    keys = _load("api_keys.json")
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = _now
            k["updated_at"] = _now
            break
    _save("api_keys.json", keys)

    dur = (time.time() - _t0) * 1000
    _log(key["id"], "getStockPeersBulk", params, 200, "miss", dur, result_count=len(page_items), error_code=None)

    return {"data": page_items, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

