def getBalanceSheetStatementsBulk(year, period, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_year(y):
        if isinstance(y, int):
            return y
        if isinstance(y, str) and y.isdigit():
            return int(y)
        return None

    def _validate_period(p):
        return p in ("Q1", "Q2", "Q3", "Q4", "FY")

    def _log_request(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        ts = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": (None if result_count is None else int(max(0, result_count))),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_authorized_key():
        keys = _load("api_keys.json")
        # Ambient authentication: choose any active key that can still serve the request.
        # If none active exist, UNAUTHORIZED.
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        # Prefer keys with highest quotas to reduce chance of quota failure.
        active.sort(key=lambda k: (int(k.get("daily_request_quota", 0)), int(k.get("minute_request_quota", 0))), reverse=True)
        return active[0]

    def _within_rolling_window(logs, api_key_id, since_dt):
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            created = r.get("created_at")
            if not isinstance(created, str):
                continue
            try:
                # accept trailing Z
                if created.endswith("Z"):
                    created_dt = datetime.datetime.fromisoformat(created[:-1])
                else:
                    created_dt = datetime.datetime.fromisoformat(created)
            except Exception:
                continue
            if created_dt >= since_dt:
                c += 1
        return c

    start = time.perf_counter()
    tool = "getBalanceSheetStatementsBulk"
    params = {"year": year, "period": period}

    # Validate inputs (schema: required year/period, additionalProperties=false already satisfied by signature)
    y = _parse_year(year)
    if y is None or y < 1900 or y > 2200:
        dur = int((time.perf_counter() - start) * 1000)
        k = _pick_authorized_key()
        api_key_id = (k.get("id") if k else "anonymous")
        _log_request(api_key_id, tool, params, 400, "bypass", dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid year. Must be a 4-digit year string or integer between 1900 and 2200.", field="year")

    if not isinstance(period, str) or not _validate_period(period):
        dur = int((time.perf_counter() - start) * 1000)
        k = _pick_authorized_key()
        api_key_id = (k.get("id") if k else "anonymous")
        _log_request(api_key_id, tool, params, 400, "bypass", dur, result_count=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid period. Must be one of Q1, Q2, Q3, Q4, FY.", field="period")

    # Authenticate (ambient)
    key = _pick_authorized_key()
    if not key:
        dur = int((time.perf_counter() - start) * 1000)
        _log_request("anonymous", tool, params, 401, "bypass", dur, result_count=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    # Enforce quotas (rolling windows based on request_logs)
    logs = _load("request_logs.json")
    now = datetime.datetime.utcnow()
    minute_quota = int(key.get("minute_request_quota", 0) or 0)
    daily_quota = int(key.get("daily_request_quota", 0) or 0)

    if minute_quota >= 0:
        since = now - datetime.timedelta(minutes=1)
        used = _within_rolling_window(logs, key["id"], since)
        if used + 1 > minute_quota:
            dur = int((time.perf_counter() - start) * 1000)
            _log_request(key["id"], tool, params, 429, "bypass", dur, result_count=None, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Minute request quota exceeded.", limit=minute_quota, window_seconds=60)

    if daily_quota >= 0:
        since = now - datetime.timedelta(days=1)
        used = _within_rolling_window(logs, key["id"], since)
        if used + 1 > daily_quota:
            dur = int((time.perf_counter() - start) * 1000)
            _log_request(key["id"], tool, params, 429, "bypass", dur, result_count=None, error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=daily_quota, window_seconds=86400)

    # Read bulk payload from content_items
    items = _load("content_items.json")
    want_year = y
    want_period = period
    matches = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("status") != "active":
            continue
        if it.get("content_type") != "financial_statement":
            continue
        if it.get("identifier_1") != "balance_sheet":
            continue
        if it.get("year") != want_year:
            continue
        if it.get("period") != want_period:
            continue
        payload = it.get("payload")
        if isinstance(payload, dict) and isinstance(payload.get("rows"), list):
            matches.append(it)

    # Deterministic pick if multiple exist (newest updated_at)
    chosen = None
    if matches:
        def _dt_key(r):
            s = r.get("updated_at") or r.get("created_at") or ""
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return datetime.datetime.min
        matches.sort(key=_dt_key, reverse=True)
        chosen = matches[0]

    result = []
    if chosen:
        result = chosen.get("payload", {}).get("rows", [])
        if not isinstance(result, list):
            result = []

    # Update last_used_at on success path (authenticated, quota ok)
    keys_all = _load("api_keys.json")
    now_iso = _now_iso()
    for k in keys_all:
        if isinstance(k, dict) and k.get("id") == key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys_all)

    dur = int((time.perf_counter() - start) * 1000)
    _log_request(key["id"], tool, params, 200, "miss", dur, result_count=len(result), error_code=None)
    return {
        "year": str(want_year),
        "period": want_period,
        "data": result,
        "meta": {"result_count": len(result)},
    }

