def createApiKey(apikey, label, plan, status=None, daily_request_quota=None, minute_request_quota=None, concurrency_limit=None, allowed_exchanges=None, allowed_asset_types=None, **_extra):
    import json, os, datetime, time, hashlib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "createApiKey"
    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    def _iso_now_z(dt=None):
        dt = dt or now_dt
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        seed = hashlib.sha1((str(time.time()) + "|" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{seed}"

    def _hash_key_plain(plain):
        return hashlib.sha256(plain.encode("utf-8")).hexdigest()

    def _log(api_key_id, params_obj, http_status, result_count=None, error_code=None, cache_status="bypass"):
        logs = _load("request_logs.json")
        now_iso = _iso_now_z()
        duration_ms = int((time.time() - t0) * 1000)
        if duration_ms < 0:
            duration_ms = 0
        logs.append({
            "id": _new_id("fmp_req"),
            "api_key_id": api_key_id if isinstance(api_key_id, str) else "unknown",
            "tool_name": tool_name,
            "params": params_obj,
            "http_status": int(http_status),
            "cache_status": cache_status if cache_status in ("hit", "miss", "bypass") else "bypass",
            "duration_ms": int(duration_ms),
            "result_count": (None if result_count is None else int(result_count)),
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _rolling_counts(api_key_id):
        logs = _load("request_logs.json")
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_ts(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                d += 1
                if dt >= minute_ago:
                    m += 1
        return m, d

    def _authenticate_caller(plain_or_id):
        # IMPORTANT: must match against stored id OR stored client-visible value; store only has id and key_hash.
        # Therefore allow:
        #  - direct match with api_keys.id
        #  - OR treat provided apikey as plaintext and hash it to match key_hash
        keys = _load("api_keys.json")
        if not isinstance(plain_or_id, str) or not plain_or_id.strip():
            return None, "missing"
        token = plain_or_id.strip()

        by_id = next((k for k in keys if isinstance(k, dict) and k.get("id") == token), None)
        if by_id is not None:
            return by_id, None

        h = _hash_key_plain(token)
        by_hash = next((k for k in keys if isinstance(k, dict) and k.get("key_hash") == h), None)
        if by_hash is not None:
            return by_hash, None
        return None, "invalid"

    def _enforce_quota_for_key(key_row):
        min_q = key_row.get("minute_request_quota")
        day_q = key_row.get("daily_request_quota")
        if not isinstance(min_q, int) or min_q < 0:
            min_q = 0
        if not isinstance(day_q, int) or day_q < 0:
            day_q = 0
        m, d = _rolling_counts(key_row["id"])
        if min_q == 0 and day_q == 0:
            return False, "quota_zero"
        if min_q != 0 and m + 1 > min_q:
            return False, "quota_minute_exceeded"
        if day_q != 0 and d + 1 > day_q:
            return False, "quota_daily_exceeded"
        return True, None

    params_obj = {"apikey": apikey, "label": label, "plan": plan}
    if status is not None:
        params_obj["status"] = status
    if daily_request_quota is not None:
        params_obj["daily_request_quota"] = daily_request_quota
    if minute_request_quota is not None:
        params_obj["minute_request_quota"] = minute_request_quota
    if concurrency_limit is not None:
        params_obj["concurrency_limit"] = concurrency_limit
    if allowed_exchanges is not None:
        params_obj["allowed_exchanges"] = allowed_exchanges
    if allowed_asset_types is not None:
        params_obj["allowed_asset_types"] = allowed_asset_types

    # Validate inputs (schema)
    if not isinstance(apikey, str) or not apikey.strip():
        _log("unknown", params_obj, 401, None, "unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid caller API key.", http_status=401)
    if not isinstance(label, str) or not label.strip():
        caller, _ = _authenticate_caller(apikey)
        _log(caller["id"] if caller else "unknown", params_obj, 400, None, "validation_error")
        return _err("VALIDATION_ERROR", "`label` must be a non-empty string.", http_status=400)
    if not isinstance(plan, str) or not plan.strip():
        caller, _ = _authenticate_caller(apikey)
        _log(caller["id"] if caller else "unknown", params_obj, 400, None, "validation_error")
        return _err("VALIDATION_ERROR", "`plan` must be a non-empty string.", http_status=400)

    if status is None:
        status_v = "active"
    else:
        if not isinstance(status, str) or status not in ("active", "suspended"):
            caller, _ = _authenticate_caller(apikey)
            _log(caller["id"] if caller else "unknown", params_obj, 400, None, "validation_error")
            return _err("VALIDATION_ERROR", "`status` must be one of: active, suspended.", http_status=400)
        status_v = status

    for fld, val in (("daily_request_quota", daily_request_quota), ("minute_request_quota", minute_request_quota), ("concurrency_limit", concurrency_limit)):
        if val is None:
            continue
        if not isinstance(val, int) or isinstance(val, bool) or val < 0:
            caller, _ = _authenticate_caller(apikey)
            _log(caller["id"] if caller else "unknown", params_obj, 400, None, "validation_error")
            return _err("VALIDATION_ERROR", f"`{fld}` must be an integer >= 0.", http_status=400)

    if allowed_exchanges is not None:
        if not isinstance(allowed_exchanges, list) or any((not isinstance(x, str) or not x.strip()) for x in allowed_exchanges):
            caller, _ = _authenticate_caller(apikey)
            _log(caller["id"] if caller else "unknown", params_obj, 400, None, "validation_error")
            return _err("VALIDATION_ERROR", "`allowed_exchanges` must be an array of strings.", http_status=400)

    if allowed_asset_types is not None:
        valid = {"stock", "etf", "fund", "forex", "crypto", "commodity", "index"}
        if not isinstance(allowed_asset_types, list) or any((not isinstance(x, str) or x not in valid) for x in allowed_asset_types):
            caller, _ = _authenticate_caller(apikey)
            _log(caller["id"] if caller else "unknown", params_obj, 400, None, "validation_error")
            return _err("VALIDATION_ERROR", "`allowed_asset_types` must be an array of valid asset type strings.", http_status=400)

    # Authenticate caller
    caller, auth_err = _authenticate_caller(apikey)
    if caller is None or caller.get("status") != "active":
        _log(caller["id"] if caller else "unknown", params_obj, 401, None, "unauthorized")
        return _err("UNAUTHORIZED", "Missing/invalid API key or key is not active.", http_status=401)

    ok_quota, q_reason = _enforce_quota_for_key(caller)
    if not ok_quota:
        _log(caller["id"], params_obj, 429, None, q_reason)
        return _err("QUOTA_EXCEEDED", "Request quota exceeded.", reason=q_reason, http_status=429)

    # Authorization: require plan pro/enterprise to create keys (provider-like)
    if caller.get("plan") not in ("pro", "enterprise"):
        _log(caller["id"], params_obj, 403, None, "forbidden")
        return _err("UNAUTHORIZED", "Forbidden: your plan does not allow creating API keys.", http_status=403)

    # Plan validation against provider enums
    if plan not in ("free", "starter", "pro", "enterprise"):
        _log(caller["id"], params_obj, 400, None, "validation_error")
        return _err("VALIDATION_ERROR", "`plan` must be one of: free, starter, pro, enterprise.", http_status=400)

    # Business constraints: basic "unsupported limits for plan" guard (lightweight, but not over-strict)
    # Only enforce non-negative (already done) and a gentle upper bound based on plan to avoid absurd values.
    plan_caps = {
        "free": {"daily": 5000, "minute": 60, "conc": 2},
        "starter": {"daily": 50000, "minute": 300, "conc": 5},
        "pro": {"daily": 500000, "minute": 2000, "conc": 50},
        "enterprise": {"daily": 5000000, "minute": 10000, "conc": 500},
    }
    caps = plan_caps.get(plan, plan_caps["starter"])
    d_q = daily_request_quota if daily_request_quota is not None else caps["daily"]
    m_q = minute_request_quota if minute_request_quota is not None else caps["minute"]
    c_l = concurrency_limit if concurrency_limit is not None else caps["conc"]
    if d_q > caps["daily"] or m_q > caps["minute"] or c_l > caps["conc"]:
        _log(caller["id"], params_obj, 409, None, "unsupported_limits")
        return _err("CONFLICT", "Requested quotas/limits exceed what the selected plan supports.", rule="plan_caps", http_status=409)

    # Create new key: one-time plaintext
    plain = "fmp_" + secrets.token_urlsafe(24)
    key_hash = _hash_key_plain(plain)

    keys = _load("api_keys.json")
    if any(isinstance(k, dict) and k.get("key_hash") == key_hash for k in keys):
        # extremely unlikely; retry once
        plain = "fmp_" + secrets.token_urlsafe(28)
        key_hash = _hash_key_plain(plain)
        if any(isinstance(k, dict) and k.get("key_hash") == key_hash for k in keys):
            _log(caller["id"], params_obj, 409, None, "conflict")
            return _err("CONFLICT", "Unable to allocate a unique API key. Please retry.", http_status=409)

    new_id = "fmp_key_" + secrets.token_hex(14)
    now_iso = _iso_now_z()

    row = {
        "id": new_id,
        "key_hash": key_hash,
        "label": label.strip(),
        "status": status_v,
        "plan": plan,
        "daily_request_quota": int(d_q),
        "minute_request_quota": int(m_q),
        "concurrency_limit": int(c_l),
        "allowed_exchanges": (None if allowed_exchanges is None else [x for x in allowed_exchanges]),
        "allowed_asset_types": (None if allowed_asset_types is None else [x for x in allowed_asset_types]),
        "created_at": now_iso,
        "updated_at": now_iso,
        "last_used_at": None,
    }
    keys.append(row)
    _save("api_keys.json", keys)

    # Update caller last_used_at for successful authenticated request
    for k in keys:
        if isinstance(k, dict) and k.get("id") == caller.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    # Log success
    _log(caller["id"], params_obj, 201, 1, None)

    # Return metadata + one-time plaintext
    resp = dict(row)
    resp["apikey"] = plain
    # do not return key_hash in client view
    resp.pop("key_hash", None)
    return {"data": resp, "meta": {"created": True}}

def updateApiKey(apikey, id, label=None, status=None, daily_request_quota=None, minute_request_quota=None, concurrency_limit=None, allowed_exchanges=None, allowed_asset_types=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("rlog"),
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count,
            "error_code": error_code,
            "created_at": _now,
            "updated_at": _now,
        }
        # best-effort FK: keep unknown if not authenticated
        logs.append(row)
        _save("request_logs.json", logs)

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _parse_dt(s):
        # accepts RFC3339-ish: "YYYY-MM-DDTHH:MM:SSZ" or with offset; store uses ISO string, so compare as datetime
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _window_counts(logs, api_key_id, now_dt):
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = 0
        d = 0
        inflight = 0  # not trackable; treat as 0
        for r in logs:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at") or "")
            if ts is None:
                continue
            if ts >= day_ago:
                d += 1
                if ts >= minute_ago:
                    m += 1
        return m, d, inflight

    def _authenticate(keys, presented):
        if not isinstance(presented, str) or not presented:
            return None
        for k in keys:
            if k.get("id") == presented:
                return k
        ph = _sha256_hex(presented)
        for k in keys:
            if k.get("key_hash") == ph:
                return k
        return None

    # Validate inputs and additionalProperties already enforced by signature
    params = {
        "apikey": apikey,
        "id": id,
        "label": label,
        "status": status,
        "daily_request_quota": daily_request_quota,
        "minute_request_quota": minute_request_quota,
        "concurrency_limit": concurrency_limit,
        "allowed_exchanges": allowed_exchanges,
        "allowed_asset_types": allowed_asset_types,
    }

    # Basic type validation
    if not isinstance(apikey, str) or not apikey:
        # log attempt (unknown api key)
        _log("unknown", "updateApiKey", params, 401, "bypass", (time.time() - _t0) * 1000, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid api key.")
    if not isinstance(id, str) or not id:
        _log("unknown", "updateApiKey", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a non-empty string.")

    if label is not None and not isinstance(label, str):
        _log("unknown", "updateApiKey", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'label' must be a string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
            _log("unknown", "updateApiKey", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parameter 'status' must be one of: active, suspended, revoked.")
    for n, v in (("daily_request_quota", daily_request_quota), ("minute_request_quota", minute_request_quota), ("concurrency_limit", concurrency_limit)):
        if v is not None:
            if not isinstance(v, int):
                _log("unknown", "updateApiKey", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Parameter '{n}' must be an integer.")
            if v < 0:
                _log("unknown", "updateApiKey", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Constraint violation: {n} must be >= 0.")
    if allowed_exchanges is not None:
        if not isinstance(allowed_exchanges, list) or any((not isinstance(x, str) or not x) for x in allowed_exchanges):
            _log("unknown", "updateApiKey", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parameter 'allowed_exchanges' must be an array of non-empty strings.")
    if allowed_asset_types is not None:
        if not isinstance(allowed_asset_types, list):
            _log("unknown", "updateApiKey", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parameter 'allowed_asset_types' must be an array.")
        _aat_allowed = {"stock", "etf", "fund", "forex", "crypto", "commodity", "index"}
        for x in allowed_asset_types:
            if not isinstance(x, str) or x not in _aat_allowed:
                _log("unknown", "updateApiKey", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Parameter 'allowed_asset_types' contains invalid value(s).")

    keys = _load("api_keys.json")
    caller = _authenticate(keys, apikey)

    if caller is None:
        _log("unknown", "updateApiKey", params, 401, "bypass", (time.time() - _t0) * 1000, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Status checks: business rules say only active can authenticate; otherwise authorization error and log attempt 401/403.
    if caller.get("status") != "active":
        _log(caller.get("id"), "updateApiKey", params, 403, "bypass", (time.time() - _t0) * 1000, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active.")

    # Quota enforcement prior to mutation
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    m_used, d_used, inflight = _window_counts(logs, caller["id"], now_dt)
    if caller.get("minute_request_quota", 0) >= 0 and m_used + 1 > int(caller.get("minute_request_quota", 0)):
        _log(caller["id"], "updateApiKey", params, 429, "bypass", (time.time() - _t0) * 1000, None, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Per-minute request quota exceeded.")
    if caller.get("daily_request_quota", 0) >= 0 and d_used + 1 > int(caller.get("daily_request_quota", 0)):
        _log(caller["id"], "updateApiKey", params, 429, "bypass", (time.time() - _t0) * 1000, None, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    # Permissions / plan: only enterprise can manage keys in this local server.
    if caller.get("plan") != "enterprise":
        _log(caller["id"], "updateApiKey", params, 403, "bypass", (time.time() - _t0) * 1000, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Insufficient permissions to manage API keys.")

    # Find target
    target_idx = None
    for i, k in enumerate(keys):
        if k.get("id") == id:
            target_idx = i
            break
    if target_idx is None:
        _log(caller["id"], "updateApiKey", params, 404, "bypass", (time.time() - _t0) * 1000, None, "NOT_FOUND")
        return _err("NOT_FOUND", "API key record not found.")

    target = keys[target_idx]

    # Enforce lifecycle transitions
    if status is not None:
        cur = target.get("status")
        transitions = {
            "active": {"suspended", "revoked"},
            "suspended": {"active", "revoked"},
            "revoked": set(),
        }
        if cur not in transitions:
            _log(caller["id"], "updateApiKey", params, 409, "bypass", (time.time() - _t0) * 1000, None, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Current key status is invalid.")
        if status != cur and status not in transitions[cur]:
            _log(caller["id"], "updateApiKey", params, 409, "bypass", (time.time() - _t0) * 1000, None, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Illegal status transition from '{cur}' to '{status}'.")

    # Apply updates (mutable fields only)
    changed = False
    if label is not None and label != target.get("label"):
        target["label"] = label
        changed = True
    if status is not None and status != target.get("status"):
        target["status"] = status
        changed = True
    if daily_request_quota is not None and daily_request_quota != target.get("daily_request_quota"):
        target["daily_request_quota"] = int(daily_request_quota)
        changed = True
    if minute_request_quota is not None and minute_request_quota != target.get("minute_request_quota"):
        target["minute_request_quota"] = int(minute_request_quota)
        changed = True
    if concurrency_limit is not None and concurrency_limit != target.get("concurrency_limit"):
        target["concurrency_limit"] = int(concurrency_limit)
        changed = True
    if allowed_exchanges is not None:
        if allowed_exchanges != target.get("allowed_exchanges"):
            target["allowed_exchanges"] = allowed_exchanges
            changed = True
    if allowed_asset_types is not None:
        if allowed_asset_types != target.get("allowed_asset_types"):
            target["allowed_asset_types"] = allowed_asset_types
            changed = True

    if not changed:
        # No success without effect: treat as conflict-free idempotent? Vendor says "updates ... and returns updated record".
        # But contract demands no success without effect on mutations; return NOT_FOUND-equivalent not appropriate.
        _log(caller["id"], "updateApiKey", params, 409, "bypass", (time.time() - _t0) * 1000, None, "CONFLICT")
        return _err("CONFLICT", "No changes detected; update would have no effect.")

    target["updated_at"] = _now
    keys[target_idx] = target
    _save("api_keys.json", keys)

    # Update caller last_used_at on successful authenticated request
    for i, k in enumerate(keys):
        if k.get("id") == caller.get("id"):
            keys[i]["last_used_at"] = _now
            keys[i]["updated_at"] = _now
            break
    _save("api_keys.json", keys)

    _log(caller["id"], "updateApiKey", params, 200, "bypass", (time.time() - _t0) * 1000, 1, None)
    return {"data": target}

