        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    # entitlement filters based on key allowlists
    allowed_ex = caller.get("allowed_exchanges", None)
    allowed_assets = caller.get("allowed_asset_types", None)

    def _map_asset_param_to_schema(a):
        # tool uses stock/etf/fund..., schema uses equity/etf/mutual_fund/index/crypto/forex/commodity/note
        if a == "stock":
            return {"equity"}
        if a == "fund":
            return {"mutual_fund"}
        if a == "etf":
            return {"etf"}
        if a == "index":
            return {"index"}
        if a == "crypto":
            return {"crypto"}
        if a == "forex":
            return {"forex"}
        if a == "commodity":
            return {"commodity"}
        return set()

    def _map_allowed_asset_list(lst):
        if lst is None:
