        # filters
        if sym_norm is not None and inst.get("normalized_symbol") != sym_norm:
            continue
        if ex_filter is not None and (inst.get("exchange") or None) != ex_filter:
            continue
        if requested_asset_schema is not None and inst.get("asset_type") not in requested_asset_schema:
