            continue
        if is_fund is not None and bool(inst.get("is_fund")) != is_fund:
            continue
        if updated_since_dt is not None:
            inst_ud = _parse_dt(inst.get("updated_at") or "")
            if inst_ud is None or inst_ud < updated_since_dt:
                continue

        out.append(inst)

    # stable sort: updated_at desc then id
    def _sort_key(x):
        dt = _parse_dt(x.get("updated_at") or "") or datetime.datetime(1970, 1, 1)
        return (dt, x.get("id") or "")
    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    start = page * limit
    end = start + limit
    page_items = out[start:end]
    has_more = end < total
    next_cursor = None
    if has_more:
        next_cursor = {"page": page + 1, "limit": limit}

    # update last_used_at on success
    keys2 = _load("api_keys.json")
    for i, k in enumerate(keys2):
        if k.get("id") == caller.get("id"):
            keys2[i]["last_used_at"] = _now
            keys2[i]["updated_at"] = _now
            break
    _save("api_keys.json", keys2)

    _log(caller["id"], "listInstruments", params, 200, "bypass", (time.time() - _t0) * 1000, len(page_items), None)
    return {
        "data": page_items,
        "meta": {
            "page": page,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def getInstrumentById(apikey, id, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0464000" if __import__("os").path.isdir("./environment_mix/0464000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(api_key_id, tool_name, params, http_status, cache_status, duration_ms, result_count=None, error_code=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": _new_id("rlog"),
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "tool_name": tool_name,
            "params": params,
            "http_status": int(http_status),
            "cache_status": cache_status,
            "duration_ms": int(max(0, duration_ms)),
            "result_count": result_count,
            "error_code": error_code,
            "created_at": _now,
            "updated_at": _now,
        })
        _save("request_logs.json", logs)

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _parse_dt(s):
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _window_counts(logs, api_key_id, now_dt):
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = 0
        d = 0
        for r in logs:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at") or "")
            if ts is None:
                continue
            if ts >= day_ago:
                d += 1
                if ts >= minute_ago:
                    m += 1
        return m, d

    def _authenticate(keys, presented):
        if not isinstance(presented, str) or not presented:
            return None
        for k in keys:
            if k.get("id") == presented:
                return k
        ph = _sha256_hex(presented)
        for k in keys:
            if k.get("key_hash") == ph:
                return k
        return None

    params = {"apikey": apikey, "id": id}

    if not isinstance(apikey, str) or not apikey:
        _log("unknown", "getInstrumentById", params, 401, "bypass", (time.time() - _t0) * 1000, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid api key.")
    if not isinstance(id, str) or not id:
        _log("unknown", "getInstrumentById", params, 400, "bypass", (time.time() - _t0) * 1000, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.")

    keys = _load("api_keys.json")
    caller = _authenticate(keys, apikey)
    if caller is None:
        _log("unknown", "getInstrumentById", params, 401, "bypass", (time.time() - _t0) * 1000, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")
    if caller.get("status") != "active":
        _log(caller.get("id"), "getInstrumentById", params, 403, "bypass", (time.time() - _t0) * 1000, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active.")

    # quota
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    m_used, d_used = _window_counts(logs, caller["id"], now_dt)
    if m_used + 1 > int(caller.get("minute_request_quota", 0)):
        _log(caller["id"], "getInstrumentById", params, 429, "bypass", (time.time() - _t0) * 1000, None, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Per-minute request quota exceeded.")
    if d_used + 1 > int(caller.get("daily_request_quota", 0)):
        _log(caller["id"], "getInstrumentById", params, 429, "bypass", (time.time() - _t0) * 1000, None, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    instruments = _load("instruments.json")
    inst = None
    for r in instruments:
        if r.get("id") == id:
            inst = r
            break
    if inst is None:
        _log(caller["id"], "getInstrumentById", params, 404, "bypass", (time.time() - _t0) * 1000, None, "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found.")

    # entitlement visibility
    allowed_ex = caller.get("allowed_exchanges", None)
    allowed_assets = caller.get("allowed_asset_types", None)

    def _map_allowed_asset_list(lst):
        if lst is None:
            return None
        mapped = set()
        for a in lst:
            if a == "stock":
                mapped.add("equity")
            elif a == "fund":
                mapped.add("mutual_fund")
            elif a == "etf":
                mapped.add("etf")
            elif a == "index":
                mapped.add("index")
            elif a == "crypto":
                mapped.add("crypto")
            elif a == "forex":
                mapped.add("forex")
            elif a == "commodity":
                mapped.add("commodity")
        return mapped

    allowed_asset_schema = _map_allowed_asset_list(allowed_assets)

    if allowed_ex is not None:
        ex = inst.get("exchange")
        if ex is not None and ex not in allowed_ex:
            _log(caller["id"], "getInstrumentById", params, 404, "bypass", (time.time() - _t0) * 1000, None, "NOT_FOUND")
            return _err("NOT_FOUND", "Instrument not found.")
    if allowed_asset_schema is not None and inst.get("asset_type") not in allowed_asset_schema:
        _log(caller["id"], "getInstrumentById", params, 404, "bypass", (time.time() - _t0) * 1000, None, "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found.")

    # update last_used_at on success
    keys2 = _load("api_keys.json")
    for i, k in enumerate(keys2):
        if k.get("id") == caller.get("id"):
            keys2[i]["last_used_at"] = _now
            keys2[i]["updated_at"] = _now
            break
    _save("api_keys.json", keys2)

    _log(caller["id"], "getInstrumentById", params, 200, "bypass", (time.time() - _t0) * 1000, 1, None)
    return {"data": inst}
